use super::tests_runtime::{request, running};
use super::*;

#[tokio::test]
async fn open_repeater_capacity_is_reserved_before_dispatching_side_effects() {
    let (mut running, mut calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);
    for _ in 0..63 {
        running
            .broker
            .bind_resource(Uuid::new_v4(), 1, false)
            .unwrap();
    }
    for id in [1, 2] {
        let call = HostCall {
            operation: Some(host_call::Operation::OpenRepeater(request().into())),
            parent_request_id: 0,
        };
        let envelope = Envelope::new(
            running.identity,
            id,
            1,
            envelope::Body::HostCall(call.clone()),
            MAX_OPERATION,
        );
        running.host_call(&envelope, call, &outgoing).await.unwrap();
    }
    let first = calls.try_recv().unwrap();
    assert!(
        calls.try_recv().is_err(),
        "the 65th resource must be rejected before a tab is created"
    );
    let denied = wire.try_recv().unwrap();
    assert_eq!(denied.in_reply_to, 2);
    assert!(matches!(
        denied.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(_))
        }))
    ));
    first
        .reply
        .send(Err(Failure::new(ErrorCode::Cancelled, "test cancelled")))
        .unwrap();
    let completed = timeout(MAX_OPERATION, running.service_tasks.join_next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    running.complete_service(completed, &outgoing).unwrap();
    let call = HostCall {
        operation: Some(host_call::Operation::OpenRepeater(request().into())),
        parent_request_id: 0,
    };
    let envelope = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::HostCall(call.clone()),
        MAX_OPERATION,
    );
    running.host_call(&envelope, call, &outgoing).await.unwrap();
    assert_eq!(
        calls.try_recv().unwrap().request_id,
        3,
        "failed opens must release their reservation"
    );
}

#[tokio::test]
async fn a_closed_new_tab_cannot_be_bound_by_a_late_open_repeater_result() {
    let (mut running, mut calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);
    let resource = Uuid::new_v4();
    let call = HostCall {
        operation: Some(host_call::Operation::OpenRepeater(request().into())),
        parent_request_id: 0,
    };
    let envelope = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::HostCall(call.clone()),
        MAX_OPERATION,
    );
    running.host_call(&envelope, call, &outgoing).await.unwrap();
    calls
        .try_recv()
        .unwrap()
        .reply
        .send(Ok(ServiceResult::Resource {
            id: resource,
            revision: 1,
        }))
        .unwrap();
    let completed = timeout(MAX_OPERATION, running.service_tasks.join_next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    let (reply, _closed) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: protocol::PANEL_ID,
                id: resource,
                remove_panel: false,
                reply,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(matches!(
        wire.try_recv().unwrap().body,
        Some(envelope::Body::CloseRequest(_))
    ));
    running.complete_service(completed, &outgoing).unwrap();
    assert!(
        !running.broker.resources.contains_key(&resource),
        "closing a just-created tab must win over the earlier service reply"
    );
    assert!(
        running.revoked_resources.is_empty(),
        "finished creates must release close barriers"
    );
    let result = wire.try_recv().unwrap();
    assert_eq!(result.in_reply_to, 1);
    assert!(matches!(
        result.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(_))
        }))
    ));
}

#[tokio::test]
async fn oversized_open_is_a_correlated_error_without_a_wire_write() {
    let (mut running, _calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);
    let mut large = request();
    large.body = vec![0; protocol::MAX_INLINE_BODY + 1];
    let (reply, mut opened) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: large,
                reply,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(
        matches!(opened.try_recv(), Ok(Err(_))),
        "an oversized open must fail its own reply, not kill the pipe writer"
    );
    assert!(wire.try_recv().is_err());
    assert!(running.opening_request.is_none());
    assert!(running.broker.resources.is_empty());
}

#[tokio::test]
async fn oversized_host_results_fail_only_the_correlated_call() {
    let (mut running, _calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);
    for size in [protocol::MAX_INLINE_BODY + 1, protocol::MAX_FRAME_BYTES + 1] {
        running
            .complete_service(
                ServiceCompletion {
                    request_id: 7,
                    panel_id: protocol::PANEL_ID,
                    resource_binding: None,
                    result: Ok(ServiceResult::Response(HttpResponse {
                        status: 200,
                        version: mio_plugin_api::HttpVersion::Http11,
                        reason_phrase: None,
                        headers: vec![],
                        body: vec![0; size],
                        trailers: vec![],
                    })),
                },
                &outgoing,
            )
            .unwrap();
        let result = wire.try_recv().unwrap();
        assert_eq!(result.in_reply_to, 7);
        assert!(
            matches!(
                result.body,
                Some(envelope::Body::HostResult(HostResult {
                    outcome: Some(host_result::Outcome::Error(_))
                }))
            ),
            "oversized results need a per-call error, not oversized pipe data"
        );
        result.validate().unwrap();
    }
}

#[tokio::test]
async fn multiplexed_panels_route_open_commit_and_revoke_independently() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);

    let res2 = Uuid::new_v4();
    let res3 = Uuid::new_v4();
    let (reply2, mut opened2) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: reply2,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open2_wire = wire.try_recv().unwrap();
    assert_eq!(open2_wire.panel_id, 2);

    let (reply3, mut opened3) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 3,
                id: res3,
                revision: 1,
                read_only: false,
                request: request(),
                reply: reply3,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open3_wire = wire.try_recv().unwrap();
    assert_eq!(open3_wire.panel_id, 3);

    for (seq, panel_id, reply_id, body_text) in [
        (1u64, 2u64, open2_wire.request_id, b"p2".to_vec()),
        (2u64, 3u64, open3_wire.request_id, b"p3".to_vec()),
    ] {
        let mut frame = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Snapshot(PanelSnapshot {
                revision: 1,
                title: format!("panel-{panel_id}"),
                root: Some(panel::Node::new(
                    1,
                    "ed",
                    panel::node::Kind::Editor(panel::Editor {
                        document_id: 1,
                        revision: 1,
                        contents: body_text,
                        format: panel::EditorFormat::Utf8 as i32,
                        read_only: false,
                    }),
                )),
            }),
            MAX_OPERATION,
        )
        .with_panel_id(panel_id);
        frame.in_reply_to = reply_id;
        running.frame(frame, &outgoing).await.unwrap();
    }

    assert_eq!(opened2.try_recv().unwrap().unwrap().title, "panel-2");
    assert_eq!(opened3.try_recv().unwrap().unwrap().title, "panel-3");
    assert!(matches!(
        updates.try_recv().unwrap(),
        PluginEvent::Panel { panel_id: 2, .. }
    ));
    assert!(matches!(
        updates.try_recv().unwrap(),
        PluginEvent::Panel { panel_id: 3, .. }
    ));

    // Commit on panel 2 succeeds independently of panel 3.
    let (commit_reply, mut committed2) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: res2.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"p2".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: commit_reply,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let commit2_wire = wire.try_recv().unwrap();
    assert_eq!(commit2_wire.panel_id, 2);
    let mut commit_res = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Committed(protocol::Committed {
            resource_id: res2.as_bytes().to_vec(),
            message_revision: 1,
            document_id: 1,
            document_revision: 1,
            request: Some(request().into()),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    commit_res.in_reply_to = commit2_wire.request_id;
    running.frame(commit_res, &outgoing).await.unwrap();
    assert!(committed2.try_recv().unwrap().is_ok());

    // Revoke panel 2 with remove_panel=true leaves panel 3 intact.
    let (rev_reply, mut revoked2) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: res2,
                remove_panel: true,
                reply: rev_reply,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close2_wire = wire.try_recv().unwrap();
    assert_eq!(close2_wire.panel_id, 2);
    let mut ack2 = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    ack2.in_reply_to = close2_wire.request_id;
    running.frame(ack2, &outgoing).await.unwrap();
    revoked2.try_recv().unwrap().unwrap();
    assert!(!running.panels.contains_key(&2));
    assert!(running.panels.contains_key(&3));
    assert!(running.broker.has_panel_resource(3, res3));
}

#[tokio::test]
async fn cross_panel_reply_mismatch_rejected_and_duplicate_revoke_is_idempotent() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);

    let res2 = Uuid::new_v4();
    let res3 = Uuid::new_v4();
    let (reply2, mut opened2) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: reply2,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open2_wire = wire.try_recv().unwrap();

    let (reply3, mut opened3) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 3,
                id: res3,
                revision: 1,
                read_only: false,
                request: request(),
                reply: reply3,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open3_wire = wire.try_recv().unwrap();

    // Inject cross-panel Snapshot pretending panel 2 answered panel 3's request_id.
    let mut mismatched = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "hijack".into(),
            root: Some(panel::Node::new(
                1,
                "hijack",
                panel::node::Kind::Text(panel::Text {
                    text: "hijack".into(),
                    tone: 0,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    mismatched.in_reply_to = open3_wire.request_id;
    let mismatch_err = running.frame(mismatched, &outgoing).await.unwrap_err();
    assert!(mismatch_err.to_string().contains("panel_id"));
    // Panel 3's pending open must NOT have been consumed or overwritten by panel 2.
    assert!(running.requests.contains_key(&open3_wire.request_id));
    assert!(opened3.try_recv().is_err());

    // Now answer panel 2 & panel 3 properly.
    for (seq, pid, rid) in [(2u64, 2u64, open2_wire.request_id), (3u64, 3u64, open3_wire.request_id)] {
        let mut frame = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Snapshot(PanelSnapshot {
                revision: 1,
                title: format!("panel-{pid}"),
                root: Some(panel::Node::new(
                    1,
                    "panel",
                    panel::node::Kind::Editor(panel::Editor {
                        document_id: 1,
                        revision: 1,
                        contents: b"ok".to_vec(),
                        format: panel::EditorFormat::Utf8 as i32,
                        read_only: false,
                    }),
                )),
            }),
            MAX_OPERATION,
        )
        .with_panel_id(pid);
        frame.in_reply_to = rid;
        running.frame(frame, &outgoing).await.unwrap();
    }
    assert!(opened2.try_recv().unwrap().is_ok());
    assert!(opened3.try_recv().unwrap().is_ok());
    while updates.try_recv().is_ok() {}

    // Revoke unknown panel (99) before any Open: succeeds immediately without writing CloseRequest.
    let (rev99_tx, mut rev99_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 99,
                id: Uuid::new_v4(),
                remove_panel: true,
                reply: rev99_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    rev99_rx.try_recv().unwrap().unwrap();
    assert!(wire.try_recv().is_err());

    // Revoke panel 2 twice concurrently: first emits CloseRequest and marks closing, second is no-op Ok(()).
    let (rev2a_tx, mut rev2a_rx) = oneshot::channel();
    let (rev2b_tx, mut rev2b_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: res2,
                remove_panel: true,
                reply: rev2a_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close2_wire = wire.try_recv().unwrap();
    assert_eq!(close2_wire.panel_id, 2);
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: res2,
                remove_panel: true,
                reply: rev2b_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    // Both concurrent revokes wait until the single CloseRequest's Ack settles, then both get Ok(()).
    assert!(rev2a_rx.try_recv().is_err());
    assert!(rev2b_rx.try_recv().is_err());
    assert!(wire.try_recv().is_err(), "duplicate close must not emit a second CloseRequest");
    let mut ack2 = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    ack2.in_reply_to = close2_wire.request_id;
    running.frame(ack2, &outgoing).await.unwrap();
    rev2a_rx.try_recv().unwrap().unwrap();
    rev2b_rx.try_recv().unwrap().unwrap();
    assert!(!running.panels.contains_key(&2));

    // Cancelling panel 3's commit via CancelPanelOp clears Pending and sends Cancel on panel 3.
    let (commit3_tx, mut commit3_rx) = oneshot::channel();
    let cancel_op3 = Uuid::new_v4();
    running
        .control(
            Control::Commit {
                panel_id: 3,
                op_id: cancel_op3,
                request: CommitEditor {
                    resource_id: res3.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"ok".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: commit3_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let commit3_wire = wire.try_recv().unwrap();
    running
        .control(
            Control::CancelPanelOp {
                panel_id: 3,
                op_id: cancel_op3,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(commit3_rx.try_recv().unwrap().is_err());
    let cancel_wire = wire.try_recv().unwrap();
    assert_eq!(cancel_wire.panel_id, 3);
    assert!(matches!(
        cancel_wire.body,
        Some(envelope::Body::Cancel(ref c)) if c.request_id == commit3_wire.request_id
    ));
}

#[tokio::test]
async fn multiplexed_over_limit_open_fails_single_request_without_killing_worker() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY * 2);

    for idx in 0..MAX_MULTIPLEXED_PANELS {
        let panel_id = protocol::PANEL_ID + 1 + idx as u64;
        let (reply, _rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let _ = wire.try_recv().unwrap();
    }
    let (over_tx, mut over_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: protocol::PANEL_ID + 1 + MAX_MULTIPLEXED_PANELS as u64,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: over_tx,
            },
            &outgoing,
        )
        .await
        .expect("over-limit open on child panel must not fail worker loop");
    assert!(over_rx.try_recv().unwrap().is_err());
}

#[tokio::test]
async fn child_panel_timeout_isolates_without_killing_shared_worker() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);

    let res2 = Uuid::new_v4();
    let res3 = Uuid::new_v4();
    let (reply2, mut opened2) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: reply2,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open2_wire = wire.try_recv().unwrap();

    let (reply3, mut opened3) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 3,
                id: res3,
                revision: 1,
                read_only: false,
                request: request(),
                reply: reply3,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open3_wire = wire.try_recv().unwrap();

    let mut snap3 = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "panel-3".into(),
            root: Some(panel::Node::new(
                1,
                "panel-3",
                panel::node::Kind::Text(panel::Text {
                    text: "panel-3".into(),
                    tone: 0,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(3);
    snap3.in_reply_to = open3_wire.request_id;
    running.frame(snap3, &outgoing).await.unwrap();
    assert!(opened3.try_recv().unwrap().is_ok());
    while updates.try_recv().is_ok() {}

    // Expire panel 2's pending open: shared worker stays alive and panel 3 stays intact.
    running.requests.get_mut(&open2_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();

    let cancel2_wire = wire.try_recv().unwrap();
    assert_eq!(cancel2_wire.panel_id, 2);
    assert!(matches!(
        cancel2_wire.body,
        Some(envelope::Body::Cancel(ref c)) if c.request_id == open2_wire.request_id
    ));
    assert!(opened2.try_recv().unwrap().is_err());
    assert!(matches!(
        updates.try_recv().unwrap(),
        PluginEvent::Error { panel_id: 2, .. }
    ));
    assert!(running.panels.contains_key(&3));

    // Expire a Close on child panel 2: panel 2 slot is cleaned up (no zombie closing slot).
    let (rev2_tx, mut rev2_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: res2,
                remove_panel: true,
                reply: rev2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close2_wire = wire.try_recv().unwrap();
    running.requests.get_mut(&close2_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    assert!(
        wire.try_recv().is_err(),
        "timed-out CloseRequest(destroy_panel=true) must NOT emit trailing Cancel"
    );
    assert!(rev2_rx.try_recv().unwrap().is_err());
    assert!(
        matches!(
            running.panels.get(&2),
            Some(slot) if slot.closing && slot.destroy_failed && slot.state.is_none()
        ),
        "timed-out child destroy must keep a failed tombstone slot"
    );
    assert!(running.panels.contains_key(&3));

    // Expiring a main-panel operation still terminates the worker loop.
    let (main_tx, _main_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: main_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let main_wire = wire.try_recv().unwrap();
    running.requests.get_mut(&main_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    assert!(running.handle_timeouts(Instant::now(), &outgoing).await.is_err());
}

fn push_sleb_i64(mut v: i64, out: &mut Vec<u8>) {
    loop {
        let b = (v & 0x7f) as u8;
        v >>= 7;
        let done = (v == 0 && b & 0x40 == 0) || (v == -1 && b & 0x40 != 0);
        out.push(if done { b } else { b | 0x80 });
        if done {
            break;
        }
    }
}

fn push_sleb_i32(mut v: i32, out: &mut Vec<u8>) {
    loop {
        let b = (v & 0x7f) as u8;
        v >>= 7;
        let done = (v == 0 && b & 0x40 == 0) || (v == -1 && b & 0x40 != 0);
        out.push(if done { b } else { b | 0x80 });
        if done {
            break;
        }
    }
}

fn push_wasm_sec(id: u8, body: &[u8], out: &mut Vec<u8>) {
    fn uleb(mut n: usize, dst: &mut Vec<u8>) {
        loop {
            let mut b = (n & 0x7f) as u8;
            n >>= 7;
            if n != 0 {
                b |= 0x80;
            }
            dst.push(b);
            if n == 0 {
                break;
            }
        }
    }
    out.push(id);
    uleb(body.len(), out);
    out.extend_from_slice(body);
}

fn build_strict_v14_envelope_wasm(snapshot: PanelSnapshot) -> Vec<u8> {
    let reply_env = Envelope::new(
        ChannelIdentity {
            instance_id: Uuid::new_v4(),
            project: ProjectKey {
                id: Uuid::new_v4(),
                generation: 1,
            },
        },
        1,
        snapshot.revision,
        envelope::Body::Snapshot(snapshot),
        Duration::from_secs(5),
    )
    .with_minor(protocol::LEGACY_HANDSHAKE_MINOR)
    .encode_bytes();
    let reply_addr: i32 = 0x1800;
    let packed: i64 = ((i64::from(reply_addr)) << 32) | (reply_env.len() as i64);

    let mut wasm = vec![0, b'a', b's', b'm', 1, 0, 0, 0];
    // Types: 0=(i32)->i32 (mio_alloc), 1=(i32,i32)->i64 (mio_dispatch)
    push_wasm_sec(1, &[2, 0x60, 1, 0x7f, 1, 0x7f, 0x60, 2, 0x7f, 0x7f, 1, 0x7e], &mut wasm);
    push_wasm_sec(3, &[2, 0, 1], &mut wasm);
    push_wasm_sec(5, &[1, 1, 1, 16], &mut wasm);
    let mut exports = vec![3];
    exports.extend_from_slice(b"\x06memory\x02\x00");
    exports.extend_from_slice(b"\x09mio_alloc\x00\x00");
    exports.extend_from_slice(b"\x0cmio_dispatch\x00\x01");
    push_wasm_sec(7, &exports, &mut wasm);

    // f0: mio_alloc(_) -> 0x1000
    let mut f0 = vec![0u8, 0x41];
    push_sleb_i32(0x1000, &mut f0);
    f0.push(0x0b);

    // f1: mio_dispatch(ptr=0, len=1) -> traps unless envelope.minor <= 4
    let mut f1 = vec![0u8];
    f1.extend_from_slice(&[0x20, 1, 0x41, 4, 0x49, 0x04, 0x40, 0x00, 0x0b]); // if len < 4 trap
    f1.extend_from_slice(&[0x20, 0, 0x2d, 0x00, 2, 0x41, 0x10, 0x47, 0x04, 0x40, 0x00, 0x0b]); // if ptr[2] != 0x10 trap
    f1.extend_from_slice(&[0x20, 0, 0x2d, 0x00, 3, 0x41, 4, 0x4b, 0x04, 0x40, 0x00, 0x0b]); // if ptr[3] > 4 trap
    f1.push(0x42);
    push_sleb_i64(packed, &mut f1);
    f1.push(0x0b);

    let mut code = vec![2u8];
    for func in [&f0, &f1] {
        code.push(func.len() as u8);
        code.extend_from_slice(func);
    }
    push_wasm_sec(10, &code, &mut wasm);

    let mut data = vec![1u8, 0, 0x41];
    push_sleb_i32(reply_addr, &mut data);
    data.push(0x0b);
    data.push(reply_env.len() as u8);
    data.extend_from_slice(&reply_env);
    push_wasm_sec(11, &data, &mut wasm);
    wasm
}

#[tokio::test]
async fn v15_host_downgrades_and_gates_multiplexing_for_v14_worker_and_wasm_uses_v14_minor() {
    // 1. Real 1.5 host handshake against a strict v1.4 peer over duplex streams.
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.strict-v14-native".into(),
        version: "1.0.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![],
        contributions: vec!["suite_panel".into()],
    };
    let grants = BTreeSet::new();
    let (mut host_to_worker, mut worker_rx) = tokio::io::duplex(16 * 1024);
    let (mut worker_tx, mut worker_to_host) = tokio::io::duplex(16 * 1024);
    let manifest_worker = manifest.clone();
    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await.unwrap();
        assert_eq!(hello.minor, protocol::LEGACY_HANDSHAKE_MINOR);
        assert!(matches!(
            hello.body,
            Some(envelope::Body::Hello(ref h)) if h.host_minor == protocol::PROTOCOL_MINOR
        ));
        let mut reg = Envelope::new(
            identity,
            1,
            1,
            envelope::Body::Register(protocol::Register {
                plugin_id: manifest_worker.id,
                plugin_version: manifest_worker.version,
                required_components: vec![],
                panel: Some(PanelSnapshot {
                    revision: 1,
                    title: "v14".into(),
                    root: Some(panel::Node::new(
                        1,
                        "r",
                        panel::node::Kind::Text(panel::Text {
                            text: "v14".into(),
                            tone: 0,
                        }),
                    )),
                }),
                // Even if set, host must gate multiplexing off when negotiated minor == 4.
                supports_panel_multiplexing: true,
            }),
            MAX_OPERATION,
        )
        .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        reg.in_reply_to = hello.request_id;
        worker_tx.write_all(&protocol::encode_frame(&reg).unwrap()).await.unwrap();
        worker_tx.flush().await.unwrap();

        let ready = read_async_frame(&mut worker_rx).await.unwrap();
        assert_eq!(ready.minor, protocol::LEGACY_HANDSHAKE_MINOR);
        assert!(matches!(ready.body, Some(envelope::Body::Ready(_))));
    });
    let (_state, seq, multiplexing, minor) = super::supervisor::handshake_native(
        &mut host_to_worker,
        &mut worker_to_host,
        identity,
        &manifest,
        &grants,
    )
    .await
    .unwrap();
    worker_task.await.unwrap();
    assert_eq!(seq, 1);
    assert_eq!(minor, protocol::LEGACY_HANDSHAKE_MINOR);
    assert!(!multiplexing);

    // Verify downgraded Running rejects v1.5 frames and stamps v1.4 outbound frames.
    let (mut running, _calls, _updates) = running();
    running.protocol_minor = protocol::LEGACY_HANDSHAKE_MINOR;
    running.supports_panel_multiplexing = false;
    assert_eq!(
        running
            .envelope_for(protocol::PANEL_ID, envelope::Body::Ready(panel::Empty {}), 0)
            .unwrap()
            .minor,
        protocol::LEGACY_HANDSHAKE_MINOR
    );
    let (outgoing, _wire) = mpsc::channel(QUEUE_CAPACITY);
    let too_new = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "future minor")),
        MAX_OPERATION,
    )
    .with_minor(protocol::PROTOCOL_MINOR);
    assert!(running.frame(too_new, &outgoing).await.is_err());

    // 2. Real strict v1.4 WASM bytecode that traps on minor > 4 succeeds in both initial_wasm_panel and spawn_sandbox_worker!
    let custom_snap = PanelSnapshot {
        revision: 1,
        title: "ignored".into(),
        root: Some(panel::Node::new(
            77,
            "strict-v14-root",
            panel::node::Kind::Text(panel::Text {
                text: "strict-v14-ok".into(),
                tone: 0,
            }),
        )),
    };
    let strict_wasm = build_strict_v14_envelope_wasm(custom_snap);
    let wasm_module = wasm::WasmModule::parse(&strict_wasm).unwrap();
    assert!(wasm_module.is_envelope_abi());
    let wasm_manifest = PluginManifest {
        id: "lab.strict-wasm-v14".into(),
        version: "1.0.0".into(),
        api_version: 1,
        engine: "wasm".into(),
        entry: "plugin.wasm".into(),
        permissions: vec![],
        contributions: vec!["suite_panel".into()],
    };
    let panel = wasm::initial_wasm_panel(&wasm_manifest, &wasm_module, &grants).unwrap();
    assert_eq!(
        panel.root.as_ref().unwrap().accessibility_label,
        "strict-v14-root",
        "initial_wasm_panel must receive real WASM response rather than falling back due to v1.5 minor"
    );

    // Direct v1.5 envelope traps on the strict v1.4 WASM module.
    let mut vm_check = wasm::WasmInstance::new(wasm_module.clone()).unwrap();
    let tok = CancellationToken::new();
    let mut noop = |_: &[u8], _: &mut [u8], _: bool, _: &CancellationToken| Ok(0);
    let v15_env = Envelope::new(identity, 2, 1, envelope::Body::Resync(panel.clone()), MAX_OPERATION)
        .with_minor(protocol::PROTOCOL_MINOR);
    assert!(
        wasm::dispatch_wasm_envelope(&mut vm_check, &v15_env, wasm::WASM_CALL_FUEL, &tok, &mut noop)
            .is_err()
    );

    // Running + spawn_sandbox_worker sends v1.4 requests and emits v1.4 replies from the strict v1.4 WASM worker!
    let (writes_tx, writes_rx) = mpsc::channel(8);
    let (wire_tx, mut wire_rx) = mpsc::channel(8);
    let cancel_worker = CancellationToken::new();
    let worker_handle = wasm::spawn_sandbox_worker(
        identity,
        wasm_manifest.id,
        wasm_module,
        writes_rx,
        wire_tx,
        Arc::new(super::OutboundWriteClaims::default()),
        cancel_worker.clone(),
    );
    let v14_ev = Envelope::new(
        identity,
        2,
        1,
        envelope::Body::UiEvent(UiEvent {
            node_id: 1,
            event: None,
            editors: vec![],
        }),
        MAX_OPERATION,
    )
    .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
    writes_tx.send(v14_ev).await.unwrap();
    let Wire::Frame(wasm_reply) = wire_rx.recv().await.unwrap() else {
        panic!("expected Wire::Frame from strict v1.4 WASM worker");
    };
    assert_eq!(wasm_reply.minor, protocol::LEGACY_HANDSHAKE_MINOR);
    assert!(matches!(
        wasm_reply.body,
        Some(envelope::Body::Snapshot(ref s))
            if s.root.as_ref().is_some_and(|r| r.accessibility_label == "strict-v14-root")
    ));
    drop(writes_tx);
    cancel_worker.cancel();
    worker_handle.await.unwrap();
}

#[tokio::test]
async fn child_panel_expired_frame_queue_headroom_and_cancel_services() {
    let (mut running, mut calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY * 2);

    let res2 = Uuid::new_v4();
    let res3 = Uuid::new_v4();
    let (reply2, mut opened2) = oneshot::channel();
    let (reply3, mut opened3) = oneshot::channel();
    for (pid, res, rep) in [(2u64, res2, reply2), (3u64, res3, reply3)] {
        running
            .control(
                Control::Open {
                    panel_id: pid,
                    id: res,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: rep,
                },
                &outgoing,
            )
            .await
            .unwrap();
    }
    let open2_wire = wire.try_recv().unwrap();
    let open3_wire = wire.try_recv().unwrap();
    for (seq, pid, rid) in [(1u64, 2u64, open2_wire.request_id), (2u64, 3u64, open3_wire.request_id)] {
        let mut snap = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Snapshot(PanelSnapshot {
                revision: 1,
                title: format!("p-{pid}"),
                root: Some(panel::Node::new(
                    1,
                    "ed",
                    panel::node::Kind::Editor(panel::Editor {
                        document_id: 1,
                        revision: 1,
                        contents: b"ok".to_vec(),
                        format: panel::EditorFormat::Utf8 as i32,
                        read_only: false,
                    }),
                )),
            }),
            MAX_OPERATION,
        )
        .with_panel_id(pid);
        snap.in_reply_to = rid;
        running.frame(snap, &outgoing).await.unwrap();
    }
    assert!(opened2.try_recv().unwrap().is_ok());
    assert!(opened3.try_recv().unwrap().is_ok());
    while updates.try_recv().is_ok() {}

    // 1. Expired frame on child panel 2 does NOT kill shared worker and emits Deadline diagnostic.
    let mut expired_child_ev = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "late")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    expired_child_ev.deadline_unix_ms = 1;
    running.frame(expired_child_ev, &outgoing).await.unwrap();
    assert!(matches!(
        updates.try_recv().unwrap(),
        PluginEvent::Error {
            panel_id: 2,
            failure: Failure { code, .. },
            ..
        } if code == ErrorCode::Deadline as i32
    ));
    assert!(running.panels.contains_key(&3));

    // 2. Per-op cancellation isolation, synchronous service cancellation inheritance & late cancelled HostCall blocking.
    let commit_cancel = CancellationToken::new();
    let commit_op = Uuid::new_v4();
    let (commit_tx, mut commit_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: commit_op,
                request: CommitEditor {
                    resource_id: res2.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"ok".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: commit_cancel.clone(),
                reply: commit_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let commit_wire = wire.try_recv().unwrap();
    let hc = HostCall {
        operation: Some(host_call::Operation::UpdateDraft(protocol::DraftUpdate {
            resource_id: res2.as_bytes().to_vec(),
            expected_revision: 1,
            request: Some(request().into()),
        })),
        parent_request_id: commit_wire.request_id,
    };
    let hc_env = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::HostCall(hc.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.host_call(&hc_env, hc.clone(), &outgoing).await.unwrap();
    let svc_req = calls.try_recv().unwrap();
    assert!(!svc_req.cancel.is_cancelled());

    // Cancelling commit_cancel immediately cancels inherited UpdateDraft service token synchronously!
    commit_cancel.cancel();
    assert!(
        svc_req.cancel.is_cancelled(),
        "derived service token must inherit commit cancellation immediately"
    );

    // CancelPanelOp removes commit_wire and records its request_id in cancelled_requests.
    running
        .control(
            Control::CancelPanelOp {
                panel_id: 2,
                op_id: commit_op,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(commit_rx.try_recv().unwrap().is_err());
    while wire.try_recv().is_ok() {}

    // A NEW commit on the SAME panel 2 is NOT cancelled by a delayed CancelPanelOp for the old op_id!
    let commit2_op = Uuid::new_v4();
    let (commit2_tx, mut commit2_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: commit2_op,
                request: CommitEditor {
                    resource_id: res2.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"ok".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: commit2_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let _commit2_wire = wire.try_recv().unwrap();
    running
        .control(
            Control::CancelPanelOp {
                panel_id: 2,
                op_id: commit_op,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(
        commit2_rx.try_recv().is_err(),
        "stale CancelPanelOp for old op_id must not cancel new commit on the same panel"
    );

    // Late HostCall referencing the cancelled parent_request_id is STILL blocked after Pending removal!
    let hc_late = Envelope::new(
        running.identity,
        5,
        1,
        envelope::Body::HostCall(hc.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.host_call(&hc_late, hc, &outgoing).await.unwrap();
    let denied = wire.try_recv().unwrap();
    assert_eq!(denied.in_reply_to, 5);
    assert!(matches!(
        denied.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
        })) if code == ErrorCode::Cancelled as i32
    ));

    // 3. Soft limit (CHILD_QUEUE_SOFT_LIMIT = 96) rejects extra child opens and child resync non-fatally while reserving
    // headroom for main panel events and child CloseRequest.
    let mut held_replies = Vec::new();
    for i in 0..CHILD_QUEUE_SOFT_LIMIT {
        let (tx, rx) = oneshot::channel();
        held_replies.push(rx);
        running
            .control(
                Control::Commit {
                    panel_id: 3,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res3.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"ok".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let _ = i;
        while wire.try_recv().is_ok() {}
    }
    while updates.try_recv().is_ok() {}
    running
        .resync_panel(2, &outgoing, 0, "busy resync".into())
        .await
        .expect("child resync at soft limit must degrade safely without killing shared worker");
    assert!(matches!(
        updates.try_recv().unwrap(),
        PluginEvent::Error { panel_id: 2, .. }
    ));
    let (busy_tx, mut busy_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 4,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: busy_tx,
            },
            &outgoing,
        )
        .await
        .expect("child open hitting soft limit must not fail worker loop");
    assert!(busy_rx.try_recv().unwrap().is_err());

    let (main_tx, _main_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: main_tx,
            },
            &outgoing,
        )
        .await
        .expect("main panel open must retain queue headroom above child soft limit");
    let main_open_wire = wire.try_recv().unwrap();
    assert_eq!(main_open_wire.panel_id, protocol::PANEL_ID);

    let (rev3_tx, _rev3_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 3,
                id: res3,
                remove_panel: true,
                reply: rev3_tx,
            },
            &outgoing,
        )
        .await
        .expect("child CloseRequest must retain queue headroom above child soft limit");
    let mut saw_close3 = false;
    while let Ok(frame) = wire.try_recv() {
        assert_eq!(frame.panel_id, 3);
        match frame.body {
            Some(envelope::Body::CloseRequest(_)) => {
                saw_close3 = true;
                break;
            }
            Some(envelope::Body::Cancel(_)) => {}
            other => panic!("unexpected frame during panel 3 revoke: {other:?}"),
        }
    }
    assert!(saw_close3, "expected CloseRequest on panel 3");
}

#[tokio::test]
async fn pending_destroy_queues_under_full_requests_and_flushes_on_recovery() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res2 = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_wire = wire.try_recv().unwrap();
    let mut open_reply = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p2".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"init".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_reply.in_reply_to = open_wire.request_id;
    running.frame(open_reply, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    // Fill all QUEUE_CAPACITY request slots on main panel (e.g. 128 pending UI events).
    for _ in 0..QUEUE_CAPACITY {
        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    event: panel::UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    expected_snapshot: None,
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
    }
    while wire.try_recv().is_ok() {}
    assert_eq!(running.requests.len(), QUEUE_CAPACITY);

    // Revoking panel 2 with remove_panel=true while requests == QUEUE_CAPACITY MUST queue pending_destroy instead of dropping it!
    let (rev_tx, mut rev_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: res2,
                remove_panel: true,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.pending_revokes.len(), 1);
    assert!(matches!(running.panels.get(&2), Some(slot) if slot.closing && !slot.destroy_failed));
    assert!(matches!(
        rev_rx.try_recv(),
        Err(oneshot::error::TryRecvError::Empty)
    ));
    assert!(wire.try_recv().is_err());

    // A second concurrent revoke coalesces onto the queued pending_revoke.
    let (rev_dup_tx, mut rev_dup_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: res2,
                remove_panel: true,
                reply: rev_dup_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.pending_revokes.len(), 1);
    assert!(matches!(
        rev_dup_rx.try_recv(),
        Err(oneshot::error::TryRecvError::Empty)
    ));

    // Completing one main request frees capacity and automatically flushes CloseRequest(destroy_panel=true).
    let one_main_req = *running.requests.keys().next().unwrap();
    let mut main_ack =
        Envelope::new(running.identity, 2, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    main_ack.in_reply_to = one_main_req;
    running.frame(main_ack, &outgoing).await.unwrap();
    assert!(running.pending_revokes.is_empty());

    let destroy_wire = wire.try_recv().unwrap();
    assert_eq!(destroy_wire.panel_id, 2);
    assert!(matches!(
        destroy_wire.body,
        Some(envelope::Body::CloseRequest(ref c)) if c.destroy_panel
    ));
    assert!(matches!(
        rev_rx.try_recv(),
        Err(oneshot::error::TryRecvError::Empty)
    ));

    let mut close_ack =
        Envelope::new(running.identity, 3, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    close_ack.in_reply_to = destroy_wire.request_id;
    running.frame(close_ack, &outgoing).await.unwrap();
    assert!(rev_rx.try_recv().unwrap().is_ok());
    assert!(rev_dup_rx.try_recv().unwrap().is_ok());
    assert!(!running.panels.contains_key(&2));
    running.requests.clear();

    // Also verify rejected CloseRequest(destroy_panel=true) keeps tombstone & rejects follow-up revokes.
    let res3 = Uuid::new_v4();
    let (open3_tx, open3_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 3,
                id: res3,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open3_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open3_wire = wire.try_recv().unwrap();
    let mut open3_reply = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p3".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"p3".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(3);
    open3_reply.in_reply_to = open3_wire.request_id;
    running.frame(open3_reply, &outgoing).await.unwrap();
    assert!(open3_rx.await.is_ok());
    while updates.try_recv().is_ok() {}

    let (rev3_tx, mut rev3_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 3,
                id: res3,
                remove_panel: true,
                reply: rev3_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let destroy3_wire = wire.try_recv().unwrap();
    let mut close3_err = Envelope::new(
        running.identity,
        5,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "refused close")),
        MAX_OPERATION,
    )
    .with_panel_id(3);
    close3_err.in_reply_to = destroy3_wire.request_id;
    running.frame(close3_err, &outgoing).await.unwrap();
    assert!(rev3_rx.try_recv().unwrap().is_err());
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Error { panel_id: 3, .. })
    ));
    assert!(matches!(
        running.panels.get(&3),
        Some(slot) if slot.closing && slot.destroy_failed && slot.state.is_none()
    ));

    let (rev3_again_tx, mut rev3_again_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 3,
                id: res3,
                remove_panel: true,
                reply: rev3_again_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(rev3_again_rx.try_recv().unwrap().is_err());
}

#[tokio::test]
async fn host_call_validates_parent_clamps_deadline_and_expired_reply_cancels_derived_service() {
    let (mut running, mut calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);
    let res2 = Uuid::new_v4();
    let res3 = Uuid::new_v4();

    for (panel_id, seq, res) in [(2u64, 1u64, res2), (3u64, 2u64, res3)] {
        let (tx, rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id,
                    id: res,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ow = wire.try_recv().unwrap();
        let mut snap = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Snapshot(PanelSnapshot {
                revision: 1,
                title: format!("p-{panel_id}"),
                root: Some(panel::Node::new(
                    1,
                    "ed",
                    panel::node::Kind::Editor(panel::Editor {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        format: panel::EditorFormat::Utf8 as i32,
                        read_only: false,
                    }),
                )),
            }),
            MAX_OPERATION,
        )
        .with_panel_id(panel_id);
        snap.in_reply_to = ow.request_id;
        running.frame(snap, &outgoing).await.unwrap();
        assert!(rx.await.is_ok());
    }

    // 1. Unknown non-zero parent_request_id MUST be rejected with Stale (never reaches `calls`).
    let hc_unknown = HostCall {
        operation: Some(host_call::Operation::UpdateDraft(protocol::DraftUpdate {
            resource_id: res2.as_bytes().to_vec(),
            expected_revision: 1,
            request: Some(request().into()),
        })),
        parent_request_id: 9999,
    };
    let env_unknown = Envelope::new(
        running.identity,
        10,
        1,
        envelope::Body::HostCall(hc_unknown.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.host_call(&env_unknown, hc_unknown, &outgoing).await.unwrap();
    assert!(calls.try_recv().is_err());
    let err_unknown = wire.try_recv().unwrap();
    assert!(matches!(
        err_unknown.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
        })) if code == ErrorCode::Stale as i32
    ));

    // 2. Active Commit on panel 2 cannot authorize HostCall on panel 3 (cross-panel parent_request_id rejected).
    let (c2_tx, mut c2_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: res2.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: c2_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let c2_wire = wire.try_recv().unwrap();
    let parent_deadline = Instant::now() + Duration::from_millis(120);
    running.requests.get_mut(&c2_wire.request_id).unwrap().deadline = parent_deadline;

    let hc_cross = HostCall {
        operation: Some(host_call::Operation::UpdateDraft(protocol::DraftUpdate {
            resource_id: res3.as_bytes().to_vec(),
            expected_revision: 1,
            request: Some(request().into()),
        })),
        parent_request_id: c2_wire.request_id,
    };
    let env_cross = Envelope::new(
        running.identity,
        11,
        1,
        envelope::Body::HostCall(hc_cross.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(3);
    running.host_call(&env_cross, hc_cross, &outgoing).await.unwrap();
    assert!(calls.try_recv().is_err());
    let err_cross = wire.try_recv().unwrap();
    assert!(matches!(
        err_cross.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
        })) if code == ErrorCode::Stale as i32
    ));

    // 3. Valid same-panel parent clamps ServiceRequest.deadline to parent.deadline (NOT full 5s).
    let hc_ok = HostCall {
        operation: Some(host_call::Operation::UpdateDraft(protocol::DraftUpdate {
            resource_id: res2.as_bytes().to_vec(),
            expected_revision: 1,
            request: Some(request().into()),
        })),
        parent_request_id: c2_wire.request_id,
    };
    let env_ok = Envelope::new(
        running.identity,
        12,
        1,
        envelope::Body::HostCall(hc_ok.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.host_call(&env_ok, hc_ok.clone(), &outgoing).await.unwrap();
    let svc_req = calls.try_recv().unwrap();
    assert!(
        svc_req.deadline <= parent_deadline,
        "derived service deadline must be clamped by parent deadline"
    );

    // 4. An expired reply arriving at io::frame MUST centrally record cancelled parent + cancel in-flight derived service.
    while updates.try_recv().is_ok() {}
    let mut expired_reply = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    expired_reply.deadline_unix_ms = 1;
    expired_reply.in_reply_to = c2_wire.request_id;
    running.frame(expired_reply, &outgoing).await.unwrap();
    assert!(c2_rx.try_recv().unwrap().is_err());
    assert!(
        svc_req.cancel.is_cancelled(),
        "expired reply rejecting parent MUST cancel in-flight derived service"
    );

    // Subsequent late HostCall referencing that parent_request_id is rejected as Cancelled.
    let env_after = Envelope::new(
        running.identity,
        13,
        1,
        envelope::Body::HostCall(hc_ok.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.host_call(&env_after, hc_ok, &outgoing).await.unwrap();
    assert!(calls.try_recv().is_err());
    let mut saw_cancelled = false;
    while let Ok(msg) = wire.try_recv() {
        if msg.in_reply_to == 13 {
            saw_cancelled = matches!(
                msg.body,
                Some(envelope::Body::HostResult(HostResult {
                    outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
                })) if code == ErrorCode::Cancelled as i32
            );
        }
    }
    assert!(saw_cancelled);

    // 5. Parent past deadline blocks new derived HostCall IMMEDIATELY even before handle_timeouts runs.
    let (c3_tx, mut c3_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 3,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: res3.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: c3_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let c3_wire = wire.try_recv().unwrap();
    running.requests.get_mut(&c3_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_millis(5);
    let hc_expired_parent = HostCall {
        operation: Some(host_call::Operation::UpdateDraft(protocol::DraftUpdate {
            resource_id: res3.as_bytes().to_vec(),
            expected_revision: 1,
            request: Some(request().into()),
        })),
        parent_request_id: c3_wire.request_id,
    };
    let env_expired_parent = Envelope::new(
        running.identity,
        14,
        1,
        envelope::Body::HostCall(hc_expired_parent.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(3);
    running
        .host_call(&env_expired_parent, hc_expired_parent, &outgoing)
        .await
        .unwrap();
    assert!(calls.try_recv().is_err());
    assert!(c3_rx.try_recv().unwrap().is_err());
    let mut saw_deadline = false;
    while let Ok(msg) = wire.try_recv() {
        if msg.in_reply_to == 14 {
            saw_deadline = matches!(
                msg.body,
                Some(envelope::Body::HostResult(HostResult {
                    outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
                })) if code == ErrorCode::Deadline as i32
            );
        }
    }
    assert!(saw_deadline);
}

#[tokio::test]
async fn outbound_queue_absorbs_backpressure_fifo_and_detects_closed_pipe() {
    let (mut running, _calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(1);

    // Fill the 1-slot outgoing channel.
    let first_id = running
        .send_on_panel(
            &outgoing,
            protocol::PANEL_ID,
            envelope::Body::Ack(panel::Empty {}),
            1,
        )
        .unwrap();
    // Next complete_service and send_on_panel hit TrySendError::Full -> buffered in outbound_queue without error!
    running
        .complete_service(
            ServiceCompletion {
                request_id: 20,
                panel_id: protocol::PANEL_ID,
                resource_binding: None,
                result: Ok(ServiceResult::Done),
            },
            &outgoing,
        )
        .expect("backpressure during complete_service must buffer rather than kill worker");
    let third_id = running
        .send_on_panel(
            &outgoing,
            protocol::PANEL_ID,
            envelope::Body::Cancel(protocol::Cancel { request_id: 21 }),
            0,
        )
        .unwrap();
    assert_eq!(running.outbound_queue.len(), 2);

    // Drain channel and flush outbound_queue -> strict FIFO order preserved.
    let mut received = Vec::new();
    while let Ok(env) = wire.try_recv() {
        received.push(env);
        running.flush_outbound_nonblocking(&outgoing).unwrap();
    }
    assert!(running.outbound_queue.is_empty());
    assert_eq!(received.len(), 3);
    assert_eq!(received[0].request_id, first_id);
    assert_eq!(received[1].in_reply_to, 20);
    assert_eq!(received[2].request_id, third_id);
    assert!(received[0].request_id < received[1].request_id && received[1].request_id < received[2].request_id);

    // Dropping receiver closes pipe -> next send MUST report pipe closure Err.
    drop(wire);
    let err = running
        .send_on_panel(
            &outgoing,
            protocol::PANEL_ID,
            envelope::Body::Ack(panel::Empty {}),
            2,
        )
        .unwrap_err();
    assert!(err.to_string().contains("关闭"));
}

#[tokio::test]
async fn overload_fails_hook_non_fatally_and_defers_extra_resource_revoke() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    running.broker.grants.insert(Permission::TrafficRead);
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let res2 = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_wire = wire.try_recv().unwrap();
    let mut snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p2".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"init".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    snap.in_reply_to = open_wire.request_id;
    running.frame(snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    // Fill all QUEUE_CAPACITY slots on main panel (e.g. mixed workload hitting 128).
    for _ in 0..QUEUE_CAPACITY {
        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    event: panel::UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    expected_snapshot: None,
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
    }
    while wire.try_recv().is_ok() {}
    assert_eq!(running.requests.len(), QUEUE_CAPACITY);

    // 1. Hook arriving at capacity limit MUST fail only the hook reply, returning Ok(()) to keep worker alive!
    let (hook_tx, mut hook_rx) = oneshot::channel();
    running
        .control(
            Control::Hook {
                permission: Permission::TrafficRead,
                body: envelope::Body::HttpHookCall(protocol::HttpHookCall {
                    source: protocol::SourceDto::Repeater as i32,
                    flow_id: Uuid::new_v4().as_bytes().to_vec(),
                    plugin_id: String::new(),
                    response_stage: false,
                    response_head_only: false,
                    request: Some(request().into()),
                    response: None,
                }),
                cancelled: CancellationToken::new(),
                reply: hook_tx,
            },
            &outgoing,
        )
        .await
        .expect("main hook overload must not terminate shared worker");
    assert!(hook_rx.try_recv().unwrap().is_err());

    // 2. Non-panel extra-resource Revoke (remove_panel=false) at saturation defers into pending_revokes.
    let extra_res = Uuid::new_v4();
    let (rev_tx, mut rev_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: extra_res,
                remove_panel: false,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.pending_revokes.len(), 1);
    assert!(matches!(
        rev_rx.try_recv(),
        Err(oneshot::error::TryRecvError::Empty)
    ));
    assert!(wire.try_recv().is_err());

    // Free one slot -> deferred resource CloseRequest(destroy_panel=false) flushes automatically & resolves Ok(()).
    let one_main_req = *running.requests.keys().next().unwrap();
    let mut main_ack =
        Envelope::new(running.identity, 2, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    main_ack.in_reply_to = one_main_req;
    running.frame(main_ack, &outgoing).await.unwrap();
    assert!(running.pending_revokes.is_empty());

    let close_wire = wire.try_recv().unwrap();
    assert_eq!(close_wire.panel_id, 2);
    assert!(matches!(
        close_wire.body,
        Some(envelope::Body::CloseRequest(ref c)) if !c.destroy_panel
    ));
    let mut close_ack =
        Envelope::new(running.identity, 3, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    close_ack.in_reply_to = close_wire.request_id;
    running.frame(close_ack, &outgoing).await.unwrap();
    assert!(rev_rx.try_recv().unwrap().is_ok());
}

#[tokio::test]
async fn late_verified_destroy_ack_reclaims_tombstone_and_emits_panel_closed() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    for (panel_id, seq) in [(2u64, 1u64), (3u64, 2u64)] {
        let res = Uuid::new_v4();
        let (tx, rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id,
                    id: res,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ow = wire.try_recv().unwrap();
        let mut snap = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Snapshot(PanelSnapshot {
                revision: 1,
                title: format!("p-{panel_id}"),
                root: Some(panel::Node::new(
                    1,
                    "ed",
                    panel::node::Kind::Editor(panel::Editor {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        format: panel::EditorFormat::Utf8 as i32,
                        read_only: false,
                    }),
                )),
            }),
            MAX_OPERATION,
        )
        .with_panel_id(panel_id);
        snap.in_reply_to = ow.request_id;
        running.frame(snap, &outgoing).await.unwrap();
        assert!(rx.await.is_ok());
    }
    while updates.try_recv().is_ok() {}

    // 1. Panel 2 destroy times out -> tombstone keeps destroy_request_id.
    let (rev2_tx, mut rev2_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: Uuid::new_v4(),
                remove_panel: true,
                reply: rev2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close2_wire = wire.try_recv().unwrap();
    running.requests.get_mut(&close2_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    assert!(
        wire.try_recv().is_err(),
        "timed-out CloseRequest(destroy_panel=true) must NOT emit trailing Cancel"
    );
    assert!(rev2_rx.try_recv().unwrap().is_err());
    assert_eq!(
        running.panels.get(&2).unwrap().destroy_request_id,
        Some(close2_wire.request_id)
    );
    while updates.try_recv().is_ok() {}

    // Late verified Ack (even expired) reclaims panel 2 tombstone & emits PluginEvent::PanelClosed!
    let mut late_ack2 =
        Envelope::new(running.identity, 3, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    late_ack2.in_reply_to = close2_wire.request_id;
    late_ack2.deadline_unix_ms = 1;
    running.frame(late_ack2, &outgoing).await.unwrap();
    assert!(!running.panels.contains_key(&2));
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::PanelClosed { panel_id: 2, .. })
    ));

    // 2. Panel 3 destroy explicitly rejected by worker Error -> clears destroy_request_id so wrong Ack cannot reclaim it!
    let (rev3_tx, mut rev3_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 3,
                id: Uuid::new_v4(),
                remove_panel: true,
                reply: rev3_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close3_wire = wire.try_recv().unwrap();
    let mut err3 = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "destroy refused")),
        MAX_OPERATION,
    )
    .with_panel_id(3);
    err3.in_reply_to = close3_wire.request_id;
    running.frame(err3, &outgoing).await.unwrap();
    assert!(rev3_rx.try_recv().unwrap().is_err());
    assert_eq!(running.panels.get(&3).unwrap().destroy_request_id, None);
    while updates.try_recv().is_ok() {}

    let mut bogus_ack3 =
        Envelope::new(running.identity, 5, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(3);
    bogus_ack3.in_reply_to = close3_wire.request_id;
    running.frame(bogus_ack3, &outgoing).await.unwrap();
    assert!(running.panels.contains_key(&3));
}

#[tokio::test]
async fn on_cancel_cleanup_host_call_allows_safe_ops_clamps_deadline_and_blocks_mutations() {
    let (mut running, mut calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    running.broker.grants.insert(Permission::RepeaterOpen);
    running.broker.grants.insert(Permission::TrafficModify);
    let (outgoing, mut wire) = mpsc::channel(QUEUE_CAPACITY);
    let res2 = Uuid::new_v4();

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p2".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"init".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    snap.in_reply_to = ow.request_id;
    running.frame(snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    let commit_op = Uuid::new_v4();
    let (c_tx, _c_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: commit_op,
                request: CommitEditor {
                    resource_id: res2.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: c_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let _commit_wire = wire.try_recv().unwrap();

    // Cancel Commit -> host emits Cancel frame whose request_id is recorded in cancel_notifications.
    running
        .control(
            Control::CancelPanelOp {
                panel_id: 2,
                op_id: commit_op,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let cancel_wire = wire.try_recv().unwrap();
    assert!(matches!(cancel_wire.body, Some(envelope::Body::Cancel(_))));
    let expected_cancel_deadline = running.cancel_notifications.back().unwrap().deadline;

    // 1. Safe allowlisted cleanup calls (`QueryHistory`, `ScopeCheck`) succeed and clamp deadline.
    for op in [
        host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        }),
        host_call::Operation::ScopeCheck("https://example.invalid/".into()),
    ] {
        let hc_safe = HostCall {
            operation: Some(op),
            parent_request_id: cancel_wire.request_id,
        };
        let env_safe = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::HostCall(hc_safe.clone()),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        running.host_call(&env_safe, hc_safe, &outgoing).await.unwrap();
        let req_safe = calls.try_recv().unwrap();
        assert!(req_safe.deadline <= expected_cancel_deadline);
    }

    // 2. Non-allowlisted mutating calls (`UpdateDraft`, `OpenRepeater`, `ScopeUpdate`, `OpenOrganiser`)
    // are ALL rejected with ErrorCode::Cancelled even when granted!
    for op in [
        host_call::Operation::UpdateDraft(protocol::DraftUpdate {
            resource_id: res2.as_bytes().to_vec(),
            expected_revision: 1,
            request: Some(request().into()),
        }),
        host_call::Operation::OpenRepeater(request().into()),
        host_call::Operation::ScopeUpdate(protocol::ScopeUpdateDto {
            url_prefix: "https://example.invalid/".into(),
            exclude: false,
            include_subdomains: true,
        }),
        host_call::Operation::OpenOrganiser(protocol::OpenOrganiserDto {
            request: Some(request().into()),
            response: None,
            notes: "cancel-attempt".into(),
            highlight_color: None,
        }),
    ] {
        let hc_mut = HostCall {
            operation: Some(op),
            parent_request_id: cancel_wire.request_id,
        };
        let env_mut = Envelope::new(
            running.identity,
            3,
            1,
            envelope::Body::HostCall(hc_mut.clone()),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        running.host_call(&env_mut, hc_mut, &outgoing).await.unwrap();
        assert!(calls.try_recv().is_err());
        let reply = wire.try_recv().unwrap();
        assert!(matches!(
            reply.body,
            Some(envelope::Body::HostResult(HostResult {
                outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
            })) if code == ErrorCode::Cancelled as i32
        ));
    }

    // 3. Past cancel window -> even QueryHistory is rejected with Deadline!
    running.cancel_notifications.back_mut().unwrap().deadline =
        Instant::now() - Duration::from_millis(5);
    let hc_late = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: cancel_wire.request_id,
    };
    let env_late = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::HostCall(hc_late.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.host_call(&env_late, hc_late, &outgoing).await.unwrap();
    assert!(calls.try_recv().is_err());
    let late_reply = wire.try_recv().unwrap();
    assert!(matches!(
        late_reply.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
        })) if code == ErrorCode::Deadline as i32
    ));

    // 4. Sending Ack(in_reply_to: cancel_wire.request_id) immediately terminates the cancel window -> Stale!
    running.cancel_notifications.back_mut().unwrap().deadline = Instant::now() + MAX_OPERATION;
    let mut cancel_ack =
        Envelope::new(running.identity, 2, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    cancel_ack.in_reply_to = cancel_wire.request_id;
    running.frame(cancel_ack, &outgoing).await.unwrap();
    assert!(running.cancel_notifications.is_empty());

    let hc_after_ack = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: cancel_wire.request_id,
    };
    let env_after_ack = Envelope::new(
        running.identity,
        5,
        1,
        envelope::Body::HostCall(hc_after_ack.clone()),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running
        .host_call(&env_after_ack, hc_after_ack, &outgoing)
        .await
        .unwrap();
    assert!(calls.try_recv().is_err());
    let after_ack_reply = wire.try_recv().unwrap();
    assert!(matches!(
        after_ack_reply.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
        })) if code == ErrorCode::Stale as i32
    ));
}

#[tokio::test]
async fn resync_retries_boundedly_on_deadline_error_and_clears_only_on_valid_ack() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res2 = Uuid::new_v4();

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p2".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"init".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    snap.in_reply_to = ow.request_id;
    running.frame(snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    // 1. Schedule Resync -> emits Resync #1 while retaining resync_needed_seq.
    running.schedule_panel_resync(2);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync1 = wire.try_recv().unwrap();
    assert!(matches!(resync1.body, Some(envelope::Body::Resync(_))));
    assert_eq!(running.panels[&2].resync_attempts, 1);
    assert_ne!(running.panels[&2].resync_needed_seq, 0);

    // 2. Worker replies Deadline Error -> host MUST retain need & retry Resync #2 immediately!
    let mut deadline_err = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Deadline, "queued resync expired")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    deadline_err.in_reply_to = resync1.request_id;
    running.frame(deadline_err, &outgoing).await.unwrap();
    let resync2 = wire.try_recv().unwrap();
    assert!(matches!(resync2.body, Some(envelope::Body::Resync(_))));
    assert_eq!(running.panels[&2].resync_attempts, 2);

    // 3. Worker replies Ack for Resync #2 -> resync_needed_seq clears to 0!
    let mut ack2 =
        Envelope::new(running.identity, 3, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    ack2.in_reply_to = resync2.request_id;
    running.frame(ack2, &outgoing).await.unwrap();
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    assert_eq!(running.panels[&2].resync_attempts, 0);
    assert!(wire.try_recv().is_err());

    // 4. Exhaust MAX_RESYNC_RETRIES (3) via repeated Deadline errors -> stops cleanly without infinite loop!
    while updates.try_recv().is_ok() {}
    running.schedule_panel_resync(2);
    running.flush_pending_resyncs(&outgoing).unwrap();
    for seq in 4..=(3 + u64::from(MAX_RESYNC_RETRIES)) {
        let r = wire.try_recv().unwrap();
        assert!(matches!(r.body, Some(envelope::Body::Resync(_))));
        let mut err = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "expired")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        err.in_reply_to = r.request_id;
        running.frame(err, &outgoing).await.unwrap();
    }
    assert!(
        wire.try_recv().is_err(),
        "resync retries must stop after MAX_RESYNC_RETRIES"
    );
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Error { panel_id: 2, .. })
    ));
}

#[tokio::test]
async fn oversized_multi_editor_ui_event_and_oversized_resync_fail_panel_only() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    // Build main panel with 4 editable 256 KiB editors + 1 commit button.
    let big_editor_bytes = vec![b'a'; panel::MAX_EDITOR_BYTES];
    let mut main_children = Vec::new();
    let mut editor_snaps = Vec::new();
    for doc_id in 1..=4u64 {
        main_children.push(panel::Node::new(
            doc_id,
            format!("ed-{doc_id}"),
            panel::node::Kind::Editor(panel::Editor {
                document_id: doc_id,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        ));
        editor_snaps.push(EditorSnapshot {
            document_id: doc_id,
            revision: 2,
            contents: big_editor_bytes.clone(),
            ..Default::default()
        });
    }
    main_children.push(panel::Node::new(
        10,
        "commit-btn",
        panel::node::Kind::Button(panel::Button {
            label: "Go".into(),
            enabled: true,
            commit_editors: true,
        }),
    ));
    running.panel = PanelState::new(PanelSnapshot {
        revision: 1,
        title: "multi-big".into(),
        root: Some(panel::Node::new(
            99,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: main_children,
            }),
        )),
    })
    .unwrap();

    // 1. Multi-editor UiEvent > 1 MiB MUST emit single-panel Error without killing worker OR mutating state!
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: panel::UiEvent {
                    node_id: 10,
                    editors: editor_snaps,
                    event: Some(panel::ui_event::Event::Click(panel::Empty {})),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .expect("oversized multi-editor UiEvent must NOT kill worker");
    assert!(wire.try_recv().is_err());
    assert_eq!(running.panel.editor(1).unwrap().revision, 1);
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Error {
            panel_id: protocol::PANEL_ID,
            ..
        })
    ));

    // 2. Child panel accumulates 5 x 220 KiB editors via valid patches (> 1 MiB full snapshot):
    // automatic Resync must emit single-panel Error and clear retry without killing shared worker!
    let res2 = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let child_children: Vec<_> = (1..=5u64)
        .map(|doc_id| {
            panel::Node::new(
                doc_id,
                format!("c-{doc_id}"),
                panel::node::Kind::Editor(panel::Editor {
                    document_id: doc_id,
                    revision: 1,
                    contents: vec![b'x'; 160 * 1024],
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )
        })
        .collect();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "child-grow".into(),
            root: Some(panel::Node::new(
                99,
                "col",
                panel::node::Kind::Column(panel::Container {
                    children: child_children,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    for (idx, doc_id) in (1..=5u64).enumerate() {
        let rev = idx as u64 + 2;
        let patch_env = Envelope::new(
            running.identity,
            rev,
            rev,
            envelope::Body::Patch(panel::PanelPatch {
                base_revision: rev - 1,
                revision: rev,
                operations: vec![panel::PatchOperation {
                    node_id: doc_id,
                    change: Some(panel::patch_operation::Change::Editor(panel::EditorUpdate {
                        base_revision: 1,
                        snapshot: Some(EditorSnapshot {
                            document_id: doc_id,
                            revision: 2,
                            contents: vec![b'y'; 230 * 1024],
                            ..Default::default()
                        }),
                    })),
                }],
            }),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        running.frame(patch_env, &outgoing).await.unwrap();
    }
    while updates.try_recv().is_ok() {}

    // Now full PanelSnapshot on child panel 2 is > 1 MiB: resync_panel and flush_pending_resyncs fail panel-only!
    running
        .resync_panel(2, &outgoing, 0, "stale patch".into())
        .await
        .expect("oversized resync must not terminate shared worker");
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    assert!(wire.try_recv().is_err());
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Error { panel_id: 2, .. })
    ));
}

#[tokio::test]
async fn resync_repeated_invalid_snapshot_respects_retry_budget_and_never_loops() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res2 = Uuid::new_v4();

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let child_root = || {
        Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        ))
    };
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p2".into(),
            root: child_root(),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    // Advance child panel 2 locally to rev=2 so Snapshot(rev=1) will be rejected by PanelState::replace.
    let mut rev2_snap = Envelope::new(
        running.identity,
        2,
        2,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 2,
            title: "p2-rev2".into(),
            root: child_root(),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    rev2_snap.in_reply_to = 0;
    running.frame(rev2_snap, &outgoing).await.unwrap();
    while updates.try_recv().is_ok() {}

    // 1. Rejection starts ONE recovery cycle and emits Resync #1 (`resync_attempts == 1`).
    running
        .resync_panel(2, &outgoing, 0, "initial mismatch".into())
        .await
        .unwrap();
    let resync1 = wire.try_recv().unwrap();
    assert!(matches!(resync1.body, Some(envelope::Body::Resync(_))));
    assert_eq!(running.panels[&2].resync_attempts, 1);
    let seq = running.panels[&2].resync_needed_seq;
    assert_ne!(seq, 0);

    // 2. While Resync #1 is in flight, an unrelated late Snapshot arrives -> must NOT open a new generation or emit duplicate Resync!
    let mut late_unrelated = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "late-stale".into(),
            root: child_root(),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    late_unrelated.in_reply_to = 9999;
    running.frame(late_unrelated, &outgoing).await.unwrap();
    assert!(wire.try_recv().is_err());
    assert_eq!(running.panels[&2].resync_needed_seq, seq);
    assert_eq!(running.panels[&2].resync_attempts, 1);

    // 3. Repeatedly rejecting Resync responses with stale rev=1 Snapshot advances within the SAME budget up to MAX_RESYNC_RETRIES (3).
    let mut current_resync_id = resync1.request_id;
    let mut wire_seq = 4u64;
    for expected_next_attempt in 2..=MAX_RESYNC_RETRIES {
        let mut bad_reply = Envelope::new(
            running.identity,
            wire_seq,
            1,
            envelope::Body::Snapshot(PanelSnapshot {
                revision: 1,
                title: "still-stale".into(),
                root: child_root(),
            }),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        bad_reply.in_reply_to = current_resync_id;
        wire_seq += 1;
        running.frame(bad_reply, &outgoing).await.unwrap();
        let next_resync = wire.try_recv().unwrap();
        assert!(matches!(next_resync.body, Some(envelope::Body::Resync(_))));
        assert_eq!(running.panels[&2].resync_needed_seq, seq);
        assert_eq!(running.panels[&2].resync_attempts, expected_next_attempt);
        current_resync_id = next_resync.request_id;
    }

    // Rejecting the 3rd Resync hits MAX_RESYNC_RETRIES -> stops retrying cleanly and leaves wire empty!
    let mut final_bad = Envelope::new(
        running.identity,
        wire_seq,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "still-stale-final".into(),
            root: child_root(),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    final_bad.in_reply_to = current_resync_id;
    running.frame(final_bad, &outgoing).await.unwrap();
    assert!(
        wire.try_recv().is_err(),
        "repeated rejected resync snapshots must halt at MAX_RESYNC_RETRIES"
    );
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
}

#[tokio::test]
async fn fresh_wire_snapshot_after_local_pending_deadline_recovers_child_without_killing_worker() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res2 = Uuid::new_v4();

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p2-base".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"base".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    running
        .control(
            Control::Event {
                panel_id: 2,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ev_wire = wire.try_recv().unwrap();

    // Expire local Pending.deadline BEFORE handle_timeouts runs, while worker reply carries a FRESH wire deadline!
    running.requests.get_mut(&ev_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_millis(10);
    while updates.try_recv().is_ok() {}

    let mut fresh_wire_late_snap = Envelope::new(
        running.identity,
        2,
        2,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 2,
            title: "p2-mutated-late".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 2,
                    contents: b"stale".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    fresh_wire_late_snap.in_reply_to = ev_wire.request_id;
    running
        .frame(fresh_wire_late_snap, &outgoing)
        .await
        .expect("fresh-wire reply after local Pending deadline must recover child instead of failing loop");

    assert_eq!(
        running.panel_revision(2),
        1,
        "expired local Pending MUST prevent Snapshot(rev=2) from mutating host panel state"
    );
    let cancel_msg = wire.try_recv().unwrap();
    let resync_msg = wire.try_recv().unwrap();
    assert!(matches!(cancel_msg.body, Some(envelope::Body::Cancel(_))));
    assert!(matches!(resync_msg.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Error { panel_id: 2, .. })
    ));
}

#[tokio::test]
async fn legacy_cancel_snapshot_reply_closes_window_and_resyncs_main_panel() {
    let (mut running, mut calls, mut updates) = running();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res1 = Uuid::new_v4();

    let (open_tx, _open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: res1,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let _open_wire = wire.try_recv().unwrap();

    // Revoke main panel resource while Open is active -> host sends Cancel and tracks it in cancel_notifications.
    let (rev_tx, _rev_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: protocol::PANEL_ID,
                id: res1,
                remove_panel: false,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let cancel_wire = wire.try_recv().unwrap();
    let _close_wire = wire.try_recv().unwrap();
    assert!(matches!(cancel_wire.body, Some(envelope::Body::Cancel(_))));
    assert_eq!(running.cancel_notifications.len(), 1);
    while updates.try_recv().is_ok() {}

    // Legacy plugin replies to Cancel with a drifted Snapshot(rev=2) -> consumes silently & triggers Resync(1)!
    let mut legacy_snap = Envelope::new(
        running.identity,
        1,
        2,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 2,
            title: "legacy-cancel-snap".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"legacy".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    );
    legacy_snap.in_reply_to = cancel_wire.request_id;
    running.frame(legacy_snap, &outgoing).await.unwrap();

    assert!(running.cancel_notifications.is_empty());
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 1);
    assert!(
        updates.try_recv().is_err(),
        "legacy Cancel Snapshot reply must not emit spurious Stale diagnostic"
    );
    let resync_msg = wire.try_recv().unwrap();
    assert_eq!(resync_msg.panel_id, protocol::PANEL_ID);
    assert!(matches!(resync_msg.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));

    // After Cancel reply window closed, HostCall referencing cancel_wire.request_id is rejected as Stale.
    let hc_after = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: cancel_wire.request_id,
    };
    let env_after = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::HostCall(hc_after.clone()),
        MAX_OPERATION,
    );
    running.host_call(&env_after, hc_after, &outgoing).await.unwrap();
    assert!(calls.try_recv().is_err());
    let stale_reply = wire.try_recv().unwrap();
    assert!(matches!(
        stale_reply.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
        })) if code == ErrorCode::Stale as i32
    ));
}

#[tokio::test]
async fn late_resync_snapshot_after_budget_exhausted_does_not_restart_cycle() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res2 = Uuid::new_v4();

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let child_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("p2-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(child_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    // Exhaust 7 recovery cycles (21 Resync attempts > 16) on the SAME child panel 2.
    let mut sent_resync_ids = Vec::new();
    for _cycle in 0..7 {
        running.schedule_panel_resync(2);
        running.flush_pending_resyncs(&outgoing).unwrap();
        for _ in 0..MAX_RESYNC_RETRIES {
            let r = wire.try_recv().unwrap();
            assert!(matches!(r.body, Some(envelope::Body::Resync(_))));
            sent_resync_ids.push(r.request_id);
            running.requests.get_mut(&r.request_id).unwrap().deadline =
                Instant::now() - Duration::from_secs(1);
            running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
            let cancel_msg = wire.try_recv().unwrap();
            assert!(matches!(cancel_msg.body, Some(envelope::Body::Cancel(_))));
        }
        assert_eq!(running.panels[&2].resync_needed_seq, 0);
        assert!(wire.try_recv().is_err());
    }
    assert!(sent_resync_ids.len() > 16);
    while updates.try_recv().is_ok() {}

    // Late Snapshots replying to ANY of the 21 exhausted Resync request_ids (including the earliest) MUST NOT restart recovery!
    let mut seq = 2u64;
    for old_resync_id in sent_resync_ids {
        let mut late_resync_snap = Envelope::new(
            running.identity,
            seq,
            2,
            envelope::Body::Snapshot(child_snap(2)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        seq += 1;
        late_resync_snap.in_reply_to = old_resync_id;
        running.frame(late_resync_snap, &outgoing).await.unwrap();
        assert!(
            wire.try_recv().is_err(),
            "late reply to exhausted Resync cycle must not re-trigger Resync even after >16 same-panel resyncs"
        );
        assert_eq!(running.panels[&2].resync_needed_seq, 0);
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id: 2, .. })
        ));
    }

    // An unknown/unassociated request_id is also dropped without starting Resync.
    let mut unknown_late = Envelope::new(
        running.identity,
        seq,
        2,
        envelope::Body::Snapshot(child_snap(2)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    unknown_late.in_reply_to = 9999;
    running.frame(unknown_late, &outgoing).await.unwrap();
    assert!(wire.try_recv().is_err());
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    assert!(running.panels[&2].resync_semantic_drift);
    while updates.try_recv().is_ok() {}

    // By contrast, a genuinely cancelled non-resync child UiEvent STILL triggers a fresh Resync once on its first late Snapshot.
    let (mut running, _calls, _updates) = super::tests_runtime::running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(child_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());
    let mut seq = 2u64;

    running
        .control(
            Control::Event {
                panel_id: 2,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ui_req = wire.try_recv().unwrap();
    running.requests.get_mut(&ui_req.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    let _ui_cancel = wire.try_recv().unwrap();
    let initial_ui_resync = wire.try_recv().unwrap();
    assert!(matches!(initial_ui_resync.body, Some(envelope::Body::Resync(_))));
    let mut resync_ack =
        Envelope::new(running.identity, seq, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    seq += 1;
    resync_ack.in_reply_to = initial_ui_resync.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    while wire.try_recv().is_ok() {}

    let mut late_ui_snap = Envelope::new(
        running.identity,
        seq,
        2,
        envelope::Body::Snapshot(child_snap(2)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    seq += 1;
    late_ui_snap.in_reply_to = ui_req.request_id;
    running.frame(late_ui_snap, &outgoing).await.unwrap();
    let fresh_resync = wire.try_recv().unwrap();
    assert!(matches!(fresh_resync.body, Some(envelope::Body::Resync(_))));
    let mut resync_ack2 =
        Envelope::new(running.identity, seq, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    seq += 1;
    resync_ack2.in_reply_to = fresh_resync.request_id;
    running.frame(resync_ack2, &outgoing).await.unwrap();

    // Replaying the same cancelled UiEvent id a second time must NOT re-trigger Resync.
    let mut replay_ui_snap = Envelope::new(
        running.identity,
        seq,
        2,
        envelope::Body::Snapshot(child_snap(2)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    replay_ui_snap.in_reply_to = ui_req.request_id;
    running.frame(replay_ui_snap, &outgoing).await.unwrap();
    assert!(wire.try_recv().is_err());
}

#[tokio::test]
async fn main_panel_resync_timeout_retries_boundedly_without_killing_worker() {
    let (mut running, _calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    running.schedule_panel_resync(protocol::PANEL_ID);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync1 = wire.try_recv().unwrap();
    assert!(matches!(resync1.body, Some(envelope::Body::Resync(_))));
    assert_eq!(running.main_resync_attempts, 1);

    // 1. Natural timeout on main-panel Resync #1 MUST NOT kill worker -> emits Cancel + Resync #2!
    running.requests.get_mut(&resync1.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running
        .handle_timeouts(Instant::now(), &outgoing)
        .await
        .expect("main-panel Resync timeout must retry boundedly without terminating worker");
    let cancel1 = wire.try_recv().unwrap();
    let resync2 = wire.try_recv().unwrap();
    assert!(matches!(cancel1.body, Some(envelope::Body::Cancel(_))));
    assert!(matches!(resync2.body, Some(envelope::Body::Resync(_))));
    assert_eq!(running.main_resync_attempts, 2);

    // 2. Wire-expired reply to main-panel Resync #2 (even with fresh local deadline) ALSO retries boundedly without killing worker!
    let mut wire_expired_resync2_snap = Envelope::new(
        running.identity,
        1,
        2,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 2,
            title: "wire-expired-resync2".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 2,
                    contents: b"late".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    );
    wire_expired_resync2_snap.deadline_unix_ms = 1;
    wire_expired_resync2_snap.in_reply_to = resync2.request_id;
    running
        .frame(wire_expired_resync2_snap, &outgoing)
        .await
        .expect("wire-expired main-panel Resync Snapshot must not terminate worker");
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 1);
    let cancel2 = wire.try_recv().unwrap();
    let resync3 = wire.try_recv().unwrap();
    assert!(matches!(cancel2.body, Some(envelope::Body::Cancel(_))));
    assert!(matches!(resync3.body, Some(envelope::Body::Resync(_))));
    assert_eq!(running.main_resync_attempts, 3);

    // 3. Local-expired + fresh-wire Snapshot replying to main-panel Resync #3 stops cleanly at MAX_RESYNC_RETRIES without killing worker!
    running.requests.get_mut(&resync3.request_id).unwrap().deadline =
        Instant::now() - Duration::from_millis(5);
    let mut local_expired_resync3_snap = Envelope::new(
        running.identity,
        2,
        2,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 2,
            title: "local-expired-resync3".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 2,
                    contents: b"late".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    );
    local_expired_resync3_snap.in_reply_to = resync3.request_id;
    running.frame(local_expired_resync3_snap, &outgoing).await.unwrap();
    let cancel3 = wire.try_recv().unwrap();
    assert!(matches!(cancel3.body, Some(envelope::Body::Cancel(_))));
    assert!(wire.try_recv().is_err());
    assert_eq!(running.main_resync_needed_seq, 0);
    assert!(running.main_resync_semantic_drift);

    // 4. Ordinary main-panel UiEvent timeout still terminates the worker loop.
    let (mut running, _calls, mut updates) = super::tests_runtime::running();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ev_wire = wire.try_recv().unwrap();
    running.requests.get_mut(&ev_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    assert!(running.handle_timeouts(Instant::now(), &outgoing).await.is_err());
    let _ = updates.try_recv();
}

#[tokio::test]
async fn main_panel_local_expired_non_resync_matches_fatal_timeout_policy_and_drifted_host_call_resyncs()
{
    // 1. Main-panel drifted HostCall (revision=2 > host_rev=1) schedules main-panel Resync(1)!
    {
        let (mut running, _calls, _updates) = running();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let hc_drifted = HostCall {
            operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
                offset: 0,
                limit: 1,
                filter: String::new(),
            })),
            parent_request_id: 0,
        };
        let env_drifted = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::HostCall(hc_drifted),
            MAX_OPERATION,
        );
        running.frame(env_drifted, &outgoing).await.unwrap();
        let main_hc_resync = wire.try_recv().unwrap();
        assert!(matches!(
            main_hc_resync.body,
            Some(envelope::Body::Resync(ref s)) if s.revision == 1
        ));
        let mut ack_hc_resync = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        );
        ack_hc_resync.in_reply_to = main_hc_resync.request_id;
        running.frame(ack_hc_resync, &outgoing).await.unwrap();
        assert!(running.main_resync_semantic_drift);
    }

    let (mut running, _calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res1 = Uuid::new_v4();

    // 2. Main-panel Open expires locally before timer -> Snapshot rejected with fatal timeout policy without mutating panel!
    let (open_tx, mut open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: res1,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    running.requests.get_mut(&ow.request_id).unwrap().deadline =
        Instant::now() - Duration::from_millis(5);
    let mut late_open_snap = Envelope::new(
        running.identity,
        3,
        2,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 2,
            title: "late-open-main".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 2,
                    contents: b"stale".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    );
    late_open_snap.in_reply_to = ow.request_id;
    let err_open = running.frame(late_open_snap, &outgoing).await.unwrap_err();
    assert!(err_open.to_string().contains("超时"));
    assert!(open_rx.try_recv().unwrap().is_err());
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 1);
    while wire.try_recv().is_ok() {}

    // 3. Main-panel Close expires locally before timer -> fresh-wire Ack triggers fatal timeout instead of Ok(())!
    let (rev_tx, mut rev_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: protocol::PANEL_ID,
                id: res1,
                remove_panel: false,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close_wire = wire.try_recv().unwrap();
    running.requests.get_mut(&close_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_millis(5);
    let mut late_close_ack =
        Envelope::new(running.identity, 4, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    late_close_ack.in_reply_to = close_wire.request_id;
    let err_close = running.frame(late_close_ack, &outgoing).await.unwrap_err();
    assert!(err_close.to_string().contains("超时"));
    assert!(rev_rx.try_recv().unwrap().is_err());
    while wire.try_recv().is_ok() {}

    // 4. Main-panel non-resync UiEvent expires locally before timer -> fresh-wire Ack triggers fatal timeout Err!
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ev_wire = wire.try_recv().unwrap();
    running.requests.get_mut(&ev_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_millis(5);
    let mut late_ev_ack =
        Envelope::new(running.identity, 5, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    late_ev_ack.in_reply_to = ev_wire.request_id;
    let err_ev = running.frame(late_ev_ack, &outgoing).await.unwrap_err();
    assert!(err_ev.to_string().contains("超时"));
}

#[tokio::test]
async fn legacy_resync_ack_with_unreverted_revision_marks_incompatible_and_stops_resync_loop() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res2 = Uuid::new_v4();

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(PanelSnapshot {
            revision: 1,
            title: "p2".into(),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"init".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    running.schedule_panel_resync(2);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync_wire = wire.try_recv().unwrap();
    while updates.try_recv().is_ok() {}

    // Legacy v1.4 peer kept local published=2 after Resync(1) and echoes revision=2 on Ack!
    let mut unreverted_ack =
        Envelope::new(running.identity, 2, 2, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    unreverted_ack.in_reply_to = resync_wire.request_id;
    running.frame(unreverted_ack, &outgoing).await.unwrap();

    assert!(running.panels[&2].resync_incompatible);
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Error { panel_id: 2, ref failure, .. })
            if failure.message.contains("重载或升级插件")
    ));

    // Subsequent drifted HostCall (rev=2) is rejected as Stale and MUST NOT loop sending Resync(1)!
    let hc = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: 0,
    };
    let hc_env = Envelope::new(running.identity, 3, 2, envelope::Body::HostCall(hc), MAX_OPERATION)
        .with_panel_id(2);
    running.frame(hc_env, &outgoing).await.unwrap();
    let stale = wire.try_recv().unwrap();
    assert!(matches!(stale.body, Some(envelope::Body::HostResult(_))));
    assert!(
        wire.try_recv().is_err(),
        "incompatible panel must not loop emitting Resync on subsequent stale HostCalls"
    );

    // Also verify an actual negotiated v1.4 main-panel session marks main_resync_incompatible and stops looping!
    let (mut v14_running, _v14_calls, mut v14_updates) = super::tests_runtime::running();
    v14_running.protocol_minor = protocol::LEGACY_HANDSHAKE_MINOR;
    v14_running.supports_panel_multiplexing = false;
    let (v14_out, mut v14_wire) = mpsc::channel(OUTGOING_CAPACITY);
    v14_running.schedule_panel_resync(protocol::PANEL_ID);
    v14_running.flush_pending_resyncs(&v14_out).unwrap();
    let v14_resync = v14_wire.try_recv().unwrap();
    assert_eq!(v14_resync.minor, protocol::LEGACY_HANDSHAKE_MINOR);
    while v14_updates.try_recv().is_ok() {}

    let mut v14_ack = Envelope::new(
        v14_running.identity,
        1,
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
    v14_ack.in_reply_to = v14_resync.request_id;
    v14_running.frame(v14_ack, &v14_out).await.unwrap();
    assert!(v14_running.main_resync_incompatible);
    assert_eq!(v14_running.main_resync_needed_seq, 0);
    assert!(matches!(
        v14_updates.try_recv(),
        Ok(PluginEvent::Error { panel_id, ref failure, .. })
            if panel_id == protocol::PANEL_ID && failure.message.contains("重载或升级插件")
    ));

    let v14_hc = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: 0,
    };
    let v14_hc_env = Envelope::new(
        v14_running.identity,
        2,
        2,
        envelope::Body::HostCall(v14_hc),
        MAX_OPERATION,
    )
    .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
    v14_running.frame(v14_hc_env, &v14_out).await.unwrap();
    let v14_stale = v14_wire.try_recv().unwrap();
    assert!(matches!(v14_stale.body, Some(envelope::Body::HostResult(_))));
    assert!(
        v14_wire.try_recv().is_err(),
        "v1.4 main panel must not loop emitting Resync once marked incompatible"
    );
}

#[tokio::test]
async fn interleaved_resync_ack_matching_sent_baseline_resyncs_latest_without_marking_incompatible() {
    let (mut running, mut calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("rev-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: rev,
                contents: format!("body-{rev}").into_bytes(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // 1. Child panel: Open at rev=1, enqueue UiEvent, then enqueue Resync(1) before Snapshot(2) returns.
    let res2 = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    running
        .control(
            Control::Event {
                panel_id: 2,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let child_ev = wire.try_recv().unwrap();
    running.schedule_panel_resync(2);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let child_resync1 = wire.try_recv().unwrap();
    let child_seq = running.panels[&2].resync_needed_seq;
    assert_ne!(child_seq, 0);
    assert!(matches!(
        child_resync1.body,
        Some(envelope::Body::Resync(ref s)) if s.revision == 1
    ));

    // Earlier in-flight UiEvent advances host child panel from rev 1 -> rev 2.
    let mut child_snap2 = Envelope::new(
        running.identity,
        2,
        2,
        envelope::Body::Snapshot(snap(2)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    child_snap2.in_reply_to = child_ev.request_id;
    running.frame(child_snap2, &outgoing).await.unwrap();
    assert_eq!(running.panel_revision(2), 2);
    while updates.try_recv().is_ok() {}

    // SDK processed Resync(1), reverted published=1, and replies Ack(1) matching resync_revision=1!
    let mut child_ack1 = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    child_ack1.in_reply_to = child_resync1.request_id;
    running.frame(child_ack1, &outgoing).await.unwrap();

    assert!(
        !running.panels[&2].resync_incompatible,
        "valid Ack matching sent resync_revision=1 must NOT mark panel incompatible"
    );
    assert!(updates.try_recv().is_err());
    assert_eq!(running.panels[&2].resync_needed_seq, child_seq);
    assert_eq!(running.panels[&2].resync_attempts, 2);
    let child_resync2 = wire.try_recv().unwrap();
    assert!(matches!(
        child_resync2.body,
        Some(envelope::Body::Resync(ref s)) if s.revision == 2
    ));

    let mut child_ack2 = Envelope::new(
        running.identity,
        4,
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    child_ack2.in_reply_to = child_resync2.request_id;
    running.frame(child_ack2, &outgoing).await.unwrap();
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    assert_eq!(running.panels[&2].resync_attempts, 0);

    let child_hc = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: 0,
    };
    running
        .frame(
            Envelope::new(
                running.identity,
                5,
                2,
                envelope::Body::HostCall(child_hc),
                MAX_OPERATION,
            )
            .with_panel_id(2),
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(calls.try_recv().unwrap().panel_id, 2);

    // 2. Main panel: same interleaving of in-flight UiEvent + Resync(1) -> Snapshot(2) -> Ack(1) -> Resync(2) -> Ack(2).
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let main_ev = wire.try_recv().unwrap();
    running.schedule_panel_resync(protocol::PANEL_ID);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let main_resync1 = wire.try_recv().unwrap();
    let main_seq = running.main_resync_needed_seq;
    assert_ne!(main_seq, 0);
    assert!(matches!(
        main_resync1.body,
        Some(envelope::Body::Resync(ref s)) if s.revision == 1
    ));

    let mut main_snap2 = Envelope::new(
        running.identity,
        6,
        2,
        envelope::Body::Snapshot(snap(2)),
        MAX_OPERATION,
    );
    main_snap2.in_reply_to = main_ev.request_id;
    running.frame(main_snap2, &outgoing).await.unwrap();
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 2);
    while updates.try_recv().is_ok() {}

    let mut main_ack1 = Envelope::new(
        running.identity,
        7,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    main_ack1.in_reply_to = main_resync1.request_id;
    running.frame(main_ack1, &outgoing).await.unwrap();

    assert!(!running.main_resync_incompatible);
    assert!(updates.try_recv().is_err());
    assert_eq!(running.main_resync_needed_seq, main_seq);
    assert_eq!(running.main_resync_attempts, 2);
    let main_resync2 = wire.try_recv().unwrap();
    assert!(matches!(
        main_resync2.body,
        Some(envelope::Body::Resync(ref s)) if s.revision == 2
    ));

    let mut main_ack2 = Envelope::new(
        running.identity,
        8,
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    main_ack2.in_reply_to = main_resync2.request_id;
    running.frame(main_ack2, &outgoing).await.unwrap();
    assert_eq!(running.main_resync_needed_seq, 0);
    assert_eq!(running.main_resync_attempts, 0);

    let main_hc = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: 0,
    };
    running
        .frame(
            Envelope::new(
                running.identity,
                9,
                2,
                envelope::Body::HostCall(main_hc),
                MAX_OPERATION,
            ),
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(calls.try_recv().unwrap().panel_id, protocol::PANEL_ID);
}

#[tokio::test]
async fn final_resync_cancel_snapshot_reply_does_not_restart_exhausted_budget() {
    let (mut running, mut calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res2 = Uuid::new_v4();

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("rev-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    let mut wire_in_seq = 2u64;
    for target_panel in [2u64, protocol::PANEL_ID] {
        running.schedule_panel_resync(target_panel);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let mut last_cancel_id = 0u64;
        for _ in 0..MAX_RESYNC_RETRIES {
            let resync = wire.try_recv().unwrap();
            assert_eq!(resync.panel_id, target_panel);
            assert!(matches!(resync.body, Some(envelope::Body::Resync(_))));
            running.requests.get_mut(&resync.request_id).unwrap().deadline =
                Instant::now() - Duration::from_secs(1);
            running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
            let cancel_msg = wire.try_recv().unwrap();
            assert!(matches!(cancel_msg.body, Some(envelope::Body::Cancel(_))));
            last_cancel_id = cancel_msg.request_id;
        }
        assert!(wire.try_recv().is_err());
        while updates.try_recv().is_ok() {}
        assert_ne!(last_cancel_id, 0);
        assert!(
            running
                .cancel_notifications
                .iter()
                .any(|n| n.panel_id == target_panel
                    && n.cancel_frame_id == last_cancel_id
                    && !n.can_restart_resync)
        );

        // 1. Active window: allowlisted on_cancel cleanup HostCall referencing final Resync's Cancel with drifted rev MUST NOT restart Resync.
        let hc = HostCall {
            operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
                offset: 0,
                limit: 1,
                filter: String::new(),
            })),
            parent_request_id: last_cancel_id,
        };
        running
            .frame(
                Envelope::new(
                    running.identity,
                    wire_in_seq,
                    2,
                    envelope::Body::HostCall(hc.clone()),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel),
                &outgoing,
            )
            .await
            .unwrap();
        wire_in_seq += 1;
        assert_eq!(calls.try_recv().unwrap().panel_id, target_panel);
        assert!(wire.try_recv().is_err());

        // 2. Expired window: drifted HostCall arriving after Cancel notification's 5s window expires is rejected WITHOUT restarting Resync!
        running
            .cancel_notifications
            .iter_mut()
            .rev()
            .find(|n| n.panel_id == target_panel && n.cancel_frame_id == last_cancel_id)
            .unwrap()
            .deadline = Instant::now() - Duration::from_millis(5);
        running
            .frame(
                Envelope::new(
                    running.identity,
                    wire_in_seq,
                    2,
                    envelope::Body::HostCall(hc.clone()),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel),
                &outgoing,
            )
            .await
            .unwrap();
        wire_in_seq += 1;
        assert!(calls.try_recv().is_err());
        assert!(matches!(
            wire.try_recv().unwrap().body,
            Some(envelope::Body::HostResult(HostResult {
                outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
            })) if code == ErrorCode::Stale as i32
        ));
        assert!(wire.try_recv().is_err());

        // 3. Evicted notification: even if capacity evicts a Cancel notification before a drifted HostCall arrives, unknown parent CANNOT restart Resync!
        let evicted_cancel_id = 800_000 + target_panel;
        running.record_cancel_notification(target_panel, evicted_cancel_id, true, None);
        for offset in 1..=QUEUE_CAPACITY {
            running.record_cancel_notification(
                target_panel,
                evicted_cancel_id + offset as u64,
                false,
                None,
            );
        }
        assert!(
            !running
                .cancel_notifications
                .iter()
                .any(|n| n.panel_id == target_panel && n.cancel_frame_id == evicted_cancel_id)
        );
        running
            .frame(
                Envelope::new(
                    running.identity,
                    wire_in_seq,
                    2,
                    envelope::Body::HostCall(HostCall {
                        operation: hc.operation.clone(),
                        parent_request_id: evicted_cancel_id,
                    }),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel),
                &outgoing,
            )
            .await
            .unwrap();
        wire_in_seq += 1;
        assert!(calls.try_recv().is_err());
        assert!(matches!(
            wire.try_recv().unwrap().body,
            Some(envelope::Body::HostResult(HostResult {
                outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
            })) if code == ErrorCode::Stale as i32
        ));
        assert!(wire.try_recv().is_err());
        while updates.try_recv().is_ok() {}
        running.cancel_notifications.clear();
        running.record_cancel_notification(target_panel, last_cancel_id, true, None);

        // 4. Legacy Cancel reply Snapshot(rev=2) on the final Resync's Cancel settles window without restarting Resync!
        let mut legacy_cancel_snap = Envelope::new(
            running.identity,
            wire_in_seq,
            2,
            envelope::Body::Snapshot(make_snap(2)),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        wire_in_seq += 1;
        legacy_cancel_snap.in_reply_to = last_cancel_id;
        running.frame(legacy_cancel_snap, &outgoing).await.unwrap();

        assert!(
            !running
                .cancel_notifications
                .iter()
                .any(|n| n.panel_id == target_panel && n.cancel_frame_id == last_cancel_id)
        );
        assert!(wire.try_recv().is_err());
        assert!(updates.try_recv().is_err());
        assert_eq!(running.panel_revision(target_panel), 1);
        if target_panel == protocol::PANEL_ID {
            assert_eq!(running.main_resync_needed_seq, 0);
        } else {
            assert_eq!(running.panels[&target_panel].resync_needed_seq, 0);
        }
    }
}

#[tokio::test]
async fn v14_session_resync_timeout_degrades_without_stacking_expired_frames_on_real_duplex_transport() {
    // Part A: Immediate unit verification across timeout/wire-expired/Error paths on v1.4 session.
    {
        let (mut running, _calls, mut updates) = running();
        running.protocol_minor = protocol::LEGACY_HANDSHAKE_MINOR;
        running.supports_panel_multiplexing = false;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync1 = wire.try_recv().unwrap();
        assert_eq!(resync1.minor, protocol::LEGACY_HANDSHAKE_MINOR);

        running.requests.get_mut(&resync1.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        assert!(
            wire.try_recv().is_err(),
            "v1.4 Resync timeout must NOT send Cancel or retry Resync onto pipe"
        );
        assert!(running.main_resync_incompatible);
        assert_eq!(running.main_resync_needed_seq, 0);
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == protocol::PANEL_ID
                    && failure.code == ErrorCode::Deadline as i32
                    && failure.message.contains("v1.4")
                    && failure.message.contains("重载或升级插件")
        ));

        // Reset flag and verify wire-expired Resync reply also degrades without stacking frames.
        running.clear_panel_resync_incompatible(protocol::PANEL_ID);
        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync2 = wire.try_recv().unwrap();
        let mut wire_exp = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        wire_exp.deadline_unix_ms = 1;
        wire_exp.in_reply_to = resync2.request_id;
        running.frame(wire_exp, &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(running.main_resync_incompatible);
        assert_eq!(running.main_resync_needed_seq, 0);

        // Reset flag and verify Error(Deadline) on v1.4 Resync degrades with explicit reload diagnostic + original cause.
        running.clear_panel_resync_incompatible(protocol::PANEL_ID);
        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync3 = wire.try_recv().unwrap();
        while updates.try_recv().is_ok() {}
        let mut err_deadline = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "v1.4 deadline")),
            MAX_OPERATION,
        )
        .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        err_deadline.in_reply_to = resync3.request_id;
        running.frame(err_deadline, &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(running.main_resync_incompatible);
        assert_eq!(running.main_resync_needed_seq, 0);
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == protocol::PANEL_ID
                    && failure.code == ErrorCode::Deadline as i32
                    && failure.message.contains("v1.4")
                    && failure.message.contains("已停止自动重同步")
                    && failure.message.contains("重载或升级插件")
                    && failure.message.contains("v1.4 deadline")
        ));

        // Reset flag and verify BOTH wire-expired AND local-expired Error(Deadline) preserve original plugin reason!
        running.clear_panel_resync_incompatible(protocol::PANEL_ID);
        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync4 = wire.try_recv().unwrap();
        while updates.try_recv().is_ok() {}
        let mut wire_exp_err = Envelope::new(
            running.identity,
            3,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "v1.4 wire expired cause")),
            MAX_OPERATION,
        )
        .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        wire_exp_err.deadline_unix_ms = 1;
        wire_exp_err.in_reply_to = resync4.request_id;
        running.frame(wire_exp_err, &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(running.main_resync_incompatible);
        assert_eq!(running.main_resync_needed_seq, 0);
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == protocol::PANEL_ID
                    && failure.code == ErrorCode::Deadline as i32
                    && failure.message.contains("v1.4")
                    && failure.message.contains("已停止自动重同步")
                    && failure.message.contains("重载或升级插件")
                    && failure.message.contains("v1.4 wire expired cause")
        ));

        running.clear_panel_resync_incompatible(protocol::PANEL_ID);
        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync5 = wire.try_recv().unwrap();
        while updates.try_recv().is_ok() {}
        running.requests.get_mut(&resync5.request_id).unwrap().deadline =
            Instant::now() - Duration::from_millis(5);
        let mut local_exp_err = Envelope::new(
            running.identity,
            4,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "v1.4 local expired cause")),
            MAX_OPERATION,
        )
        .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        local_exp_err.in_reply_to = resync5.request_id;
        running.frame(local_exp_err, &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(running.main_resync_incompatible);
        assert_eq!(running.main_resync_needed_seq, 0);
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == protocol::PANEL_ID
                    && failure.code == ErrorCode::Deadline as i32
                    && failure.message.contains("v1.4")
                    && failure.message.contains("已停止自动重同步")
                    && failure.message.contains("重载或升级插件")
                    && failure.message.contains("v1.4 local expired cause")
        ));

        // Timer-first: handle_timeouts removes pending v1.4 Resync FIRST, then late Error(Deadline) still preserves original cause once!
        running.clear_panel_resync_incompatible(protocol::PANEL_ID);
        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync6 = wire.try_recv().unwrap();
        while updates.try_recv().is_ok() {}
        running.requests.get_mut(&resync6.request_id).unwrap().deadline =
            Instant::now() - Duration::from_millis(5);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(running.main_resync_incompatible);
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == protocol::PANEL_ID
                    && failure.code == ErrorCode::Deadline as i32
                    && failure.message.contains("v1.4")
        ));
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::PanelSynced { panel_id, .. }) if panel_id == protocol::PANEL_ID
        ));

        let mut timer_first_late_err = Envelope::new(
            running.identity,
            5,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "v1.4 timer-first cause")),
            MAX_OPERATION,
        )
        .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        timer_first_late_err.in_reply_to = resync6.request_id;
        running.frame(timer_first_late_err, &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == protocol::PANEL_ID
                    && failure.code == ErrorCode::Deadline as i32
                    && failure.message.contains("v1.4")
                    && failure.message.contains("已停止自动重同步")
                    && failure.message.contains("重载或升级插件")
                    && failure.message.contains("v1.4 timer-first cause")
        ));

        // Replaying the same resync6 id falls back to generic Stale (one-shot correlation consumed).
        let mut replay_late_err = Envelope::new(
            running.identity,
            6,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "v1.4 timer-first replay")),
            MAX_OPERATION,
        )
        .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        replay_late_err.in_reply_to = resync6.request_id;
        running.frame(replay_late_err, &outgoing).await.unwrap();
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == protocol::PANEL_ID && failure.code == ErrorCode::Stale as i32
        ));
    }

    // Part B: Real duplex transport test enforcing exact v1.4 WorkerSession::receive deadline checking!
    async fn v14_receive(
        rx: &mut tokio::io::DuplexStream,
        identity: ChannelIdentity,
        incoming_seq: &mut u64,
    ) -> Result<Envelope> {
        let env = read_async_frame(rx).await?;
        // Exact v1.4 WorkerSession::receive semantic: fails immediately if deadline_unix_ms <= unix_ms().
        env.check_channel(identity, *incoming_seq)
            .map_err(anyhow::Error::msg)?;
        *incoming_seq = env.request_id;
        Ok(env)
    }

    async fn v14_send(
        tx: &mut tokio::io::DuplexStream,
        identity: ChannelIdentity,
        outgoing_seq: &mut u64,
        rev: u64,
        in_reply_to: u64,
        body: envelope::Body,
    ) -> Result<()> {
        *outgoing_seq += 1;
        let mut env = Envelope::new(identity, *outgoing_seq, rev, body, MAX_OPERATION)
            .with_minor(protocol::LEGACY_HANDSHAKE_MINOR);
        env.in_reply_to = in_reply_to;
        tx.write_all(&protocol::encode_frame(&env)?).await?;
        tx.flush().await?;
        Ok(())
    }

    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.v14-duplex-resync".into(),
        version: "1.0.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![],
        contributions: vec!["suite_panel".into()],
    };
    let make_panel = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: rev,
                contents: label.as_bytes().to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let (host_to_worker, mut worker_rx) = tokio::io::duplex(32 * 1024);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(32 * 1024);
    let resync_seen = Arc::new(tokio::sync::Notify::new());
    let resync_seen_worker = resync_seen.clone();
    let resync_done = Arc::new(tokio::sync::Notify::new());
    let resync_done_worker = resync_done.clone();

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        ensure!(hello.minor == protocol::LEGACY_HANDSHAKE_MINOR);
        let mut outgoing_seq = 0u64;
        v14_send(
            &mut worker_tx,
            identity,
            &mut outgoing_seq,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.v14-duplex-resync".into(),
                plugin_version: "1.0.0".into(),
                required_components: vec![],
                panel: Some(make_panel(1, "init")),
                supports_panel_multiplexing: false,
            }),
        )
        .await?;

        let mut incoming_seq = hello.request_id;
        let ready = v14_receive(&mut worker_rx, identity, &mut incoming_seq).await?;
        ensure!(matches!(ready.body, Some(envelope::Body::Ready(_))));

        let mut rev = 1u64;
        let mut ui_count = 0u32;
        loop {
            let env = match v14_receive(&mut worker_rx, identity, &mut incoming_seq).await {
                Ok(env) => env,
                Err(err)
                    if err
                        .downcast_ref::<std::io::Error>()
                        .is_some_and(|e| e.kind() == std::io::ErrorKind::UnexpectedEof) =>
                {
                    break;
                }
                Err(err) => return Err(err),
            };
            match env.body {
                Some(envelope::Body::UiEvent(_)) => {
                    ui_count += 1;
                    if ui_count == 2 {
                        // Emit stale revision (1 < 2) to trigger host Resync(rev=2).
                        v14_send(
                            &mut worker_tx,
                            identity,
                            &mut outgoing_seq,
                            1,
                            env.request_id,
                            envelope::Body::Snapshot(make_panel(1, "stale")),
                        )
                        .await?;
                    } else {
                        rev += 1;
                        v14_send(
                            &mut worker_tx,
                            identity,
                            &mut outgoing_seq,
                            rev,
                            env.request_id,
                            envelope::Body::Snapshot(make_panel(rev, &format!("ok-{rev}"))),
                        )
                        .await?;
                    }
                }
                Some(envelope::Body::Resync(snap)) => {
                    resync_seen_worker.notify_one();
                    // Block for > 2 * MAX_OPERATION (10.5s): any Cancel or retry Resync queued by host would expire in pipe!
                    tokio::time::sleep(Duration::from_millis(10_500)).await;
                    v14_send(
                        &mut worker_tx,
                        identity,
                        &mut outgoing_seq,
                        snap.revision,
                        env.request_id,
                        envelope::Body::Ack(panel::Empty {}),
                    )
                    .await?;
                    resync_done_worker.notify_one();
                }
                Some(envelope::Body::Shutdown(_)) => break,
                other => bail!("unexpected frame in v1.4 worker: {other:?}"),
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();
    let ui_focus = || UiEvent {
        node_id: 1,
        editors: vec![],
        event: Some(panel::ui_event::Event::Focus(true)),
    };

    // Wait initial panel rev=1.
    let ev0 = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    assert!(matches!(ev0, PluginEvent::Panel { snapshot, .. } if snapshot.revision == 1));

    // UiEvent #1 -> advances to rev=2.
    handle.try_event(ui_focus()).unwrap();
    let ev1 = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    assert!(matches!(ev1, PluginEvent::Panel { snapshot, .. } if snapshot.revision == 2));

    // UiEvent #2 -> worker replies stale Snapshot(1) -> host sends Resync(2).
    handle.try_event(ui_focus()).unwrap();
    timeout(MAX_OPERATION, resync_seen.notified()).await.unwrap();

    // First error: resync scheduled; second error (~5s): v1.4 Resync timeout degrades cleanly!
    let e_resync = timeout(Duration::from_secs(7), supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(matches!(e_resync, PluginEvent::Error { .. }));
    let e_timeout = timeout(Duration::from_secs(7), supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(
        matches!(
            e_timeout,
            PluginEvent::Error { panel_id, ref failure, .. }
                if panel_id == protocol::PANEL_ID
                    && failure.code == ErrorCode::Deadline as i32
                    && failure.message.contains("v1.4")
                    && failure.message.contains("重载或升级插件")
        ),
        "expected v1.4 degrade diagnostic, got {e_timeout:?}"
    );
    let e_timeout_sync = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(matches!(
        e_timeout_sync,
        PluginEvent::PanelSynced {
            panel_id: protocol::PANEL_ID,
            ..
        }
    ));

    // Worker finishes 10.5s block and sends late Ack -> host drops late Ack safely as Stale.
    timeout(Duration::from_secs(8), resync_done.notified()).await.unwrap();
    let e_late = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    assert!(matches!(
        e_late,
        PluginEvent::Error { ref failure, .. } if failure.code == ErrorCode::Stale as i32
    ));

    // Unconfirmed interactive Focus stays blocked locally under persistent semantic drift.
    handle.try_event(ui_focus()).unwrap();
    let e_drifted_focus = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(
        matches!(
            e_drifted_focus,
            PluginEvent::Error { ref failure, .. } if failure.code == ErrorCode::Stale as i32
        ),
        "expected Stale rejection for unconfirmed interactive event, got {e_drifted_focus:?}"
    );

    // EditorChanged still reaches Worker through strict v1.4 check_channel (no expired frames in pipe!) and returns Snapshot(rev=3) clearing drift.
    handle
        .try_event(UiEvent {
            node_id: 1,
            editors: vec![],
            event: Some(panel::ui_event::Event::EditorChanged(panel::EditorSnapshot {
                document_id: 1,
                revision: 3,
                contents: b"ok-3".to_vec(),
                selection_start: 0,
                selection_end: 0,
            })),
        })
        .unwrap();
    let ev3 = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    assert!(
        matches!(ev3, PluginEvent::Panel { ref snapshot, .. } if snapshot.revision == 3),
        "expected recovered panel rev 3, got {ev3:?}"
    );

    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn interleaved_resync_host_call_error_keeps_budget_and_resyncs_latest() {
    let (mut running, mut calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("rev-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: rev,
                contents: format!("body-{rev}").into_bytes(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let res2 = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    let mut in_seq = 2u64;
    for target_panel in [2u64, protocol::PANEL_ID] {
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    event: panel::UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    expected_snapshot: None,
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_wire = wire.try_recv().unwrap();
        running.schedule_panel_resync(target_panel);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync1 = wire.try_recv().unwrap();
        assert!(matches!(resync1.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));
        let seq = if target_panel == protocol::PANEL_ID {
            running.main_resync_needed_seq
        } else {
            running.panels[&target_panel].resync_needed_seq
        };
        assert_ne!(seq, 0);

        // Earlier in-flight UiEvent completes and advances host revision from 1 -> 2.
        let mut snap2 = Envelope::new(
            running.identity,
            in_seq,
            2,
            envelope::Body::Snapshot(snap(2)),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        in_seq += 1;
        snap2.in_reply_to = ev_wire.request_id;
        running.frame(snap2, &outgoing).await.unwrap();
        assert_eq!(running.panel_revision(target_panel), 2);
        while updates.try_recv().is_ok() {}

        // Inside on_panel_resync(1), SDK calls QueryHistory at published=1 referencing in-flight resync1.
        let hc1 = HostCall {
            operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
                offset: 0,
                limit: 1,
                filter: String::new(),
            })),
            parent_request_id: resync1.request_id,
        };
        running
            .frame(
                Envelope::new(
                    running.identity,
                    in_seq,
                    1,
                    envelope::Body::HostCall(hc1),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel),
                &outgoing,
            )
            .await
            .unwrap();
        in_seq += 1;
        assert!(calls.try_recv().is_err());
        let stale_hr = wire.try_recv().unwrap();
        assert!(matches!(
            stale_hr.body,
            Some(envelope::Body::HostResult(HostResult {
                outcome: Some(host_result::Outcome::Error(Failure { code, .. })),
            })) if code == ErrorCode::Stale as i32
        ));
        assert!(wire.try_recv().is_err());

        // SDK propagates that HostCall error as Error(Invalid, rev=1) for superseded resync1!
        let mut err1 = Envelope::new(
            running.identity,
            in_seq,
            1,
            envelope::Body::Error(Failure::new(
                ErrorCode::Invalid,
                "服务调用来自旧面板 revision",
            )),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        in_seq += 1;
        err1.in_reply_to = resync1.request_id;
        running.frame(err1, &outgoing).await.unwrap();

        // Must preserve recovery cycle, keep budget intact, NOT mark incompatible, and immediately send Resync(2)!
        let resync2 = wire.try_recv().unwrap();
        assert!(matches!(resync2.body, Some(envelope::Body::Resync(ref s)) if s.revision == 2));
        if target_panel == protocol::PANEL_ID {
            assert!(!running.main_resync_incompatible);
            assert_eq!(running.main_resync_needed_seq, seq);
            assert_eq!(running.main_resync_attempts, 2);
        } else {
            assert!(!running.panels[&target_panel].resync_incompatible);
            assert_eq!(running.panels[&target_panel].resync_needed_seq, seq);
            assert_eq!(running.panels[&target_panel].resync_attempts, 2);
        }

        // Now inside on_panel_resync(2), HostCall at rev=2 referencing resync2 succeeds and Ack(2) completes recovery!
        let hc2 = HostCall {
            operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
                offset: 0,
                limit: 1,
                filter: String::new(),
            })),
            parent_request_id: resync2.request_id,
        };
        running
            .frame(
                Envelope::new(
                    running.identity,
                    in_seq,
                    2,
                    envelope::Body::HostCall(hc2),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel),
                &outgoing,
            )
            .await
            .unwrap();
        in_seq += 1;
        assert_eq!(calls.try_recv().unwrap().panel_id, target_panel);

        let mut ack2 = Envelope::new(
            running.identity,
            in_seq,
            2,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        in_seq += 1;
        ack2.in_reply_to = resync2.request_id;
        running.frame(ack2, &outgoing).await.unwrap();
        if target_panel == protocol::PANEL_ID {
            assert_eq!(running.main_resync_needed_seq, 0);
            assert_eq!(running.main_resync_attempts, 0);
        } else {
            assert_eq!(running.panels[&target_panel].resync_needed_seq, 0);
            assert_eq!(running.panels[&target_panel].resync_attempts, 0);
        }
    }
}

#[tokio::test]
async fn child_non_destroy_close_timer_timeout_resyncs_and_recovers_late_snapshot() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();
    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("child-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    running.broker.bind_panel_resource(2, extra, 1, false).unwrap();
    let (rev_tx, mut rev_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: extra,
                remove_panel: false,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close_wire = wire.try_recv().unwrap();
    assert!(matches!(
        close_wire.body,
        Some(envelope::Body::CloseRequest(ref c)) if !c.destroy_panel
    ));

    // Timer fires FIRST on CloseRequest(destroy_panel=false): cancels close, records allowlist id, emits Cancel + Resync(1).
    running.requests.get_mut(&close_wire.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    assert!(rev_rx.try_recv().unwrap().is_err());
    assert!(
        running.panels[&2]
            .cancelled_state_requests
            .iter()
            .any(|&(id, _)| id == close_wire.request_id)
    );
    let cancel_msg = wire.try_recv().unwrap();
    assert!(matches!(cancel_msg.body, Some(envelope::Body::Cancel(_))));
    let resync1 = wire.try_recv().unwrap();
    assert!(matches!(resync1.body, Some(envelope::Body::Resync(_))));

    let mut resync1_ack =
        Envelope::new(running.identity, 2, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    resync1_ack.in_reply_to = resync1.request_id;
    running.frame(resync1_ack, &outgoing).await.unwrap();
    assert_eq!(running.panels[&2].resync_needed_seq, 0);
    assert!(wire.try_recv().is_err());

    // SDK's on_panel_close_request finally finishes and publishes Snapshot(2) after timer recovery already settled!
    let mut late_close_snap = Envelope::new(
        running.identity,
        3,
        2,
        envelope::Body::Snapshot(make_snap(2)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    late_close_snap.in_reply_to = close_wire.request_id;
    running.frame(late_close_snap, &outgoing).await.unwrap();

    let resync2 = wire.try_recv().unwrap();
    assert!(matches!(resync2.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));
    assert!(
        !running.panels[&2]
            .cancelled_state_requests
            .iter()
            .any(|&(id, _)| id == close_wire.request_id)
    );
    let mut resync2_ack =
        Envelope::new(running.identity, 4, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    resync2_ack.in_reply_to = resync2.request_id;
    running.frame(resync2_ack, &outgoing).await.unwrap();

    // Replay of the same close id must not trigger another Resync.
    let mut replay_close_snap = Envelope::new(
        running.identity,
        5,
        2,
        envelope::Body::Snapshot(make_snap(2)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    replay_close_snap.in_reply_to = close_wire.request_id;
    running.frame(replay_close_snap, &outgoing).await.unwrap();
    assert!(wire.try_recv().is_err());
}

#[tokio::test]
async fn interleaved_resync_snapshot_reply_does_not_overwrite_newer_confirmed_panel() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let make_snap = |rev: u64, status: &str| PanelSnapshot {
        revision: rev,
        title: format!("panel-{rev}"),
        root: Some(panel::Node::new(
            3,
            "layout",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        2,
                        "status",
                        panel::node::Kind::Text(panel::Text {
                            text: status.into(),
                            tone: 0,
                        }),
                    ),
                ],
            }),
        )),
    };
    running.panel = PanelState::new(make_snap(1, "v1-old")).unwrap();

    // Prepare child panel 2 at rev=1 (keeping existing main panel at rev=1 too).
    let res2 = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: res2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, "v1-old")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    let mut in_seq = 2u64;
    for target_panel in [2u64, protocol::PANEL_ID] {
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    event: panel::UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    expected_snapshot: None,
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_wire = wire.try_recv().unwrap();
        running.schedule_panel_resync(target_panel);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync1 = wire.try_recv().unwrap();
        assert!(matches!(resync1.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));
        let seq = if target_panel == protocol::PANEL_ID {
            running.main_resync_needed_seq
        } else {
            running.panels[&target_panel].resync_needed_seq
        };
        assert_ne!(seq, 0);

        // Earlier in-flight UiEvent completes and advances confirmed panel to rev=2 with "v2-confirmed".
        let mut snap2 = Envelope::new(
            running.identity,
            in_seq,
            2,
            envelope::Body::Snapshot(make_snap(2, "v2-confirmed")),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        in_seq += 1;
        snap2.in_reply_to = ev_wire.request_id;
        running.frame(snap2, &outgoing).await.unwrap();
        assert_eq!(running.panel_revision(target_panel), 2);
        while updates.try_recv().is_ok() {}

        // Callback handling stale Resync(1) rebuilds state from rev=1 and replies with higher rev=3 full Snapshot!
        // Because resync_revision(1) != current host_rev(2), host MUST reject overwriting "v2-confirmed" and send Resync(2).
        let mut stale_resync_snap3 = Envelope::new(
            running.identity,
            in_seq,
            3,
            envelope::Body::Snapshot(make_snap(3, "v1-rebuilt-stale")),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        in_seq += 1;
        stale_resync_snap3.in_reply_to = resync1.request_id;
        running.frame(stale_resync_snap3, &outgoing).await.unwrap();

        assert_eq!(running.panel_revision(target_panel), 2);
        let retained_snap = running.panel_snapshot(target_panel).unwrap();
        let status_node = retained_snap.root.as_ref().unwrap().find(2).unwrap();
        assert!(matches!(
            status_node.kind,
            Some(panel::node::Kind::Text(ref t)) if t.text == "v2-confirmed"
        ));

        let resync2 = wire.try_recv().unwrap();
        assert!(matches!(
            resync2.body,
            Some(envelope::Body::Resync(ref s))
                if s.revision == 2
                    && matches!(
                        s.root.as_ref().and_then(|r| r.find(2)).and_then(|n| n.kind.as_ref()),
                        Some(panel::node::Kind::Text(t)) if t.text == "v2-confirmed"
                    )
        ));
        if target_panel == protocol::PANEL_ID {
            assert!(!running.main_resync_incompatible);
            assert_eq!(running.main_resync_needed_seq, seq);
            assert_eq!(running.main_resync_attempts, 2);
        } else {
            assert!(!running.panels[&target_panel].resync_incompatible);
            assert_eq!(running.panels[&target_panel].resync_needed_seq, seq);
            assert_eq!(running.panels[&target_panel].resync_attempts, 2);
        }

        // Reply to Resync(2) with full Snapshot(4) succeeds and settles recovery cleanly.
        let mut ok_resync_snap4 = Envelope::new(
            running.identity,
            in_seq,
            4,
            envelope::Body::Snapshot(make_snap(4, "v2-resynced")),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        in_seq += 1;
        ok_resync_snap4.in_reply_to = resync2.request_id;
        running.frame(ok_resync_snap4, &outgoing).await.unwrap();
        assert_eq!(running.panel_revision(target_panel), 4);
        if target_panel == protocol::PANEL_ID {
            assert_eq!(running.main_resync_needed_seq, 0);
            assert_eq!(running.main_resync_attempts, 0);
        } else {
            assert_eq!(running.panels[&target_panel].resync_needed_seq, 0);
            assert_eq!(running.panels[&target_panel].resync_attempts, 0);
        }
    }
}

#[tokio::test]
async fn child_resync_barrier_defers_commands_until_settled_and_revoke_cancels() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();
    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("p2-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = ow.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    running.schedule_panel_resync(2);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync1 = wire.try_recv().unwrap();
    assert!(matches!(resync1.body, Some(envelope::Body::Resync(_))));

    // While child panel 2 resync is in flight, both UiEvent and Open(extra) are deferred behind barrier.
    running
        .control(
            Control::Event {
                panel_id: 2,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let (extra_tx, mut extra_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: extra,
                revision: 1,
                read_only: false,
                request: request(),
                reply: extra_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(wire.try_recv().is_err());
    assert_eq!(running.panels[&2].deferred_commands.len(), 2);

    // Revoking `extra` (destroy_panel=false) immediately cancels deferred Open(extra) and revokes broker,
    // while deferring CloseRequest behind the active Resync barrier!
    let (rev_tx, mut rev_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: extra,
                remove_panel: false,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(extra_rx.try_recv().unwrap().is_err());
    assert_eq!(running.panels[&2].deferred_commands.len(), 1);
    assert_eq!(running.pending_revokes.len(), 1);
    assert!(
        wire.try_recv().is_err(),
        "non-destroy CloseRequest must not overtake active Resync barrier"
    );

    // Settling Resync releases ONLY non-destroy CloseRequest first while keeping deferred UiEvent queued
    // behind the in-flight non-destroy close barrier; ONLY after CloseRequest settles does UiEvent flush!
    let mut resync_ack =
        Envelope::new(running.identity, 2, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    resync_ack.in_reply_to = resync1.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();
    assert!(running.pending_revokes.is_empty());
    assert_eq!(
        running.panels[&2].deferred_commands.len(),
        1,
        "deferred UiEvent must remain queued while non-destroy CloseRequest is in flight"
    );
    let close_wire = wire.try_recv().unwrap();
    assert_eq!(close_wire.panel_id, 2);
    assert!(matches!(
        close_wire.body,
        Some(envelope::Body::CloseRequest(ref c)) if !c.destroy_panel
    ));
    assert!(
        wire.try_recv().is_err(),
        "deferred UiEvent must not overtake in-flight non-destroy CloseRequest"
    );

    let mut close_ack =
        Envelope::new(running.identity, 3, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
            .with_panel_id(2);
    close_ack.in_reply_to = close_wire.request_id;
    running.frame(close_ack, &outgoing).await.unwrap();
    assert!(rev_rx.try_recv().unwrap().is_ok());
    assert!(running.panels[&2].deferred_commands.is_empty());
    let flushed_ev = wire.try_recv().unwrap();
    assert_eq!(flushed_ev.panel_id, 2);
    assert!(matches!(flushed_ev.body, Some(envelope::Body::UiEvent(_))));

    // Failure completion policy: when Resync aborts while a non-destroy Revoke is deferred,
    // the Revoke reply completes with an explicit error without emitting CloseRequest!
    running.schedule_panel_resync(2);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync2 = wire.try_recv().unwrap();
    let (rev2_tx, mut rev2_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: primary,
                remove_panel: false,
                reply: rev2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.pending_revokes.len(), 1);
    assert!(wire.try_recv().is_err());

    let mut abort_err = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "resync aborted")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    abort_err.in_reply_to = resync2.request_id;
    running.frame(abort_err, &outgoing).await.unwrap();
    assert!(running.pending_revokes.is_empty());
    assert!(wire.try_recv().is_err());
    let err_msg = rev2_rx.try_recv().unwrap().unwrap_err().to_string();
    assert!(err_msg.contains("重同步未完成") && err_msg.contains("本地资源授权已撤销"));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn real_sdk_resync_barrier_prevents_queued_ui_event_from_reverting_confirmed_panel() {
    use std::io::{Read, Write};
    use std::sync::{Arc, Mutex};
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    struct BlockingReader(DuplexStream, tokio::runtime::Handle);
    impl Read for BlockingReader {
        fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.read(buf))
        }
    }
    struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
    impl Write for BlockingWriter {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.write(buf))
        }
        fn flush(&mut self) -> std::io::Result<()> {
            self.1.block_on(self.0.flush())
        }
    }

    struct InterleavedBarrierPlugin {
        status: Mutex<String>,
        ev0_entered: Arc<tokio::sync::Notify>,
        ev0_release: Arc<tokio::sync::Notify>,
        resync1_entered: Arc<tokio::sync::Notify>,
        resync1_release: Arc<tokio::sync::Notify>,
        rt: tokio::runtime::Handle,
    }

    impl InterleavedBarrierPlugin {
        fn make_snap(rev: u64, status: &str, ed_rev: u64, ed_bytes: Vec<u8>) -> PanelSnapshot {
            PanelSnapshot {
                revision: rev,
                title: "sdk-resync-barrier".into(),
                root: Some(panel::Node::new(
                    3,
                    "col",
                    panel::node::Kind::Column(panel::Container {
                        children: vec![
                            panel::Node::new(
                                1,
                                "ed",
                                panel::node::Kind::Editor(panel::Editor {
                                    document_id: 1,
                                    revision: ed_rev,
                                    contents: ed_bytes,
                                    format: panel::EditorFormat::Utf8 as i32,
                                    read_only: false,
                                }),
                            ),
                            panel::Node::new(
                                2,
                                "status",
                                panel::node::Kind::Text(panel::Text {
                                    text: status.to_owned(),
                                    tone: panel::Tone::Foreground as i32,
                                }),
                            ),
                            panel::Node::new(
                                10,
                                "btn0",
                                panel::node::Kind::Button(panel::Button {
                                    label: "TriggerStale".into(),
                                    enabled: true,
                                    commit_editors: false,
                                }),
                            ),
                            panel::Node::new(
                                12,
                                "btnB",
                                panel::node::Kind::Button(panel::Button {
                                    label: "EventB".into(),
                                    enabled: true,
                                    commit_editors: false,
                                }),
                            ),
                        ],
                    }),
                )),
            }
        }
    }

    impl mio_plugin_sdk::MioPlugin for InterleavedBarrierPlugin {
        fn id(&self) -> &str {
            "lab.sdk-resync-barrier"
        }

        fn version(&self) -> &str {
            "1.5.0"
        }

        fn supports_panel_multiplexing(&self) -> bool {
            false
        }

        fn initial_panel(&self) -> PanelSnapshot {
            Self::make_snap(1, "v1-old", 1, b"init".to_vec())
        }

        fn on_panel_ui_event(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            event: UiEvent,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            match (event.node_id, &event.event) {
                (10, Some(panel::ui_event::Event::Click(_))) => {
                    self.ev0_entered.notify_one();
                    self.rt.block_on(self.ev0_release.notified());
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        "stale-from-ev0",
                        1,
                        b"init".to_vec(),
                    )));
                }
                (1, Some(panel::ui_event::Event::EditorChanged(ed))) => {
                    let mut st = self.status.lock().unwrap();
                    *st = "v2-confirmed".into();
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        &st,
                        ed.revision,
                        ed.contents.clone(),
                    )));
                }
                (12, Some(panel::ui_event::Event::Click(_))) => {
                    let mut st = self.status.lock().unwrap();
                    *st = format!("{st}+evB");
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        &st,
                        2,
                        b"user-edit".to_vec(),
                    )));
                }
                _ => {}
            }
            Ok(None)
        }

        fn on_panel_resync(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            snapshot: PanelSnapshot,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            let status_text = snapshot
                .root
                .as_ref()
                .and_then(|r| r.find(2))
                .and_then(|n| match &n.kind {
                    Some(panel::node::Kind::Text(t)) => Some(t.text.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            if status_text == "v1-old" {
                self.resync1_entered.notify_one();
                self.rt.block_on(self.resync1_release.notified());
                *self.status.lock().unwrap() = status_text.clone();
                let rev = ctx.next_panel_revision();
                return Ok(Some(Self::make_snap(rev, &status_text, 2, b"user-edit".to_vec())));
            }
            *self.status.lock().unwrap() = status_text.clone();
            let rev = ctx.next_panel_revision();
            Ok(Some(Self::make_snap(rev, &status_text, 2, b"user-edit".to_vec())))
        }
    }

    let rt_handle = tokio::runtime::Handle::current();
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.sdk-resync-barrier".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![],
        contributions: vec!["suite_panel".into()],
    };
    let (host_tx, worker_rx) = tokio::io::duplex(64 * 1024);
    let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
    let ev0_entered = Arc::new(tokio::sync::Notify::new());
    let ev0_release = Arc::new(tokio::sync::Notify::new());
    let resync1_entered = Arc::new(tokio::sync::Notify::new());
    let resync1_release = Arc::new(tokio::sync::Notify::new());
    let ev0_entered_w = ev0_entered.clone();
    let ev0_release_w = ev0_release.clone();
    let resync1_entered_w = resync1_entered.clone();
    let resync1_release_w = resync1_release.clone();

    let worker_thread = std::thread::spawn(move || {
        let mut plugin = InterleavedBarrierPlugin {
            status: Mutex::new("v1-old".into()),
            ev0_entered: ev0_entered_w,
            ev0_release: ev0_release_w,
            resync1_entered: resync1_entered_w,
            resync1_release: resync1_release_w,
            rt: rt_handle.clone(),
        };
        mio_plugin_sdk::run_with_io(
            BlockingReader(worker_rx, rt_handle.clone()),
            BlockingWriter(worker_tx, rt_handle),
            &mut plugin,
        )
        .unwrap();
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_tx,
        host_rx,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let extract_status = |snap: &PanelSnapshot| -> String {
        snap.root
            .as_ref()
            .and_then(|r| r.find(2))
            .and_then(|n| match &n.kind {
                Some(panel::node::Kind::Text(t)) => Some(t.text.clone()),
                _ => None,
            })
            .unwrap_or_default()
    };

    let mut seen_statuses = Vec::new();
    let ev_init = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    let PluginEvent::Panel { snapshot, .. } = ev_init else {
        panic!("expected initial panel");
    };
    seen_statuses.push(extract_status(&snapshot));
    assert_eq!(seen_statuses.last().map(String::as_str), Some("v1-old"));

    // 1. Trigger ev0 -> enters worker on_panel_ui_event and pauses before returning stale editor rev=1.
    handle
        .try_event(UiEvent {
            node_id: 10,
            editors: vec![],
            event: Some(panel::ui_event::Event::Click(panel::Empty {})),
        })
        .unwrap();
    timeout(MAX_OPERATION, ev0_entered.notified()).await.unwrap();

    // 2. While ev0 is in flight on worker, native EditorChanged (UiEvent A) updates host editor rev=2 and queues on wire.
    handle
        .try_event(UiEvent {
            node_id: 1,
            editors: vec![],
            event: Some(panel::ui_event::Event::EditorChanged(panel::EditorSnapshot {
                document_id: 1,
                revision: 2,
                contents: b"user-edit".to_vec(),
                selection_start: 0,
                selection_end: 0,
            })),
        })
        .unwrap();

    // 3. Release ev0 -> host rejects ev0's stale Snapshot -> emits Resync(1) AFTER UiEvent A;
    //    worker first completes UiEvent A ("v2-confirmed") and then blocks inside Resync(1).
    ev0_release.notify_one();
    timeout(MAX_OPERATION, resync1_entered.notified()).await.unwrap();
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Panel { snapshot, .. }) = supervisor.events.recv().await {
                let s = extract_status(&snapshot);
                seen_statuses.push(s.clone());
                if s == "v2-confirmed" {
                    break;
                }
            }
        }
    })
    .await
    .unwrap();

    // 4. While stale Resync(1) is STILL in flight on worker, issue UiEvent B (Click node 12)!
    //    Per-panel barrier MUST defer UiEvent B until corrective Resync settles!
    handle
        .try_event(UiEvent {
            node_id: 12,
            editors: vec![],
            event: Some(panel::ui_event::Event::Click(panel::Empty {})),
        })
        .unwrap();
    resync1_release.notify_one();

    // 5. Expect final confirmed state "v2-confirmed+evB", and NEVER "v1-old" or "v1-old+evB" after "v2-confirmed"!
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Panel { snapshot, .. }) = supervisor.events.recv().await {
                let s = extract_status(&snapshot);
                seen_statuses.push(s.clone());
                if s == "v2-confirmed+evB" {
                    break;
                }
            }
        }
    })
    .await
    .unwrap();

    let v2_pos = seen_statuses.iter().position(|s| s == "v2-confirmed").unwrap();
    assert!(
        !seen_statuses[v2_pos + 1..]
            .iter()
            .any(|s| s == "v1-old" || s == "v1-old+evB"),
        "confirmed panel reverted during interleaved resync + queued UiEvent: {seen_statuses:?}"
    );

    supervisor.stop().await.unwrap();
    worker_thread.join().unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn real_sdk_non_destroy_close_waits_for_resync_barrier_and_never_reverts_panel() {
    use std::collections::HashMap;
    use std::io::{Read, Write};
    use std::sync::{Arc, Mutex};
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    struct BlockingReader(DuplexStream, tokio::runtime::Handle);
    impl Read for BlockingReader {
        fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.read(buf))
        }
    }
    struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
    impl Write for BlockingWriter {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.write(buf))
        }
        fn flush(&mut self) -> std::io::Result<()> {
            self.1.block_on(self.0.flush())
        }
    }

    struct ChildCloseBarrierPlugin {
        statuses: Mutex<HashMap<u64, String>>,
        ev0_entered: Arc<tokio::sync::Notify>,
        ev0_release: Arc<tokio::sync::Notify>,
        resync1_entered: Arc<tokio::sync::Notify>,
        resync1_release: Arc<tokio::sync::Notify>,
        rt: tokio::runtime::Handle,
    }

    impl ChildCloseBarrierPlugin {
        fn make_snap(rev: u64, status: &str, ed_rev: u64, ed_bytes: Vec<u8>) -> PanelSnapshot {
            PanelSnapshot {
                revision: rev,
                title: format!("sdk-child-{rev}"),
                root: Some(panel::Node::new(
                    3,
                    "col",
                    panel::node::Kind::Column(panel::Container {
                        children: vec![
                            panel::Node::new(
                                1,
                                "ed",
                                panel::node::Kind::Editor(panel::Editor {
                                    document_id: 1,
                                    revision: ed_rev,
                                    contents: ed_bytes,
                                    format: panel::EditorFormat::Utf8 as i32,
                                    read_only: false,
                                }),
                            ),
                            panel::Node::new(
                                2,
                                "status",
                                panel::node::Kind::Text(panel::Text {
                                    text: status.to_owned(),
                                    tone: panel::Tone::Foreground as i32,
                                }),
                            ),
                            panel::Node::new(
                                10,
                                "btn0",
                                panel::node::Kind::Button(panel::Button {
                                    label: "TriggerStale".into(),
                                    enabled: true,
                                    commit_editors: false,
                                }),
                            ),
                        ],
                    }),
                )),
            }
        }
    }

    impl mio_plugin_sdk::MioPlugin for ChildCloseBarrierPlugin {
        fn id(&self) -> &str {
            "lab.sdk-close-barrier"
        }

        fn version(&self) -> &str {
            "1.5.0"
        }

        fn supports_panel_multiplexing(&self) -> bool {
            true
        }

        fn initial_panel(&self) -> PanelSnapshot {
            Self::make_snap(1, "main-init", 1, b"init".to_vec())
        }

        fn on_panel_open_request(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            panel_id: u64,
            _open: protocol::OpenRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            self.statuses
                .lock()
                .unwrap()
                .insert(panel_id, "v1-old".into());
            let rev = ctx.next_panel_revision();
            Ok(Some(Self::make_snap(rev, "v1-old", 1, b"init".to_vec())))
        }

        fn on_panel_ui_event(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            panel_id: u64,
            event: UiEvent,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            match (event.node_id, &event.event) {
                (10, Some(panel::ui_event::Event::Click(_))) => {
                    self.ev0_entered.notify_one();
                    self.rt.block_on(self.ev0_release.notified());
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        "stale-from-ev0",
                        1,
                        b"init".to_vec(),
                    )));
                }
                (1, Some(panel::ui_event::Event::EditorChanged(ed))) => {
                    let mut map = self.statuses.lock().unwrap();
                    map.insert(panel_id, "v2-confirmed".into());
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        "v2-confirmed",
                        ed.revision,
                        ed.contents.clone(),
                    )));
                }
                _ => {}
            }
            Ok(None)
        }

        fn on_panel_resync(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            panel_id: u64,
            snapshot: PanelSnapshot,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            let status_text = snapshot
                .root
                .as_ref()
                .and_then(|r| r.find(2))
                .and_then(|n| match &n.kind {
                    Some(panel::node::Kind::Text(t)) => Some(t.text.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            if status_text == "v1-old" {
                self.resync1_entered.notify_one();
                self.rt.block_on(self.resync1_release.notified());
                self.statuses
                    .lock()
                    .unwrap()
                    .insert(panel_id, status_text.clone());
                let rev = ctx.next_panel_revision();
                return Ok(Some(Self::make_snap(rev, &status_text, 2, b"user-edit".to_vec())));
            }
            self.statuses.lock().unwrap().insert(panel_id, status_text);
            Ok(None)
        }

        fn on_panel_close_request(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            panel_id: u64,
            close: protocol::CloseRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            assert!(!close.destroy_panel);
            let mut map = self.statuses.lock().unwrap();
            let next = format!(
                "{}+closed",
                map.get(&panel_id).map_or("", String::as_str)
            );
            map.insert(panel_id, next.clone());
            let rev = ctx.next_panel_revision();
            Ok(Some(Self::make_snap(rev, &next, 2, b"user-edit".to_vec())))
        }
    }

    let rt_handle = tokio::runtime::Handle::current();
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.sdk-close-barrier".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_tx, worker_rx) = tokio::io::duplex(64 * 1024);
    let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
    let ev0_entered = Arc::new(tokio::sync::Notify::new());
    let ev0_release = Arc::new(tokio::sync::Notify::new());
    let resync1_entered = Arc::new(tokio::sync::Notify::new());
    let resync1_release = Arc::new(tokio::sync::Notify::new());
    let ev0_entered_w = ev0_entered.clone();
    let ev0_release_w = ev0_release.clone();
    let resync1_entered_w = resync1_entered.clone();
    let resync1_release_w = resync1_release.clone();

    let worker_thread = std::thread::spawn(move || {
        let mut plugin = ChildCloseBarrierPlugin {
            statuses: Mutex::new(HashMap::new()),
            ev0_entered: ev0_entered_w,
            ev0_release: ev0_release_w,
            resync1_entered: resync1_entered_w,
            resync1_release: resync1_release_w,
            rt: rt_handle.clone(),
        };
        mio_plugin_sdk::run_with_io(
            BlockingReader(worker_rx, rt_handle.clone()),
            BlockingWriter(worker_tx, rt_handle),
            &mut plugin,
        )
        .unwrap();
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_tx,
        host_rx,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();
    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();

    let extract_status = |snap: &PanelSnapshot| -> String {
        snap.root
            .as_ref()
            .and_then(|r| r.find(2))
            .and_then(|n| match &n.kind {
                Some(panel::node::Kind::Text(t)) => Some(t.text.clone()),
                _ => None,
            })
            .unwrap_or_default()
    };

    // Wait initial main panel, then open child panel 2 with `primary`.
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    let opened = timeout(
        MAX_OPERATION,
        handle.open_request_on_panel(2, primary, 1, false, request()),
    )
    .await
    .unwrap()
    .unwrap();
    assert_eq!(extract_status(&opened), "v1-old");

    let mut seen_child_statuses = Vec::new();
    // 1. Trigger ev0 -> worker pauses inside on_panel_ui_event(10) on child panel 2.
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 10,
                editors: vec![],
                event: Some(panel::ui_event::Event::Click(panel::Empty {})),
            },
        )
        .unwrap();
    timeout(MAX_OPERATION, ev0_entered.notified()).await.unwrap();

    // 2. Native EditorChanged (UiEvent A) bumps host child editor rev=2 and queues on wire.
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 1,
                editors: vec![],
                event: Some(panel::ui_event::Event::EditorChanged(panel::EditorSnapshot {
                    document_id: 1,
                    revision: 2,
                    contents: b"user-edit".to_vec(),
                    selection_start: 0,
                    selection_end: 0,
                })),
            },
        )
        .unwrap();

    // 3. Release ev0 -> host rejects stale Snapshot -> sends Resync(1) AFTER UiEvent A;
    //    worker first completes UiEvent A ("v2-confirmed") then blocks inside Resync(1).
    ev0_release.notify_one();
    timeout(MAX_OPERATION, resync1_entered.notified()).await.unwrap();
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Panel { panel_id: 2, snapshot, .. }) =
                supervisor.events.recv().await
            {
                let s = extract_status(&snapshot);
                seen_child_statuses.push(s.clone());
                if s == "v2-confirmed" {
                    break;
                }
            }
        }
    })
    .await
    .unwrap();

    // 4. Issue non-destroy revoke while stale Resync(1) is active on worker!
    let revoke_handle = handle.clone();
    let revoke_task = tokio::spawn(async move {
        revoke_handle.revoke_panel_resource(2, extra, false).await
    });
    tokio::time::sleep(Duration::from_millis(20)).await;
    resync1_release.notify_one();

    // CloseRequest(destroy_panel=false) must wait until corrective Resync settles "v2-confirmed",
    // yielding final state "v2-confirmed+closed" without EVER reverting to "v1-old" or "v1-old+closed".
    timeout(MAX_OPERATION, revoke_task).await.unwrap().unwrap().unwrap();
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Panel { panel_id: 2, snapshot, .. }) =
                supervisor.events.recv().await
            {
                let s = extract_status(&snapshot);
                seen_child_statuses.push(s.clone());
                if s == "v2-confirmed+closed" {
                    break;
                }
            }
        }
    })
    .await
    .unwrap();

    let v2_pos = seen_child_statuses.iter().position(|s| s == "v2-confirmed").unwrap();
    assert!(
        !seen_child_statuses[v2_pos + 1..]
            .iter()
            .any(|s| s == "v1-old" || s == "v1-old+closed"),
        "confirmed child panel reverted via CloseRequest(destroy=false): {seen_child_statuses:?}"
    );

    supervisor.stop().await.unwrap();
    worker_thread.join().unwrap();
}

#[tokio::test]
async fn deferred_command_event_rejected_when_resync_changes_widget_semantics() {
    let make_snap = |rev: u64, opts: [&str; 2], btn_ctx: &str, ed_text: &[u8]| PanelSnapshot {
        revision: rev,
        title: "semantic-panel".into(),
        root: Some(panel::Node::new(
            1,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        2,
                        "record-ctx",
                        panel::node::Kind::Text(panel::Text {
                            text: btn_ctx.to_owned(),
                            tone: 0,
                        }),
                    ),
                    panel::Node::new(
                        5,
                        "action-select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Action".into(),
                            options: opts.iter().map(|s| (*s).to_owned()).collect(),
                            selected_index: 1,
                            enabled: true,
                        }),
                    ),
                    panel::Node::new(
                        10,
                        "delete-btn",
                        panel::node::Kind::Button(panel::Button {
                            label: "Delete".into(),
                            enabled: true,
                            commit_editors: false,
                        }),
                    ),
                    panel::Node::new(
                        20,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: ed_text.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                ],
            }),
        )),
    };

    let (mut running, _calls, mut updates) = running();
    let snap_rev1 = Arc::new(make_snap(1, ["Allow", "Deny"], "Record A", b"init"));
    running.panel = PanelState::new((*snap_rev1).clone()).unwrap();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    // 1. Trigger main-panel Resync(1) -> barrier active; defer SelectedOption(0) & Click(10) from snap_rev1.
    running.schedule_panel_resync(protocol::PANEL_ID);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync1 = wire.try_recv().unwrap();

    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: UiEvent {
                    node_id: 5,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                expected_snapshot: Some(snap_rev1.clone()),
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: UiEvent {
                    node_id: 10,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Click(panel::Empty {})),
                },
                expected_snapshot: Some(snap_rev1.clone()),
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(wire.try_recv().is_err());

    // Corrective Resync reply returns Snapshot(2) that REORDERED Select options ["Allow","Deny"] -> ["Deny","Allow"]
    // AND rebound sibling context "Record A" -> "Record B"!
    while updates.try_recv().is_ok() {}
    let mut resync_snap2 = Envelope::new(
        running.identity,
        1,
        2,
        envelope::Body::Snapshot(make_snap(2, ["Deny", "Allow"], "Record B", b"init")),
        MAX_OPERATION,
    );
    resync_snap2.in_reply_to = resync1.request_id;
    running.frame(resync_snap2, &outgoing).await.unwrap();

    // Neither SelectedOption(0) nor Click(10) may be emitted onto wire; both emit Stale diagnostics!
    assert!(wire.try_recv().is_err());
    let mut stale_count = 0usize;
    while let Ok(ev) = updates.try_recv() {
        if let PluginEvent::Error { failure, .. } = ev
            && failure.code == ErrorCode::Stale as i32
            && failure.message.contains("插件面板内容已更新")
        {
            stale_count += 1;
        }
    }
    assert_eq!(stale_count, 2);

    // 2. Identical content tree across revision bump (2 -> 3) STILL rebases Click(10) cleanly;
    //    EditorChanged STILL merges cleanly even when sibling text ("Record B" -> "Record C") changes!
    let snap_rev2 = Arc::new(running.panel.snapshot().clone());
    running.schedule_panel_resync(protocol::PANEL_ID);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync2 = wire.try_recv().unwrap();

    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: UiEvent {
                    node_id: 10,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Click(panel::Empty {})),
                },
                expected_snapshot: Some(snap_rev2),
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                event: UiEvent {
                    node_id: 20,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::EditorChanged(panel::EditorSnapshot {
                        document_id: 1,
                        revision: 2,
                        contents: b"typed-during-resync".to_vec(),
                        selection_start: 0,
                        selection_end: 0,
                    })),
                },
                expected_snapshot: Some(snap_rev1),
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(wire.try_recv().is_err());

    let mut resync_snap3 = Envelope::new(
        running.identity,
        2,
        3,
        envelope::Body::Snapshot(make_snap(3, ["Deny", "Allow"], "Record B", b"init")),
        MAX_OPERATION,
    );
    resync_snap3.in_reply_to = resync2.request_id;
    running.frame(resync_snap3, &outgoing).await.unwrap();

    // Deferred commands serialize: ONLY Click(10) emits first while EditorChanged waits for it to settle.
    let ev_click = wire.try_recv().unwrap();
    assert_eq!(ev_click.revision, 3);
    assert!(matches!(ev_click.body, Some(envelope::Body::UiEvent(ref u)) if u.node_id == 10));
    assert!(
        wire.try_recv().is_err(),
        "second deferred command must wait for first state-updating deferred event to settle"
    );

    let mut click_snap4 = Envelope::new(
        running.identity,
        3,
        4,
        envelope::Body::Snapshot(make_snap(4, ["Deny", "Allow"], "Record C", b"init")),
        MAX_OPERATION,
    );
    click_snap4.in_reply_to = ev_click.request_id;
    running.frame(click_snap4, &outgoing).await.unwrap();

    // Now EditorChanged merges cleanly at revision 4 even though sibling text ("Record B" -> "Record C") changed!
    let ev_edit = wire.try_recv().unwrap();
    assert_eq!(ev_edit.revision, 4);
    assert!(matches!(ev_edit.body, Some(envelope::Body::UiEvent(ref u)) if u.node_id == 20));
    assert_eq!(running.panel.editor(1).unwrap().contents, b"typed-during-resync");
}

#[tokio::test]
async fn child_deferred_command_wakes_when_outgoing_capacity_recovers_without_new_frames() {
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.outbound-wakeup".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let pause_reading = Arc::new(tokio::sync::Notify::new());
    let send_ack = Arc::new(tokio::sync::Notify::new());
    let resume_reading = Arc::new(tokio::sync::Notify::new());
    let pause_reading_w = pause_reading.clone();
    let send_ack_w = send_ack.clone();
    let resume_reading_w = resume_reading.clone();
    let open2_ready = Arc::new(tokio::sync::Notify::new());
    let open2_ready_w = open2_ready.clone();

    let send_frame = move |_tx: &mut tokio::io::DuplexStream,
                      seq: &mut u64,
                      panel_id: u64,
                      rev: u64,
                      in_reply_to: u64,
                      body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION)
            .with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut worker_tx,
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.outbound-wakeup".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        // Open child panel 2 at rev=1, then send unsolicited Snapshot(rev=2) + stale Snapshot(rev=1) to trigger Resync(2).
        let open2 = read_async_frame(&mut worker_rx).await?;
        let s1 = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            1,
            open2.request_id,
            envelope::Body::Snapshot(make_snap(1, "c2-v1")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s1)?).await?;
        let s2 = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            2,
            0,
            envelope::Body::Snapshot(make_snap(2, "c2-v2")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s2)?).await?;
        let stale = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            1,
            0,
            envelope::Body::Snapshot(make_snap(1, "c2-stale")),
        );
        worker_tx.write_all(&protocol::encode_frame(&stale)?).await?;
        worker_tx.flush().await?;

        let resync = read_async_frame(&mut worker_rx).await?;
        ensure!(matches!(resync.body, Some(envelope::Body::Resync(_))));

        // Stop reading worker_rx so duplex buffer fills and wait until test queues `open_extra` behind Resync(2).
        pause_reading_w.notify_one();
        send_ack_w.notified().await;

        // Emit enough invalid-parent HostCalls so `outgoing` holds > (OUTGOING_CAPACITY - RESERVED_CONTROL_OUTGOING) HostResult frames.
        for _ in 0..(OUTGOING_CAPACITY - RESERVED_CONTROL_OUTGOING + 8) {
            let hc = send_frame(
                &mut worker_tx,
                &mut out_seq,
                2,
                2,
                0,
                envelope::Body::HostCall(HostCall {
                    operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
                        offset: 0,
                        limit: 1,
                        filter: String::new(),
                    })),
                    parent_request_id: 999_999,
                }),
            );
            worker_tx.write_all(&protocol::encode_frame(&hc)?).await?;
        }
        // Now settle Resync(2) via Ack(2) and STOP sending any further inbound frames!
        let ack = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            2,
            resync.request_id,
            envelope::Body::Ack(panel::Empty {}),
        );
        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
        worker_tx.flush().await?;

        // Wait until test confirms `open_extra` is queued while `worker_rx` is paused, then resume draining ONLY worker_rx!
        resume_reading_w.notified().await;
        let open_extra = loop {
            let env = read_async_frame(&mut worker_rx).await?;
            if matches!(env.body, Some(envelope::Body::OpenRequest(_))) {
                break env;
            }
        };
        open2_ready_w.notify_one();
        let reply_snap = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            3,
            open_extra.request_id,
            envelope::Body::Snapshot(make_snap(3, "c2-extra-opened")),
        );
        worker_tx.write_all(&protocol::encode_frame(&reply_snap)?).await?;
        worker_tx.flush().await?;

        loop {
            match read_async_frame(&mut worker_rx).await {
                Ok(env) if matches!(env.body, Some(envelope::Body::Shutdown(_))) => break,
                Ok(_) => {}
                Err(_) => break,
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    handle
        .open_request_on_panel(2, primary, 1, false, request())
        .await
        .unwrap();

    // Wait until worker received Resync(2) and paused reading worker_rx, then queue open_extra behind Resync(2).
    timeout(MAX_OPERATION, pause_reading.notified()).await.unwrap();
    let open_handle = handle.clone();
    let mut open_extra_task = tokio::spawn(async move {
        open_handle
            .open_request_on_panel(2, extra, 1, false, request())
            .await
    });
    tokio::time::sleep(Duration::from_millis(30)).await;
    send_ack.notify_one();

    // Wait long enough for Running to process HostCalls + Ack(2) and hit outgoing capacity congestion with zero further events.
    tokio::time::sleep(Duration::from_millis(80)).await;
    assert!(
        tokio::time::timeout(Duration::from_millis(10), &mut open_extra_task)
            .await
            .is_err(),
        "open_extra must still be blocked while outgoing capacity is saturated"
    );

    // Resume reading ONLY on worker_rx — zero new inbound frames or commands are sent —
    // Running MUST wake purely from outbound capacity recovery and deliver OpenRequest(extra)!
    resume_reading.notify_one();
    timeout(MAX_OPERATION, open2_ready.notified()).await.unwrap();
    let reopened_snap = timeout(MAX_OPERATION, open_extra_task)
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert_eq!(reopened_snap.title, "c2-extra-opened");

    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn resync_panel_schedules_barrier_before_flushing_queued_non_destroy_revoke() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("panel-r{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();
    let third = Uuid::new_v4();
    let (open1_tx, open1_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open1_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open1_wire = wire.try_recv().unwrap();
    let mut open1_snap = Envelope::new(
        running.identity,
        1,
        2,
        envelope::Body::Snapshot(make_snap(2)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open1_snap.in_reply_to = open1_wire.request_id;
    running.frame(open1_snap, &outgoing).await.unwrap();
    assert!(open1_rx.await.is_ok());

    // Keep one in-flight Open on child panel 2, then saturate `requests` to QUEUE_CAPACITY on main panel.
    let (open2_tx, mut open2_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: extra,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open2_wire = wire.try_recv().unwrap();

    let mut main_req_ids = Vec::new();
    while running.requests.len() < QUEUE_CAPACITY {
        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    event: panel::UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    expected_snapshot: None,
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_wire = wire.try_recv().unwrap();
        main_req_ids.push(ev_wire.request_id);
    }
    assert_eq!(running.requests.len(), QUEUE_CAPACITY);

    // Queue a non-destroy Revoke while `requests` is full -> waits in `pending_revokes`.
    let (rev_tx, mut rev_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: third,
                remove_panel: false,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.pending_revokes.len(), 1);
    assert!(wire.try_recv().is_err());

    // An unapplicable Snapshot on `open2` invokes `resync_panel`, which frees a slot
    // (`128 -> 127`). `schedule_panel_resync(2)` MUST run BEFORE `flush_pending_revokes`!
    let mut bad_snap = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Snapshot(make_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    bad_snap.in_reply_to = open2_wire.request_id;
    running.frame(bad_snap, &outgoing).await.unwrap();
    assert!(open2_rx.try_recv().unwrap().is_err());
    assert!(running.is_panel_resyncing(2));
    assert_eq!(
        running.pending_revokes.len(),
        1,
        "queued non-destroy CloseRequest must remain behind Resync barrier freed by reject_response"
    );
    assert!(
        wire.try_recv().is_err(),
        "CloseRequest must not leak ahead of scheduled child Resync"
    );

    // Drain main requests below CHILD_QUEUE_SOFT_LIMIT -> only Resync(2) flushes; CloseRequest stays queued.
    let mut seq = 3u64;
    while running.requests.len() >= CHILD_QUEUE_SOFT_LIMIT {
        let req_id = main_req_ids.pop().unwrap();
        let mut ack = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        );
        seq += 1;
        ack.in_reply_to = req_id;
        running.frame(ack, &outgoing).await.unwrap();
    }
    let resync_wire = wire.try_recv().unwrap();
    assert_eq!(resync_wire.panel_id, 2);
    assert!(matches!(resync_wire.body, Some(envelope::Body::Resync(_))));
    assert!(wire.try_recv().is_err());
    assert_eq!(running.pending_revokes.len(), 1);

    // Settling Resync releases the deferred CloseRequest!
    let mut resync_ack = Envelope::new(
        running.identity,
        seq,
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    resync_ack.in_reply_to = resync_wire.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();
    assert!(running.pending_revokes.is_empty());
    let close_wire = wire.try_recv().unwrap();
    assert_eq!(close_wire.panel_id, 2);
    assert!(matches!(
        close_wire.body,
        Some(envelope::Body::CloseRequest(ref c)) if !c.destroy_panel
    ));
    let mut close_ack = Envelope::new(
        running.identity,
        seq + 1,
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    close_ack.in_reply_to = close_wire.request_id;
    running.frame(close_ack, &outgoing).await.unwrap();
    assert!(rev_rx.try_recv().unwrap().is_ok());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn real_sdk_non_destroy_close_reordering_select_rejects_deferred_ui_event() {
    use std::io::{Read, Write};
    use std::sync::{Arc, Mutex};
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    struct BlockingReader(DuplexStream, tokio::runtime::Handle);
    impl Read for BlockingReader {
        fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.read(buf))
        }
    }
    struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
    impl Write for BlockingWriter {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.write(buf))
        }
        fn flush(&mut self) -> std::io::Result<()> {
            self.1.block_on(self.0.flush())
        }
    }

    struct SelectCloseReorderPlugin {
        seen_select_events: Arc<Mutex<Vec<u32>>>,
        ev0_entered: Arc<tokio::sync::Notify>,
        ev0_release: Arc<tokio::sync::Notify>,
        resync1_entered: Arc<tokio::sync::Notify>,
        resync1_release: Arc<tokio::sync::Notify>,
        rt: tokio::runtime::Handle,
    }

    impl SelectCloseReorderPlugin {
        fn make_snap(
            rev: u64,
            status: &str,
            ed_rev: u64,
            ed_bytes: Vec<u8>,
            opts: [&str; 2],
        ) -> PanelSnapshot {
            PanelSnapshot {
                revision: rev,
                title: "sdk-select-close".into(),
                root: Some(panel::Node::new(
                    3,
                    "col",
                    panel::node::Kind::Column(panel::Container {
                        children: vec![
                            panel::Node::new(
                                1,
                                "ed",
                                panel::node::Kind::Editor(panel::Editor {
                                    document_id: 1,
                                    revision: ed_rev,
                                    contents: ed_bytes,
                                    format: panel::EditorFormat::Utf8 as i32,
                                    read_only: false,
                                }),
                            ),
                            panel::Node::new(
                                2,
                                "status",
                                panel::node::Kind::Text(panel::Text {
                                    text: status.to_owned(),
                                    tone: panel::Tone::Foreground as i32,
                                }),
                            ),
                            panel::Node::new(
                                10,
                                "btn0",
                                panel::node::Kind::Button(panel::Button {
                                    label: "TriggerStale".into(),
                                    enabled: true,
                                    commit_editors: false,
                                }),
                            ),
                            panel::Node::new(
                                20,
                                "action-select",
                                panel::node::Kind::Select(panel::SelectNode {
                                    label: "Action".into(),
                                    options: opts.iter().map(|s| (*s).to_owned()).collect(),
                                    selected_index: 1,
                                    enabled: true,
                                }),
                            ),
                        ],
                    }),
                )),
            }
        }
    }

    impl mio_plugin_sdk::MioPlugin for SelectCloseReorderPlugin {
        fn id(&self) -> &str {
            "lab.sdk-select-close-reorder"
        }

        fn version(&self) -> &str {
            "1.5.0"
        }

        fn supports_panel_multiplexing(&self) -> bool {
            true
        }

        fn initial_panel(&self) -> PanelSnapshot {
            Self::make_snap(1, "main-init", 1, b"init".to_vec(), ["Allow", "Deny"])
        }

        fn on_panel_open_request(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            _open: protocol::OpenRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            let rev = ctx.next_panel_revision();
            Ok(Some(Self::make_snap(
                rev,
                "v1-old",
                1,
                b"init".to_vec(),
                ["Allow", "Deny"],
            )))
        }

        fn on_panel_ui_event(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            event: UiEvent,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            match (event.node_id, &event.event) {
                (10, Some(panel::ui_event::Event::Click(_))) => {
                    self.ev0_entered.notify_one();
                    self.rt.block_on(self.ev0_release.notified());
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        "stale-from-ev0",
                        1,
                        b"init".to_vec(),
                        ["Allow", "Deny"],
                    )));
                }
                (1, Some(panel::ui_event::Event::EditorChanged(ed))) => {
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        "v2-confirmed",
                        ed.revision,
                        ed.contents.clone(),
                        ["Allow", "Deny"],
                    )));
                }
                (20, Some(panel::ui_event::Event::SelectedOption(idx))) => {
                    self.seen_select_events.lock().unwrap().push(*idx);
                }
                _ => {}
            }
            Ok(None)
        }

        fn on_panel_resync(
            &mut self,
            _ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            snapshot: PanelSnapshot,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            let status_text = snapshot
                .root
                .as_ref()
                .and_then(|r| r.find(2))
                .and_then(|n| match &n.kind {
                    Some(panel::node::Kind::Text(t)) => Some(t.text.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            if status_text == "v1-old" {
                self.resync1_entered.notify_one();
                self.rt.block_on(self.resync1_release.notified());
            }
            Ok(None)
        }

        fn on_panel_close_request(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            close: protocol::CloseRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            assert!(!close.destroy_panel);
            let rev = ctx.next_panel_revision();
            Ok(Some(Self::make_snap(
                rev,
                "v2-closed-reordered",
                2,
                b"user-edit".to_vec(),
                ["Deny", "Allow"],
            )))
        }
    }

    let rt_handle = tokio::runtime::Handle::current();
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.sdk-select-close-reorder".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_tx, worker_rx) = tokio::io::duplex(64 * 1024);
    let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
    let seen_select_events = Arc::new(Mutex::new(Vec::new()));
    let seen_select_events_w = seen_select_events.clone();
    let ev0_entered = Arc::new(tokio::sync::Notify::new());
    let ev0_release = Arc::new(tokio::sync::Notify::new());
    let resync1_entered = Arc::new(tokio::sync::Notify::new());
    let resync1_release = Arc::new(tokio::sync::Notify::new());
    let ev0_entered_w = ev0_entered.clone();
    let ev0_release_w = ev0_release.clone();
    let resync1_entered_w = resync1_entered.clone();
    let resync1_release_w = resync1_release.clone();

    let worker_thread = std::thread::spawn(move || {
        let mut plugin = SelectCloseReorderPlugin {
            seen_select_events: seen_select_events_w,
            ev0_entered: ev0_entered_w,
            ev0_release: ev0_release_w,
            resync1_entered: resync1_entered_w,
            resync1_release: resync1_release_w,
            rt: rt_handle.clone(),
        };
        mio_plugin_sdk::run_with_io(
            BlockingReader(worker_rx, rt_handle.clone()),
            BlockingWriter(worker_tx, rt_handle),
            &mut plugin,
        )
        .unwrap();
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_tx,
        host_rx,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();
    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();

    let extract_status = |snap: &PanelSnapshot| -> String {
        snap.root
            .as_ref()
            .and_then(|r| r.find(2))
            .and_then(|n| match &n.kind {
                Some(panel::node::Kind::Text(t)) => Some(t.text.clone()),
                _ => None,
            })
            .unwrap_or_default()
    };

    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    timeout(
        MAX_OPERATION,
        handle.open_request_on_panel(2, primary, 1, false, request()),
    )
    .await
    .unwrap()
    .unwrap();

    // 1. Enter ev0 and advance confirmed state to v2 ("Allow", "Deny") via EditorChanged.
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 10,
                editors: vec![],
                event: Some(panel::ui_event::Event::Click(panel::Empty {})),
            },
        )
        .unwrap();
    timeout(MAX_OPERATION, ev0_entered.notified()).await.unwrap();
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 1,
                editors: vec![],
                event: Some(panel::ui_event::Event::EditorChanged(panel::EditorSnapshot {
                    document_id: 1,
                    revision: 2,
                    contents: b"user-edit".to_vec(),
                    selection_start: 0,
                    selection_end: 0,
                })),
            },
        )
        .unwrap();

    // 2. Release ev0 -> triggers Resync(1), worker confirms v2-confirmed, then pauses in Resync(1).
    ev0_release.notify_one();
    timeout(MAX_OPERATION, resync1_entered.notified()).await.unwrap();
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Panel { panel_id: 2, snapshot, .. }) =
                supervisor.events.recv().await
                && extract_status(&snapshot) == "v2-confirmed"
            {
                break;
            }
        }
    })
    .await
    .unwrap();

    // 3. While Resync is active:
    //    - Capture and defer `SelectedOption(0)` (meaning "Allow" on `v2-confirmed`)
    //    - Queue non-destroy `revoke_panel_resource(2, extra, false)` behind `Resync`
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 20,
                editors: vec![],
                event: Some(panel::ui_event::Event::SelectedOption(0)),
            },
        )
        .unwrap();
    let revoke_handle = handle.clone();
    let revoke_task = tokio::spawn(async move {
        revoke_handle.revoke_panel_resource(2, extra, false).await
    });
    tokio::time::sleep(Duration::from_millis(20)).await;
    resync1_release.notify_one();

    // CloseRequest settles with snapshot reordering Select to ["Deny", "Allow"],
    // so deferred `SelectedOption(0)` MUST wait for CloseRequest AND be rejected as Stale!
    timeout(MAX_OPERATION, revoke_task).await.unwrap().unwrap().unwrap();
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Error { panel_id: 2, failure, .. }) =
                supervisor.events.recv().await
                && failure.code == ErrorCode::Stale as i32
                && failure.message.contains("插件面板内容已更新")
            {
                break;
            }
        }
    })
    .await
    .unwrap();
    assert!(
        seen_select_events.lock().unwrap().is_empty(),
        "deferred SelectedOption must NOT execute on worker after CloseRequest reordered Select options"
    );

    supervisor.stop().await.unwrap();
    worker_thread.join().unwrap();
}

#[tokio::test]
async fn child_headroom_blocked_rechecks_recovered_outgoing_capacity() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("panel-r{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    let primary = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_wire = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = open_wire.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    let identity = running.identity;
    let fill_to_reserved = |tx: &mpsc::Sender<Envelope>| {
        while tx.capacity() > RESERVED_CONTROL_OUTGOING {
            let env = Envelope::new(
                identity,
                0,
                1,
                envelope::Body::Ack(panel::Empty {}),
                MAX_OPERATION,
            );
            tx.try_send(env).unwrap();
        }
        assert_eq!(tx.capacity(), RESERVED_CONTROL_OUTGOING);
    };

    // Part A: deferred child command blocked on outgoing capacity sets `child_headroom_blocked`.
    fill_to_reserved(&outgoing);
    running
        .panels
        .get_mut(&2)
        .unwrap()
        .deferred_commands
        .push_back(SequencedControl {
            seq: 0,
            command: Control::Event {
                panel_id: 2,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
        });
    running.child_headroom_blocked = false;
    running.flush_deferred_panel_commands(&outgoing).await.unwrap();
    assert_eq!(running.panels[&2].deferred_commands.len(), 1);
    assert!(running.child_headroom_blocked);

    // Writer drains 1 permit between flush and select! -> recheck condition triggers immediately.
    let _ = wire.try_recv().unwrap();
    assert!(running.child_headroom_blocked && outgoing.capacity() > RESERVED_CONTROL_OUTGOING);

    running.child_headroom_blocked = false;
    running.flush_deferred_panel_commands(&outgoing).await.unwrap();
    assert!(running.panels[&2].deferred_commands.is_empty());
    assert!(!running.child_headroom_blocked);
    while wire.try_recv().is_ok() {}

    // Part B: child pending Resync blocked on outgoing capacity also sets `child_headroom_blocked`.
    fill_to_reserved(&outgoing);
    running.schedule_panel_resync(2);
    running.child_headroom_blocked = false;
    running.flush_pending_resyncs(&outgoing).unwrap();
    assert!(running.is_panel_resyncing(2));
    assert!(running.child_headroom_blocked);

    let _ = wire.try_recv().unwrap();
    assert!(running.child_headroom_blocked && outgoing.capacity() > RESERVED_CONTROL_OUTGOING);

    running.child_headroom_blocked = false;
    running.flush_pending_resyncs(&outgoing).unwrap();
    assert!(!running.child_headroom_blocked);
    let mut saw_resync = false;
    while let Ok(env) = wire.try_recv() {
        if matches!(env.body, Some(envelope::Body::Resync(_))) {
            saw_resync = true;
        }
    }
    assert!(saw_resync);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn real_sdk_deferred_interactions_serialize_after_close_ack_and_reject_reordered_second_event() {
    use std::io::{Read, Write};
    use std::sync::{Arc, Mutex};
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    struct BlockingReader(DuplexStream, tokio::runtime::Handle);
    impl Read for BlockingReader {
        fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.read(buf))
        }
    }
    struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
    impl Write for BlockingWriter {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.write(buf))
        }
        fn flush(&mut self) -> std::io::Result<()> {
            self.1.block_on(self.0.flush())
        }
    }

    struct SerializedInteractionsPlugin {
        seen_clicks: Arc<Mutex<Vec<u32>>>,
        seen_selects: Arc<Mutex<Vec<u32>>>,
        close_entered: Arc<tokio::sync::Notify>,
        close_release: Arc<tokio::sync::Notify>,
        rt: tokio::runtime::Handle,
    }

    impl SerializedInteractionsPlugin {
        fn make_snap(rev: u64, status: &str, opts: [&str; 2]) -> PanelSnapshot {
            PanelSnapshot {
                revision: rev,
                title: "sdk-close-ack-serialize".into(),
                root: Some(panel::Node::new(
                    3,
                    "col",
                    panel::node::Kind::Column(panel::Container {
                        children: vec![
                            panel::Node::new(
                                1,
                                "ed",
                                panel::node::Kind::Editor(panel::Editor {
                                    document_id: 1,
                                    revision: 1,
                                    contents: b"init".to_vec(),
                                    format: panel::EditorFormat::Utf8 as i32,
                                    read_only: false,
                                }),
                            ),
                            panel::Node::new(
                                2,
                                "status",
                                panel::node::Kind::Text(panel::Text {
                                    text: status.to_owned(),
                                    tone: panel::Tone::Foreground as i32,
                                }),
                            ),
                            panel::Node::new(
                                11,
                                "btn-reorder",
                                panel::node::Kind::Button(panel::Button {
                                    label: "ReorderSelect".into(),
                                    enabled: true,
                                    commit_editors: false,
                                }),
                            ),
                            panel::Node::new(
                                20,
                                "action-select",
                                panel::node::Kind::Select(panel::SelectNode {
                                    label: "Action".into(),
                                    options: opts.iter().map(|s| (*s).to_owned()).collect(),
                                    selected_index: 1,
                                    enabled: true,
                                }),
                            ),
                        ],
                    }),
                )),
            }
        }
    }

    impl mio_plugin_sdk::MioPlugin for SerializedInteractionsPlugin {
        fn id(&self) -> &str {
            "lab.sdk-close-ack-serialize"
        }

        fn version(&self) -> &str {
            "1.5.0"
        }

        fn supports_panel_multiplexing(&self) -> bool {
            true
        }

        fn initial_panel(&self) -> PanelSnapshot {
            Self::make_snap(1, "main-init", ["Allow", "Deny"])
        }

        fn on_panel_open_request(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            _open: protocol::OpenRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            let rev = ctx.next_panel_revision();
            Ok(Some(Self::make_snap(rev, "v1-open", ["Allow", "Deny"])))
        }

        fn on_panel_close_request(
            &mut self,
            _ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            close: protocol::CloseRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            assert!(!close.destroy_panel);
            self.close_entered.notify_one();
            self.rt.block_on(self.close_release.notified());
            Ok(None)
        }

        fn on_panel_ui_event(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            event: UiEvent,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            match (event.node_id, &event.event) {
                (11, Some(panel::ui_event::Event::Click(_))) => {
                    self.seen_clicks.lock().unwrap().push(11);
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        "v2-reordered",
                        ["Deny", "Allow"],
                    )));
                }
                (20, Some(panel::ui_event::Event::SelectedOption(idx))) => {
                    self.seen_selects.lock().unwrap().push(*idx);
                }
                _ => {}
            }
            Ok(None)
        }
    }

    let rt_handle = tokio::runtime::Handle::current();
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.sdk-close-ack-serialize".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_tx, worker_rx) = tokio::io::duplex(64 * 1024);
    let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
    let seen_clicks = Arc::new(Mutex::new(Vec::new()));
    let seen_selects = Arc::new(Mutex::new(Vec::new()));
    let close_entered = Arc::new(tokio::sync::Notify::new());
    let close_release = Arc::new(tokio::sync::Notify::new());
    let seen_clicks_w = seen_clicks.clone();
    let seen_selects_w = seen_selects.clone();
    let close_entered_w = close_entered.clone();
    let close_release_w = close_release.clone();

    let worker_thread = std::thread::spawn(move || {
        let mut plugin = SerializedInteractionsPlugin {
            seen_clicks: seen_clicks_w,
            seen_selects: seen_selects_w,
            close_entered: close_entered_w,
            close_release: close_release_w,
            rt: rt_handle.clone(),
        };
        mio_plugin_sdk::run_with_io(
            BlockingReader(worker_rx, rt_handle.clone()),
            BlockingWriter(worker_tx, rt_handle),
            &mut plugin,
        )
        .unwrap();
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_tx,
        host_rx,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();
    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();

    let _ = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    timeout(
        MAX_OPERATION,
        handle.open_request_on_panel(2, primary, 1, false, request()),
    )
    .await
    .unwrap()
    .unwrap();

    // Start non-destroy CloseRequest -> worker pauses inside on_panel_close_request before Ack.
    let revoke_handle = handle.clone();
    let revoke_task = tokio::spawn(async move {
        revoke_handle.revoke_panel_resource(2, extra, false).await
    });
    timeout(MAX_OPERATION, close_entered.notified()).await.unwrap();

    // Queue TWO interactions on panel 2 behind the close barrier against `["Allow", "Deny"]`:
    // 1) Click(11) which will reorder Select options to ["Deny", "Allow"],
    // 2) SelectedOption(0) captured against the old ["Allow", "Deny"] view.
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 11,
                editors: vec![],
                event: Some(panel::ui_event::Event::Click(panel::Empty {})),
            },
        )
        .unwrap();
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 20,
                editors: vec![],
                event: Some(panel::ui_event::Event::SelectedOption(0)),
            },
        )
        .unwrap();
    tokio::time::sleep(Duration::from_millis(30)).await;
    close_release.notify_one();

    // Close Ack settles, then Click(11) ONLY runs -> returns reordered Snapshot ->
    // SelectedOption(0) MUST wait for Click(11)'s Snapshot and be rejected as Stale!
    timeout(MAX_OPERATION, revoke_task).await.unwrap().unwrap().unwrap();
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Error { panel_id: 2, failure, .. }) =
                supervisor.events.recv().await
                && failure.code == ErrorCode::Stale as i32
                && failure.message.contains("插件面板内容已更新")
            {
                break;
            }
        }
    })
    .await
    .unwrap();

    supervisor.stop().await.unwrap();
    worker_thread.join().unwrap();
    assert_eq!(*seen_clicks.lock().unwrap(), vec![11]);
    assert!(
        seen_selects.lock().unwrap().is_empty(),
        "second deferred SelectedOption must NEVER run on SDK after first deferred interaction reordered options"
    );
}

#[tokio::test]
async fn single_capacity_sample_sets_child_headroom_blocked_when_writer_drains_mid_check() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("panel-r{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    let primary = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_wire = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = open_wire.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    let identity = running.identity;
    let fill_to_reserved = |tx: &mpsc::Sender<Envelope>| {
        while tx.capacity() > RESERVED_CONTROL_OUTGOING {
            let env = Envelope::new(
                identity,
                0,
                1,
                envelope::Body::Ack(panel::Empty {}),
                MAX_OPERATION,
            );
            tx.try_send(env).unwrap();
        }
        assert_eq!(tx.capacity(), RESERVED_CONTROL_OUTGOING);
    };

    // Part A: writer drains ONE permit immediately AFTER `flush_deferred_panel_commands_with`'s
    // single capacity sample -> must sample ONLY ONCE and still set `child_headroom_blocked = true`.
    fill_to_reserved(&outgoing);
    running
        .panels
        .get_mut(&2)
        .unwrap()
        .deferred_commands
        .push_back(SequencedControl {
            seq: 0,
            command: Control::Event {
                panel_id: 2,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
        });
    running.child_headroom_blocked = false;
    let mut cmd_reads = 0usize;
    running
        .flush_deferred_panel_commands_with(&outgoing, |tx| {
            cmd_reads += 1;
            let cap = tx.capacity();
            if cmd_reads == 1 {
                let _ = wire.try_recv();
            }
            cap
        })
        .await
        .unwrap();
    assert_eq!(cmd_reads, 1);
    assert_eq!(running.panels[&2].deferred_commands.len(), 1);
    assert!(running.child_headroom_blocked);
    assert!(outgoing.capacity() > RESERVED_CONTROL_OUTGOING);

    running.child_headroom_blocked = false;
    running.flush_deferred_panel_commands(&outgoing).await.unwrap();
    assert!(running.panels[&2].deferred_commands.is_empty());
    assert!(!running.child_headroom_blocked);
    while wire.try_recv().is_ok() {}
    running.requests.clear();

    // Part B: identical mid-check writer drain during `flush_pending_resyncs_with`.
    fill_to_reserved(&outgoing);
    running.schedule_panel_resync(2);
    running.child_headroom_blocked = false;
    let mut resync_reads = 0usize;
    running
        .flush_pending_resyncs_with(&outgoing, |tx| {
            resync_reads += 1;
            let cap = tx.capacity();
            if resync_reads == 1 {
                let _ = wire.try_recv();
            }
            cap
        })
        .unwrap();
    assert_eq!(resync_reads, 1);
    assert!(running.is_panel_resyncing(2));
    assert!(running.child_headroom_blocked);
    assert!(outgoing.capacity() > RESERVED_CONTROL_OUTGOING);

    running.child_headroom_blocked = false;
    running.flush_pending_resyncs(&outgoing).unwrap();
    assert!(!running.child_headroom_blocked);
    let mut saw_resync = false;
    while let Ok(env) = wire.try_recv() {
        if matches!(env.body, Some(envelope::Body::Resync(_))) {
            saw_resync = true;
        }
    }
    assert!(saw_resync);
}

#[tokio::test]
async fn revoke_and_cancel_op_precede_deferred_flush_after_capacity_recovery() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("panel-r{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let open_child = |panel_id: u64, res: Uuid, seq: u64| {
        (panel_id, res, seq)
    };
    for &(panel_id, res, seq) in &[
        open_child(2, Uuid::new_v4(), 1),
        open_child(3, Uuid::new_v4(), 2),
        open_child(4, Uuid::new_v4(), 3),
    ] {
        let (open_tx, open_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id,
                    id: res,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: open_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ow = wire.try_recv().unwrap();
        let mut snap = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Snapshot(make_snap(1)),
            MAX_OPERATION,
        )
        .with_panel_id(panel_id);
        snap.in_reply_to = ow.request_id;
        running.frame(snap, &outgoing).await.unwrap();
        assert!(open_rx.await.is_ok());
    }

    // Subcase A: panel 2 has deferred `Open(extra)` + `Event(Focus)` queued during capacity saturation.
    // Once capacity recovers AND `Control::Revoke(2, extra, false)` arrives before the next loop flush,
    // `Open(extra)` MUST be cancelled BEFORE any flush and MUST NEVER emit onto `wire`.
    let extra = Uuid::new_v4();
    let (open_extra_tx, mut open_extra_rx) = oneshot::channel();
    {
        let slot2 = running.panels.get_mut(&2).unwrap();
        slot2.deferred_commands.push_back(SequencedControl {
            seq: 0,
            command: Control::Open {
                panel_id: 2,
                id: extra,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_extra_tx,
            },
        });
        slot2.deferred_commands.push_back(SequencedControl {
            seq: 0,
            command: Control::Event {
                panel_id: 2,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
        });
    }
    let (rev2_tx, mut rev2_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 2,
                id: extra,
                remove_panel: false,
                reply: rev2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(open_extra_rx.try_recv().unwrap().is_err());
    let close2 = wire.try_recv().unwrap();
    assert_eq!(close2.panel_id, 2);
    assert!(matches!(
        close2.body,
        Some(envelope::Body::CloseRequest(ref c)) if !c.destroy_panel
    ));
    assert!(
        wire.try_recv().is_err(),
        "neither cancelled Open(extra) nor deferred UiEvent behind close may emit while CloseRequest is in flight"
    );
    let mut ack2 = Envelope::new(
        running.identity,
        10,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    ack2.in_reply_to = close2.request_id;
    running.frame(ack2, &outgoing).await.unwrap();
    assert!(rev2_rx.try_recv().unwrap().is_ok());
    let focus2 = wire.try_recv().unwrap();
    assert_eq!(focus2.panel_id, 2);
    assert!(matches!(focus2.body, Some(envelope::Body::UiEvent(_))));

    // Subcase B: panel 3 has deferred `Event(Focus)` + pending resync; capacity recovers when
    // `Control::Revoke(3, res, true)` arrives -> ONLY `CloseRequest(destroy_panel=true)` emits!
    let (p3_res, _) = running.panels[&3].active_resource.unwrap();
    running
        .panels
        .get_mut(&3)
        .unwrap()
        .deferred_commands
        .push_back(SequencedControl {
            seq: 0,
            command: Control::Event {
                panel_id: 3,
                event: panel::UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
        });
    running.schedule_panel_resync(3);
    let (rev3_tx, _rev3_rx) = oneshot::channel();
    running
        .control(
            Control::Revoke {
                panel_id: 3,
                id: p3_res,
                remove_panel: true,
                reply: rev3_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close3 = wire.try_recv().unwrap();
    assert_eq!(close3.panel_id, 3);
    assert!(matches!(
        close3.body,
        Some(envelope::Body::CloseRequest(ref c)) if c.destroy_panel
    ));
    assert!(
        wire.try_recv().is_err(),
        "destroying revoke must emit neither deferred UiEvent nor Resync after capacity recovery"
    );
    assert!(running.panels[&3].deferred_commands.is_empty());

    // Subcase C: panel 4 has deferred `Control::Commit`; capacity recovers when
    // `Control::CancelPanelOp(4, op_id)` arrives -> cancelled BEFORE flush, zero `CommitEditor` emitted!
    let (p4_res, p4_msg_rev) = running.panels[&4].active_resource.unwrap();
    let op_id = Uuid::new_v4();
    let (commit_tx, mut commit_rx) = oneshot::channel();
    running
        .panels
        .get_mut(&4)
        .unwrap()
        .deferred_commands
        .push_back(SequencedControl {
            seq: 0,
            command: Control::Commit {
                panel_id: 4,
                op_id,
                request: CommitEditor {
                    resource_id: p4_res.as_bytes().to_vec(),
                    message_revision: p4_msg_rev,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: commit_tx,
                            expected_snapshot: None,
            },
        });
    running
        .control(Control::CancelPanelOp { panel_id: 4, op_id }, &outgoing)
        .await
        .unwrap();
    assert!(commit_rx.try_recv().unwrap().is_err());
    assert!(wire.try_recv().is_err());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn real_sdk_empty_deferred_queue_still_blocks_new_event_until_inflight_deferred_click_settles() {
    use std::io::{Read, Write};
    use std::sync::{Arc, Mutex};
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    struct BlockingReader(DuplexStream, tokio::runtime::Handle);
    impl Read for BlockingReader {
        fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.read(buf))
        }
    }
    struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
    impl Write for BlockingWriter {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.write(buf))
        }
        fn flush(&mut self) -> std::io::Result<()> {
            self.1.block_on(self.0.flush())
        }
    }

    struct DeferredEntryBarrierPlugin {
        seen_clicks: Arc<Mutex<Vec<u32>>>,
        seen_selects: Arc<Mutex<Vec<u32>>>,
        close_entered: Arc<tokio::sync::Notify>,
        close_release: Arc<tokio::sync::Notify>,
        click_entered: Arc<tokio::sync::Notify>,
        click_release: Arc<tokio::sync::Notify>,
        rt: tokio::runtime::Handle,
    }

    impl DeferredEntryBarrierPlugin {
        fn make_snap(rev: u64, status: &str, opts: [&str; 2]) -> PanelSnapshot {
            PanelSnapshot {
                revision: rev,
                title: "sdk-entry-barrier".into(),
                root: Some(panel::Node::new(
                    3,
                    "col",
                    panel::node::Kind::Column(panel::Container {
                        children: vec![
                            panel::Node::new(
                                1,
                                "ed",
                                panel::node::Kind::Editor(panel::Editor {
                                    document_id: 1,
                                    revision: 1,
                                    contents: b"init".to_vec(),
                                    format: panel::EditorFormat::Utf8 as i32,
                                    read_only: false,
                                }),
                            ),
                            panel::Node::new(
                                2,
                                "status",
                                panel::node::Kind::Text(panel::Text {
                                    text: status.to_owned(),
                                    tone: panel::Tone::Foreground as i32,
                                }),
                            ),
                            panel::Node::new(
                                11,
                                "btn-reorder",
                                panel::node::Kind::Button(panel::Button {
                                    label: "ReorderSelect".into(),
                                    enabled: true,
                                    commit_editors: false,
                                }),
                            ),
                            panel::Node::new(
                                20,
                                "action-select",
                                panel::node::Kind::Select(panel::SelectNode {
                                    label: "Action".into(),
                                    options: opts.iter().map(|s| (*s).to_owned()).collect(),
                                    selected_index: 1,
                                    enabled: true,
                                }),
                            ),
                        ],
                    }),
                )),
            }
        }
    }

    impl mio_plugin_sdk::MioPlugin for DeferredEntryBarrierPlugin {
        fn id(&self) -> &str {
            "lab.sdk-entry-barrier"
        }

        fn version(&self) -> &str {
            "1.5.0"
        }

        fn supports_panel_multiplexing(&self) -> bool {
            true
        }

        fn initial_panel(&self) -> PanelSnapshot {
            Self::make_snap(1, "main-init", ["Allow", "Deny"])
        }

        fn on_panel_open_request(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            _open: protocol::OpenRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            let rev = ctx.next_panel_revision();
            Ok(Some(Self::make_snap(rev, "v1-open", ["Allow", "Deny"])))
        }

        fn on_panel_close_request(
            &mut self,
            _ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            close: protocol::CloseRequest,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            assert!(!close.destroy_panel);
            self.close_entered.notify_one();
            self.rt.block_on(self.close_release.notified());
            Ok(None)
        }

        fn on_panel_ui_event(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            _panel_id: u64,
            event: UiEvent,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            match (event.node_id, &event.event) {
                (11, Some(panel::ui_event::Event::Click(_))) => {
                    self.seen_clicks.lock().unwrap().push(11);
                    self.click_entered.notify_one();
                    self.rt.block_on(self.click_release.notified());
                    let rev = ctx.next_panel_revision();
                    return Ok(Some(Self::make_snap(
                        rev,
                        "v2-reordered",
                        ["Deny", "Allow"],
                    )));
                }
                (20, Some(panel::ui_event::Event::SelectedOption(idx))) => {
                    self.seen_selects.lock().unwrap().push(*idx);
                }
                _ => {}
            }
            Ok(None)
        }
    }

    let rt_handle = tokio::runtime::Handle::current();
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.sdk-entry-barrier".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_tx, worker_rx) = tokio::io::duplex(64 * 1024);
    let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
    let seen_clicks = Arc::new(Mutex::new(Vec::new()));
    let seen_selects = Arc::new(Mutex::new(Vec::new()));
    let close_entered = Arc::new(tokio::sync::Notify::new());
    let close_release = Arc::new(tokio::sync::Notify::new());
    let click_entered = Arc::new(tokio::sync::Notify::new());
    let click_release = Arc::new(tokio::sync::Notify::new());
    let seen_clicks_w = seen_clicks.clone();
    let seen_selects_w = seen_selects.clone();
    let close_entered_w = close_entered.clone();
    let close_release_w = close_release.clone();
    let click_entered_w = click_entered.clone();
    let click_release_w = click_release.clone();

    let worker_thread = std::thread::spawn(move || {
        let mut plugin = DeferredEntryBarrierPlugin {
            seen_clicks: seen_clicks_w,
            seen_selects: seen_selects_w,
            close_entered: close_entered_w,
            close_release: close_release_w,
            click_entered: click_entered_w,
            click_release: click_release_w,
            rt: rt_handle.clone(),
        };
        mio_plugin_sdk::run_with_io(
            BlockingReader(worker_rx, rt_handle.clone()),
            BlockingWriter(worker_tx, rt_handle),
            &mut plugin,
        )
        .unwrap();
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_tx,
        host_rx,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();
    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();

    let _ = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    timeout(
        MAX_OPERATION,
        handle.open_request_on_panel(2, primary, 1, false, request()),
    )
    .await
    .unwrap()
    .unwrap();

    // 1. Pause non-destroy CloseRequest inside worker; queue ONLY ONE Click(11) behind it.
    let revoke_handle = handle.clone();
    let revoke_task = tokio::spawn(async move {
        revoke_handle.revoke_panel_resource(2, extra, false).await
    });
    timeout(MAX_OPERATION, close_entered.notified()).await.unwrap();
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 11,
                editors: vec![],
                event: Some(panel::ui_event::Event::Click(panel::Empty {})),
            },
        )
        .unwrap();
    tokio::time::sleep(Duration::from_millis(20)).await;

    // 2. Release CloseRequest -> Click(11) pops (deferred queue is now EMPTY!), enters worker and blocks.
    close_release.notify_one();
    timeout(MAX_OPERATION, revoke_task).await.unwrap().unwrap().unwrap();
    timeout(MAX_OPERATION, click_entered.notified()).await.unwrap();

    // 3. While deferred_commands is EMPTY and Click(11) (from_deferred_queue=true) is still in flight,
    //    send a fresh SelectedOption(0) -> MUST defer behind Click(11)'s entry barrier!
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 20,
                editors: vec![],
                event: Some(panel::ui_event::Event::SelectedOption(0)),
            },
        )
        .unwrap();
    tokio::time::sleep(Duration::from_millis(30)).await;
    click_release.notify_one();

    // 4. Click(11) returns reordered Select(["Deny", "Allow"]) -> SelectedOption(0) MUST fail Stale
    //    and never reach the SDK worker!
    timeout(MAX_OPERATION, async {
        loop {
            if let Some(PluginEvent::Error { panel_id: 2, failure, .. }) =
                supervisor.events.recv().await
                && failure.code == ErrorCode::Stale as i32
                && failure.message.contains("插件面板内容已更新")
            {
                break;
            }
        }
    })
    .await
    .unwrap();

    supervisor.stop().await.unwrap();
    worker_thread.join().unwrap();
    assert_eq!(*seen_clicks.lock().unwrap(), vec![11]);
    assert!(
        seen_selects.lock().unwrap().is_empty(),
        "new SelectedOption arriving while deferred Click was in flight must not overtake and run against reordered options"
    );
}

#[tokio::test]
async fn real_duplex_supervisor_prioritizes_queued_revoke_over_deferred_open_on_capacity_recovery() {
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.revoke-priority-recovery".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let pause_reading = Arc::new(tokio::sync::Notify::new());
    let send_ack_and_fill_events = Arc::new(tokio::sync::Notify::new());
    let resume_reading = Arc::new(tokio::sync::Notify::new());
    let results_drained = Arc::new(tokio::sync::Notify::new());
    let pause_reading_w = pause_reading.clone();
    let send_ack_w = send_ack_and_fill_events.clone();
    let resume_reading_w = resume_reading.clone();
    let results_drained_w = results_drained.clone();

    let send_frame = move |_tx: &mut tokio::io::DuplexStream,
                      seq: &mut u64,
                      panel_id: u64,
                      rev: u64,
                      in_reply_to: u64,
                      body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let host_call_count = OUTGOING_CAPACITY - RESERVED_CONTROL_OUTGOING + 8;
    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut worker_tx,
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.revoke-priority-recovery".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let open2 = read_async_frame(&mut worker_rx).await?;
        let s1 = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            1,
            open2.request_id,
            envelope::Body::Snapshot(make_snap(1, "c2-v1")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s1)?).await?;
        let s2 = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            2,
            0,
            envelope::Body::Snapshot(make_snap(2, "c2-v2")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s2)?).await?;
        let stale = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            1,
            0,
            envelope::Body::Snapshot(make_snap(1, "c2-stale")),
        );
        worker_tx.write_all(&protocol::encode_frame(&stale)?).await?;
        worker_tx.flush().await?;

        let resync = read_async_frame(&mut worker_rx).await?;
        ensure!(matches!(resync.body, Some(envelope::Body::Resync(_))));

        // Pause reading worker_rx while test queues `open_extra` behind Resync(2).
        pause_reading_w.notify_one();
        send_ack_w.notified().await;

        // 1) Saturate host outgoing with invalid-parent HostCalls (HostResult replies fill pipe & outgoing),
        // 2) Settle Resync(2) via Ack(2) so `open_extra` stays in deferred_commands blocked on headroom,
        // 3) Saturate host->supervisor `events` channel so Running blocks inside `self.events.send`!
        for _ in 0..host_call_count {
            let hc = send_frame(
                &mut worker_tx,
                &mut out_seq,
                2,
                2,
                0,
                envelope::Body::HostCall(HostCall {
                    operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
                        offset: 0,
                        limit: 1,
                        filter: String::new(),
                    })),
                    parent_request_id: 999_999,
                }),
            );
            worker_tx.write_all(&protocol::encode_frame(&hc)?).await?;
        }
        let ack = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            2,
            resync.request_id,
            envelope::Body::Ack(panel::Empty {}),
        );
        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
        for _ in 0..(QUEUE_CAPACITY + 2) {
            let err_ev = send_frame(
                &mut worker_tx,
                &mut out_seq,
                2,
                2,
                0,
                envelope::Body::Error(Failure::new(ErrorCode::Internal, "fill-events")),
            );
            worker_tx.write_all(&protocol::encode_frame(&err_ev)?).await?;
        }
        worker_tx.flush().await?;

        // Resume reading ONLY until all HostResults are drained -> `outgoing` capacity fully recovers!
        resume_reading_w.notified().await;
        let mut seen_results = 0usize;
        let mut saw_open_extra = false;
        let close_req = loop {
            let env = read_async_frame(&mut worker_rx).await?;
            match env.body {
                Some(envelope::Body::HostResult(_)) => {
                    seen_results += 1;
                    if seen_results == host_call_count {
                        results_drained_w.notify_one();
                    }
                }
                Some(envelope::Body::OpenRequest(_)) => {
                    saw_open_extra = true;
                }
                Some(envelope::Body::CloseRequest(ref c)) => {
                    ensure!(!c.destroy_panel);
                    break env;
                }
                _ => {}
            }
        };
        ensure!(
            !saw_open_extra,
            "deferred Open(extra) must NOT overtake queued Revoke when capacity recovers"
        );
        let close_ack = send_frame(
            &mut worker_tx,
            &mut out_seq,
            2,
            2,
            close_req.request_id,
            envelope::Body::Ack(panel::Empty {}),
        );
        worker_tx.write_all(&protocol::encode_frame(&close_ack)?).await?;
        worker_tx.flush().await?;

        loop {
            match read_async_frame(&mut worker_rx).await {
                Ok(env) if matches!(env.body, Some(envelope::Body::Shutdown(_))) => break,
                Ok(env) => {
                    ensure!(!matches!(env.body, Some(envelope::Body::OpenRequest(_))));
                }
                Err(_) => break,
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    handle
        .open_request_on_panel(2, primary, 1, false, request())
        .await
        .unwrap();
    while supervisor.events.try_recv().is_ok() {}

    // Queue `open_extra` behind Resync(2), then pause Running on full `supervisor.events`.
    timeout(MAX_OPERATION, pause_reading.notified()).await.unwrap();
    let open_handle = handle.clone();
    let mut open_extra_task = tokio::spawn(async move {
        open_handle
            .open_request_on_panel(2, extra, 1, false, request())
            .await
    });
    tokio::time::sleep(Duration::from_millis(30)).await;
    send_ack_and_fill_events.notify_one();
    tokio::time::sleep(Duration::from_millis(80)).await;

    // Drain outgoing completely so outbound capacity + write_progress_rx are ready WHILE Running
    // is still blocked in `events.send`, then enqueue `Control::Revoke(extra, false)` into `commands`!
    resume_reading.notify_one();
    timeout(MAX_OPERATION, results_drained.notified()).await.unwrap();
    let revoke_handle = handle.clone();
    let mut revoke_task = tokio::spawn(async move {
        revoke_handle.revoke_panel_resource(2, extra, false).await
    });
    tokio::time::sleep(Duration::from_millis(20)).await;

    // Unblock `Running::run` by draining `supervisor.events`: BOTH outbound capacity recovery AND
    // queued `Control::Revoke` are simultaneously ready -> Revoke MUST win cleanly!
    let mut revoke_res = None;
    let mut open_res = None;
    timeout(MAX_OPERATION, async {
        while revoke_res.is_none() || open_res.is_none() {
            tokio::select! {
                res = &mut revoke_task, if revoke_res.is_none() => {
                    revoke_res = Some(res.unwrap());
                }
                res = &mut open_extra_task, if open_res.is_none() => {
                    open_res = Some(res.unwrap());
                }
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap();
    while supervisor.events.try_recv().is_ok() {}
    revoke_res.unwrap().unwrap();
    assert!(open_res.unwrap().is_err());

    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn real_duplex_supervisor_full_control_queue_revoke_cancels_queued_and_deferred_opens() {
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.full-ctrl-revoke".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let pause_reading = Arc::new(tokio::sync::Notify::new());
    let send_ack_and_fill_events = Arc::new(tokio::sync::Notify::new());
    let resume_reading = Arc::new(tokio::sync::Notify::new());
    let results_drained = Arc::new(tokio::sync::Notify::new());
    let pause_reading_w = pause_reading.clone();
    let send_ack_w = send_ack_and_fill_events.clone();
    let resume_reading_w = resume_reading.clone();
    let results_drained_w = results_drained.clone();

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let host_call_count = OUTGOING_CAPACITY - RESERVED_CONTROL_OUTGOING + 8;
    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.full-ctrl-revoke".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let open2 = read_async_frame(&mut worker_rx).await?;
        let s1 = send_frame(
            &mut out_seq,
            2,
            1,
            open2.request_id,
            envelope::Body::Snapshot(make_snap(1, "c2-v1")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s1)?).await?;
        let s2 = send_frame(
            &mut out_seq,
            2,
            2,
            0,
            envelope::Body::Snapshot(make_snap(2, "c2-v2")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s2)?).await?;
        let stale = send_frame(
            &mut out_seq,
            2,
            1,
            0,
            envelope::Body::Snapshot(make_snap(1, "c2-stale")),
        );
        worker_tx.write_all(&protocol::encode_frame(&stale)?).await?;
        worker_tx.flush().await?;

        let resync = read_async_frame(&mut worker_rx).await?;
        ensure!(matches!(resync.body, Some(envelope::Body::Resync(_))));

        pause_reading_w.notify_one();
        send_ack_w.notified().await;

        for _ in 0..host_call_count {
            let hc = send_frame(
                &mut out_seq,
                2,
                2,
                0,
                envelope::Body::HostCall(HostCall {
                    operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
                        offset: 0,
                        limit: 1,
                        filter: String::new(),
                    })),
                    parent_request_id: 999_999,
                }),
            );
            worker_tx.write_all(&protocol::encode_frame(&hc)?).await?;
        }
        let ack = send_frame(
            &mut out_seq,
            2,
            2,
            resync.request_id,
            envelope::Body::Ack(panel::Empty {}),
        );
        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
        for _ in 0..(QUEUE_CAPACITY + 2) {
            let err_ev = send_frame(
                &mut out_seq,
                2,
                2,
                0,
                envelope::Body::Error(Failure::new(ErrorCode::Internal, "fill-events")),
            );
            worker_tx.write_all(&protocol::encode_frame(&err_ev)?).await?;
        }
        worker_tx.flush().await?;

        resume_reading_w.notified().await;
        let mut seen_results = 0usize;
        let mut acked_main_events = 0usize;
        let mut close_count = 0usize;
        loop {
            match read_async_frame(&mut worker_rx).await {
                Ok(env) => match env.body {
                    Some(envelope::Body::Shutdown(_)) => break,
                    Some(envelope::Body::HostResult(_)) => {
                        seen_results += 1;
                        if seen_results == host_call_count {
                            results_drained_w.notify_one();
                        }
                    }
                    Some(envelope::Body::CloseRequest(ref c)) => {
                        ensure!(!c.destroy_panel);
                        close_count += 1;
                        let close_ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            2,
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&close_ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::OpenRequest(ref open)) => {
                        ensure!(
                            open.message_revision == 2 && close_count == 2,
                            "pre-revoke OpenRequest (rev={}) leaked past urgent Revoke (close_count={close_count})",
                            open.message_revision
                        );
                        let snap = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            3,
                            env.request_id,
                            envelope::Body::Snapshot(make_snap(3, "c2-reopened-after-revoke")),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::UiEvent(_)) if acked_main_events < 48 => {
                        acked_main_events += 1;
                        let ev_ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&ev_ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    _ => {}
                },
                Err(_) => break,
            }
        }
        ensure!(close_count == 2, "expected both CloseRequests, saw {close_count}");
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let primary = Uuid::new_v4();
    let extra_deferred = Uuid::new_v4();
    let extra_head = Uuid::new_v4();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    handle
        .open_request_on_panel(2, primary, 1, false, request())
        .await
        .unwrap();

    // 1. Queue `open_deferred_task` behind Resync(2), then pause Running on full `supervisor.events`.
    timeout(MAX_OPERATION, pause_reading.notified()).await.unwrap();
    let open_deferred_handle = handle.clone();
    let mut open_deferred_task = tokio::spawn(async move {
        open_deferred_handle
            .open_request_on_panel(2, extra_deferred, 1, false, request())
            .await
    });
    tokio::time::sleep(Duration::from_millis(30)).await;
    while supervisor.events.try_recv().is_ok() {}
    send_ack_and_fill_events.notify_one();
    tokio::time::sleep(Duration::from_millis(80)).await;

    // 2. While Running is paused in `events.send`, fill ALL 128 slots of `handle.control`:
    //    head slot = `open_head_task`, trailing 127 slots = main-panel Focus events.
    let open_head_handle = handle.clone();
    let mut open_head_task = tokio::spawn(async move {
        open_head_handle
            .open_request_on_panel(2, extra_head, 1, false, request())
            .await
    });
    tokio::time::sleep(Duration::from_millis(15)).await;
    for i in 0..(QUEUE_CAPACITY - 1) {
        handle
            .try_event(panel::UiEvent {
                node_id: 1,
                editors: vec![],
                event: Some(panel::ui_event::Event::Focus(true)),
            })
            .unwrap_or_else(|e| panic!("failed filling control slot {i}: {e}"));
    }
    assert!(
        handle
            .try_event(panel::UiEvent {
                node_id: 1,
                editors: vec![],
                event: Some(panel::ui_event::Event::Focus(true)),
            })
            .is_err(),
        "control channel must be 128/128 full before sending urgent revokes"
    );

    // 3. Drain all HostResults so outbound capacity recovers, then enqueue BOTH urgent revokes
    //    via `urgent_control` (succeeding even though `control` is 128/128 full!).
    resume_reading.notify_one();
    timeout(MAX_OPERATION, results_drained.notified()).await.unwrap();
    let rev_def_handle = handle.clone();
    let mut revoke_deferred = tokio::spawn(async move {
        rev_def_handle.revoke_panel_resource(2, extra_deferred, false).await
    });
    let rev_head_handle = handle.clone();
    let mut revoke_head = tokio::spawn(async move {
        rev_head_handle.revoke_panel_resource(2, extra_head, false).await
    });
    tokio::time::sleep(Duration::from_millis(20)).await;

    // 4. Resume Running by draining `supervisor.events`: both pre-revoke Opens MUST fail,
    //    both Revokes MUST complete Ok(()), and neither pre-revoke Open may ever hit worker_rx!
    let mut rev_def_res = None;
    let mut rev_head_res = None;
    let mut open_def_res = None;
    let mut open_head_res = None;
    timeout(MAX_OPERATION, async {
        while rev_def_res.is_none()
            || rev_head_res.is_none()
            || open_def_res.is_none()
            || open_head_res.is_none()
        {
            tokio::select! {
                res = &mut revoke_deferred, if rev_def_res.is_none() => rev_def_res = Some(res.unwrap()),
                res = &mut revoke_head, if rev_head_res.is_none() => rev_head_res = Some(res.unwrap()),
                res = &mut open_deferred_task, if open_def_res.is_none() => open_def_res = Some(res.unwrap()),
                res = &mut open_head_task, if open_head_res.is_none() => open_head_res = Some(res.unwrap()),
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap();
    rev_def_res.unwrap().unwrap();
    rev_head_res.unwrap().unwrap();
    assert!(open_def_res.unwrap().is_err());
    assert!(open_head_res.unwrap().is_err());

    // 5. Causal ordering preserves explicit post-revoke reopen (`seq > revoke_head.seq`).
    let reopen_handle = handle.clone();
    let mut reopen_task = tokio::spawn(async move {
        reopen_handle
            .open_request_on_panel(2, extra_head, 2, false, request())
            .await
    });
    let reopened = timeout(MAX_OPERATION, async {
        loop {
            tokio::select! {
                res = &mut reopen_task => break res.unwrap(),
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap()
    .unwrap();
    assert_eq!(reopened.title, "c2-reopened-after-revoke");
    while supervisor.events.try_recv().is_ok() {}

    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn overtaken_control_event_uses_pre_close_snapshot_and_rejects_after_reorder() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let make_snap = |rev: u64, opts: [&str; 2]| PanelSnapshot {
        revision: rev,
        title: "overtaken-select".into(),
        root: Some(panel::Node::new(
            20,
            "action-select",
            panel::node::Kind::Select(panel::SelectNode {
                label: "Action".into(),
                options: opts.iter().map(|s| (*s).to_owned()).collect(),
                selected_index: 1,
                enabled: true,
            }),
        )),
    };

    let primary = Uuid::new_v4();
    let extra = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control_with_seq(
            1,
            Control::Open {
                panel_id: 2,
                id: primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_wire = wire.try_recv().unwrap();
    let mut open_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, ["Allow", "Deny"])),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = open_wire.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());

    // Urgent Revoke at seq=20 overtakes an earlier Click/Select at seq=10,
    // and CloseRequest returns a Snapshot(2) reordering options to ["Deny", "Allow"].
    let (rev_tx, rev_rx) = oneshot::channel();
    running
        .control_with_seq(
            20,
            Control::Revoke {
                panel_id: 2,
                id: extra,
                remove_panel: false,
                reply: rev_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let close_wire = wire.try_recv().unwrap();
    let mut close_snap = Envelope::new(
        running.identity,
        2,
        2,
        envelope::Body::Snapshot(make_snap(2, ["Deny", "Allow"])),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    close_snap.in_reply_to = close_wire.request_id;
    running.frame(close_snap, &outgoing).await.unwrap();
    assert!(rev_rx.await.unwrap().is_ok());
    while updates.try_recv().is_ok() {}

    // Overtaken SelectedOption(0) at seq=10 (< 20) MUST compare against pre-close rev=1 snapshot
    // and fail as Stale without emitting onto wire!
    running
        .control_with_seq(
            10,
            Control::Event {
                panel_id: 2,
                event: UiEvent {
                    node_id: 20,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(wire.try_recv().is_err());
    let err = updates.try_recv().unwrap();
    assert!(matches!(
        err,
        PluginEvent::Error { panel_id: 2, ref failure, .. }
            if failure.code == ErrorCode::Stale as i32
                && failure.message.contains("插件面板内容已更新")
    ));

    // Post-revoke SelectedOption(0) at seq=25 (> 20) reflects the current snapshot and dispatches!
    running
        .control_with_seq(
            25,
            Control::Event {
                panel_id: 2,
                event: UiEvent {
                    node_id: 20,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                expected_snapshot: None,
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let sent = wire.try_recv().unwrap();
    assert_eq!(sent.panel_id, 2);
    assert_eq!(sent.revision, 2);
}

#[tokio::test]
async fn evicted_causal_seq_floors_reject_older_destroy_revoke_and_cancel_op() {
    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let snap = PanelSnapshot {
        revision: 1,
        title: "floor-test".into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    let primary = Uuid::new_v4();
    let (open_tx, open_rx) = oneshot::channel();
    running
        .control_with_seq(
            1,
            Control::Open {
                panel_id: 2,
                id: primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    let mut osnap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(snap),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    osnap.in_reply_to = ow.request_id;
    running.frame(osnap, &outgoing).await.unwrap();
    assert!(open_rx.await.is_ok());
    while updates.try_recv().is_ok() {}

    // 1. Evict panel_destroy_control_seq past MAX_TRACKED_DESTROY_SEQS.
    let mut seq = 10u64;
    let old_destroy_seq = seq;
    let (rtx, _) = oneshot::channel();
    running
        .control_with_seq(
            old_destroy_seq,
            Control::Revoke {
                panel_id: 500,
                id: Uuid::new_v4(),
                remove_panel: true,
                reply: rtx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    for i in 0..MAX_TRACKED_DESTROY_SEQS {
        seq += 1;
        let (tx, _) = oneshot::channel();
        running
            .control_with_seq(
                seq,
                Control::Revoke {
                    panel_id: 600 + i as u64,
                    id: Uuid::new_v4(),
                    remove_panel: true,
                    reply: tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
    }
    assert!(running.panel_destroy_seq_floor >= old_destroy_seq);
    assert!(!running.panel_destroy_control_seq.contains_key(&500));
    let (old_open_tx, mut old_open_rx) = oneshot::channel();
    running
        .control_with_seq(
            old_destroy_seq - 1,
            Control::Open {
                panel_id: 500,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: old_open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(old_open_rx.try_recv().unwrap().is_err());
    assert!(wire.try_recv().is_err());

    // Main panel (`PANEL_ID`) is never falsely rejected by child-only destroy/cancel floors!
    let (main_open_tx, main_open_rx) = oneshot::channel();
    running
        .control_with_seq(
            old_destroy_seq - 1,
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: main_open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(wire.try_recv().is_ok());
    drop(main_open_rx);

    // 2. Evict resource_revoke_control_seq past MAX_TRACKED_REVOKE_SEQS.
    seq += 1;
    let old_rev_seq = seq;
    let old_rev_res = Uuid::new_v4();
    let (rtx2, _) = oneshot::channel();
    running
        .control_with_seq(
            old_rev_seq,
            Control::Revoke {
                panel_id: 2,
                id: old_rev_res,
                remove_panel: false,
                reply: rtx2,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let cw = wire.try_recv().unwrap();
    let mut cack = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    cack.in_reply_to = cw.request_id;
    running.frame(cack, &outgoing).await.unwrap();
    for i in 0..MAX_TRACKED_REVOKE_SEQS {
        seq += 1;
        let (tx, _) = oneshot::channel();
        running
            .control_with_seq(
                seq,
                Control::Revoke {
                    panel_id: 2000 + i as u64,
                    id: Uuid::new_v4(),
                    remove_panel: false,
                    reply: tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
    }
    assert!(running.resource_revoke_seq_floor >= old_rev_seq);
    assert!(!running.resource_revoke_control_seq.contains_key(&(2, old_rev_res)));
    let (old_r_tx, mut old_r_rx) = oneshot::channel();
    running
        .control_with_seq(
            old_rev_seq - 1,
            Control::Open {
                panel_id: 2,
                id: old_rev_res,
                revision: 1,
                read_only: false,
                request: request(),
                reply: old_r_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(old_r_rx.try_recv().unwrap().is_err());
    assert!(wire.try_recv().is_err());

    // 3. Evict cancelled_op_control_seq past MAX_TRACKED_CANCELLED_OPS.
    seq += 1;
    let old_op_seq = seq;
    let old_op = Uuid::new_v4();
    running
        .control_with_seq(
            old_op_seq,
            Control::CancelPanelOp {
                panel_id: 2,
                op_id: old_op,
            },
            &outgoing,
        )
        .await
        .unwrap();
    for _ in 0..MAX_TRACKED_CANCELLED_OPS {
        seq += 1;
        running
            .control_with_seq(
                seq,
                Control::CancelPanelOp {
                    panel_id: 2,
                    op_id: Uuid::new_v4(),
                },
                &outgoing,
            )
            .await
            .unwrap();
    }
    assert!(running.cancelled_op_seq_floor >= old_op_seq);
    assert!(!running.cancelled_op_control_seq.contains_key(&(2, old_op)));
    let (commit_tx, mut commit_rx) = oneshot::channel();
    running
        .control_with_seq(
            old_op_seq - 1,
            Control::Commit {
                panel_id: 2,
                op_id: old_op,
                request: CommitEditor {
                    resource_id: primary.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: commit_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(commit_rx.try_recv().unwrap().is_err());
    assert!(wire.try_recv().is_err());
}

#[tokio::test]
async fn real_duplex_supervisor_evicted_revoke_seq_floor_still_blocks_old_queued_open() {
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.evict-floor".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(64 * 1024);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.evict-floor".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let open1 = read_async_frame(&mut worker_rx).await?;
        let s1 = send_frame(
            &mut out_seq,
            2,
            1,
            open1.request_id,
            envelope::Body::Snapshot(make_snap(1, "c2-v1")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s1)?).await?;
        // Fill supervisor.events (128 slots) exactly without blocking yet!
        for _ in 0..QUEUE_CAPACITY {
            let err_ev = send_frame(
                &mut out_seq,
                2,
                1,
                0,
                envelope::Body::Error(Failure::new(ErrorCode::Internal, "fill-events")),
            );
            worker_tx.write_all(&protocol::encode_frame(&err_ev)?).await?;
        }
        worker_tx.flush().await?;

        let mut close_count = 0usize;
        let mut reopen_ok = false;
        loop {
            match read_async_frame(&mut worker_rx).await {
                Ok(env) => match env.body {
                    Some(envelope::Body::Shutdown(_)) => break,
                    Some(envelope::Body::CloseRequest(ref c)) => {
                        ensure!(!c.destroy_panel);
                        close_count += 1;
                        let ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::OpenRequest(ref open)) => {
                        ensure!(
                            open.message_revision == 2,
                            "evicted old OpenRequest(rev={}) must never reach worker after floor eviction",
                            open.message_revision
                        );
                        reopen_ok = true;
                        let snap = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            2,
                            env.request_id,
                            envelope::Body::Snapshot(make_snap(2, "c2-reopened-after-evict")),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                        worker_tx.flush().await?;
                    }
                    _ => {}
                },
                Err(_) => break,
            }
        }
        ensure!(close_count == 1 && reopen_ok);
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let primary = Uuid::new_v4();
    let extra_old = Uuid::new_v4();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    handle
        .open_request_on_panel(2, primary, 1, false, request())
        .await
        .unwrap();

    // Wait until Running has pushed all 128 Errors into `supervisor.events` (channel 128/128 full!).
    tokio::time::sleep(Duration::from_millis(50)).await;

    // Enqueue invalid UiEvent at control[0] -> Running immediately blocks in `self.events.send`!
    handle
        .try_event_on_panel(
            2,
            UiEvent {
                node_id: 9999,
                editors: vec![],
                event: Some(panel::ui_event::Event::Focus(true)),
            },
        )
        .unwrap();
    tokio::time::sleep(Duration::from_millis(20)).await;

    // Now while Running is parked on `events.send`, queue 5 invalid UiEvents + `open_old_task` in `control`,
    // then `revoke_old` in `urgent_control`. `open_old` has committed `seq < revoke_old.seq`.
    for _ in 0..5 {
        handle
            .try_event_on_panel(
                2,
                UiEvent {
                    node_id: 9999,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
            )
            .unwrap();
    }
    let open_old_handle = handle.clone();
    let mut open_old_task = tokio::spawn(async move {
        open_old_handle
            .open_request_on_panel(2, extra_old, 1, false, request())
            .await
    });
    tokio::time::sleep(Duration::from_millis(15)).await;
    let rev_old_handle = handle.clone();
    let mut revoke_old_task = tokio::spawn(async move {
        rev_old_handle.revoke_panel_resource(2, extra_old, false).await
    });
    tokio::time::sleep(Duration::from_millis(10)).await;

    // Step through the 5 parked invalid-event waves, issuing 120 unrelated urgent revokes per wave
    // (600 > MAX_TRACKED_REVOKE_SEQS = 512) so `revoke_old`'s map entry IS EVICTED BEFORE `open_old`
    // is ever reached on `control`!
    for wave in 0..5u64 {
        let mut wave_tasks = Vec::with_capacity(120);
        for j in 0..120u64 {
            let h = handle.clone();
            let panel_id = 1000 + wave * 120 + j;
            let res = Uuid::new_v4();
            wave_tasks.push(tokio::spawn(async move {
                h.revoke_panel_resource(panel_id, res, false).await
            }));
        }
        tokio::time::sleep(Duration::from_millis(10)).await;
        // Release exactly 1 event slot: Running drains all urgent revokes first, then blocks on next invalid event!
        let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
        for t in wave_tasks {
            timeout(MAX_OPERATION, t).await.unwrap().unwrap().unwrap();
        }
        if wave == 0 {
            timeout(MAX_OPERATION, &mut revoke_old_task)
                .await
                .unwrap()
                .unwrap()
                .unwrap();
        }
    }

    // Release the final event slot and drain `supervisor.events`: `open_old` MUST still be rejected
    // by `resource_revoke_seq_floor >= open_old.seq` even though `revoke_old`'s key was evicted!
    let open_old_res = timeout(MAX_OPERATION, async {
        loop {
            tokio::select! {
                res = &mut open_old_task => break res.unwrap(),
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap();
    assert!(
        open_old_res.is_err(),
        "old Open must fail against evicted floor even after 600 newer revokes"
    );

    // Explicit reopen AFTER eviction has `seq > floor` and succeeds cleanly!
    let reopen_handle = handle.clone();
    let mut reopen_task = tokio::spawn(async move {
        reopen_handle
            .open_request_on_panel(2, extra_old, 2, false, request())
            .await
    });
    let reopened = timeout(MAX_OPERATION, async {
        loop {
            tokio::select! {
                res = &mut reopen_task => break res.unwrap(),
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap()
    .unwrap();
    assert_eq!(reopened.title, "c2-reopened-after-evict");
    while supervisor.events.try_recv().is_ok() {}

    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn concurrent_handles_and_late_older_revoke_preserve_newer_explicit_open() {
    // Part A: Exact unit proof protecting newer in-flight and bound opens against older late Revokes.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let make_snap = |rev: u64| PanelSnapshot {
            revision: rev,
            title: format!("p2-r{rev}"),
            root: Some(panel::Node::new(
                1,
                "ed",
                panel::node::Kind::Editor(panel::Editor {
                    document_id: 1,
                    revision: 1,
                    contents: b"init".to_vec(),
                    format: panel::EditorFormat::Utf8 as i32,
                    read_only: false,
                }),
            )),
        };
        let primary = Uuid::new_v4();
        let extra = Uuid::new_v4();
        let (open1_tx, open1_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: primary,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: open1_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ow1 = wire.try_recv().unwrap();
        let mut s1 = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        s1.in_reply_to = ow1.request_id;
        running.frame(s1, &outgoing).await.unwrap();
        assert!(open1_rx.await.is_ok());

        // Newer explicit Open arrives at seq=20 (in flight).
        let (open2_tx, open2_rx) = oneshot::channel();
        running
            .control_with_seq(
                20,
                Control::Open {
                    panel_id: 2,
                    id: extra,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: open2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ow2 = wire.try_recv().unwrap();

        // Late older non-destroy Revoke at seq=10 (< 20): must preserve in-flight Open(20) and emit nothing!
        let (rev_old_inflight_tx, rev_old_inflight_rx) = oneshot::channel();
        running
            .control_with_seq(
                10,
                Control::Revoke {
                    panel_id: 2,
                    id: extra,
                    remove_panel: false,
                    reply: rev_old_inflight_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(rev_old_inflight_rx.await.unwrap().is_ok());
        assert!(wire.try_recv().is_err());

        // Settle Open(20) cleanly -> binds `(2, extra)` with `open_seq = 20`.
        let mut s2 = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Snapshot(make_snap(2)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        s2.in_reply_to = ow2.request_id;
        running.frame(s2, &outgoing).await.unwrap();
        assert!(open2_rx.await.is_ok());
        assert!(running.broker.has_panel_resource(2, extra));

        // Late older non-destroy Revoke at seq=15 (< 20): must preserve active `(2, extra)` binding!
        let (rev_old_bound_tx, rev_old_bound_rx) = oneshot::channel();
        running
            .control_with_seq(
                15,
                Control::Revoke {
                    panel_id: 2,
                    id: extra,
                    remove_panel: false,
                    reply: rev_old_bound_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(rev_old_bound_rx.await.unwrap().is_ok());
        assert!(wire.try_recv().is_err());
        assert!(running.broker.has_panel_resource(2, extra));
        assert_eq!(running.panels[&2].active_resource, Some((extra, 1)));

        // Late older destroying Revoke at seq=18 (< 20): must preserve panel 2 because `open_seq = 20 > 18`!
        let (rev_old_destroy_tx, rev_old_destroy_rx) = oneshot::channel();
        running
            .control_with_seq(
                18,
                Control::Revoke {
                    panel_id: 2,
                    id: primary,
                    remove_panel: true,
                    reply: rev_old_destroy_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(rev_old_destroy_rx.await.unwrap().is_ok());
        assert!(wire.try_recv().is_err());
        assert!(!running.panels[&2].closing);
        assert!(running.broker.has_panel_resource(2, extra));

        // Explicitly newer Revoke at seq=25 (> 20) DOES revoke `(2, extra)` and emits CloseRequest!
        let (rev_new_tx, rev_new_rx) = oneshot::channel();
        running
            .control_with_seq(
                25,
                Control::Revoke {
                    panel_id: 2,
                    id: extra,
                    remove_panel: false,
                    reply: rev_new_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(!running.broker.has_panel_resource(2, extra));
        let close_w = wire.try_recv().unwrap();
        assert!(matches!(close_w.body, Some(envelope::Body::CloseRequest(_))));
        let mut cack = Envelope::new(
            running.identity,
            3,
            2,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        cack.in_reply_to = close_w.request_id;
        running.frame(cack, &outgoing).await.unwrap();
        assert!(rev_new_rx.await.unwrap().is_ok());
    }

    // Part B: Two cloned `PluginHandle`s racing `open_request_on_panel` and `revoke_panel_resource`
    // concurrently over a real duplex supervisor across multiple rounds.
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.dual-handle-race".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(64 * 1024);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("race-r{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let mut rev = 1u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            rev,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.dual-handle-race".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(rev)),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let mut p2_rev = 0u64;
        loop {
            match read_async_frame(&mut worker_rx).await {
                Ok(env) => match env.body {
                    Some(envelope::Body::Shutdown(_)) => break,
                    Some(envelope::Body::OpenRequest(_)) => {
                        p2_rev += 1;
                        rev = p2_rev;
                        let snap = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            rev,
                            env.request_id,
                            envelope::Body::Snapshot(make_snap(rev)),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::CloseRequest(_)) => {
                        let ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            p2_rev.max(1),
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::Resync(ref resync)) => {
                        p2_rev = resync.revision;
                        let ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            p2_rev,
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    _ => {}
                },
                Err(_) => break,
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let h1 = supervisor.handle();
    let h2 = h1.clone();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();

    for round in 1..=12u64 {
        let res = Uuid::new_v4();
        let a = h1.clone();
        let b = h2.clone();
        let open_fut = tokio::spawn(async move {
            a.open_request_on_panel(2, res, round, false, request()).await
        });
        let revoke_fut = tokio::spawn(async move {
            b.revoke_panel_resource(2, res, false).await
        });
        let (open_res, rev_res) = timeout(MAX_OPERATION, async {
            tokio::join!(open_fut, revoke_fut)
        })
        .await
        .unwrap();
        rev_res.unwrap().unwrap();
        if open_res.unwrap().is_ok() {
            // If `Open` won the causal order after `Revoke`, an explicit subsequent `Revoke` cleans up!
            timeout(MAX_OPERATION, h1.revoke_panel_resource(2, res, false))
                .await
                .unwrap()
                .unwrap();
        }
        while supervisor.events.try_recv().is_ok() {}
    }

    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn nonexistent_and_destroyed_panel_revokes_never_leak_snapshot_history() {
    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    // 1. Non-destroy revokes on non-existent child panels create NO snapshot history or floor entries.
    for i in 0..100u64 {
        let (tx, rx) = oneshot::channel();
        running
            .control_with_seq(
                i + 1,
                Control::Revoke {
                    panel_id: 100 + i,
                    id: Uuid::new_v4(),
                    remove_panel: false,
                    reply: tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(rx.await.unwrap().is_ok());
    }
    assert!(running.panel_revoke_snapshots.is_empty());
    assert!(running.panel_revoke_snapshot_floor.is_empty());

    // 2. Open live child panel 2 and exceed MAX_PANEL_REVOKE_SNAPSHOTS -> bounded to 16 + floor updated.
    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("p-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    for &(panel_id, seq) in &[(2u64, 101u64), (3u64, 201u64)] {
        let res = Uuid::new_v4();
        let (otx, orx) = oneshot::channel();
        running
            .control_with_seq(
                seq,
                Control::Open {
                    panel_id,
                    id: res,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: otx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ow = wire.try_recv().unwrap();
        let mut s = Envelope::new(
            running.identity,
            panel_id,
            1,
            envelope::Body::Snapshot(make_snap(1)),
            MAX_OPERATION,
        )
        .with_panel_id(panel_id);
        s.in_reply_to = ow.request_id;
        running.frame(s, &outgoing).await.unwrap();
        assert!(orx.await.is_ok());
    }
    let mut seq = 300u64;
    for panel_id in [2u64, 3u64] {
        for _ in 0..20 {
            seq += 1;
            let (tx, rx) = oneshot::channel();
            running
                .control_with_seq(
                    seq,
                    Control::Revoke {
                        panel_id,
                        id: Uuid::new_v4(),
                        remove_panel: false,
                        reply: tx,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            let cw = wire.try_recv().unwrap();
            seq += 1;
            let mut cack = Envelope::new(
                running.identity,
                seq,
                1,
                envelope::Body::Ack(panel::Empty {}),
                MAX_OPERATION,
            )
            .with_panel_id(panel_id);
            cack.in_reply_to = cw.request_id;
            running.frame(cack, &outgoing).await.unwrap();
            assert!(rx.await.unwrap().is_ok());
        }
        assert_eq!(
            running.panel_revoke_snapshots[&panel_id].len(),
            MAX_PANEL_REVOKE_SNAPSHOTS
        );
        assert!(running.panel_revoke_snapshot_floor.contains_key(&panel_id));
    }

    // 3. Destroying panel 2 and marking panel 3 destroy_failed clean both maps for those panels!
    let (d2_tx, d2_rx) = oneshot::channel();
    running
        .control_with_seq(
            900,
            Control::Revoke {
                panel_id: 2,
                id: Uuid::new_v4(),
                remove_panel: true,
                reply: d2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let d2_w = wire.try_recv().unwrap();
    let mut d2_ack = Envelope::new(
        running.identity,
        900,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    d2_ack.in_reply_to = d2_w.request_id;
    running.frame(d2_ack, &outgoing).await.unwrap();
    assert!(d2_rx.await.unwrap().is_ok());
    assert!(!running.panel_revoke_snapshots.contains_key(&2));
    assert!(!running.panel_revoke_snapshot_floor.contains_key(&2));

    running.mark_panel_destroy_failed(3, None);
    assert!(running.panel_revoke_snapshots.is_empty());
    assert!(running.panel_revoke_snapshot_floor.is_empty());

    // 4. Late non-destroy revokes on closing/destroy-failed panel 3 & unknown panels 200..250 do NOT leak entries!
    for i in 0..50u64 {
        let (tx3, _rx3) = oneshot::channel();
        running
            .control_with_seq(
                1000 + i * 2,
                Control::Revoke {
                    panel_id: 3,
                    id: Uuid::new_v4(),
                    remove_panel: false,
                    reply: tx3,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let (txu, _rxu) = oneshot::channel();
        running
            .control_with_seq(
                1001 + i * 2,
                Control::Revoke {
                    panel_id: 200 + i,
                    id: Uuid::new_v4(),
                    remove_panel: false,
                    reply: txu,
                },
                &outgoing,
            )
            .await
            .unwrap();
    }
    assert!(running.panel_revoke_snapshots.is_empty());
    assert!(running.panel_revoke_snapshot_floor.is_empty());
}

#[tokio::test]
async fn real_duplex_supervisor_revoke_cancels_unpermitted_open_waiting_on_full_control_channel() {
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.prepermit-revoke".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead, Permission::DraftWrite],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(64 * 1024);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
    let send_errors = Arc::new(tokio::sync::Notify::new());
    let send_errors_w = send_errors.clone();

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.prepermit-revoke".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let open1 = read_async_frame(&mut worker_rx).await?;
        let s1 = send_frame(
            &mut out_seq,
            2,
            1,
            open1.request_id,
            envelope::Body::Snapshot(make_snap(1, "c2-v1")),
        );
        worker_tx.write_all(&protocol::encode_frame(&s1)?).await?;
        worker_tx.flush().await?;
        send_errors_w.notified().await;
        for _ in 0..=QUEUE_CAPACITY {
            let err_ev = send_frame(
                &mut out_seq,
                2,
                1,
                0,
                envelope::Body::Error(Failure::new(ErrorCode::Internal, "fill-events")),
            );
            worker_tx.write_all(&protocol::encode_frame(&err_ev)?).await?;
        }
        worker_tx.flush().await?;

        let mut close_count = 0usize;
        let mut reopen_ok = false;
        loop {
            match read_async_frame(&mut worker_rx).await {
                Ok(env) => match env.body {
                    Some(envelope::Body::Shutdown(_)) => break,
                    Some(envelope::Body::CommitEditor(_)) => {
                        bail!("revoked pre-permit CommitEditor must never reach worker");
                    }
                    Some(envelope::Body::CloseRequest(ref c)) => {
                        ensure!(!c.destroy_panel);
                        close_count += 1;
                        let ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::OpenRequest(ref open)) => {
                        ensure!(
                            open.message_revision == 2,
                            "pre-permit OpenRequest(rev={}) must never reach worker after revoke",
                            open.message_revision
                        );
                        reopen_ok = true;
                        let snap = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            2,
                            env.request_id,
                            envelope::Body::Snapshot(make_snap(
                                2,
                                "c2-reopened-after-unpermitted-cancel",
                            )),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::UiEvent(_)) => {
                        let ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    _ => {}
                },
                Err(_) => break,
            }
        }
        ensure!(close_count == 1 && reopen_ok);
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead, Permission::DraftWrite]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let primary = Uuid::new_v4();
    let extra_res = Uuid::new_v4();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    handle
        .open_request_on_panel(2, primary, 1, false, request())
        .await
        .unwrap();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();

    // Signal worker to send QUEUE_CAPACITY + 1 Errors: first 128 fill `supervisor.events`,
    // Error #129 parks Running inside `self.events.send` while `handle.control` is 0/128 empty.
    send_errors.notify_one();
    tokio::time::sleep(Duration::from_millis(50)).await;

    // 1. Saturate ALL 128 slots of `handle.control` with Focus events (0 channel permits left).
    for i in 0..QUEUE_CAPACITY {
        handle
            .try_event(UiEvent {
                node_id: 1,
                editors: vec![],
                event: Some(panel::ui_event::Event::Focus(true)),
            })
            .unwrap_or_else(|e| panic!("failed filling control slot {i}: {e}"));
    }
    assert!(
        handle
            .try_event(UiEvent {
                node_id: 1,
                editors: vec![],
                event: Some(panel::ui_event::Event::Focus(true)),
            })
            .is_err()
    );

    // 2. Spawn `open_request_on_panel` and `commit_on_panel` while `control` is 128/128 full
    //    (neither can reserve a permit yet!), plus a pre-polled `begin_open` handle!
    let open_h = handle.clone();
    let mut open_unpermitted_task = tokio::spawn(async move {
        open_h
            .open_request_on_panel(2, extra_res, 1, false, request())
            .await
    });
    let commit_h = handle.clone();
    let mut commit_unpermitted_task = tokio::spawn(async move {
        commit_h
            .commit_on_panel(
                2,
                CommitEditor {
                    resource_id: extra_res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"stale-draft".to_vec(),
                        ..Default::default()
                    }),
                },
                CancellationToken::new(),
            )
            .await
    });
    let pre_polled_open = handle.begin_open(2, extra_res);
    tokio::time::sleep(Duration::from_millis(20)).await;
    assert!(
        tokio::time::timeout(Duration::from_millis(10), &mut open_unpermitted_task)
            .await
            .is_err(),
        "open must be waiting on full control channel before revoke"
    );
    assert!(
        tokio::time::timeout(Duration::from_millis(10), &mut commit_unpermitted_task)
            .await
            .is_err(),
        "commit must be waiting on full control channel before revoke"
    );

    // 3. Issue `revoke_panel_resource(2, extra_res, false)` -> MUST immediately cancel the parked
    //    waiters BEFORE `handle.control` ever recovers capacity, AND settle Ok(()) once events drain!
    let rev_h = handle.clone();
    let mut revoke_task = tokio::spawn(async move {
        rev_h.revoke_panel_resource(2, extra_res, false).await
    });
    assert!(
        timeout(MAX_OPERATION, open_unpermitted_task)
            .await
            .unwrap()
            .unwrap()
            .is_err()
    );
    assert!(
        timeout(MAX_OPERATION, commit_unpermitted_task)
            .await
            .unwrap()
            .unwrap()
            .is_err()
    );
    assert!(
        timeout(
            MAX_OPERATION,
            pre_polled_open.open_request(1, false, request()),
        )
        .await
        .unwrap()
        .is_err()
    );

    // 4. Drain `supervisor.events` -> Running resumes, settles `CloseRequest`, drains all 128 Focus
    //    events cleanly, and NEVER receives `OpenRequest(rev=1)` or `CommitEditor`.
    timeout(MAX_OPERATION, async {
        loop {
            tokio::select! {
                res = &mut revoke_task => {
                    res.unwrap().unwrap();
                    break;
                }
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap();

    // 5. Explicit post-revoke reopen with `rev = 2` succeeds cleanly!
    let reopen_h = handle.clone();
    let mut reopen_task = tokio::spawn(async move {
        reopen_h
            .open_request_on_panel(2, extra_res, 2, false, request())
            .await
    });
    let reopened = timeout(MAX_OPERATION, async {
        loop {
            tokio::select! {
                res = &mut reopen_task => break res.unwrap(),
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap()
    .unwrap();
    assert_eq!(reopened.title, "c2-reopened-after-unpermitted-cancel");
    while supervisor.events.try_recv().is_ok() {}

    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn real_duplex_supervisor_begin_commit_cancelled_before_poll_on_bound_resource() {
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.begin-commit-prepoll".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead, Permission::DraftWrite],
        contributions: vec!["suite_panel".into(), "message_editor".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(64 * 1024);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
    let commit_requests = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, u64)>::new()));
    let commit_responses = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, u64)>::new()));
    let commit_reqs_w = commit_requests.clone();
    let commit_resps_w = commit_responses.clone();

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.begin-commit-prepoll".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        loop {
            match read_async_frame(&mut worker_rx).await {
                Ok(env) => match env.body {
                    Some(envelope::Body::Shutdown(_)) => break,
                    Some(envelope::Body::OpenRequest(_)) => {
                        let snap = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::Snapshot(make_snap(1, "c2-bound")),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::CommitEditor(c)) => {
                        let rid = protocol::uuid(&c.resource_id).map_err(anyhow::Error::msg)?;
                        commit_reqs_w
                            .lock()
                            .unwrap()
                            .push((env.panel_id, rid, c.message_revision));
                        let committed = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::Committed(protocol::Committed {
                                resource_id: c.resource_id,
                                message_revision: c.message_revision,
                                document_id: 1,
                                document_revision: c.editor.as_ref().map_or(1, |e| e.revision),
                                request: c.request,
                            }),
                        );
                        worker_tx
                            .write_all(&protocol::encode_frame(&committed)?)
                            .await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::CommitResponseEditor(c)) => {
                        let rid = protocol::uuid(&c.resource_id).map_err(anyhow::Error::msg)?;
                        commit_resps_w
                            .lock()
                            .unwrap()
                            .push((env.panel_id, rid, c.message_revision));
                        let committed = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::ResponseCommitted(protocol::ResponseCommitted {
                                resource_id: c.resource_id,
                                message_revision: c.message_revision,
                                document_id: 1,
                                document_revision: c.editor.as_ref().map_or(1, |e| e.revision),
                                response: c.response,
                            }),
                        );
                        worker_tx
                            .write_all(&protocol::encode_frame(&committed)?)
                            .await?;
                        worker_tx.flush().await?;
                    }
                    Some(envelope::Body::CloseRequest(_)) => {
                        let ack = send_frame(
                            &mut out_seq,
                            env.panel_id,
                            1,
                            env.request_id,
                            envelope::Body::Ack(panel::Empty {}),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                        worker_tx.flush().await?;
                    }
                    _ => {}
                },
                Err(_) => break,
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead, Permission::DraftWrite]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let bound_res = Uuid::new_v4();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    let snap = handle
        .open_request_on_panel(2, bound_res, 1, false, request())
        .await
        .unwrap();
    assert_eq!(snap.title, "c2-bound");
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();

    // Register PendingCommit waiters while `bound_res` is genuinely bound and control channel is empty,
    // cancel them BEFORE first poll (before any remote revoke runs), then poll them.
    let unpolled_req_commit = handle.begin_commit(2, Some(bound_res));
    let unpolled_resp_commit = handle.begin_commit(2, Some(bound_res));
    handle.cancel_pending_resource_ops(2, bound_res, false);

    assert!(
        timeout(
            MAX_OPERATION,
            unpolled_req_commit.commit_request(
                CommitEditor {
                    resource_id: bound_res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 2,
                        contents: b"prepoll-stale-req".to_vec(),
                        ..Default::default()
                    }),
                },
                CancellationToken::new(),
            ),
        )
        .await
        .unwrap()
        .is_err()
    );
    assert!(
        timeout(
            MAX_OPERATION,
            unpolled_resp_commit.commit_response(
                protocol::CommitResponseEditor {
                    resource_id: bound_res.as_bytes().to_vec(),
                    message_revision: 1,
                    response: Some(
                        HttpResponse {
                            status: 200,
                            version: mio_plugin_api::HttpVersion::Http11,
                            reason_phrase: Some("OK".into()),
                            headers: vec![],
                            body: b"body".to_vec(),
                            trailers: vec![],
                        }
                        .into(),
                    ),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 2,
                        contents: b"prepoll-stale-resp".to_vec(),
                        ..Default::default()
                    }),
                },
                CancellationToken::new(),
            ),
        )
        .await
        .unwrap()
        .is_err()
    );
    assert!(commit_requests.lock().unwrap().is_empty());
    assert!(commit_responses.lock().unwrap().is_empty());

    // Positive control: `bound_res` IS genuinely bound on panel 2 and still commits normally.
    let committed_req = handle
        .commit_on_panel(
            2,
            CommitEditor {
                resource_id: bound_res.as_bytes().to_vec(),
                message_revision: 1,
                request: Some(request().into()),
                editor: Some(EditorSnapshot {
                    document_id: 1,
                    revision: 2,
                    contents: b"live-req".to_vec(),
                    ..Default::default()
                }),
            },
            CancellationToken::new(),
        )
        .await
        .unwrap();
    assert_eq!(committed_req.url, request().url);
    let committed_resp = handle
        .commit_response_on_panel(
            2,
            protocol::CommitResponseEditor {
                resource_id: bound_res.as_bytes().to_vec(),
                message_revision: 1,
                response: Some(
                    HttpResponse {
                        status: 200,
                        version: mio_plugin_api::HttpVersion::Http11,
                        reason_phrase: Some("OK".into()),
                        headers: vec![],
                        body: b"live-resp".to_vec(),
                        trailers: vec![],
                    }
                    .into(),
                ),
                editor: Some(EditorSnapshot {
                    document_id: 1,
                    revision: 2,
                    contents: b"live-resp".to_vec(),
                    ..Default::default()
                }),
            },
            CancellationToken::new(),
        )
        .await
        .unwrap();
    assert_eq!(committed_resp.body, b"live-resp");
    assert_eq!(commit_requests.lock().unwrap().as_slice(), &[(2, bound_res, 1)]);
    assert_eq!(commit_responses.lock().unwrap().as_slice(), &[(2, bound_res, 1)]);

    handle
        .revoke_panel_resource(2, bound_res, true)
        .await
        .unwrap();
    while supervisor.events.try_recv().is_ok() {}
    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn real_duplex_supervisor_batch_revoke_cancels_deferred_second_open_before_first_close_ack() {
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.batch-revoke-deferred".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead, Permission::DraftWrite],
        contributions: vec!["suite_panel".into(), "message_editor".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(64 * 1024);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let res_c = Uuid::new_v4();
    let res_a = Uuid::new_v4();
    let res_b = Uuid::new_v4();
    let saw_close_c = Arc::new(tokio::sync::Notify::new());
    let saw_close_c_w = saw_close_c.clone();
    let release_close_c = Arc::new(tokio::sync::Notify::new());
    let release_close_c_w = release_close_c.clone();
    let received_opens = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, u64)>::new()));
    let received_closes = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, bool)>::new()));
    let max_inflight_closes = Arc::new(std::sync::Mutex::new(0usize));
    let opens_w = received_opens.clone();
    let closes_w = received_closes.clone();
    let max_inflight_w = max_inflight_closes.clone();

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.batch-revoke-deferred".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let mut revs: HashMap<u64, u64> = HashMap::from([(protocol::PANEL_ID, 1)]);
        let mut inflight_closes = 0usize;
        let mut held_close_c: Option<(u64, u64, u64)> = None;
        loop {
            tokio::select! {
                biased;
                _ = release_close_c_w.notified(), if held_close_c.is_some() => {
                    let (panel_id, req_id, rev) = held_close_c.take().unwrap();
                    inflight_closes = inflight_closes.saturating_sub(1);
                    let ack = send_frame(
                        &mut out_seq,
                        panel_id,
                        rev,
                        req_id,
                        envelope::Body::Ack(panel::Empty {}),
                    );
                    worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                    worker_tx.flush().await?;
                }
                incoming = read_async_frame(&mut worker_rx) => {
                    let Ok(env) = incoming else { break; };
                    match env.body {
                        Some(envelope::Body::Shutdown(_)) => break,
                        Some(envelope::Body::OpenRequest(ref open)) => {
                            let rid = protocol::uuid(&open.resource_id).map_err(anyhow::Error::msg)?;
                            opens_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, open.message_revision));
                            let rev = revs.entry(env.panel_id).or_insert(0);
                            *rev += 1;
                            let snap = send_frame(
                                &mut out_seq,
                                env.panel_id,
                                *rev,
                                env.request_id,
                                envelope::Body::Snapshot(make_snap(
                                    *rev,
                                    &format!("p-{}-rev-{}", env.panel_id, open.message_revision),
                                )),
                            );
                            worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                            worker_tx.flush().await?;
                        }
                        Some(envelope::Body::CloseRequest(ref close)) => {
                            let rid = protocol::uuid(&close.resource_id).map_err(anyhow::Error::msg)?;
                            closes_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, close.destroy_panel));
                            inflight_closes += 1;
                            {
                                let mut max = max_inflight_w.lock().unwrap();
                                *max = (*max).max(inflight_closes);
                            }
                            let rev = *revs.get(&env.panel_id).unwrap_or(&1);
                            if rid == res_c && !close.destroy_panel {
                                held_close_c = Some((env.panel_id, env.request_id, rev));
                                saw_close_c_w.notify_one();
                            } else {
                                inflight_closes = inflight_closes.saturating_sub(1);
                                let ack = send_frame(
                                    &mut out_seq,
                                    env.panel_id,
                                    rev,
                                    env.request_id,
                                    envelope::Body::Ack(panel::Empty {}),
                                );
                                worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                                worker_tx.flush().await?;
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead, Permission::DraftWrite]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    for res in [res_c, res_a, res_b] {
        handle
            .open_request_on_panel(2, res, 1, false, request())
            .await
            .unwrap();
        let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    }

    // 1. Start CloseRequest(res_c) and hold its Ack at the worker -> non-destroy close barrier active on panel 2.
    let h_c = handle.clone();
    let revoke_c_task =
        tokio::spawn(async move { h_c.revoke_panel_resource(2, res_c, false).await });
    timeout(MAX_OPERATION, saw_close_c.notified()).await.unwrap();

    // 2. Enqueue older `Open(res_b, rev=2)` on panel 2 -> enters Running::panels[2].deferred_commands behind CloseRequest(res_c).
    let h_b = handle.clone();
    let mut deferred_open_b = tokio::spawn(async move {
        h_b.open_request_on_panel(2, res_b, 2, false, request()).await
    });
    tokio::time::sleep(Duration::from_millis(25)).await;
    assert!(
        tokio::time::timeout(Duration::from_millis(10), &mut deferred_open_b)
            .await
            .is_err(),
        "open_b must be parked behind CloseRequest(res_c) barrier"
    );

    // 3. Batch revoke [res_a, res_b] while CloseRequest(res_c) is still unacked:
    //    `deferred_open_b` MUST fail immediately BEFORE CloseRequest(res_c) receives its Ack!
    let h_batch = handle.clone();
    let revoke_batch_task = tokio::spawn(async move {
        h_batch.revoke_panel_resources(2, vec![res_a, res_b]).await
    });
    assert!(
        timeout(MAX_OPERATION, deferred_open_b)
            .await
            .unwrap()
            .unwrap()
            .is_err(),
        "batch revoke must cancel deferred open for res_b before CloseRequest(res_c) Ack"
    );

    // Worker must not have seen res_b rev=2 open or res_a/res_b closes yet while res_c is held.
    assert!(received_closes.lock().unwrap().as_slice() == &[(2, res_c, false)]);
    assert!(
        received_opens
            .lock()
            .unwrap()
            .iter()
            .all(|(_, rid, rev)| !(*rid == res_b && *rev == 2))
    );

    // Unrelated healthy child panel 3 must NOT be rejected as congested while panel 2 queues [res_a, res_b]
    // behind panel 2's in-flight non-destroy CloseRequest(res_c).
    let p3_res = Uuid::new_v4();
    let p3_snap = handle
        .open_request_on_panel(3, p3_res, 1, false, request())
        .await
        .unwrap();
    assert_eq!(p3_snap.title, "p-3-rev-1");
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();

    // 4. Release CloseRequest(res_c) Ack -> res_a then res_b close sequentially without ever dispatching res_b rev=2.
    release_close_c.notify_one();
    timeout(MAX_OPERATION, revoke_c_task).await.unwrap().unwrap().unwrap();
    timeout(MAX_OPERATION, revoke_batch_task).await.unwrap().unwrap().unwrap();

    assert_eq!(*max_inflight_closes.lock().unwrap(), 1);
    assert_eq!(
        received_closes.lock().unwrap().as_slice(),
        &[(2, res_c, false), (2, res_a, false), (2, res_b, false)]
    );
    assert!(
        received_opens
            .lock()
            .unwrap()
            .iter()
            .all(|(_, rid, rev)| !(*rid == res_b && *rev == 2))
    );

    // 5. Positive control: post-batch reopen with newer revision `rev = 3` succeeds cleanly.
    let reopened = handle
        .open_request_on_panel(2, res_b, 3, false, request())
        .await
        .unwrap();
    assert_eq!(reopened.title, "p-2-rev-3");
    handle.revoke_panel_resource(2, res_b, true).await.unwrap();
    while supervisor.events.try_recv().is_ok() {}
    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn real_duplex_supervisor_revoke_retracts_unsent_open_from_outbound_queue_when_writer_blocked()
{
    // Part 0: Direct Running::control_with_seq verification — even when `outgoing` regains capacity before
    // `control_with_seq` runs, `Revoke` drains urgent/retracts the unsent `Open` from `outbound_queue`
    // BEFORE flushing outbound frames, sending ONLY `CloseRequest` and ZERO `OpenRequest` or `Cancel`.
    {
        let (mut running, _calls, _updates) = running();
        let (outgoing, mut wire) = mpsc::channel(2);
        running
            .send(&outgoing, envelope::Body::Cancel(protocol::Cancel { request_id: 901 }), 0)
            .unwrap();
        running
            .send(&outgoing, envelope::Body::Cancel(protocol::Cancel { request_id: 902 }), 0)
            .unwrap();
        let res_unsent = Uuid::new_v4();
        let (open_tx, mut open_rx) = oneshot::channel();
        running
            .control_with_seq(
                9,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: res_unsent,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: open_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.outbound_queue.len(), 1);
        let _ = wire.try_recv().unwrap();
        let _ = wire.try_recv().unwrap();

        let (rev_tx, rev_rx) = oneshot::channel();
        running
            .control_with_seq(
                10,
                Control::Revoke {
                    panel_id: protocol::PANEL_ID,
                    id: res_unsent,
                    remove_panel: false,
                    reply: rev_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(open_rx.try_recv().unwrap().is_err());
        assert!(running.outbound_queue.is_empty());

        let first = wire.try_recv().unwrap();
        assert!(
            matches!(first.body, Some(envelope::Body::CloseRequest(ref c)) if !c.destroy_panel),
            "expected only CloseRequest after retracting unsent OpenRequest, got {:?}",
            first.body
        );
        assert!(wire.try_recv().is_err(), "retracted OpenRequest and Cancel must not be sent");

        let mut ack = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        );
        ack.in_reply_to = first.request_id;
        running.frame(ack, &outgoing).await.unwrap();
        rev_rx.await.unwrap().unwrap();
    }

    // Part A + B: Real duplex transport with 512B blocked writer pipe and contrast with already-written Open.
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.outbound-retract".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let res_a = Uuid::new_v4();
    let res_b = Uuid::new_v4();
    let res_c = Uuid::new_v4();
    let block_reader = Arc::new(tokio::sync::Notify::new());
    let unblock_reader = Arc::new(tokio::sync::Notify::new());
    let burst_sent = Arc::new(tokio::sync::Notify::new());
    let saw_open_c = Arc::new(tokio::sync::Notify::new());
    let block_reader_w = block_reader.clone();
    let unblock_reader_w = unblock_reader.clone();
    let burst_sent_w = burst_sent.clone();
    let saw_open_c_w = saw_open_c.clone();

    let received_opens = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, u64)>::new()));
    let received_closes = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, bool)>::new()));
    let received_cancels = Arc::new(std::sync::Mutex::new(Vec::<(u64, u64)>::new()));
    let open_c_req_id = Arc::new(std::sync::Mutex::new(None::<u64>));
    let opens_w = received_opens.clone();
    let closes_w = received_closes.clone();
    let cancels_w = received_cancels.clone();
    let open_c_req_id_w = open_c_req_id.clone();

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let burst_count = OUTGOING_CAPACITY + 24;
    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.outbound-retract".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: false,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let mut rev = 1u64;
        let mut reader_blocked = false;
        loop {
            tokio::select! {
                biased;
                _ = block_reader_w.notified(), if !reader_blocked => {
                    reader_blocked = true;
                    for _ in 0..burst_count {
                        let hc = send_frame(
                            &mut out_seq,
                            protocol::PANEL_ID,
                            rev,
                            0,
                            envelope::Body::HostCall(HostCall {
                                operation: Some(host_call::Operation::QueryHistory(
                                    protocol::HistoryQuery {
                                        offset: 0,
                                        limit: 1,
                                        filter: String::new(),
                                    },
                                )),
                                parent_request_id: 999_999,
                            }),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&hc)?).await?;
                    }
                    let fence = send_frame(
                        &mut out_seq,
                        protocol::PANEL_ID,
                        rev,
                        0,
                        envelope::Body::Error(Failure::new(ErrorCode::Internal, "flush-fence")),
                    );
                    worker_tx.write_all(&protocol::encode_frame(&fence)?).await?;
                    worker_tx.flush().await?;
                    burst_sent_w.notify_one();
                }
                _ = unblock_reader_w.notified(), if reader_blocked => {
                    reader_blocked = false;
                }
                incoming = read_async_frame(&mut worker_rx), if !reader_blocked => {
                    let Ok(env) = incoming else { break; };
                    match env.body {
                        Some(envelope::Body::Shutdown(_)) => break,
                        Some(envelope::Body::OpenRequest(ref open)) => {
                            let rid = protocol::uuid(&open.resource_id).map_err(anyhow::Error::msg)?;
                            opens_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, open.message_revision));
                            if rid == res_c {
                                *open_c_req_id_w.lock().unwrap() = Some(env.request_id);
                                saw_open_c_w.notify_one();
                            } else {
                                rev += 1;
                                let snap = send_frame(
                                    &mut out_seq,
                                    env.panel_id,
                                    rev,
                                    env.request_id,
                                    envelope::Body::Snapshot(make_snap(rev, "opened")),
                                );
                                worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                                worker_tx.flush().await?;
                            }
                        }
                        Some(envelope::Body::Cancel(ref cancel)) => {
                            cancels_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, cancel.request_id));
                            let ack = send_frame(
                                &mut out_seq,
                                env.panel_id,
                                rev,
                                env.request_id,
                                envelope::Body::Ack(panel::Empty {}),
                            );
                            worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                            worker_tx.flush().await?;
                        }
                        Some(envelope::Body::CloseRequest(ref close)) => {
                            let rid = protocol::uuid(&close.resource_id).map_err(anyhow::Error::msg)?;
                            closes_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, close.destroy_panel));
                            let ack = send_frame(
                                &mut out_seq,
                                env.panel_id,
                                rev,
                                env.request_id,
                                envelope::Body::Ack(panel::Empty {}),
                            );
                            worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                            worker_tx.flush().await?;
                        }
                        _ => {}
                    }
                }
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    handle
        .open_request(res_a, 1, false, request())
        .await
        .unwrap();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();

    // Block worker reader and fill the 512B writer pipe + `outgoing` (256) so `HostResult`s spill
    // into `Running::outbound_queue`.
    block_reader.notify_one();
    timeout(MAX_OPERATION, burst_sent.notified()).await.unwrap();
    let fence_ev = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(matches!(
        fence_ev,
        PluginEvent::Error { ref failure, .. } if failure.message == "flush-fence"
    ));

    // Spawn `open_request(res_b)` -> accepted into `Running::outbound_queue` behind the spilled HostResults.
    let h_b = handle.clone();
    let mut open_b_task = tokio::spawn(async move {
        h_b.open_request(res_b, 1, false, request()).await
    });
    tokio::time::sleep(Duration::from_millis(25)).await;
    assert!(
        tokio::time::timeout(Duration::from_millis(10), &mut open_b_task)
            .await
            .is_err(),
        "open_b must be parked inside blocked outbound_queue"
    );

    // Issue batch revoke [res_a, res_b] while writer pipe is STILL blocked:
    // `open_b_task` MUST immediately fail (retracted from `outbound_queue`) BEFORE `unblock_reader` fires!
    let revoke_batch = handle.begin_revoke_panel_resources(protocol::PANEL_ID, vec![res_a, res_b]);
    assert!(
        timeout(MAX_OPERATION, open_b_task)
            .await
            .unwrap()
            .unwrap()
            .is_err(),
        "batch revoke must fail unsent open_b immediately while writer is still blocked"
    );

    // Unblock worker reader -> HostResults + CloseRequest(res_a) then CloseRequest(res_b) flush cleanly,
    // with ZERO `OpenRequest(res_b)` and ZERO `Cancel` sent to the worker!
    unblock_reader.notify_one();
    timeout(MAX_OPERATION, async {
        let mut wait_fut = std::pin::pin!(revoke_batch.wait());
        loop {
            tokio::select! {
                res = &mut wait_fut => {
                    res.unwrap();
                    break;
                }
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap();

    assert_eq!(received_opens.lock().unwrap().as_slice(), &[(protocol::PANEL_ID, res_a, 1)]);
    assert!(received_cancels.lock().unwrap().is_empty());
    assert_eq!(
        received_closes.lock().unwrap().as_slice(),
        &[(protocol::PANEL_ID, res_a, false), (protocol::PANEL_ID, res_b, false)]
    );

    // Part B: Contrast — when `OpenRequest(res_c)` HAS already been written to the worker, revoking `res_c`
    // sends an explicit `Cancel` frame targeting `OpenRequest(res_c)`'s `request_id` plus `CloseRequest(res_c)`.
    let h_c = handle.clone();
    let open_c_task = tokio::spawn(async move {
        h_c.open_request(res_c, 1, false, request()).await
    });
    timeout(MAX_OPERATION, saw_open_c.notified()).await.unwrap();
    let expected_c_req_id = open_c_req_id.lock().unwrap().unwrap();
    handle.revoke_resource(res_c).await.unwrap();
    assert!(timeout(MAX_OPERATION, open_c_task).await.unwrap().unwrap().is_err());

    assert_eq!(
        received_cancels.lock().unwrap().as_slice(),
        &[(protocol::PANEL_ID, expected_c_req_id)]
    );
    assert_eq!(
        received_closes.lock().unwrap().as_slice(),
        &[
            (protocol::PANEL_ID, res_a, false),
            (protocol::PANEL_ID, res_b, false),
            (protocol::PANEL_ID, res_c, false),
        ]
    );

    while supervisor.events.try_recv().is_ok() {}
    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn real_duplex_supervisor_urgent_burst_past_queue_capacity_still_cancels_deferred_open_before_ready_close_ack()
{
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.urgent-burst-revoke".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead, Permission::DraftWrite],
        contributions: vec!["suite_panel".into(), "message_editor".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(64 * 1024);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let res_c = Uuid::new_v4();
    let res_a = Uuid::new_v4();
    let res_b = Uuid::new_v4();
    let saw_close_c = Arc::new(tokio::sync::Notify::new());
    let release_close_c = Arc::new(tokio::sync::Notify::new());
    let sent_close_c_ack = Arc::new(tokio::sync::Notify::new());
    let send_errors = Arc::new(tokio::sync::Notify::new());
    let errors_sent = Arc::new(tokio::sync::Notify::new());
    let saw_close_c_w = saw_close_c.clone();
    let release_close_c_w = release_close_c.clone();
    let sent_close_c_ack_w = sent_close_c_ack.clone();
    let send_errors_w = send_errors.clone();
    let errors_sent_w = errors_sent.clone();
    let received_opens = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, u64)>::new()));
    let received_closes = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, bool)>::new()));
    let max_inflight_closes = Arc::new(std::sync::Mutex::new(0usize));
    let opens_w = received_opens.clone();
    let closes_w = received_closes.clone();
    let max_inflight_w = max_inflight_closes.clone();

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.urgent-burst-revoke".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: true,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let mut revs: HashMap<u64, u64> = HashMap::from([(protocol::PANEL_ID, 1)]);
        let mut inflight_closes = 0usize;
        let mut held_close_c: Option<(u64, u64, u64)> = None;
        let mut sent_err_burst = false;
        loop {
            tokio::select! {
                biased;
                _ = send_errors_w.notified(), if !sent_err_burst => {
                    sent_err_burst = true;
                    for _ in 0..=QUEUE_CAPACITY {
                        let err_ev = send_frame(
                            &mut out_seq,
                            protocol::PANEL_ID,
                            1,
                            0,
                            envelope::Body::Error(Failure::new(ErrorCode::Internal, "park-running")),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&err_ev)?).await?;
                    }
                    worker_tx.flush().await?;
                    errors_sent_w.notify_one();
                }
                _ = release_close_c_w.notified(), if held_close_c.is_some() => {
                    let (panel_id, req_id, rev) = held_close_c.take().unwrap();
                    inflight_closes = inflight_closes.saturating_sub(1);
                    let ack = send_frame(
                        &mut out_seq,
                        panel_id,
                        rev,
                        req_id,
                        envelope::Body::Ack(panel::Empty {}),
                    );
                    worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                    worker_tx.flush().await?;
                    sent_close_c_ack_w.notify_one();
                }
                incoming = read_async_frame(&mut worker_rx) => {
                    let Ok(env) = incoming else { break; };
                    match env.body {
                        Some(envelope::Body::Shutdown(_)) => break,
                        Some(envelope::Body::OpenRequest(ref open)) => {
                            let rid = protocol::uuid(&open.resource_id).map_err(anyhow::Error::msg)?;
                            opens_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, open.message_revision));
                            let rev = revs.entry(env.panel_id).or_insert(0);
                            *rev += 1;
                            let snap = send_frame(
                                &mut out_seq,
                                env.panel_id,
                                *rev,
                                env.request_id,
                                envelope::Body::Snapshot(make_snap(
                                    *rev,
                                    &format!("p-{}-rev-{}", env.panel_id, open.message_revision),
                                )),
                            );
                            worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                            worker_tx.flush().await?;
                        }
                        Some(envelope::Body::CloseRequest(ref close)) => {
                            let rid = protocol::uuid(&close.resource_id).map_err(anyhow::Error::msg)?;
                            closes_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, close.destroy_panel));
                            inflight_closes += 1;
                            {
                                let mut max = max_inflight_w.lock().unwrap();
                                *max = (*max).max(inflight_closes);
                            }
                            let rev = *revs.get(&env.panel_id).unwrap_or(&1);
                            if rid == res_c && !close.destroy_panel {
                                held_close_c = Some((env.panel_id, env.request_id, rev));
                                saw_close_c_w.notify_one();
                            } else {
                                inflight_closes = inflight_closes.saturating_sub(1);
                                let ack = send_frame(
                                    &mut out_seq,
                                    env.panel_id,
                                    rev,
                                    env.request_id,
                                    envelope::Body::Ack(panel::Empty {}),
                                );
                                worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                                worker_tx.flush().await?;
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead, Permission::DraftWrite]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    for res in [res_c, res_a, res_b] {
        handle
            .open_request_on_panel(2, res, 1, false, request())
            .await
            .unwrap();
        let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    }

    // 1. Start CloseRequest(res_c) and hold its Ack -> active non-destroy close barrier on panel 2.
    let h_c = handle.clone();
    let mut revoke_c_task =
        tokio::spawn(async move { h_c.revoke_panel_resource(2, res_c, false).await });
    timeout(MAX_OPERATION, saw_close_c.notified()).await.unwrap();

    // 2. Park older `Open(res_b, rev=2)` inside Running's panel-2 `deferred_commands`.
    let h_b = handle.clone();
    let mut deferred_open_b = tokio::spawn(async move {
        h_b.open_request_on_panel(2, res_b, 2, false, request()).await
    });
    tokio::time::sleep(Duration::from_millis(25)).await;
    assert!(
        tokio::time::timeout(Duration::from_millis(10), &mut deferred_open_b)
            .await
            .is_err()
    );

    // 3. Park Running inside `self.events.send` with a full supervisor.events channel.
    send_errors.notify_one();
    timeout(MAX_OPERATION, errors_sent.notified()).await.unwrap();
    tokio::time::sleep(Duration::from_millis(40)).await;

    // 4. Burst past old `QUEUE_CAPACITY` (128) with unrelated urgent revokes, THEN synchronously
    //    register `batch_revoke` for [res_a, res_b] WITHOUT polling `.wait()` yet, AND make
    //    CloseRequest(res_c)'s Ack ALREADY readable in Running's `incoming` channel before waking it!
    let mut noise_revokes = Vec::with_capacity(QUEUE_CAPACITY + 8);
    for i in 0..(QUEUE_CAPACITY + 8) {
        noise_revokes.push(handle.begin_revoke_panel_resource(
            100 + i as u64,
            Uuid::new_v4(),
            false,
        ));
    }
    let batch_revoke = handle.begin_revoke_panel_resources(2, vec![res_a, res_b]);
    release_close_c.notify_one();
    timeout(MAX_OPERATION, sent_close_c_ack.notified()).await.unwrap();
    tokio::time::sleep(Duration::from_millis(15)).await;

    // 5. Unblock Running by draining supervisor.events — WITHOUT ever polling `batch_revoke.wait()`:
    //    `Running` MUST drain all 136 noise revokes + `batch_revoke` BEFORE CloseRequest(res_c)'s ready
    //    Ack dispatches deferred `Open(res_b, rev=2)`.
    let mut open_b_done = false;
    let mut rev_c_done = false;
    timeout(MAX_OPERATION, async {
        while !(open_b_done && rev_c_done) {
            tokio::select! {
                _ = supervisor.events.recv() => {}
                res = &mut deferred_open_b, if !open_b_done => {
                    assert!(
                        res.unwrap().is_err(),
                        "synchronously registered batch revoke past QUEUE_CAPACITY must cancel deferred open before already-ready Ack"
                    );
                    open_b_done = true;
                }
                res = &mut revoke_c_task, if !rev_c_done => {
                    res.unwrap().unwrap();
                    rev_c_done = true;
                }
            }
        }
    })
    .await
    .unwrap();

    // 6. Now collect `batch_revoke.wait()` and all noise revoke replies cleanly while draining events.
    timeout(MAX_OPERATION, async {
        let mut wait_fut = std::pin::pin!(batch_revoke.wait());
        loop {
            tokio::select! {
                res = &mut wait_fut => {
                    res.unwrap();
                    break;
                }
                _ = supervisor.events.recv() => {}
            }
        }
        for nr in noise_revokes {
            nr.wait().await.unwrap();
        }
    })
    .await
    .unwrap();

    assert_eq!(*max_inflight_closes.lock().unwrap(), 1);
    assert_eq!(
        received_closes.lock().unwrap().as_slice(),
        &[(2, res_c, false), (2, res_a, false), (2, res_b, false)]
    );
    assert!(
        received_opens
            .lock()
            .unwrap()
            .iter()
            .all(|(_, rid, rev)| !(*rid == res_b && *rev == 2))
    );

    // 7. Positive control: post-batch reopen with `rev = 3` succeeds cleanly.
    let reopened = handle
        .open_request_on_panel(2, res_b, 3, false, request())
        .await
        .unwrap();
    assert_eq!(reopened.title, "p-2-rev-3");
    handle.revoke_panel_resource(2, res_b, true).await.unwrap();
    while supervisor.events.try_recv().is_ok() {}
    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn two_independent_ready_urgent_revokes_retract_second_unsent_open_before_first_flushes_outbound()
{
    // Sub-part 1: Two independent ready revokes sitting together in `urgent_commands` during `drain_urgent_controls`.
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"retained".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    let (mut running, _calls, _updates) = running();
    let (urgent_tx, urgent_rx) = mpsc::unbounded_channel();
    running.urgent_commands = Some(urgent_rx);
    let (outgoing, mut wire) = mpsc::channel(4);

    let res_a = Uuid::new_v4();
    let res_b = Uuid::new_v4();
    let (oa_tx, oa_rx) = oneshot::channel();
    running
        .control_with_seq(
            1,
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: res_a,
                revision: 1,
                read_only: false,
                request: request(),
                reply: oa_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let oa_w = wire.try_recv().unwrap();
    let mut snap_a = Envelope::new(
        running.identity,
        1,
        2,
        envelope::Body::Snapshot(make_snap(2, "a-bound")),
        MAX_OPERATION,
    );
    snap_a.in_reply_to = oa_w.request_id;
    running.frame(snap_a, &outgoing).await.unwrap();
    oa_rx.await.unwrap().unwrap();
    while wire.try_recv().is_ok() {}

    // Fill `outgoing` (4/4), enqueue `Open(res_b)` into `running.outbound_queue`, then drain `wire`
    // so `outgoing` has free capacity when urgent revokes arrive.
    for s in 901..=904u64 {
        running
            .send(&outgoing, envelope::Body::Cancel(protocol::Cancel { request_id: s }), 0)
            .unwrap();
    }
    let (ob_tx, mut ob_rx) = oneshot::channel();
    running
        .control_with_seq(
            2,
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: res_b,
                revision: 1,
                read_only: false,
                request: request(),
                reply: ob_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.outbound_queue.len(), 1);
    for _ in 0..4 {
        let _ = wire.try_recv().unwrap();
    }

    let (ra_tx, ra_rx) = oneshot::channel();
    let (rb_tx, rb_rx) = oneshot::channel();
    urgent_tx
        .send(SequencedControl {
            seq: 20,
            command: Control::Revoke {
                panel_id: protocol::PANEL_ID,
                id: res_a,
                remove_panel: false,
                reply: ra_tx,
            },
        })
        .unwrap();
    urgent_tx
        .send(SequencedControl {
            seq: 21,
            command: Control::Revoke {
                panel_id: protocol::PANEL_ID,
                id: res_b,
                remove_panel: false,
                reply: rb_tx,
            },
        })
        .unwrap();

    running.drain_urgent_controls(&outgoing).unwrap();
    assert!(ob_rx.try_recv().unwrap().is_err());
    assert!(running.outbound_queue.is_empty());

    let cw_a = wire.try_recv().unwrap();
    assert!(
        matches!(cw_a.body, Some(envelope::Body::CloseRequest(ref c)) if protocol::uuid(&c.resource_id).ok() == Some(res_a) && !c.destroy_panel),
        "unexpected wire frame: {:?}",
        cw_a.body
    );
    assert!(wire.try_recv().is_err(), "retracted Open(res_b) or Cancel must not be sent");

    let mut ack_a = Envelope::new(running.identity, 2, 2, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    ack_a.in_reply_to = cw_a.request_id;
    running.frame(ack_a, &outgoing).await.unwrap();
    ra_rx.await.unwrap().unwrap();

    let cw_b = wire.try_recv().unwrap();
    assert!(
        matches!(cw_b.body, Some(envelope::Body::CloseRequest(ref c)) if protocol::uuid(&c.resource_id).ok() == Some(res_b) && !c.destroy_panel)
    );
    assert!(wire.try_recv().is_err());
    let mut ack_b = Envelope::new(running.identity, 3, 2, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    ack_b.in_reply_to = cw_b.request_id;
    running.frame(ack_b, &outgoing).await.unwrap();
    rb_rx.await.unwrap().unwrap();

    // Sub-part 2: First Revoke delivered via `control_with_seq` while second Revoke sits in `urgent_commands`,
    // plus child-panel `[NonDestroy, Destroy]` coalescing in one urgent pass.
    let res_a2 = Uuid::new_v4();
    let res_b2 = Uuid::new_v4();
    for s in 911..=914u64 {
        running
            .send(&outgoing, envelope::Body::Cancel(protocol::Cancel { request_id: s }), 0)
            .unwrap();
    }
    let (ob2_tx, mut ob2_rx) = oneshot::channel();
    running
        .control_with_seq(
            25,
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: res_b2,
                revision: 1,
                read_only: false,
                request: request(),
                reply: ob2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.outbound_queue.len(), 1);
    for _ in 0..4 {
        let _ = wire.try_recv().unwrap();
    }

    let (ra2_tx, ra2_rx) = oneshot::channel();
    let (rb2_tx, rb2_rx) = oneshot::channel();
    urgent_tx
        .send(SequencedControl {
            seq: 31,
            command: Control::Revoke {
                panel_id: protocol::PANEL_ID,
                id: res_b2,
                remove_panel: false,
                reply: rb2_tx,
            },
        })
        .unwrap();
    running
        .control_with_seq(
            30,
            Control::Revoke {
                panel_id: protocol::PANEL_ID,
                id: res_a2,
                remove_panel: false,
                reply: ra2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(ob2_rx.try_recv().unwrap().is_err());
    assert!(running.outbound_queue.is_empty());

    let cw_a2 = wire.try_recv().unwrap();
    assert!(matches!(cw_a2.body, Some(envelope::Body::CloseRequest(ref c)) if protocol::uuid(&c.resource_id).ok() == Some(res_a2)));
    assert!(wire.try_recv().is_err());
    let mut ack_a2 = Envelope::new(running.identity, 4, 2, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    ack_a2.in_reply_to = cw_a2.request_id;
    running.frame(ack_a2, &outgoing).await.unwrap();
    ra2_rx.await.unwrap().unwrap();
    let cw_b2 = wire.try_recv().unwrap();
    let mut ack_b2 = Envelope::new(running.identity, 5, 2, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION);
    ack_b2.in_reply_to = cw_b2.request_id;
    running.frame(ack_b2, &outgoing).await.unwrap();
    rb2_rx.await.unwrap().unwrap();

    // Child panel 2: ready [NonDestroy(extra), Destroy(primary)] revokes retract extra child Open claim
    // from `c_out` and coalesce to ONE destroy CloseRequest.
    let (c_out, mut c_wire) = mpsc::channel(OUTGOING_CAPACITY);
    let c_claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(c_claims.clone());
    running.supports_panel_multiplexing = true;
    let c_primary = Uuid::new_v4();
    let c_extra = Uuid::new_v4();
    let (oc_tx, oc_rx) = oneshot::channel();
    running
        .control_with_seq(
            35,
            Control::Open {
                panel_id: 2,
                id: c_primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: oc_tx,
            },
            &c_out,
        )
        .await
        .unwrap();
    let oc_w = c_wire.try_recv().unwrap();
    assert!(c_claims.claim_for_write(2, oc_w.request_id));
    let mut snap_c = Envelope::new(
        running.identity,
        6,
        1,
        envelope::Body::Snapshot(make_snap(1, "c2")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    snap_c.in_reply_to = oc_w.request_id;
    running.frame(snap_c, &c_out).await.unwrap();
    oc_rx.await.unwrap().unwrap();
    while c_wire.try_recv().is_ok() {}

    let (ce_tx, mut ce_rx) = oneshot::channel();
    running
        .control_with_seq(
            36,
            Control::Open {
                panel_id: 2,
                id: c_extra,
                revision: 1,
                read_only: false,
                request: request(),
                reply: ce_tx,
            },
            &c_out,
        )
        .await
        .unwrap();
    // Simulate `c_extra` OpenRequest sitting inside `c_out` before the writer task pops & claims it.
    let ce_w = c_wire.try_recv().unwrap();

    let (re_tx, re_rx) = oneshot::channel();
    let (rd_tx, rd_rx) = oneshot::channel();
    urgent_tx
        .send(SequencedControl {
            seq: 40,
            command: Control::Revoke {
                panel_id: 2,
                id: c_extra,
                remove_panel: false,
                reply: re_tx,
            },
        })
        .unwrap();
    urgent_tx
        .send(SequencedControl {
            seq: 41,
            command: Control::Revoke {
                panel_id: 2,
                id: c_primary,
                remove_panel: true,
                reply: rd_tx,
            },
        })
        .unwrap();
    running.drain_urgent_controls(&c_out).unwrap();
    assert!(ce_rx.try_recv().unwrap().is_err());
    assert!(!c_claims.claim_for_write(2, ce_w.request_id));

    let cw_destroy = c_wire.try_recv().unwrap();
    assert_eq!(cw_destroy.panel_id, 2);
    assert!(matches!(cw_destroy.body, Some(envelope::Body::CloseRequest(ref c)) if c.destroy_panel));
    assert!(c_wire.try_recv().is_err());
    let mut ack_destroy = Envelope::new(running.identity, 7, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION).with_panel_id(2);
    ack_destroy.in_reply_to = cw_destroy.request_id;
    running.frame(ack_destroy, &c_out).await.unwrap();
    re_rx.await.unwrap().unwrap();
    rd_rx.await.unwrap().unwrap();
    assert!(!running.panels.contains_key(&2));
}

#[tokio::test]
async fn real_duplex_supervisor_writer_blocked_skips_retracted_open_already_in_outgoing_channel()
{
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.outgoing-claim-skip".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: vec![Permission::TrafficRead],
        contributions: vec!["suite_panel".into()],
    };
    let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
    let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

    let res_a = Uuid::new_v4();
    let res_b = Uuid::new_v4();
    let res_c = Uuid::new_v4();
    let block_reader = Arc::new(tokio::sync::Notify::new());
    let unblock_reader = Arc::new(tokio::sync::Notify::new());
    let burst_sent = Arc::new(tokio::sync::Notify::new());
    let saw_open_c = Arc::new(tokio::sync::Notify::new());
    let block_reader_w = block_reader.clone();
    let unblock_reader_w = unblock_reader.clone();
    let burst_sent_w = burst_sent.clone();
    let saw_open_c_w = saw_open_c.clone();

    let received_opens = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, u64)>::new()));
    let received_closes = Arc::new(std::sync::Mutex::new(Vec::<(u64, Uuid, bool)>::new()));
    let received_cancels = Arc::new(std::sync::Mutex::new(Vec::<(u64, u64)>::new()));
    let open_c_req_id = Arc::new(std::sync::Mutex::new(None::<u64>));
    let opens_w = received_opens.clone();
    let closes_w = received_closes.clone();
    let cancels_w = received_cancels.clone();
    let open_c_req_id_w = open_c_req_id.clone();

    let send_frame = move |seq: &mut u64,
                           panel_id: u64,
                           rev: u64,
                           in_reply_to: u64,
                           body: envelope::Body| {
        *seq += 1;
        let mut env = Envelope::new(identity, *seq, rev, body, MAX_OPERATION).with_panel_id(panel_id);
        env.in_reply_to = in_reply_to;
        env
    };
    let make_snap = |rev: u64, label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Far fewer than `OUTGOING_CAPACITY` (256), enough to saturate the 512B duplex pipe and block
    // `spawn_stream_io`'s writer inside `stdin.write_all` while `outgoing` still has >230 free slots.
    let small_burst = 20usize;
    let worker_task = tokio::spawn(async move {
        let hello = read_async_frame(&mut worker_rx).await?;
        let mut out_seq = 0u64;
        let reg = send_frame(
            &mut out_seq,
            protocol::PANEL_ID,
            1,
            hello.request_id,
            envelope::Body::Register(protocol::Register {
                plugin_id: "lab.outgoing-claim-skip".into(),
                plugin_version: "1.5.0".into(),
                required_components: vec![],
                panel: Some(make_snap(1, "main")),
                supports_panel_multiplexing: false,
            }),
        );
        worker_tx.write_all(&protocol::encode_frame(&reg)?).await?;
        worker_tx.flush().await?;
        let _ready = read_async_frame(&mut worker_rx).await?;

        let mut rev = 1u64;
        let mut reader_blocked = false;
        loop {
            tokio::select! {
                biased;
                _ = block_reader_w.notified(), if !reader_blocked => {
                    reader_blocked = true;
                    for _ in 0..small_burst {
                        let hc = send_frame(
                            &mut out_seq,
                            protocol::PANEL_ID,
                            rev,
                            0,
                            envelope::Body::HostCall(HostCall {
                                operation: Some(host_call::Operation::QueryHistory(
                                    protocol::HistoryQuery {
                                        offset: 0,
                                        limit: 1,
                                        filter: String::new(),
                                    },
                                )),
                                parent_request_id: 999_999,
                            }),
                        );
                        worker_tx.write_all(&protocol::encode_frame(&hc)?).await?;
                    }
                    let fence = send_frame(
                        &mut out_seq,
                        protocol::PANEL_ID,
                        rev,
                        0,
                        envelope::Body::Error(Failure::new(ErrorCode::Internal, "pipe-filled")),
                    );
                    worker_tx.write_all(&protocol::encode_frame(&fence)?).await?;
                    worker_tx.flush().await?;
                    burst_sent_w.notify_one();
                }
                _ = unblock_reader_w.notified(), if reader_blocked => {
                    reader_blocked = false;
                }
                incoming = read_async_frame(&mut worker_rx), if !reader_blocked => {
                    let Ok(env) = incoming else { break; };
                    match env.body {
                        Some(envelope::Body::Shutdown(_)) => break,
                        Some(envelope::Body::OpenRequest(ref open)) => {
                            let rid = protocol::uuid(&open.resource_id).map_err(anyhow::Error::msg)?;
                            opens_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, open.message_revision));
                            if rid == res_c {
                                *open_c_req_id_w.lock().unwrap() = Some(env.request_id);
                                saw_open_c_w.notify_one();
                            } else {
                                rev += 1;
                                let snap = send_frame(
                                    &mut out_seq,
                                    env.panel_id,
                                    rev,
                                    env.request_id,
                                    envelope::Body::Snapshot(make_snap(rev, "opened")),
                                );
                                worker_tx.write_all(&protocol::encode_frame(&snap)?).await?;
                                worker_tx.flush().await?;
                            }
                        }
                        Some(envelope::Body::Cancel(ref cancel)) => {
                            cancels_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, cancel.request_id));
                            let ack = send_frame(
                                &mut out_seq,
                                env.panel_id,
                                rev,
                                env.request_id,
                                envelope::Body::Ack(panel::Empty {}),
                            );
                            worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                            worker_tx.flush().await?;
                        }
                        Some(envelope::Body::CloseRequest(ref close)) => {
                            let rid = protocol::uuid(&close.resource_id).map_err(anyhow::Error::msg)?;
                            closes_w
                                .lock()
                                .unwrap()
                                .push((env.panel_id, rid, close.destroy_panel));
                            let ack = send_frame(
                                &mut out_seq,
                                env.panel_id,
                                rev,
                                env.request_id,
                                envelope::Body::Ack(panel::Empty {}),
                            );
                            worker_tx.write_all(&protocol::encode_frame(&ack)?).await?;
                            worker_tx.flush().await?;
                        }
                        _ => {}
                    }
                }
            }
        }
        Ok::<_, anyhow::Error>(())
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::from([Permission::TrafficRead]),
        host_to_worker,
        worker_to_host,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();
    handle
        .open_request(res_a, 1, false, request())
        .await
        .unwrap();
    let _ = timeout(MAX_OPERATION, supervisor.events.recv()).await.unwrap().unwrap();

    // Block worker reader and saturate the 512B duplex pipe with 20 HostResults so writer task blocks
    // inside `stdin.write_all`, while `outgoing` (256) still has free slots (`outbound_queue` is empty).
    block_reader.notify_one();
    timeout(MAX_OPERATION, burst_sent.notified()).await.unwrap();
    let fence_ev = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(matches!(
        fence_ev,
        PluginEvent::Error { ref failure, .. } if failure.message == "pipe-filled"
    ));

    // Spawn `open_request(res_b)` -> moves directly into `outgoing` writer channel (not `outbound_queue`),
    // waiting behind the blocked writer task.
    let h_b = handle.clone();
    let mut open_b_task = tokio::spawn(async move {
        h_b.open_request(res_b, 1, false, request()).await
    });
    tokio::time::sleep(Duration::from_millis(25)).await;
    assert!(
        tokio::time::timeout(Duration::from_millis(10), &mut open_b_task)
            .await
            .is_err(),
        "open_b must be parked inside blocked outgoing writer channel"
    );

    // Revoke `res_b` while writer is STILL blocked: must immediately retract `OutboundWriteClaims`
    // and fail `open_b_task` BEFORE `unblock_reader` fires!
    let revoke_b = handle.begin_revoke_panel_resource(protocol::PANEL_ID, res_b, false);
    assert!(
        timeout(MAX_OPERATION, open_b_task)
            .await
            .unwrap()
            .unwrap()
            .is_err()
    );

    // Unblock writer -> writer claims & skips `OpenRequest(res_b)`, writing only `CloseRequest(res_b)`.
    unblock_reader.notify_one();
    timeout(MAX_OPERATION, async {
        let mut wait_fut = std::pin::pin!(revoke_b.wait());
        loop {
            tokio::select! {
                res = &mut wait_fut => {
                    res.unwrap();
                    break;
                }
                _ = supervisor.events.recv() => {}
            }
        }
    })
    .await
    .unwrap();

    assert_eq!(received_opens.lock().unwrap().as_slice(), &[(protocol::PANEL_ID, res_a, 1)]);
    assert!(received_cancels.lock().unwrap().is_empty());
    assert_eq!(
        received_closes.lock().unwrap().as_slice(),
        &[(protocol::PANEL_ID, res_b, false)]
    );

    // Contrast (Part B): `OpenRequest(res_c)` already claimed & received by worker still emits Cancel + CloseRequest.
    let h_c = handle.clone();
    let open_c_task = tokio::spawn(async move {
        h_c.open_request(res_c, 1, false, request()).await
    });
    timeout(MAX_OPERATION, saw_open_c.notified()).await.unwrap();
    let expected_c_req_id = open_c_req_id.lock().unwrap().unwrap();
    handle.revoke_resource(res_c).await.unwrap();
    assert!(timeout(MAX_OPERATION, open_c_task).await.unwrap().unwrap().is_err());

    assert_eq!(
        received_cancels.lock().unwrap().as_slice(),
        &[(protocol::PANEL_ID, expected_c_req_id)]
    );
    assert_eq!(
        received_closes.lock().unwrap().as_slice(),
        &[(protocol::PANEL_ID, res_b, false), (protocol::PANEL_ID, res_c, false)]
    );

    while supervisor.events.try_recv().is_ok() {}
    supervisor.stop().await.unwrap();
    timeout(MAX_OPERATION, worker_task).await.unwrap().unwrap().unwrap();
}

#[tokio::test]
async fn shutdown_and_fatal_timeout_retract_unclaimed_frames_before_sending_shutdown_or_cancel() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Part A: Shutdown grace with blocked 512B duplex writer recovering during STOP_GRACE.
    {
        let (mut running, _calls, _updates) = running();
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        // Bind `res_bound` cleanly while worker reader is draining `worker_rx`.
        let res_bound = Uuid::new_v4();
        let (ob_tx, ob_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: res_bound,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: ob_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let open_bound_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let mut snap_bound = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"retained", "bound")),
            MAX_OPERATION,
        );
        snap_bound.in_reply_to = open_bound_env.request_id;
        running.frame(snap_bound, &outgoing).await.unwrap();
        ob_rx.await.unwrap().unwrap();

        // Stop reading `worker_rx` and saturate the 512B pipe with 20 HostResults so writer blocks mid-write.
        for s in 1..=20u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(25)).await;

        // Enqueue `Commit(res_bound)` and `Open(res_unsent)` into `outgoing` behind the blocked writer.
        let (cm_tx, mut cm_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res_bound.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 2,
                            contents: b"edited-stale".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: cm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let res_unsent = Uuid::new_v4();
        let (ou_tx, mut ou_rx) = oneshot::channel();
        running
            .control_with_seq(
                3,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: res_unsent,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: ou_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(cm_rx.try_recv().is_err());
        assert!(ou_rx.try_recv().is_err());

        // Shutdown path retracts unclaimed frames BEFORE sending Shutdown!
        running.prepare_shutdown(&outgoing);
        let mut saw_shutdown = false;
        timeout(MAX_OPERATION, async {
            while let Ok(env) = read_async_frame(&mut worker_rx).await {
                match env.body {
                    Some(envelope::Body::HostResult(_)) => {}
                    Some(envelope::Body::Shutdown(_)) => {
                        saw_shutdown = true;
                        break;
                    }
                    Some(other) => panic!("retracted frame leaked during shutdown grace: {other:?}"),
                    None => {}
                }
            }
        })
        .await
        .unwrap();
        assert!(saw_shutdown);

        io_cancel.cancel();
        io_tasks.abort_all();
    }

    // Part B: Fatal timeout retracts BOTH unclaimed frames in `outgoing` claims AND frames in `outbound_queue`,
    // emitting `Cancel` ONLY for expired frames already claimed by the writer.
    {
        let (mut running, _calls, _updates) = running();
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(4);

        let (oc_tx, _oc_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: oc_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let env_claimed = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, env_claimed.request_id));

        let (ou_tx, _ou_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: ou_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let env_unclaimed = wire.try_recv().unwrap();
        // Do NOT call claim_for_write(env_unclaimed) — simulates unclaimed frame inside `writes` channel.

        // Force a 3rd frame into `outbound_queue`, then free `outgoing` capacity before timeout fires.
        for s in 901..=904u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::Cancel(protocol::Cancel { request_id: s }),
                    0,
                )
                .unwrap();
        }
        let (oq_tx, _oq_rx) = oneshot::channel();
        running
            .control_with_seq(
                3,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: oq_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let req_queued = running.outbound_queue.back().unwrap().request_id;
        for _ in 0..4 {
            let _ = wire.try_recv().unwrap();
        }
        running
            .requests
            .get_mut(&env_claimed.request_id)
            .unwrap()
            .deadline = Instant::now() - Duration::from_secs(1);

        assert!(running.handle_timeouts(Instant::now(), &outgoing).await.is_err());
        assert!(running.outbound_queue.is_empty());
        assert!(!claims.claim_for_write(protocol::PANEL_ID, env_unclaimed.request_id));
        assert!(!claims.try_retract(protocol::PANEL_ID, req_queued));

        let cancel_env = wire.try_recv().unwrap();
        assert!(matches!(
            cancel_env.body,
            Some(envelope::Body::Cancel(protocol::Cancel { request_id })) if request_id == env_claimed.request_id
        ));
        assert!(wire.try_recv().is_err());
    }
}

#[tokio::test]
async fn child_editor_changed_retracted_on_timeout_schedules_resync_and_keeps_worker_consistent() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    // 1. Open child panel 2 with editor v1.
    let res_primary = Uuid::new_v4();
    let (o_tx, o_rx) = oneshot::channel();
    running
        .control_with_seq(
            1,
            Control::Open {
                panel_id: 2,
                id: res_primary,
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ow = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, ow.request_id));
    let mut s1 = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, 1, b"v1", "c2-v1")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    s1.in_reply_to = ow.request_id;
    running.frame(s1, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();
    while wire.try_recv().is_ok() {}

    // 2. Submit mutating `EditorChanged(v2)` on child panel 2, updating host state BEFORE leaving outgoing unclaimed.
    running
        .control_with_seq(
            2,
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::EditorChanged(EditorSnapshot {
                        document_id: 1,
                        revision: 2,
                        contents: b"user-typed-v2".to_vec(),
                        ..Default::default()
                    })),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    {
        let ed = running.editor_on_panel(2, 1).unwrap();
        assert_eq!(ed.revision, 2);
        assert_eq!(ed.contents, b"user-typed-v2");
    }
    let editor_ev = wire.try_recv().unwrap();
    // Do NOT call claim_for_write(2, editor_ev.request_id): event sits unclaimed in `outgoing`.

    // 3. Event times out -> retracted from `outgoing` (writer skips it, NO Cancel emitted), host preserves
    //    `user-typed-v2` AND schedules bounded `Resync(user-typed-v2)`!
    running
        .handle_timeouts(Instant::now() + MAX_OPERATION + Duration::from_secs(1), &outgoing)
        .await
        .unwrap();
    assert!(!claims.claim_for_write(2, editor_ev.request_id));
    {
        let ed = running.editor_on_panel(2, 1).unwrap();
        assert_eq!(ed.revision, 2);
        assert_eq!(ed.contents, b"user-typed-v2");
    }
    let resync_w = wire.try_recv().unwrap();
    assert_eq!(resync_w.panel_id, 2);
    assert!(matches!(
        resync_w.body,
        Some(envelope::Body::Resync(ref snap))
            if matches!(
                snap.root.as_ref().and_then(|n| n.kind.as_ref()),
                Some(panel::node::Kind::Editor(ed))
                    if ed.revision == 2 && ed.contents == b"user-typed-v2"
            )
    ));
    assert!(wire.try_recv().is_err());
    assert!(claims.claim_for_write(2, resync_w.request_id));

    let mut resync_ack = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    resync_ack.in_reply_to = resync_w.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();
    assert!(!running.is_panel_resyncing(2));

    // Commit after Resync settles using user-typed-v2 succeeds cleanly!
    let (cm_tx, cm_rx) = oneshot::channel();
    running
        .control_with_seq(
            3,
            Control::Commit {
                panel_id: 2,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: res_primary.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 2,
                        contents: b"user-typed-v2".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: cm_tx,
                            expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let cm_w = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, cm_w.request_id));
    let mut committed = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Committed(protocol::Committed {
            resource_id: res_primary.as_bytes().to_vec(),
            message_revision: 1,
            document_id: 1,
            document_revision: 2,
            request: Some(request().into()),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    committed.in_reply_to = cm_w.request_id;
    running.frame(committed, &outgoing).await.unwrap();
    assert_eq!(cm_rx.await.unwrap().unwrap().url, request().url);

    // 4. Negative control: retracting an unclaimed non-mutating `Focus` event does NOT trigger unnecessary Resync.
    running
        .control_with_seq(
            4,
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let focus_ev = wire.try_recv().unwrap();
    running
        .handle_timeouts(Instant::now() + MAX_OPERATION + Duration::from_secs(2), &outgoing)
        .await
        .unwrap();
    assert!(!claims.claim_for_write(2, focus_ev.request_id));
    assert!(wire.try_recv().is_err());
}

#[tokio::test]
async fn main_panel_local_expired_reply_retracts_unclaimed_open_before_sending_fatal_cancel() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Part A: Main panel local-pending-expired late reply with blocked 512B duplex writer retracts
    // another unexpired unclaimed Open in `outgoing` BEFORE sending fatal Cancel (before `prepare_shutdown`).
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let res_main = Uuid::new_v4();
        let (om_tx, om_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: res_main,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: om_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let open_main_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();

        // Saturate 512B pipe so writer task blocks mid-write before draining newer frames.
        for s in 1..=20u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(25)).await;

        let res_child = Uuid::new_v4();
        let (oc_tx, _oc_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Open {
                    panel_id: 2,
                    id: res_child,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: oc_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();

        running
            .requests
            .get_mut(&open_main_env.request_id)
            .unwrap()
            .deadline = Instant::now() - Duration::from_secs(1);

        let mut late_snap = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"retained", "late-main")),
            MAX_OPERATION,
        );
        late_snap.in_reply_to = open_main_env.request_id;
        let err = running
            .frame(late_snap, &outgoing)
            .await
            .unwrap_err()
            .to_string();
        assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
        let om_err = om_rx.await.unwrap().unwrap_err().to_string();
        assert!(om_err.contains("主面板操作已超时"), "unexpected main reply: {om_err}");

        // Writer recovers BEFORE `prepare_shutdown`: Cancel arrives and unexpired child Open never leaks.
        let mut saw_cancel = false;
        timeout(MAX_OPERATION, async {
            while let Ok(env) = read_async_frame(&mut worker_rx).await {
                match env.body {
                    Some(envelope::Body::HostResult(_)) => {}
                    Some(envelope::Body::Cancel(c)) if c.request_id == open_main_env.request_id => {
                        saw_cancel = true;
                        break;
                    }
                    Some(other) => {
                        panic!("unclaimed OpenRequest leaked before prepare_shutdown: {other:?}")
                    }
                    None => {}
                }
            }
        })
        .await
        .unwrap();
        assert!(saw_cancel);

        io_cancel.cancel();
        io_tasks.abort_all();
    }

    // Part B: `outbound_queue` implicit flush guard — sending fatal Cancel must not flush an
    // unexpired Open sitting in `outbound_queue` into a freed `outgoing` slot.
    {
        let (mut running, _calls, _updates) = running();
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(4);

        let res1 = Uuid::new_v4();
        let (o1_tx, o1_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: res1,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o1_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o1_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, o1_env.request_id));
        let mut o1_snap = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"retained", "res1")),
            MAX_OPERATION,
        );
        o1_snap.in_reply_to = o1_env.request_id;
        running.frame(o1_snap, &outgoing).await.unwrap();
        o1_rx.await.unwrap().unwrap();

        let (cm_tx, cm_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res1.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 2,
                            contents: b"edited".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: cm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let cm_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, cm_env.request_id));

        for s in 1..=4u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }

        let res2 = Uuid::new_v4();
        let (o2_tx, _o2_rx) = oneshot::channel();
        running
            .control_with_seq(
                3,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: res2,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(running.outbound_queue.iter().any(|e| {
            matches!(e.body, Some(envelope::Body::OpenRequest(_)))
        }));

        // Free 1 slot in `outgoing` so any unguarded flush would move Open(res2) into `outgoing`.
        let first_hr = wire.try_recv().unwrap();
        assert!(matches!(first_hr.body, Some(envelope::Body::HostResult(_))));

        running
            .requests
            .get_mut(&cm_env.request_id)
            .unwrap()
            .deadline = Instant::now() - Duration::from_secs(1);

        let mut late_committed = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Committed(protocol::Committed {
                resource_id: res1.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 2,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        );
        late_committed.in_reply_to = cm_env.request_id;
        let err = running
            .frame(late_committed, &outgoing)
            .await
            .unwrap_err()
            .to_string();
        assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
        assert!(cm_rx.await.unwrap().is_err());
        assert!(!running.outbound_queue.iter().any(|e| {
            matches!(e.body, Some(envelope::Body::OpenRequest(_)))
        }));

        let mut drained = Vec::new();
        while let Ok(env) = wire.try_recv() {
            drained.push(env);
        }
        assert!(
            !drained
                .iter()
                .any(|e| matches!(e.body, Some(envelope::Body::OpenRequest(_)))),
            "OpenRequest leaked into outgoing before prepare_shutdown"
        );
        assert!(
            drained.iter().any(|e| matches!(
                e.body,
                Some(envelope::Body::Cancel(ref c)) if c.request_id == cm_env.request_id
            )),
            "expected fatal Cancel for expired in-flight Commit"
        );
    }
}

#[tokio::test]
async fn child_pointer_capture_retraction_resets_host_and_cancels_worker_drag() {
    let canvas_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: "canvas".into(),
        root: Some(panel::Node::new(
            2,
            "canvas",
            panel::node::Kind::Canvas(panel::Canvas {
                width: 100.0,
                height: 100.0,
                commands: vec![],
                hit_regions: vec![panel::HitRegion {
                    id: 10,
                    bounds: Some(panel::Rect {
                        x: 0.0,
                        y: 0.0,
                        width: 100.0,
                        height: 100.0,
                    }),
                    accessibility_label: "hit".into(),
                    focusable: false,
                    capture_pointer: true,
                }],
            }),
        )),
    };

    // Part A: Unclaimed Pointer(Down) timeout & retraction resets host capture without Resync or
    // spurious Worker Pointer(Cancel), so outside Move is rejected locally.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let res_child = Uuid::new_v4();
        let (o_tx, o_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: res_child,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let open_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let mut open_snap = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(canvas_snap(1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        open_snap.in_reply_to = open_env.request_id;
        running.frame(open_snap, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        for s in 1..=20u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(25)).await;

        running
            .control_with_seq(
                2,
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                            hit_id: 10,
                            phase: panel::PointerPhase::Down as i32,
                            x: 50.0,
                            y: 50.0,
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.panel_capture(2), Some((2, 10)));
        let down_req_id = *running.requests.keys().next().unwrap();
        running.requests.get_mut(&down_req_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);

        running
            .handle_timeouts(Instant::now(), &outgoing)
            .await
            .unwrap();
        assert_eq!(running.panel_capture(2), None);
        assert_eq!(running.panels.get(&2).unwrap().resync_needed_seq, 0);
        assert!(running
            .panels
            .get(&2)
            .unwrap()
            .pending_pointer_cancels
            .is_empty());

        // Outside-bounds Move must be rejected locally because capture was cleared.
        running
            .control_with_seq(
                3,
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                            hit_id: 10,
                            phase: panel::PointerPhase::Move as i32,
                            x: 500.0,
                            y: 500.0,
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(running.requests.is_empty());

        running.prepare_shutdown(&outgoing);
        let mut saw_shutdown = false;
        timeout(MAX_OPERATION, async {
            while let Ok(env) = read_async_frame(&mut worker_rx).await {
                match env.body {
                    Some(envelope::Body::HostResult(_)) => {}
                    Some(envelope::Body::Shutdown(_)) => {
                        saw_shutdown = true;
                        break;
                    }
                    Some(other) => {
                        panic!("unexpected frame on Worker after unclaimed Down retract: {other:?}")
                    }
                    None => {}
                }
            }
        })
        .await
        .unwrap();
        assert!(saw_shutdown);

        io_cancel.cancel();
        io_tasks.abort_all();
    }

    // Part B: Already-written Pointer(Down) starts drag on Worker, then unclaimed Pointer(Up) times
    // out & retracts -> host keeps capture None, retracted Up is skipped, and Worker receives
    // tracked UiEvent::Pointer(Cancel) behind a command barrier before newer events flush.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let res_child = Uuid::new_v4();
        let (o_tx, o_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: res_child,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let open_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let mut open_snap = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(canvas_snap(1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        open_snap.in_reply_to = open_env.request_id;
        running.frame(open_snap, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        running
            .control_with_seq(
                2,
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                            hit_id: 10,
                            phase: panel::PointerPhase::Down as i32,
                            x: 50.0,
                            y: 50.0,
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let down_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let mut down_ack =
            Envelope::new(running.identity, 2, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
                .with_panel_id(2);
        down_ack.in_reply_to = down_env.request_id;
        running.frame(down_ack, &outgoing).await.unwrap();
        assert_eq!(running.panel_capture(2), Some((2, 10)));

        // Block writer and enqueue Pointer(Up).
        for s in 1..=20u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(25)).await;

        running
            .control_with_seq(
                3,
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                            hit_id: 10,
                            phase: panel::PointerPhase::Up as i32,
                            x: 250.0,
                            y: 250.0,
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.panel_capture(2), None);
        let up_req_id = *running.requests.keys().next().unwrap();
        running.requests.get_mut(&up_req_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);

        running
            .handle_timeouts(Instant::now(), &outgoing)
            .await
            .unwrap();
        assert_eq!(running.panel_capture(2), None);
        assert_eq!(running.panels.get(&2).unwrap().resync_needed_seq, 0);
        assert!(!running
            .panels
            .get(&2)
            .unwrap()
            .pending_pointer_cancels
            .is_empty());

        // Newer interaction on panel 2 must wait behind the pointer-cancel recovery barrier.
        running
            .control_with_seq(
                4,
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                            hit_id: 10,
                            phase: panel::PointerPhase::Down as i32,
                            x: 40.0,
                            y: 40.0,
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.panels.get(&2).unwrap().deferred_commands.len(), 1);

        let cancel_env = timeout(MAX_OPERATION, async {
            loop {
                let env = read_async_frame(&mut worker_rx).await.unwrap();
                match &env.body {
                    Some(envelope::Body::HostResult(_)) => continue,
                    Some(envelope::Body::UiEvent(ev)) => match &ev.event {
                        Some(panel::ui_event::Event::Pointer(p))
                            if p.phase == panel::PointerPhase::Cancel as i32
                                && ev.node_id == 2
                                && p.hit_id == 10 =>
                        {
                            return env;
                        }
                        other => panic!("unexpected UiEvent on Worker: {other:?}"),
                    },
                    other => panic!("unexpected frame on Worker: {other:?}"),
                }
            }
        })
        .await
        .unwrap();

        let mut cancel_ack =
            Envelope::new(running.identity, 3, 1, envelope::Body::Ack(panel::Empty {}), MAX_OPERATION)
                .with_panel_id(2);
        cancel_ack.in_reply_to = cancel_env.request_id;
        running.frame(cancel_ack, &outgoing).await.unwrap();
        assert!(running
            .panels
            .get(&2)
            .unwrap()
            .pending_pointer_cancels
            .is_empty());
        assert!(running
            .panels
            .get(&2)
            .unwrap()
            .deferred_commands
            .is_empty());
        assert_eq!(running.panel_capture(2), Some((2, 10)));

        let new_down_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        assert!(matches!(
            new_down_env.body,
            Some(envelope::Body::UiEvent(ref ev))
                if matches!(
                    ev.event,
                    Some(panel::ui_event::Event::Pointer(ref p))
                        if p.phase == panel::PointerPhase::Down as i32
                            && (p.x - 40.0).abs() < f32::EPSILON
                )
        ));

        io_cancel.cancel();
        io_tasks.abort_all();
    }
}

#[tokio::test]
async fn running_loop_fatal_timeout_retracts_outbound_queue_before_write_permit_or_late_reply() {
    use tokio::io::AsyncWriteExt as _;

    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Part A: Loop-top check in real `Running::run` — expired main request, unexpired Open in
    // `outbound_queue`, empty `outgoing` (write permit ready), and pre-written late Worker
    // Snapshot reply all ready simultaneously at entry; `Running::run` must fail fatally WITHOUT
    // flushing the queued OpenRequest.
    {
        let (mut running, _calls, _updates) = running();
        let (_cmd_tx, cmd_rx) = mpsc::channel(QUEUE_CAPACITY);
        let (_urgent_tx, urgent_rx) = mpsc::unbounded_channel();

        let (om_tx, om_rx) = oneshot::channel();
        running.requests.insert(
            1,
            Pending {
                panel_id: protocol::PANEL_ID,
                panel_revision_at_send: 0,
                deadline: Instant::now() - Duration::from_secs(1),
                cancel: CancellationToken::new(),
                from_deferred_queue: false,
                source_seq: 1,
                kind: PendingKind::Open {
                    resource: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    reserved: false,
                    reply: om_tx,
                },
            },
        );
        let (oq_tx, oq_rx) = oneshot::channel();
        let queued_open_env = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::OpenRequest(protocol::OpenRequest {
                resource_id: Uuid::new_v4().as_bytes().to_vec(),
                message_revision: 1,
                read_only: false,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        );
        running.outbound_queue.push_back(queued_open_env);
        running.requests.insert(
            2,
            Pending {
                panel_id: protocol::PANEL_ID,
                panel_revision_at_send: 0,
                deadline: Instant::now() + MAX_OPERATION,
                cancel: CancellationToken::new(),
                from_deferred_queue: false,
                source_seq: 2,
                kind: PendingKind::Open {
                    resource: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    reserved: false,
                    reply: oq_tx,
                },
            },
        );
        running.outgoing_sequence = 2;

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(64 * 1024);
        let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        let mut late_snap = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"retained", "late-a")),
            MAX_OPERATION,
        );
        late_snap.in_reply_to = 1;
        worker_tx
            .write_all(&protocol::encode_frame(&late_snap).unwrap())
            .await
            .unwrap();

        let reader_task = tokio::spawn(async move {
            let mut frames = Vec::new();
            while let Ok(env) = read_async_frame(&mut worker_rx).await {
                frames.push(env);
            }
            frames
        });

        let err = timeout(
            MAX_OPERATION,
            running.run(
                WorkerTransport::Duplex {
                    stdin: host_to_worker,
                    stdout: worker_to_host,
                },
                cmd_rx,
                urgent_rx,
            ),
        )
        .await
        .unwrap()
        .unwrap_err()
        .to_string();
        assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
        assert!(om_rx.await.unwrap().is_err());
        assert!(oq_rx.await.unwrap().is_err());

        let frames = reader_task.await.unwrap();
        assert!(
            !frames
                .iter()
                .any(|e| matches!(e.body, Some(envelope::Body::OpenRequest(_)))),
            "unexpired queued OpenRequest leaked during Running::run loop-top race: {frames:?}"
        );
    }

    // Part B: Active `tokio::select!` race in real `Running::run` — throttled reader continuously
    // wakes `outgoing.reserve()` across fatal expiry + late Worker reply; unexpired OpenRequest
    // behind HostResults in `outbound_queue` must still be retracted rather than flushed.
    {
        let (mut running, _calls, _updates) = running();
        let (cmd_tx, cmd_rx) = mpsc::channel(QUEUE_CAPACITY);
        let (_urgent_tx, urgent_rx) = mpsc::unbounded_channel();

        let (om_tx, om_rx) = oneshot::channel();
        running.requests.insert(
            1,
            Pending {
                panel_id: protocol::PANEL_ID,
                panel_revision_at_send: 0,
                deadline: Instant::now() + Duration::from_millis(80),
                cancel: CancellationToken::new(),
                from_deferred_queue: false,
                source_seq: 1,
                kind: PendingKind::Open {
                    resource: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    reserved: false,
                    reply: om_tx,
                },
            },
        );
        for seq in 2..=(OUTGOING_CAPACITY as u64 + 14) {
            running.outbound_queue.push_back(Envelope::new(
                running.identity,
                seq,
                1,
                envelope::Body::HostResult(HostResult {
                    outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                }),
                MAX_OPERATION,
            ));
        }
        running.outgoing_sequence = OUTGOING_CAPACITY as u64 + 14;
        let identity = running.identity;

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
        let (mut worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);

        let reader_task = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(15)).await;
            let mut frames = Vec::new();
            while let Ok(env) = read_async_frame(&mut worker_rx).await {
                frames.push(env);
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
            frames
        });

        let worker_reply_task = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(80)).await;
            let mut late_snap = Envelope::new(
                identity,
                1,
                2,
                envelope::Body::Snapshot(make_snap(2, 1, b"retained", "late-b")),
                MAX_OPERATION,
            );
            late_snap.in_reply_to = 1;
            let _ = worker_tx
                .write_all(&protocol::encode_frame(&late_snap).unwrap())
                .await;
            worker_tx
        });

        let run_handle = tokio::spawn(async move {
            running
                .run(
                    WorkerTransport::Duplex {
                        stdin: host_to_worker,
                        stdout: worker_to_host,
                    },
                    cmd_rx,
                    urgent_rx,
                )
                .await
        });

        let (oq_tx, oq_rx) = oneshot::channel();
        cmd_tx
            .send(SequencedControl {
                seq: 2,
                command: Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: oq_tx,
                },
            })
            .await
            .unwrap();

        let err = timeout(MAX_OPERATION, run_handle)
            .await
            .unwrap()
            .unwrap()
            .unwrap_err()
            .to_string();
        assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
        assert!(om_rx.await.unwrap().is_err());
        assert!(oq_rx.await.unwrap().is_err());

        let _keep_tx = worker_reply_task.await.unwrap();
        let frames = timeout(MAX_OPERATION, reader_task).await.unwrap().unwrap();
        assert!(
            !frames
                .iter()
                .any(|e| matches!(e.body, Some(envelope::Body::OpenRequest(_)))),
            "queued OpenRequest leaked past write permit / fatal deadline race"
        );
    }
}

#[tokio::test]
async fn child_pointer_error_recovery_handles_acquired_released_deadline_retry_and_definitive_abort()
{
    let canvas_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: "canvas".into(),
        root: Some(panel::Node::new(
            2,
            "canvas",
            panel::node::Kind::Canvas(panel::Canvas {
                width: 100.0,
                height: 100.0,
                commands: vec![],
                hit_regions: vec![panel::HitRegion {
                    id: 10,
                    bounds: Some(panel::Rect {
                        x: 0.0,
                        y: 0.0,
                        width: 100.0,
                        height: 100.0,
                    }),
                    accessibility_label: "hit".into(),
                    focusable: false,
                    capture_pointer: true,
                }],
            }),
        )),
    };

    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let mut worker_seq = 0u64;
    let mut next_worker_seq = || {
        worker_seq += 1;
        worker_seq
    };
    let mut cmd_seq = 0u64;
    let mut next_cmd_seq = || {
        cmd_seq += 1;
        cmd_seq
    };

    // Open child panel 2 with Canvas hit region.
    let res_child = Uuid::new_v4();
    let (o_tx, o_rx) = oneshot::channel();
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Open {
                panel_id: 2,
                id: res_child,
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_env = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, open_env.request_id));
    let mut open_snap = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Snapshot(canvas_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = open_env.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();

    // Helper closures cannot mutably borrow `running`+`claims` easily; inline clear helpers:
    let send_pointer = |phase: panel::PointerPhase, x: f32, y: f32| Control::Event {
        panel_id: 2,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                hit_id: 10,
                phase: phase as i32,
                x,
                y,
            })),
        },
        event_seq: 0,
    };

    // Case 1: Worker rejects already-sent Pointer(Down) (`Acquired`) with Error(Invalid) ->
    // Host clears capture AND dispatches tracked Pointer(Cancel) in case Worker mutated gesture.
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, down1.request_id));
    let mut down1_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "down rejected")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    down1_err.in_reply_to = down1.request_id;
    running.frame(down1_err, &outgoing).await.unwrap();
    assert_eq!(running.panel_capture(2), None);
    let cancel1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, cancel1.request_id));
    assert!(matches!(
        cancel1.body,
        Some(envelope::Body::UiEvent(ref ev))
            if matches!(
                ev.event,
                Some(panel::ui_event::Event::Pointer(ref p))
                    if p.phase == panel::PointerPhase::Cancel as i32 && p.hit_id == 10
            )
    ));
    let mut cancel1_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    cancel1_ack.in_reply_to = cancel1.request_id;
    running.frame(cancel1_ack, &outgoing).await.unwrap();
    assert!(running
        .panels
        .get(&2)
        .unwrap()
        .pending_pointer_cancels
        .is_empty());

    // Case 2: Written Pointer(Down) ACKed -> Pointer(Up) rejected with Error(Invalid) (`Released`)
    // -> synthetic Pointer(Cancel) receives Error(Deadline) (must retain seq, keep barrier & retry!)
    // -> 2nd synthetic Pointer(Cancel) ACKed -> releases deferred Pointer(Down).
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, down2.request_id));
    let mut down2_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    down2_ack.in_reply_to = down2.request_id;
    running.frame(down2_ack, &outgoing).await.unwrap();
    assert_eq!(running.panel_capture(2), Some((2, 10)));

    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.panel_capture(2), None);
    let up2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, up2.request_id));
    let mut up2_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    up2_err.in_reply_to = up2.request_id;
    running.frame(up2_err, &outgoing).await.unwrap();

    let rec2_1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, rec2_1.request_id));
    let cancel_seq2 = running
        .panels
        .get(&2)
        .unwrap()
        .pending_pointer_cancels
        .front()
        .unwrap()
        .seq;
    assert_eq!(
        running
            .panels
            .get(&2)
            .unwrap()
            .pending_pointer_cancels
            .front()
            .unwrap()
            .attempts,
        1
    );

    // Deferred Pointer(Down) must wait behind the synthetic Cancel barrier.
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 40.0, 40.0),
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.panels.get(&2).unwrap().deferred_commands.len(), 1);
    assert!(wire.try_recv().is_err());

    // Synthetic Pointer(Cancel) gets Error(Deadline): preserves `cancel_seq2`, keeps barrier, retries!
    let mut rec2_1_deadline = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Deadline, "cancel timed out")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    rec2_1_deadline.in_reply_to = rec2_1.request_id;
    running.frame(rec2_1_deadline, &outgoing).await.unwrap();
    {
        let slot = running.panels.get(&2).unwrap();
        let front = slot.pending_pointer_cancels.front().unwrap();
        assert_eq!(front.seq, cancel_seq2);
        assert_eq!(front.attempts, 2);
        assert_eq!(slot.deferred_commands.len(), 1);
    }
    let rec2_2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, rec2_2.request_id));
    assert!(wire.try_recv().is_err());

    let mut rec2_2_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    rec2_2_ack.in_reply_to = rec2_2.request_id;
    running.frame(rec2_2_ack, &outgoing).await.unwrap();
    assert!(running
        .panels
        .get(&2)
        .unwrap()
        .pending_pointer_cancels
        .is_empty());
    assert!(running
        .panels
        .get(&2)
        .unwrap()
        .deferred_commands
        .is_empty());
    assert_eq!(running.panel_capture(2), Some((2, 10)));

    // Deferred Pointer(Down) flushed now!
    let down3 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, down3.request_id));

    // Case 3: Definitive non-Deadline Error(Invalid) on synthetic Pointer(Cancel) aborts barrier
    // and fails all deferred commands cleanly.
    let mut down3_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    down3_ack.in_reply_to = down3.request_id;
    running.frame(down3_ack, &outgoing).await.unwrap();

    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    let up3 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, up3.request_id));
    let mut up3_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    up3_err.in_reply_to = up3.request_id;
    running.frame(up3_err, &outgoing).await.unwrap();
    let rec3_1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, rec3_1.request_id));

    let (def_open_tx, def_open_rx) = oneshot::channel();
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Open {
                panel_id: 2,
                id: res_child,
                revision: 2,
                read_only: false,
                request: request(),
                reply: def_open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 45.0, 45.0),
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.panels.get(&2).unwrap().deferred_commands.len(), 2);

    let mut rec3_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "cancel unsupported")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    rec3_err.in_reply_to = rec3_1.request_id;
    running.frame(rec3_err, &outgoing).await.unwrap();
    assert!(running
        .panels
        .get(&2)
        .unwrap()
        .pending_pointer_cancels
        .is_empty());
    assert!(running
        .panels
        .get(&2)
        .unwrap()
        .deferred_commands
        .is_empty());
    assert!(wire.try_recv().is_err());
    let def_open_err = def_open_rx.await.unwrap().unwrap_err().to_string();
    assert!(
        def_open_err.contains("面板指针手势取消失败"),
        "unexpected abort err: {def_open_err}"
    );

    // Case 4: Exhausting `MAX_RESYNC_RETRIES` Deadline replies clears barrier & fails deferred cmds.
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down4 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, down4.request_id));
    let mut down4_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    down4_ack.in_reply_to = down4.request_id;
    running.frame(down4_ack, &outgoing).await.unwrap();

    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    let up4 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, up4.request_id));
    let mut up4_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    up4_err.in_reply_to = up4.request_id;
    running.frame(up4_err, &outgoing).await.unwrap();

    let mut rec4_env = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, rec4_env.request_id));

    let (def2_tx, mut def2_rx) = oneshot::channel();
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Open {
                panel_id: 2,
                id: res_child,
                revision: 3,
                read_only: false,
                request: request(),
                reply: def2_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();

    for attempt in 1..=MAX_RESYNC_RETRIES {
        let mut dl = Envelope::new(
            running.identity,
            next_worker_seq(),
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "cancel timeout")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        dl.in_reply_to = rec4_env.request_id;
        running.frame(dl, &outgoing).await.unwrap();
        if attempt < MAX_RESYNC_RETRIES {
            assert!(def2_rx.try_recv().is_err());
            rec4_env = wire.try_recv().unwrap();
            assert!(claims.claim_for_write(2, rec4_env.request_id));
        }
    }
    assert!(running
        .panels
        .get(&2)
        .unwrap()
        .pending_pointer_cancels
        .is_empty());
    assert!(wire.try_recv().is_err());
    let exhausted_err = def2_rx.await.unwrap().unwrap_err().to_string();
    assert!(
        exhausted_err.contains("重试超过上限"),
        "unexpected budget exhaustion err: {exhausted_err}"
    );
}

#[tokio::test]
async fn event_backpressure_crossing_fatal_deadline_aborts_before_post_await_flush() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Part A: `handle_timeouts` suspends on saturated `events` channel while emitting child timeout
    // diagnostic; meanwhile a main-panel request crosses its fatal deadline. Once unblocked, urgent
    // Revoke / CloseRequest must NOT push/flush any unexpired outbound frame.
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let (urgent_tx, urgent_rx) = mpsc::unbounded_channel();
        running.urgent_commands = Some(urgent_rx);
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let res_child = Uuid::new_v4();
        let (oc_tx, oc_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: res_child,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: oc_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let child_open_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, child_open_env.request_id));
        let mut child_snap = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1, b"child", "child")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        child_snap.in_reply_to = child_open_env.request_id;
        running.frame(child_snap, &outgoing).await.unwrap();
        oc_rx.await.unwrap().unwrap();
        while updates.try_recv().is_ok() {}

        let (ce_tx, ce_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 2,
                    read_only: false,
                    request: request(),
                    reply: ce_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let child_expired_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, child_expired_env.request_id));
        running
            .requests
            .get_mut(&child_expired_env.request_id)
            .unwrap()
            .deadline = Instant::now() - Duration::from_secs(1);

        let (om_tx, _om_rx) = oneshot::channel();
        running
            .control_with_seq(
                3,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: om_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let main_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, main_env.request_id));
        running
            .requests
            .get_mut(&main_env.request_id)
            .unwrap()
            .deadline = Instant::now() + Duration::from_millis(25);

        // Fill outgoing channel completely, push an unexpired Open into `outbound_queue`, then free 1 slot.
        for s in 1..=(OUTGOING_CAPACITY as u64) {
            running
                .send(
                    &outgoing,
                    envelope::Body::Cancel(protocol::Cancel { request_id: s + 10_000 }),
                    0,
                )
                .unwrap();
        }
        let (oq_tx, _oq_rx) = oneshot::channel();
        running
            .control_with_seq(
                4,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 2,
                    read_only: false,
                    request: request(),
                    reply: oq_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let req_unexpired = running.outbound_queue.back().unwrap().request_id;
        assert!(matches!(wire.try_recv().unwrap().body, Some(envelope::Body::Cancel(_))));

        // Saturate `running.events` so `diagnostic_on_panel` blocks across `main_env`'s deadline.
        while running
            .events
            .try_send(PluginEvent::Stopped {
                identity: running.identity,
                reason: "fill".into(),
            })
            .is_ok()
        {}

        let helper = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(50)).await;
            let (rev_tx, rev_rx) = oneshot::channel();
            let _ = urgent_tx.send(SequencedControl {
                seq: 5,
                command: Control::Revoke {
                    panel_id: 2,
                    id: res_child,
                    remove_panel: false,
                    reply: rev_tx,
                },
            });
            while updates.try_recv().is_ok() {}
            (urgent_tx, updates, rev_rx)
        });

        let err = running
            .handle_timeouts(Instant::now(), &outgoing)
            .await
            .unwrap_err()
            .to_string();
        assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
        let _ = ce_rx.await;
        let _keep = helper.await.unwrap();

        assert!(!running.outbound_queue.iter().any(|e| {
            matches!(e.body, Some(envelope::Body::OpenRequest(_)))
        }));
        assert!(!claims.try_retract(protocol::PANEL_ID, req_unexpired));
        let mut drained = Vec::new();
        while let Ok(env) = wire.try_recv() {
            drained.push(env);
        }
        assert!(
            !drained
                .iter()
                .any(|e| matches!(e.body, Some(envelope::Body::OpenRequest(_)))),
            "OpenRequest leaked into outgoing after diagnostic await crossed fatal deadline"
        );
        assert!(
            drained.iter().any(|e| matches!(
                e.body,
                Some(envelope::Body::Cancel(ref c)) if c.request_id == main_env.request_id
            )),
            "expected fatal Cancel for main_env"
        );
    }

    // Part B: `io.rs` `Body::Error` suspends on saturated `events` channel while `main_env` crosses
    // its fatal deadline; resuming to `flush_pending_revokes` must abort fatally BEFORE urgent Revoke
    // flushes `outbound_queue`.
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let (urgent_tx, urgent_rx) = mpsc::unbounded_channel();
        running.urgent_commands = Some(urgent_rx);
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let res_child = Uuid::new_v4();
        let (oc_tx, oc_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: res_child,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: oc_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let child_open_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, child_open_env.request_id));
        let mut child_snap = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1, b"child", "child")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        child_snap.in_reply_to = child_open_env.request_id;
        running.frame(child_snap, &outgoing).await.unwrap();
        oc_rx.await.unwrap().unwrap();
        while updates.try_recv().is_ok() {}

        let (ce_tx, ce_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 2,
                    read_only: false,
                    request: request(),
                    reply: ce_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let child_err_req = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, child_err_req.request_id));

        let (om_tx, _om_rx) = oneshot::channel();
        running
            .control_with_seq(
                3,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: om_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let main_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, main_env.request_id));
        running
            .requests
            .get_mut(&main_env.request_id)
            .unwrap()
            .deadline = Instant::now() + Duration::from_millis(25);

        for s in 1..=(OUTGOING_CAPACITY as u64) {
            running
                .send(
                    &outgoing,
                    envelope::Body::Cancel(protocol::Cancel { request_id: s + 20_000 }),
                    0,
                )
                .unwrap();
        }
        let (oq_tx, _oq_rx) = oneshot::channel();
        running
            .control_with_seq(
                4,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 2,
                    read_only: false,
                    request: request(),
                    reply: oq_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let req_unexpired = running.outbound_queue.back().unwrap().request_id;
        assert!(matches!(wire.try_recv().unwrap().body, Some(envelope::Body::Cancel(_))));

        while running
            .events
            .try_send(PluginEvent::Stopped {
                identity: running.identity,
                reason: "fill".into(),
            })
            .is_ok()
        {}

        let helper = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(50)).await;
            let (rev_tx, rev_rx) = oneshot::channel();
            let _ = urgent_tx.send(SequencedControl {
                seq: 5,
                command: Control::Revoke {
                    panel_id: 2,
                    id: res_child,
                    remove_panel: false,
                    reply: rev_tx,
                },
            });
            while updates.try_recv().is_ok() {}
            (urgent_tx, updates, rev_rx)
        });

        let mut child_err_frame = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Invalid, "child op failed")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        child_err_frame.in_reply_to = child_err_req.request_id;
        let err = running
            .frame(child_err_frame, &outgoing)
            .await
            .unwrap_err()
            .to_string();
        assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
        let _ = ce_rx.await;
        let _keep = helper.await.unwrap();

        assert!(!running.outbound_queue.iter().any(|e| {
            matches!(e.body, Some(envelope::Body::OpenRequest(_)))
        }));
        assert!(!claims.try_retract(protocol::PANEL_ID, req_unexpired));
        let mut drained = Vec::new();
        while let Ok(env) = wire.try_recv() {
            drained.push(env);
        }
        assert!(
            !drained
                .iter()
                .any(|e| matches!(e.body, Some(envelope::Body::OpenRequest(_)))),
            "OpenRequest leaked into outgoing after frame diagnostic await crossed fatal deadline"
        );
        assert!(
            drained.iter().any(|e| matches!(
                e.body,
                Some(envelope::Body::Cancel(ref c)) if c.request_id == main_env.request_id
            )),
            "expected fatal Cancel for main_env"
        );
    }
}

#[tokio::test]
async fn main_panel_pointer_cancel_recovery_is_non_fatal_across_timeout_late_reply_and_host_call() {
    let canvas_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: "main-canvas".into(),
        root: Some(panel::Node::new(
            2,
            "canvas",
            panel::node::Kind::Canvas(panel::Canvas {
                width: 100.0,
                height: 100.0,
                commands: vec![],
                hit_regions: vec![panel::HitRegion {
                    id: 10,
                    bounds: Some(panel::Rect {
                        x: 0.0,
                        y: 0.0,
                        width: 100.0,
                        height: 100.0,
                    }),
                    accessibility_label: "hit".into(),
                    focusable: false,
                    capture_pointer: true,
                }],
            }),
        )),
    };

    let (mut running, _calls, _updates) = running();
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let mut worker_seq = 0u64;
    let mut next_worker_seq = || {
        worker_seq += 1;
        worker_seq
    };
    let mut cmd_seq = 0u64;
    let mut next_cmd_seq = || {
        cmd_seq += 1;
        cmd_seq
    };

    // Replace main panel with Canvas snapshot at revision 2.
    let (om_tx, om_rx) = oneshot::channel();
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: om_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_env = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, open_env.request_id));
    let mut open_snap = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Snapshot(canvas_snap(2)),
        MAX_OPERATION,
    );
    open_snap.in_reply_to = open_env.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    om_rx.await.unwrap().unwrap();

    let send_main_pointer = |phase: panel::PointerPhase, x: f32, y: f32| Control::Event {
        panel_id: protocol::PANEL_ID,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                hit_id: 10,
                phase: phase as i32,
                x,
                y,
            })),
        },
        event_seq: 0,
    };

    // Start capture on main panel -> Ack, then fail Up -> dispatches attempt 1 of Pointer(Cancel).
    running
        .control_with_seq(
            next_cmd_seq(),
            send_main_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, down1.request_id));
    let mut down1_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    down1_ack.in_reply_to = down1.request_id;
    running.frame(down1_ack, &outgoing).await.unwrap();
    assert_eq!(running.panel_capture(protocol::PANEL_ID), Some((2, 10)));

    running
        .control_with_seq(
            next_cmd_seq(),
            send_main_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    let up1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, up1.request_id));
    let mut up1_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    );
    up1_err.in_reply_to = up1.request_id;
    running.frame(up1_err, &outgoing).await.unwrap();

    let att1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att1.request_id));
    let recovery_seq = running.main_pending_pointer_cancels.front().unwrap().seq;
    assert_eq!(running.main_pending_pointer_cancels.front().unwrap().attempts, 1);

    // Enqueue a deferred main-panel interaction; it must stay blocked across retries.
    running
        .control_with_seq(
            next_cmd_seq(),
            send_main_pointer(panel::PointerPhase::Down, 40.0, 40.0),
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.main_deferred_commands.len(), 1);

    // Subcase A: Local timer expires on attempt 1 -> NON-FATAL! Keeps seq & retries as attempt 2.
    running.requests.get_mut(&att1.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running
        .handle_timeouts(Instant::now(), &outgoing)
        .await
        .unwrap();
    assert_eq!(running.main_pending_pointer_cancels.front().unwrap().seq, recovery_seq);
    assert_eq!(running.main_pending_pointer_cancels.front().unwrap().attempts, 2);
    assert_eq!(running.main_deferred_commands.len(), 1);
    let cancel_att1 = wire.try_recv().unwrap();
    assert!(matches!(
        cancel_att1.body,
        Some(envelope::Body::Cancel(ref c)) if c.request_id == att1.request_id
    ));
    let att2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att2.request_id));

    // Subcase B: Attempt 2 expires locally while fresh-wire Ack arrives -> NON-FATAL! Retries attempt 3.
    running.requests.get_mut(&att2.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    let mut late_ack2 = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    late_ack2.in_reply_to = att2.request_id;
    running.frame(late_ack2, &outgoing).await.unwrap();
    assert_eq!(running.main_pending_pointer_cancels.front().unwrap().seq, recovery_seq);
    assert_eq!(running.main_pending_pointer_cancels.front().unwrap().attempts, 3);
    assert_eq!(running.main_deferred_commands.len(), 1);
    let cancel_att2 = wire.try_recv().unwrap();
    assert!(matches!(
        cancel_att2.body,
        Some(envelope::Body::Cancel(ref c)) if c.request_id == att2.request_id
    ));
    let att3 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att3.request_id));

    // Subcase C: Derived HostCall against locally expired attempt 3 -> NON-FATAL! Exhausts budget & fails deferred command.
    running.requests.get_mut(&att3.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    let hc = HostCall {
        operation: Some(host_call::Operation::QueryHistory(protocol::HistoryQuery {
            offset: 0,
            limit: 1,
            filter: String::new(),
        })),
        parent_request_id: att3.request_id,
    };
    let hc_env = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::HostCall(hc),
        MAX_OPERATION,
    );
    running.frame(hc_env, &outgoing).await.unwrap();
    assert!(running.main_pending_pointer_cancels.is_empty());
    assert!(running.main_deferred_commands.is_empty());
    let cancel_att3 = wire.try_recv().unwrap();
    assert!(matches!(
        cancel_att3.body,
        Some(envelope::Body::Cancel(ref c)) if c.request_id == att3.request_id
    ));
    let hr = wire.try_recv().unwrap();
    assert!(matches!(
        hr.body,
        Some(envelope::Body::HostResult(HostResult {
            outcome: Some(host_result::Outcome::Error(ref f))
        })) if f.code == ErrorCode::Deadline as i32
    ));
    assert!(wire.try_recv().is_err());

    // Subcase D: Retry succeeds after timer timeout and releases new deferred Pointer(Down).
    running
        .control_with_seq(
            next_cmd_seq(),
            send_main_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down_ok = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, down_ok.request_id));
    let mut down_ok_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    down_ok_ack.in_reply_to = down_ok.request_id;
    running.frame(down_ok_ack, &outgoing).await.unwrap();

    running
        .control_with_seq(
            next_cmd_seq(),
            send_main_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    let up_ok = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, up_ok.request_id));
    let mut up_ok_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    );
    up_ok_err.in_reply_to = up_ok.request_id;
    running.frame(up_ok_err, &outgoing).await.unwrap();
    let r_att1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, r_att1.request_id));

    running.requests.get_mut(&r_att1.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running
        .handle_timeouts(Instant::now(), &outgoing)
        .await
        .unwrap();
    let _cancel_r1 = wire.try_recv().unwrap();
    let r_att2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, r_att2.request_id));

    running
        .control_with_seq(
            next_cmd_seq(),
            send_main_pointer(panel::PointerPhase::Down, 30.0, 30.0),
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.main_deferred_commands.len(), 1);

    let mut ack_r2 = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack_r2.in_reply_to = r_att2.request_id;
    running.frame(ack_r2, &outgoing).await.unwrap();
    assert!(running.main_pending_pointer_cancels.is_empty());
    assert!(running.main_deferred_commands.is_empty());
    assert_eq!(running.panel_capture(protocol::PANEL_ID), Some((2, 10)));
    let flushed_down = wire.try_recv().unwrap();
    assert!(matches!(
        flushed_down.body,
        Some(envelope::Body::UiEvent(ref ev))
            if matches!(
                ev.event,
                Some(panel::ui_event::Event::Pointer(ref p))
                    if p.phase == panel::PointerPhase::Down as i32
                        && (p.x - 30.0).abs() < f32::EPSILON
            )
    ));
}

#[tokio::test]
async fn multi_target_pointer_cancel_queue_exhausting_head_still_cancels_following_target() {
    let canvas_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: "two-hit-canvas".into(),
        root: Some(panel::Node::new(
            2,
            "canvas",
            panel::node::Kind::Canvas(panel::Canvas {
                width: 100.0,
                height: 100.0,
                commands: vec![],
                hit_regions: vec![
                    panel::HitRegion {
                        id: 10,
                        bounds: Some(panel::Rect {
                            x: 0.0,
                            y: 0.0,
                            width: 50.0,
                            height: 100.0,
                        }),
                        accessibility_label: "hit-a".into(),
                        focusable: false,
                        capture_pointer: true,
                    },
                    panel::HitRegion {
                        id: 20,
                        bounds: Some(panel::Rect {
                            x: 50.0,
                            y: 0.0,
                            width: 50.0,
                            height: 100.0,
                        }),
                        accessibility_label: "hit-b".into(),
                        focusable: false,
                        capture_pointer: true,
                    },
                ],
            }),
        )),
    };

    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let mut worker_seq = 0u64;
    let mut next_worker_seq = || {
        worker_seq += 1;
        worker_seq
    };
    let mut cmd_seq = 0u64;
    let mut next_cmd_seq = || {
        cmd_seq += 1;
        cmd_seq
    };

    let res_child = Uuid::new_v4();
    let (o_tx, o_rx) = oneshot::channel();
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Open {
                panel_id: 2,
                id: res_child,
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_env = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, open_env.request_id));
    let mut open_snap = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Snapshot(canvas_snap(1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    open_snap.in_reply_to = open_env.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();

    // 1. Capture region A (hit_id: 10) -> Ack.
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 2,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                        hit_id: 10,
                        phase: panel::PointerPhase::Down as i32,
                        x: 25.0,
                        y: 50.0,
                    })),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let down_a = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, down_a.request_id));
    let mut ack_a = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    ack_a.in_reply_to = down_a.request_id;
    running.frame(ack_a, &outgoing).await.unwrap();
    assert_eq!(running.panel_capture(2), Some((2, 10)));

    // 2. Capture switches to B (hit_id: 20), which fails with Error(Invalid) -> queues [A(10), B(20)].
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 2,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                        hit_id: 20,
                        phase: panel::PointerPhase::Down as i32,
                        x: 75.0,
                        y: 50.0,
                    })),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let down_b = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, down_b.request_id));
    let mut err_b = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "B mutated then failed")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    err_b.in_reply_to = down_b.request_id;
    running.frame(err_b, &outgoing).await.unwrap();
    assert_eq!(running.panel_capture(2), None);
    {
        let slot = running.panels.get(&2).unwrap();
        assert_eq!(slot.pending_pointer_cancels.len(), 2);
        assert_eq!(slot.pending_pointer_cancels[0].hit_id, 10);
        assert_eq!(slot.pending_pointer_cancels[1].hit_id, 20);
    }

    let mut cancel_a = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, cancel_a.request_id));
    assert!(matches!(
        cancel_a.body,
        Some(envelope::Body::UiEvent(ref ev))
            if matches!(
                ev.event,
                Some(panel::ui_event::Event::Pointer(ref p))
                    if p.phase == panel::PointerPhase::Cancel as i32 && p.hit_id == 10
            )
    ));

    let (def_open_tx, mut def_open_rx) = oneshot::channel();
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Open {
                panel_id: 2,
                id: res_child,
                revision: 2,
                read_only: false,
                request: request(),
                reply: def_open_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();

    // 3. Exhaust A's retry budget with `MAX_RESYNC_RETRIES` Deadline replies -> ONLY A is removed;
    // B MUST stay queued and flush immediately!
    for attempt in 1..=MAX_RESYNC_RETRIES {
        let mut dl = Envelope::new(
            running.identity,
            next_worker_seq(),
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "cancel A timeout")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        dl.in_reply_to = cancel_a.request_id;
        running.frame(dl, &outgoing).await.unwrap();
        if attempt < MAX_RESYNC_RETRIES {
            assert!(def_open_rx.try_recv().is_err());
            cancel_a = wire.try_recv().unwrap();
            assert!(claims.claim_for_write(2, cancel_a.request_id));
        }
    }

    let exhausted_err = def_open_rx.await.unwrap().unwrap_err().to_string();
    assert!(
        exhausted_err.contains("重试超过上限"),
        "unexpected budget exhaustion err: {exhausted_err}"
    );
    {
        let slot = running.panels.get(&2).unwrap();
        assert_eq!(slot.pending_pointer_cancels.len(), 1);
        assert_eq!(slot.pending_pointer_cancels[0].hit_id, 20);
        assert_eq!(slot.pending_pointer_cancels[0].attempts, 1);
    }

    let cancel_b = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, cancel_b.request_id));
    assert!(matches!(
        cancel_b.body,
        Some(envelope::Body::UiEvent(ref ev))
            if matches!(
                ev.event,
                Some(panel::ui_event::Event::Pointer(ref p))
                    if p.phase == panel::PointerPhase::Cancel as i32 && p.hit_id == 20
            )
    ));
    let mut ack_b = Envelope::new(
        running.identity,
        next_worker_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    ack_b.in_reply_to = cancel_b.request_id;
    running.frame(ack_b, &outgoing).await.unwrap();
    assert!(running
        .panels
        .get(&2)
        .unwrap()
        .pending_pointer_cancels
        .is_empty());
    assert!(wire.try_recv().is_err());
}

#[tokio::test]
async fn writer_task_skips_in_writes_open_when_fatal_deadline_expires_during_event_backpressure() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
    let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
    let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
    let io_cancel = CancellationToken::new();
    let mut io_tasks = JoinSet::new();

    let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
    let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
    Running::spawn_stream_io(
        host_to_worker,
        worker_to_host,
        writes,
        &wire,
        claims,
        wp_tx,
        &io_cancel,
        &mut io_tasks,
    );

    // 1. Open child panel 2 cleanly.
    let res_child = Uuid::new_v4();
    let (oc_tx, oc_rx) = oneshot::channel();
    running
        .control_with_seq(
            1,
            Control::Open {
                panel_id: 2,
                id: res_child,
                revision: 1,
                read_only: false,
                request: request(),
                reply: oc_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let child_open_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
        .await
        .unwrap()
        .unwrap();
    let mut child_snap = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, 1, b"child", "child")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    child_snap.in_reply_to = child_open_env.request_id;
    running.frame(child_snap, &outgoing).await.unwrap();
    oc_rx.await.unwrap().unwrap();
    while updates.try_recv().is_ok() {}

    // 2. Send main-panel Open (already written to Worker) and an expired child Open (triggers diagnostic await).
    let (om_tx, _om_rx) = oneshot::channel();
    running
        .control_with_seq(
            2,
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: om_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let main_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
        .await
        .unwrap()
        .unwrap();

    let (ce_tx, ce_rx) = oneshot::channel();
    running
        .control_with_seq(
            3,
            Control::Open {
                panel_id: 2,
                id: Uuid::new_v4(),
                revision: 2,
                read_only: false,
                request: request(),
                reply: ce_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let child_expired_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
        .await
        .unwrap()
        .unwrap();
    running
        .requests
        .get_mut(&child_expired_env.request_id)
        .unwrap()
        .deadline = Instant::now() - Duration::from_secs(1);

    // 3. Saturate 512B pipe with 20 HostResults so writer blocks mid-write, then push unexpired
    // main Open directly into `writes` channel (`outgoing`), NOT `outbound_queue`.
    for s in 1..=20u64 {
        running
            .send(
                &outgoing,
                envelope::Body::HostResult(HostResult {
                    outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                }),
                s,
            )
            .unwrap();
    }
    tokio::time::sleep(Duration::from_millis(25)).await;

    let (oq_tx, _oq_rx) = oneshot::channel();
    running
        .control_with_seq(
            4,
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 2,
                read_only: false,
                request: request(),
                reply: oq_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(running.outbound_queue.is_empty());

    // 4. Arrange main_env fatal deadline +30ms and saturate `running.events`.
    running
        .requests
        .get_mut(&main_env.request_id)
        .unwrap()
        .deadline = Instant::now() + Duration::from_millis(30);
    running.sync_fatal_deadline_to_claims();

    while running
        .events
        .try_send(PluginEvent::Stopped {
            identity: running.identity,
            reason: "fill".into(),
        })
        .is_ok()
    {}

    let main_req_id = main_env.request_id;
    let child_expired_id = child_expired_env.request_id;
    let helper = tokio::spawn(async move {
        // Wait until main_env crosses fatal deadline while Running is STILL suspended in diagnostic.await.
        tokio::time::sleep(Duration::from_millis(55)).await;
        // Recover writer pipe BEFORE unblocking `events` so writer pops `Open` from `writes` while
        // `Running` is still blocked on event backpressure.
        for _ in 0..20 {
            let env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
                .await
                .unwrap()
                .unwrap();
            assert!(
                matches!(env.body, Some(envelope::Body::HostResult(_))),
                "unexpected frame before draining 20 HostResults: {env:?}"
            );
        }
        tokio::time::sleep(Duration::from_millis(20)).await;

        // Now unblock `events` and confirm Cancel(child_expired_id) + Cancel(main_req_id) arrive with ZERO OpenRequest leaked.
        while updates.try_recv().is_ok() {}
        let mut saw_child_cancel = false;
        let mut saw_main_cancel = false;
        timeout(MAX_OPERATION, async {
            while let Ok(env) = read_async_frame(&mut worker_rx).await {
                match env.body {
                    Some(envelope::Body::Cancel(c)) if c.request_id == child_expired_id => {
                        saw_child_cancel = true;
                    }
                    Some(envelope::Body::Cancel(c)) if c.request_id == main_req_id => {
                        saw_main_cancel = true;
                        break;
                    }
                    Some(other) => panic!("in-writes Open leaked across fatal deadline: {other:?}"),
                    None => {}
                }
            }
        })
        .await
        .unwrap();
        assert!(saw_child_cancel && saw_main_cancel);
        updates
    });

    let err = running
        .handle_timeouts(Instant::now(), &outgoing)
        .await
        .unwrap_err()
        .to_string();
    assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
    let _ = ce_rx.await;
    let _updates = helper.await.unwrap();

    io_cancel.cancel();
    io_tasks.abort_all();
}

#[tokio::test]
async fn main_panel_timed_out_pointer_cancel_late_snapshot_resyncs_before_releasing_deferred_event()
{
    let make_snap = |rev: u64, opt_a: &str, opt_b: &str| PanelSnapshot {
        revision: rev,
        title: "canvas-select".into(),
        root: Some(panel::Node::new(
            1,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        2,
                        "canvas",
                        panel::node::Kind::Canvas(panel::Canvas {
                            width: 100.0,
                            height: 100.0,
                            commands: vec![],
                            hit_regions: vec![panel::HitRegion {
                                id: 10,
                                bounds: Some(panel::Rect {
                                    x: 0.0,
                                    y: 0.0,
                                    width: 100.0,
                                    height: 100.0,
                                }),
                                accessibility_label: "hit".into(),
                                focusable: false,
                                capture_pointer: true,
                            }],
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec![opt_a.into(), opt_b.into()],
                            selected_index: 0,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    let (mut running, _calls, _updates) = running();
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let mut worker_seq = 0u64;
    let mut next_worker_seq = || {
        worker_seq += 1;
        worker_seq
    };
    let mut cmd_seq = 0u64;
    let mut next_cmd_seq = || {
        cmd_seq += 1;
        cmd_seq
    };

    // Replace main panel to rev 2 with options ["alpha", "beta"].
    let (om_tx, om_rx) = oneshot::channel();
    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Open {
                panel_id: protocol::PANEL_ID,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: om_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let open_env = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, open_env.request_id));
    let mut open_snap = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Snapshot(make_snap(2, "alpha", "beta")),
        MAX_OPERATION,
    );
    open_snap.in_reply_to = open_env.request_id;
    running.frame(open_snap, &outgoing).await.unwrap();
    om_rx.await.unwrap().unwrap();

    let send_pointer = |phase: panel::PointerPhase, x: f32, y: f32| Control::Event {
        panel_id: protocol::PANEL_ID,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                hit_id: 10,
                phase: phase as i32,
                x,
                y,
            })),
        },
        event_seq: 0,
    };

    // Subcase A: Timer removes attempt 1 -> late Snapshot(rev=3) updates Worker options -> idempotent
    // retry returns Ack(rev=3) -> Resync updates Host to rev 4 -> deferred SelectedOption(0) rejected!
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, down1.request_id));
    let mut down1_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    down1_ack.in_reply_to = down1.request_id;
    running.frame(down1_ack, &outgoing).await.unwrap();

    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    let up1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, up1.request_id));
    let mut up1_err = Envelope::new(
        running.identity,
        next_worker_seq(),
        2,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    );
    up1_err.in_reply_to = up1.request_id;
    running.frame(up1_err, &outgoing).await.unwrap();
    let att1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att1.request_id));

    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.main_deferred_commands.len(), 1);

    // 1. Timer expires attempt 1, retaining cancelled correlation & dispatching attempt 2.
    running.requests.get_mut(&att1.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running
        .handle_timeouts(Instant::now(), &outgoing)
        .await
        .unwrap();
    assert!(running
        .main_cancelled_state_requests
        .iter()
        .any(|&(id, _)| id == att1.request_id));
    let cancel_att1 = wire.try_recv().unwrap();
    assert!(matches!(
        cancel_att1.body,
        Some(envelope::Body::Cancel(ref c)) if c.request_id == att1.request_id
    ));
    let att2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att2.request_id));

    // 2. Late Snapshot(rev=3) for timed-out attempt 1 arrives with reordered options -> schedules Resync!
    let mut late_snap = Envelope::new(
        running.identity,
        next_worker_seq(),
        3,
        envelope::Body::Snapshot(make_snap(3, "beta", "alpha")),
        MAX_OPERATION,
    );
    late_snap.in_reply_to = att1.request_id;
    running.frame(late_snap, &outgoing).await.unwrap();
    assert_eq!(running.panel.snapshot().revision, 2);
    assert_ne!(running.main_resync_needed_seq, 0);
    assert_eq!(running.main_deferred_commands.len(), 1);
    let resync1 = wire.try_recv().unwrap();
    assert!(matches!(resync1.body, Some(envelope::Body::Resync(_))));
    assert!(claims.claim_for_write(protocol::PANEL_ID, resync1.request_id));

    // 3. Idempotent retry attempt 2 returns Ack(rev=3): pointer cancel barrier clears, but Resync STILL holds deferred event!
    let mut ack2 = Envelope::new(
        running.identity,
        next_worker_seq(),
        3,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack2.in_reply_to = att2.request_id;
    running.frame(ack2, &outgoing).await.unwrap();
    assert!(running.main_pending_pointer_cancels.is_empty());
    assert_ne!(running.main_resync_needed_seq, 0);
    assert_eq!(running.main_deferred_commands.len(), 1);
    assert!(wire.try_recv().is_err());

    // 4. Resync settles at rev 4 with reordered options ["beta", "alpha"] -> stale SelectedOption(0) rejected locally!
    let mut resync1_snap = Envelope::new(
        running.identity,
        next_worker_seq(),
        4,
        envelope::Body::Snapshot(make_snap(4, "beta", "alpha")),
        MAX_OPERATION,
    );
    resync1_snap.in_reply_to = resync1.request_id;
    running.frame(resync1_snap, &outgoing).await.unwrap();
    assert_eq!(running.panel.snapshot().revision, 4);
    assert_eq!(running.main_resync_needed_seq, 0);
    assert!(running.main_deferred_commands.is_empty());
    assert!(wire.try_recv().is_err());

    // Subcase B: No late Snapshot, but retry Ack carries drifted revision (5 != host 4) ->
    // Ack revision check STILL schedules Resync before releasing deferred SelectedOption(0).
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down_b = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, down_b.request_id));
    let mut ack_down_b = Envelope::new(
        running.identity,
        next_worker_seq(),
        4,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack_down_b.in_reply_to = down_b.request_id;
    running.frame(ack_down_b, &outgoing).await.unwrap();

    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    let up_b = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, up_b.request_id));
    let mut err_up_b = Envelope::new(
        running.identity,
        next_worker_seq(),
        4,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    );
    err_up_b.in_reply_to = up_b.request_id;
    running.frame(err_up_b, &outgoing).await.unwrap();
    let att_b1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att_b1.request_id));

    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.main_deferred_commands.len(), 1);

    running.requests.get_mut(&att_b1.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running
        .handle_timeouts(Instant::now(), &outgoing)
        .await
        .unwrap();
    let _cancel_b1 = wire.try_recv().unwrap();
    let att_b2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att_b2.request_id));

    let mut drifted_ack = Envelope::new(
        running.identity,
        next_worker_seq(),
        5,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    drifted_ack.in_reply_to = att_b2.request_id;
    running.frame(drifted_ack, &outgoing).await.unwrap();
    assert!(running.main_pending_pointer_cancels.is_empty());
    assert_ne!(running.main_resync_needed_seq, 0);
    assert_eq!(running.main_deferred_commands.len(), 1);

    let resync_b = wire.try_recv().unwrap();
    assert!(matches!(resync_b.body, Some(envelope::Body::Resync(_))));
    assert!(claims.claim_for_write(protocol::PANEL_ID, resync_b.request_id));

    let mut ack_resync_b = Envelope::new(
        running.identity,
        next_worker_seq(),
        4,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack_resync_b.in_reply_to = resync_b.request_id;
    running.frame(ack_resync_b, &outgoing).await.unwrap();
    assert_eq!(running.main_resync_needed_seq, 0);
    assert!(running.main_resync_semantic_drift);
    assert!(running.main_deferred_commands.is_empty());
    // Bare Ack on a semantic-drift Resync must reject deferred interactive events AND keep rejecting subsequent ones.
    assert!(wire.try_recv().is_err());

    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(wire.try_recv().is_err());

    // Deliver a confirming full Snapshot(5, "beta", "alpha") so drift clears for Subcase C.
    running
        .frame(
            Envelope::new(
                running.identity,
                next_worker_seq(),
                5,
                envelope::Body::Snapshot(make_snap(5, "beta", "alpha")),
                MAX_OPERATION,
            ),
            &outgoing,
        )
        .await
        .unwrap();
    assert!(!running.main_resync_semantic_drift);

    // Confirming semantic Resync with an explicit Snapshot preserving ["beta", "alpha"] releases deferred SelectedOption(0).
    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Down, 50.0, 50.0),
            &outgoing,
        )
        .await
        .unwrap();
    let down_c = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, down_c.request_id));
    let mut ack_down_c = Envelope::new(
        running.identity,
        next_worker_seq(),
        5,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack_down_c.in_reply_to = down_c.request_id;
    running.frame(ack_down_c, &outgoing).await.unwrap();

    running
        .control_with_seq(
            next_cmd_seq(),
            send_pointer(panel::PointerPhase::Up, 250.0, 250.0),
            &outgoing,
        )
        .await
        .unwrap();
    let up_c = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, up_c.request_id));
    let mut err_up_c = Envelope::new(
        running.identity,
        next_worker_seq(),
        5,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    );
    err_up_c.in_reply_to = up_c.request_id;
    running.frame(err_up_c, &outgoing).await.unwrap();
    let att_c1 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(protocol::PANEL_ID, att_c1.request_id));

    running
        .control_with_seq(
            next_cmd_seq(),
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let mut drifted_ack_c = Envelope::new(
        running.identity,
        next_worker_seq(),
        6,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    drifted_ack_c.in_reply_to = att_c1.request_id;
    running.frame(drifted_ack_c, &outgoing).await.unwrap();
    let resync_c = wire.try_recv().unwrap();
    assert!(matches!(resync_c.body, Some(envelope::Body::Resync(_))));
    assert!(claims.claim_for_write(protocol::PANEL_ID, resync_c.request_id));

    let mut snap_resync_c = Envelope::new(
        running.identity,
        next_worker_seq(),
        7,
        envelope::Body::Snapshot(make_snap(7, "beta", "alpha")),
        MAX_OPERATION,
    );
    snap_resync_c.in_reply_to = resync_c.request_id;
    running.frame(snap_resync_c, &outgoing).await.unwrap();
    assert_eq!(running.panel.snapshot().revision, 7);
    assert_eq!(running.main_resync_needed_seq, 0);
    assert!(!running.main_resync_semantic_drift);
    assert!(running.main_deferred_commands.is_empty());
    let flushed = wire.try_recv().unwrap();
    assert!(matches!(
        flushed.body,
        Some(envelope::Body::UiEvent(ref ev))
            if matches!(ev.event, Some(panel::ui_event::Event::SelectedOption(0)))
    ));
}

#[tokio::test]
async fn writer_fatal_expiry_skip_forces_host_fatal_abort_even_if_reply_sampled_before_deadline() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Part A: Writer observes fatal expiry of A and marks B as ExpiredSkipped; even if Host checks
    // A's local deadline cleanly before completion, `fatal_expired_triggered` forces fatal abort
    // without publishing A or leaving B orphaned without retry.
    {
        let (mut running, _calls, _updates) = running();
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let (om_tx, om_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: om_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let env_a = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, env_a.request_id));

        let (ob_tx, _ob_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 2,
                    read_only: false,
                    request: request(),
                    reply: ob_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let env_b = wire.try_recv().unwrap();

        running.requests.get_mut(&env_a.request_id).unwrap().deadline =
            Instant::now() - Duration::from_millis(5);
        running.sync_fatal_deadline_to_claims();

        // Writer pops B after A expired and skips it -> latches `fatal_expired_triggered`.
        assert!(!claims.claim_for_write(protocol::PANEL_ID, env_b.request_id));
        assert!(claims.is_fatal_expired_triggered());

        // Restore A's local deadline above `now` to emulate Host having sampled `now < A.deadline`
        // right before the deadline boundary when A's Snapshot frame arrived.
        running.requests.get_mut(&env_a.request_id).unwrap().deadline =
            Instant::now() + MAX_OPERATION;

        let mut snap_a = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"retained", "a-rev2")),
            MAX_OPERATION,
        );
        snap_a.in_reply_to = env_a.request_id;
        let err = running
            .frame(snap_a, &outgoing)
            .await
            .unwrap_err()
            .to_string();
        assert!(err.contains("插件操作超时"), "unexpected err: {err}");
        assert_eq!(running.panel.snapshot().revision, 1);
        assert!(om_rx.await.unwrap().is_err());

        let mut cancels = Vec::new();
        while let Ok(env) = wire.try_recv() {
            if let Some(envelope::Body::Cancel(c)) = env.body {
                cancels.push(c.request_id);
            }
        }
        assert!(cancels.contains(&env_a.request_id));
        assert!(
            !cancels.contains(&env_b.request_id),
            "ExpiredSkipped B must not trigger Cancel"
        );
    }

    // Part B: If Host settles A BEFORE A's deadline, earliest fatal deadline advances cleanly to B
    // and Writer STILL writes B even after A's original deadline later passes.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let (om_tx, om_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: om_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let env_a = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, env_a.request_id));
        running.requests.get_mut(&env_a.request_id).unwrap().deadline =
            Instant::now() + Duration::from_millis(50);

        let (ob_tx, _ob_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: ob_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let env_b = wire.try_recv().unwrap();
        running.sync_fatal_deadline_to_claims();

        let mut snap_a = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"retained", "a-ok")),
            MAX_OPERATION,
        );
        snap_a.in_reply_to = env_a.request_id;
        running.frame(snap_a, &outgoing).await.unwrap();
        assert!(om_rx.await.unwrap().is_ok());

        tokio::time::sleep(Duration::from_millis(65)).await;
        assert!(
            claims.claim_for_write(2, env_b.request_id),
            "settling A early must clear A's fatal deadline before Writer pops B"
        );
    }
}

#[tokio::test]
async fn unclaimed_child_destroy_close_in_writes_is_skipped_on_fatal_deadline_and_shutdown() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], label: &str| PanelSnapshot {
        revision: rev,
        title: label.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: ed_rev,
                contents: contents.to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Part A: Fatal deadline during event backpressure skips unclaimed child destroy CloseRequest in `writes`.
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let res2 = Uuid::new_v4();
        let res3 = Uuid::new_v4();
        for (pid, res, seq) in [(2u64, res2, 1u64), (3u64, res3, 2u64)] {
            let (tx, rx) = oneshot::channel();
            running
                .control_with_seq(
                    seq,
                    Control::Open {
                        panel_id: pid,
                        id: res,
                        revision: 1,
                        read_only: false,
                        request: request(),
                        reply: tx,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            let env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
                .await
                .unwrap()
                .unwrap();
            let mut snap = Envelope::new(
                running.identity,
                seq,
                1,
                envelope::Body::Snapshot(make_snap(1, 1, b"child", "child")),
                MAX_OPERATION,
            )
            .with_panel_id(pid);
            snap.in_reply_to = env.request_id;
            running.frame(snap, &outgoing).await.unwrap();
            rx.await.unwrap().unwrap();
        }
        while updates.try_recv().is_ok() {}

        let (om_tx, _om_rx) = oneshot::channel();
        running
            .control_with_seq(
                3,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: om_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let main_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();

        let (ce_tx, ce_rx) = oneshot::channel();
        running
            .control_with_seq(
                4,
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 2,
                    read_only: false,
                    request: request(),
                    reply: ce_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let child_expired_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        running
            .requests
            .get_mut(&child_expired_env.request_id)
            .unwrap()
            .deadline = Instant::now() - Duration::from_secs(1);

        // Saturate pipe before dispatching destroy CloseRequest on panel 3 into `writes`.
        for s in 1..=20u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(25)).await;

        let (d3_tx, _d3_rx) = oneshot::channel();
        running
            .control_with_seq(
                5,
                Control::Revoke {
                    panel_id: 3,
                    id: res3,
                    remove_panel: true,
                    reply: d3_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(running.outbound_queue.is_empty());

        running
            .requests
            .get_mut(&main_env.request_id)
            .unwrap()
            .deadline = Instant::now() + Duration::from_millis(30);
        running.sync_fatal_deadline_to_claims();

        while running
            .events
            .try_send(PluginEvent::Stopped {
                identity: running.identity,
                reason: "fill".into(),
            })
            .is_ok()
        {}

        let main_req_id = main_env.request_id;
        let child_expired_id = child_expired_env.request_id;
        let helper = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(55)).await;
            for _ in 0..20 {
                let env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
                    .await
                    .unwrap()
                    .unwrap();
                assert!(matches!(env.body, Some(envelope::Body::HostResult(_))));
            }
            tokio::time::sleep(Duration::from_millis(20)).await;

            while updates.try_recv().is_ok() {}
            let mut saw_child_cancel = false;
            let mut saw_main_cancel = false;
            timeout(MAX_OPERATION, async {
                while let Ok(env) = read_async_frame(&mut worker_rx).await {
                    match env.body {
                        Some(envelope::Body::Cancel(c)) if c.request_id == child_expired_id => {
                            saw_child_cancel = true;
                        }
                        Some(envelope::Body::Cancel(c)) if c.request_id == main_req_id => {
                            saw_main_cancel = true;
                            break;
                        }
                        Some(other) => panic!("destroy CloseRequest leaked past fatal deadline: {other:?}"),
                        None => {}
                    }
                }
            })
            .await
            .unwrap();
            assert!(saw_child_cancel && saw_main_cancel);
            updates
        });

        let err = running
            .handle_timeouts(Instant::now(), &outgoing)
            .await
            .unwrap_err()
            .to_string();
        assert!(err.contains("插件操作超时"), "unexpected fatal err: {err}");
        let _ = ce_rx.await;
        let _updates = helper.await.unwrap();

        io_cancel.cancel();
        io_tasks.abort_all();
    }

    // Part B: `prepare_shutdown` skips unclaimed child destroy CloseRequest in `writes`.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(512);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let res2 = Uuid::new_v4();
        let (o2_tx, o2_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: res2,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o2_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let mut snap2 = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1, b"child", "child")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        snap2.in_reply_to = o2_env.request_id;
        running.frame(snap2, &outgoing).await.unwrap();
        o2_rx.await.unwrap().unwrap();

        for s in 1..=20u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(25)).await;

        let (d2_tx, _d2_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Revoke {
                    panel_id: 2,
                    id: res2,
                    remove_panel: true,
                    reply: d2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(running.outbound_queue.is_empty());

        running.prepare_shutdown(&outgoing);
        let mut saw_shutdown = false;
        timeout(MAX_OPERATION, async {
            while let Ok(env) = read_async_frame(&mut worker_rx).await {
                match env.body {
                    Some(envelope::Body::HostResult(_)) => {}
                    Some(envelope::Body::Shutdown(_)) => {
                        saw_shutdown = true;
                        break;
                    }
                    Some(other) => panic!("destroy CloseRequest leaked during prepare_shutdown: {other:?}"),
                    None => {}
                }
            }
        })
        .await
        .unwrap();
        assert!(saw_shutdown);

        io_cancel.cancel();
        io_tasks.abort_all();
    }

    // Part C: Non-fatal child destroy timeout on live worker preserves claim so Worker still destroys panel 2.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let res2 = Uuid::new_v4();
        let (o2_tx, o2_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: res2,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o2_env = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, o2_env.request_id));
        let mut snap2 = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1, b"child", "child")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        snap2.in_reply_to = o2_env.request_id;
        running.frame(snap2, &outgoing).await.unwrap();
        o2_rx.await.unwrap().unwrap();

        let (d2_tx, d2_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Revoke {
                    panel_id: 2,
                    id: res2,
                    remove_panel: true,
                    reply: d2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let destroy_env = wire.try_recv().unwrap();
        running
            .requests
            .get_mut(&destroy_env.request_id)
            .unwrap()
            .deadline = Instant::now() - Duration::from_secs(1);

        running
            .handle_timeouts(Instant::now(), &outgoing)
            .await
            .unwrap();
        assert!(d2_rx.await.unwrap().is_err());
        assert!(
            claims.claim_for_write(2, destroy_env.request_id),
            "live non-fatal child destroy CloseRequest must NOT be retracted on child timeout"
        );
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn real_sdk_default_on_resync_and_bare_ack_cannot_release_stale_selected_option_after_pointer_cancel_drift()
{
    use std::io::{Read, Write};
    use std::sync::{Arc, Mutex};
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    struct BlockingReader(DuplexStream, tokio::runtime::Handle);
    impl Read for BlockingReader {
        fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.read(buf))
        }
    }
    struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
    impl Write for BlockingWriter {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.1.block_on(self.0.write(buf))
        }
        fn flush(&mut self) -> std::io::Result<()> {
            self.1.block_on(self.0.flush())
        }
    }

    struct PointerDriftNoResyncPlugin {
        options: Mutex<[&'static str; 2]>,
        executed: Arc<Mutex<Vec<String>>>,
        cancel_calls: Mutex<usize>,
        down_seen: Arc<tokio::sync::Notify>,
        cancel1_entered: Arc<tokio::sync::Notify>,
        cancel1_release: Arc<tokio::sync::Notify>,
        cancel2_seen: Arc<tokio::sync::Notify>,
        rt: tokio::runtime::Handle,
    }

    impl PointerDriftNoResyncPlugin {
        fn make_snap(rev: u64, opts: [&str; 2]) -> PanelSnapshot {
            PanelSnapshot {
                revision: rev,
                title: "sdk-pointer-drift".into(),
                root: Some(panel::Node::new(
                    1,
                    "col",
                    panel::node::Kind::Column(panel::Container {
                        children: vec![
                            panel::Node::new(
                                2,
                                "canvas",
                                panel::node::Kind::Canvas(panel::Canvas {
                                    width: 100.0,
                                    height: 100.0,
                                    commands: vec![],
                                    hit_regions: vec![panel::HitRegion {
                                        id: 10,
                                        bounds: Some(panel::Rect {
                                            x: 0.0,
                                            y: 0.0,
                                            width: 100.0,
                                            height: 100.0,
                                        }),
                                        accessibility_label: "hit".into(),
                                        focusable: false,
                                        capture_pointer: true,
                                    }],
                                }),
                            ),
                            panel::Node::new(
                                3,
                                "select",
                                panel::node::Kind::Select(panel::SelectNode {
                                    label: "Choice".into(),
                                    options: vec![opts[0].into(), opts[1].into()],
                                    selected_index: 0,
                                    enabled: true,
                                }),
                            ),
                        ],
                    }),
                )),
            }
        }
    }

    // Intentionally does NOT override `on_resync` / `on_panel_resync` -> exercises SDK default!
    impl mio_plugin_sdk::MioPlugin for PointerDriftNoResyncPlugin {
        fn id(&self) -> &str {
            "lab.sdk-default-resync-drift"
        }

        fn version(&self) -> &str {
            "1.5.0"
        }

        fn initial_panel(&self) -> PanelSnapshot {
            Self::make_snap(1, ["A", "B"])
        }

        fn on_ui_event(
            &mut self,
            ctx: &mut dyn mio_plugin_sdk::HostClient,
            event: UiEvent,
        ) -> std::result::Result<Option<PanelSnapshot>, String> {
            match (event.node_id, &event.event) {
                (2, Some(panel::ui_event::Event::Pointer(p))) => {
                    match panel::PointerPhase::try_from(p.phase).unwrap() {
                        panel::PointerPhase::Down => {
                            self.down_seen.notify_one();
                            Ok(None)
                        }
                        panel::PointerPhase::Up => Err("up rejected".into()),
                        panel::PointerPhase::Cancel => {
                            let mut count = self.cancel_calls.lock().unwrap();
                            let call_idx = *count;
                            *count += 1;
                            drop(count);
                            if call_idx == 0 {
                                *self.options.lock().unwrap() = ["B", "A"];
                                self.cancel1_entered.notify_one();
                                self.rt.block_on(self.cancel1_release.notified());
                                let rev = ctx.next_panel_revision();
                                Ok(Some(Self::make_snap(rev, ["B", "A"])))
                            } else {
                                self.cancel2_seen.notify_one();
                                Ok(None)
                            }
                        }
                        panel::PointerPhase::Move => Ok(None),
                    }
                }
                (3, Some(panel::ui_event::Event::SelectedOption(idx))) => {
                    let chosen = self.options.lock().unwrap()[*idx as usize].to_owned();
                    self.executed.lock().unwrap().push(chosen);
                    Ok(None)
                }
                _ => Ok(None),
            }
        }
    }

    let rt_handle = tokio::runtime::Handle::current();
    let identity = super::tests_runtime::identity();
    let manifest = PluginManifest {
        id: "lab.sdk-default-resync-drift".into(),
        version: "1.5.0".into(),
        api_version: 1,
        engine: "native".into(),
        entry: "worker".into(),
        permissions: Vec::new(),
        contributions: vec!["suite_panel".into()],
    };
    let (host_tx, worker_rx) = tokio::io::duplex(64 * 1024);
    let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
    let executed = Arc::new(Mutex::new(Vec::new()));
    let down_seen = Arc::new(tokio::sync::Notify::new());
    let cancel1_entered = Arc::new(tokio::sync::Notify::new());
    let cancel1_release = Arc::new(tokio::sync::Notify::new());
    let cancel2_seen = Arc::new(tokio::sync::Notify::new());

    let executed_w = executed.clone();
    let down_seen_w = down_seen.clone();
    let cancel1_entered_w = cancel1_entered.clone();
    let cancel1_release_w = cancel1_release.clone();
    let cancel2_seen_w = cancel2_seen.clone();
    let worker_thread = std::thread::spawn(move || {
        let mut plugin = PointerDriftNoResyncPlugin {
            options: Mutex::new(["A", "B"]),
            executed: executed_w,
            cancel_calls: Mutex::new(0),
            down_seen: down_seen_w,
            cancel1_entered: cancel1_entered_w,
            cancel1_release: cancel1_release_w,
            cancel2_seen: cancel2_seen_w,
            rt: rt_handle.clone(),
        };
        mio_plugin_sdk::run_with_io(
            BlockingReader(worker_rx, rt_handle.clone()),
            BlockingWriter(worker_tx, rt_handle),
            &mut plugin,
        )
        .unwrap();
    });

    let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
        identity,
        manifest,
        BTreeSet::new(),
        host_tx,
        host_rx,
    )
    .await
    .unwrap();
    let handle = supervisor.handle();

    let ev_init = timeout(MAX_OPERATION, supervisor.events.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(matches!(ev_init, PluginEvent::Panel { .. }));

    handle
        .try_event(UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                hit_id: 10,
                phase: panel::PointerPhase::Down as i32,
                x: 50.0,
                y: 50.0,
            })),
        })
        .unwrap();
    timeout(MAX_OPERATION, down_seen.notified()).await.unwrap();
    tokio::time::sleep(Duration::from_millis(25)).await;

    // Trigger Pointer(Up) error -> schedules synthetic Pointer(Cancel) #1, which reorders options and blocks.
    handle
        .try_event(UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                hit_id: 10,
                phase: panel::PointerPhase::Up as i32,
                x: 250.0,
                y: 250.0,
            })),
        })
        .unwrap();
    timeout(MAX_OPERATION, cancel1_entered.notified()).await.unwrap();

    // Queue user selecting index 0 ("A") under old host view while Pointer(Cancel) barrier is active.
    handle
        .try_event(UiEvent {
            node_id: 3,
            editors: vec![],
            event: Some(panel::ui_event::Event::SelectedOption(0)),
        })
        .unwrap();

    // Wait for natural 5s host timer to expire Pointer(Cancel) #1 and schedule attempt #2.
    timeout(Duration::from_secs(7), async {
        loop {
            match supervisor.events.recv().await {
                Some(PluginEvent::Error { failure, .. })
                    if failure.message.contains("面板指针手势取消操作超时") =>
                {
                    break;
                }
                Some(PluginEvent::Stopped { reason, .. }) => {
                    panic!("pointer cancel timeout unexpectedly killed worker: {reason}")
                }
                Some(_) => continue,
                None => panic!("events closed unexpectedly"),
            }
        }
    })
    .await
    .unwrap();

    // Unblock #1 -> returns late Snapshot(rev=3, ["B","A"]); Worker then handles attempt #2 + Resync(rev=1).
    cancel1_release.notify_one();
    timeout(MAX_OPERATION, cancel2_seen.notified()).await.unwrap();

    let mut saw_resync_error = false;
    let mut saw_stale_deferred = false;
    timeout(MAX_OPERATION, async {
        while !(saw_resync_error && saw_stale_deferred) {
            match supervisor.events.recv().await {
                Some(PluginEvent::Error { failure, .. }) => {
                    if failure.message.contains("does not implement on_resync") {
                        saw_resync_error = true;
                    }
                    if failure.message.contains("面板重同步未完成") {
                        saw_stale_deferred = true;
                    }
                }
                Some(PluginEvent::Stopped { reason, .. }) => {
                    panic!("resync failure unexpectedly killed worker: {reason}")
                }
                Some(_) => continue,
                None => panic!("events closed unexpectedly"),
            }
        }
    })
    .await
    .unwrap();

    assert!(
        executed.lock().unwrap().is_empty(),
        "stale SelectedOption(0) executed wrong option B: {:?}",
        *executed.lock().unwrap()
    );

    supervisor.stop().await.unwrap();
    worker_thread.join().unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn persistent_semantic_drift_rejects_ordinary_and_repeated_interactions_until_full_snapshot() {
    use std::io::{Read, Write};
    use std::sync::{Arc, Mutex};
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    // Part A: Real SDK plugin without on_resync keeps rejecting ordinary & repeated SelectedOption(0)
    // after default on_resync Error until EditorChanged triggers a full confirming Snapshot.
    {
        struct BlockingReader(DuplexStream, tokio::runtime::Handle);
        impl Read for BlockingReader {
            fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
                self.1.block_on(self.0.read(buf))
            }
        }
        struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
        impl Write for BlockingWriter {
            fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
                self.1.block_on(self.0.write(buf))
            }
            fn flush(&mut self) -> std::io::Result<()> {
                self.1.block_on(self.0.flush())
            }
        }

        struct PersistentDriftPlugin {
            options: Mutex<[&'static str; 2]>,
            editor_rev: Mutex<u64>,
            editor_contents: Mutex<Vec<u8>>,
            executed: Arc<Mutex<Vec<String>>>,
            select_seen: Arc<tokio::sync::Notify>,
            cancel_calls: Mutex<usize>,
            down_seen: Arc<tokio::sync::Notify>,
            cancel1_entered: Arc<tokio::sync::Notify>,
            cancel1_release: Arc<tokio::sync::Notify>,
            cancel2_seen: Arc<tokio::sync::Notify>,
            rt: tokio::runtime::Handle,
        }

        impl PersistentDriftPlugin {
            fn make_snap(rev: u64, opts: [&str; 2], ed_rev: u64, contents: &[u8]) -> PanelSnapshot {
                PanelSnapshot {
                    revision: rev,
                    title: "persistent-drift".into(),
                    root: Some(panel::Node::new(
                        10,
                        "col",
                        panel::node::Kind::Column(panel::Container {
                            children: vec![
                                panel::Node::new(
                                    1,
                                    "ed",
                                    panel::node::Kind::Editor(panel::Editor {
                                        document_id: 1,
                                        revision: ed_rev,
                                        contents: contents.to_vec(),
                                        format: panel::EditorFormat::Utf8 as i32,
                                        read_only: false,
                                    }),
                                ),
                                panel::Node::new(
                                    2,
                                    "canvas",
                                    panel::node::Kind::Canvas(panel::Canvas {
                                        width: 100.0,
                                        height: 100.0,
                                        commands: vec![],
                                        hit_regions: vec![panel::HitRegion {
                                            id: 10,
                                            bounds: Some(panel::Rect {
                                                x: 0.0,
                                                y: 0.0,
                                                width: 100.0,
                                                height: 100.0,
                                            }),
                                            accessibility_label: "hit".into(),
                                            focusable: false,
                                            capture_pointer: true,
                                        }],
                                    }),
                                ),
                                panel::Node::new(
                                    3,
                                    "select",
                                    panel::node::Kind::Select(panel::SelectNode {
                                        label: "Choice".into(),
                                        options: vec![opts[0].into(), opts[1].into()],
                                        selected_index: 0,
                                        enabled: true,
                                    }),
                                ),
                            ],
                        }),
                    )),
                }
            }
        }

        impl mio_plugin_sdk::MioPlugin for PersistentDriftPlugin {
            fn id(&self) -> &str {
                "lab.persistent-semantic-drift"
            }

            fn version(&self) -> &str {
                "1.5.0"
            }

            fn initial_panel(&self) -> PanelSnapshot {
                Self::make_snap(1, ["A", "B"], 1, b"init")
            }

            fn on_ui_event(
                &mut self,
                ctx: &mut dyn mio_plugin_sdk::HostClient,
                event: UiEvent,
            ) -> std::result::Result<Option<PanelSnapshot>, String> {
                match (event.node_id, &event.event) {
                    (2, Some(panel::ui_event::Event::Pointer(p))) => {
                        match panel::PointerPhase::try_from(p.phase).unwrap() {
                            panel::PointerPhase::Down => {
                                self.down_seen.notify_one();
                                Ok(None)
                            }
                            panel::PointerPhase::Up => Err("up rejected".into()),
                            panel::PointerPhase::Cancel => {
                                let mut count = self.cancel_calls.lock().unwrap();
                                let call_idx = *count;
                                *count += 1;
                                drop(count);
                                if call_idx == 0 {
                                    *self.options.lock().unwrap() = ["B", "A"];
                                    self.cancel1_entered.notify_one();
                                    self.rt.block_on(self.cancel1_release.notified());
                                    let rev = ctx.next_panel_revision();
                                    let opts = *self.options.lock().unwrap();
                                    let ed_rev = *self.editor_rev.lock().unwrap();
                                    let contents = self.editor_contents.lock().unwrap().clone();
                                    Ok(Some(Self::make_snap(rev, opts, ed_rev, &contents)))
                                } else {
                                    self.cancel2_seen.notify_one();
                                    Ok(None)
                                }
                            }
                            panel::PointerPhase::Move => Ok(None),
                        }
                    }
                    (1, Some(panel::ui_event::Event::EditorChanged(ed))) => {
                        *self.editor_rev.lock().unwrap() = ed.revision;
                        *self.editor_contents.lock().unwrap() = ed.contents.clone();
                        let rev = ctx.next_panel_revision();
                        let opts = *self.options.lock().unwrap();
                        Ok(Some(Self::make_snap(rev, opts, ed.revision, &ed.contents)))
                    }
                    (3, Some(panel::ui_event::Event::SelectedOption(idx))) => {
                        let chosen = self.options.lock().unwrap()[*idx as usize].to_owned();
                        self.executed.lock().unwrap().push(chosen);
                        self.select_seen.notify_one();
                        Ok(None)
                    }
                    _ => Ok(None),
                }
            }
        }

        let rt_handle = tokio::runtime::Handle::current();
        let identity = super::tests_runtime::identity();
        let manifest = PluginManifest {
            id: "lab.persistent-semantic-drift".into(),
            version: "1.5.0".into(),
            api_version: 1,
            engine: "native".into(),
            entry: "worker".into(),
            permissions: Vec::new(),
            contributions: vec!["suite_panel".into()],
        };
        let (host_tx, worker_rx) = tokio::io::duplex(64 * 1024);
        let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
        let executed = Arc::new(Mutex::new(Vec::new()));
        let select_seen = Arc::new(tokio::sync::Notify::new());
        let down_seen = Arc::new(tokio::sync::Notify::new());
        let cancel1_entered = Arc::new(tokio::sync::Notify::new());
        let cancel1_release = Arc::new(tokio::sync::Notify::new());
        let cancel2_seen = Arc::new(tokio::sync::Notify::new());

        let executed_w = executed.clone();
        let select_seen_w = select_seen.clone();
        let down_seen_w = down_seen.clone();
        let cancel1_entered_w = cancel1_entered.clone();
        let cancel1_release_w = cancel1_release.clone();
        let cancel2_seen_w = cancel2_seen.clone();
        let worker_thread = std::thread::spawn(move || {
            let mut plugin = PersistentDriftPlugin {
                options: Mutex::new(["A", "B"]),
                editor_rev: Mutex::new(1),
                editor_contents: Mutex::new(b"init".to_vec()),
                executed: executed_w,
                select_seen: select_seen_w,
                cancel_calls: Mutex::new(0),
                down_seen: down_seen_w,
                cancel1_entered: cancel1_entered_w,
                cancel1_release: cancel1_release_w,
                cancel2_seen: cancel2_seen_w,
                rt: rt_handle.clone(),
            };
            mio_plugin_sdk::run_with_io(
                BlockingReader(worker_rx, rt_handle.clone()),
                BlockingWriter(worker_tx, rt_handle),
                &mut plugin,
            )
            .unwrap();
        });

        let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
            identity,
            manifest,
            BTreeSet::new(),
            host_tx,
            host_rx,
        )
        .await
        .unwrap();
        let handle = supervisor.handle();

        let ev_init = timeout(MAX_OPERATION, supervisor.events.recv())
            .await
            .unwrap()
            .unwrap();
        assert!(matches!(ev_init, PluginEvent::Panel { .. }));

        handle
            .try_event(UiEvent {
                node_id: 2,
                editors: vec![],
                event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                    hit_id: 10,
                    phase: panel::PointerPhase::Down as i32,
                    x: 50.0,
                    y: 50.0,
                })),
            })
            .unwrap();
        timeout(MAX_OPERATION, down_seen.notified()).await.unwrap();
        tokio::time::sleep(Duration::from_millis(25)).await;

        handle
            .try_event(UiEvent {
                node_id: 2,
                editors: vec![],
                event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                    hit_id: 10,
                    phase: panel::PointerPhase::Up as i32,
                    x: 250.0,
                    y: 250.0,
                })),
            })
            .unwrap();
        timeout(MAX_OPERATION, cancel1_entered.notified())
            .await
            .unwrap();

        // Deferred SelectedOption(0) queued while Pointer(Cancel) barrier is active.
        handle
            .try_event(UiEvent {
                node_id: 3,
                editors: vec![],
                event: Some(panel::ui_event::Event::SelectedOption(0)),
            })
            .unwrap();

        timeout(Duration::from_secs(7), async {
            loop {
                match supervisor.events.recv().await {
                    Some(PluginEvent::Error { failure, .. })
                        if failure.message.contains("面板指针手势取消操作超时") =>
                    {
                        break;
                    }
                    Some(PluginEvent::Stopped { reason, .. }) => {
                        panic!("pointer cancel timeout unexpectedly killed worker: {reason}")
                    }
                    Some(_) => continue,
                    None => panic!("events closed unexpectedly"),
                }
            }
        })
        .await
        .unwrap();

        cancel1_release.notify_one();
        timeout(MAX_OPERATION, cancel2_seen.notified()).await.unwrap();

        let mut saw_resync_error = false;
        let mut saw_stale_deferred = false;
        timeout(MAX_OPERATION, async {
            while !(saw_resync_error && saw_stale_deferred) {
                match supervisor.events.recv().await {
                    Some(PluginEvent::Error { failure, .. }) => {
                        if failure.message.contains("does not implement on_resync") {
                            saw_resync_error = true;
                        }
                        if failure.message.contains("面板重同步未完成") {
                            saw_stale_deferred = true;
                        }
                    }
                    Some(PluginEvent::Stopped { reason, .. }) => {
                        panic!("resync failure unexpectedly killed worker: {reason}")
                    }
                    Some(_) => continue,
                    None => panic!("events closed unexpectedly"),
                }
            }
        })
        .await
        .unwrap();

        // Resync cycle ended, yet subsequent & repeated ordinary SelectedOption(0) events MUST still fail locally as Stale!
        for _ in 0..2 {
            handle
                .try_event(UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                })
                .unwrap();
            let err_ev = timeout(MAX_OPERATION, async {
                loop {
                    match supervisor.events.recv().await {
                        Some(PluginEvent::PanelSynced { .. }) => continue,
                        other => return other,
                    }
                }
            })
            .await
            .unwrap()
            .unwrap();
            assert!(
                matches!(
                    err_ev,
                    PluginEvent::Error { ref failure, .. }
                        if failure.code == ErrorCode::Stale as i32
                            && failure.message.contains("尚未通过最新快照确认状态")
                ),
                "expected Stale drift rejection after recovery ended, got {err_ev:?}"
            );
        }
        assert!(executed.lock().unwrap().is_empty());

        // EditorChanged still proceeds and returns a confirming Snapshot(["B", "A"]) which clears drift.
        handle
            .try_event(UiEvent {
                node_id: 1,
                editors: vec![],
                event: Some(panel::ui_event::Event::EditorChanged(panel::EditorSnapshot {
                    document_id: 1,
                    revision: 2,
                    contents: b"confirmed".to_vec(),
                    selection_start: 0,
                    selection_end: 0,
                })),
            })
            .unwrap();
        timeout(MAX_OPERATION, async {
            loop {
                match supervisor.events.recv().await {
                    Some(PluginEvent::Panel { .. }) => break,
                    Some(PluginEvent::PanelSynced { .. }) => continue,
                    Some(other) => panic!("expected confirmed panel after EditorChanged, got {other:?}"),
                    None => panic!("events closed unexpectedly"),
                }
            }
        })
        .await
        .unwrap();

        handle
            .try_event(UiEvent {
                node_id: 3,
                editors: vec![],
                event: Some(panel::ui_event::Event::SelectedOption(0)),
            })
            .unwrap();
        timeout(MAX_OPERATION, select_seen.notified()).await.unwrap();
        assert_eq!(*executed.lock().unwrap(), vec!["B".to_string()]);

        supervisor.stop().await.unwrap();
        worker_thread.join().unwrap();
    }

    // Part B: Unit verification that partial Body::Patch leaves semantic drift active while full Body::Snapshot clears it.
    {
        let (mut running, _calls, mut updates) = running();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], opts: [&str; 2]| PanelSnapshot {
            revision: rev,
            title: format!("unit-drift-{rev}"),
            root: Some(panel::Node::new(
                10,
                "col",
                panel::node::Kind::Column(panel::Container {
                    children: vec![
                        panel::Node::new(
                            1,
                            "ed",
                            panel::node::Kind::Editor(panel::Editor {
                                document_id: 1,
                                revision: ed_rev,
                                contents: contents.to_vec(),
                                format: panel::EditorFormat::Utf8 as i32,
                                read_only: false,
                            }),
                        ),
                        panel::Node::new(
                            3,
                            "select",
                            panel::node::Kind::Select(panel::SelectNode {
                                label: "Choice".into(),
                                options: vec![opts[0].into(), opts[1].into()],
                                selected_index: 0,
                                enabled: true,
                            }),
                        ),
                    ],
                }),
            )),
        };
        running.panel = PanelState::new(make_snap(1, 1, b"init", ["alpha", "beta"])).unwrap();

        running.schedule_panel_semantic_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync = wire.try_recv().unwrap();

        let mut bare_ack = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        );
        bare_ack.in_reply_to = resync.request_id;
        running.frame(bare_ack, &outgoing).await.unwrap();
        assert_eq!(running.main_resync_needed_seq, 0);
        assert!(running.main_resync_semantic_drift);
        while updates.try_recv().is_ok() {}

        let select_ev = Control::Event {
            panel_id: protocol::PANEL_ID,
            expected_snapshot: None,
            event: UiEvent {
                node_id: 3,
                editors: vec![],
                event: Some(panel::ui_event::Event::SelectedOption(0)),
            },
            event_seq: 0,
        };
        running.control(select_ev, &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { ref failure, .. }) if failure.code == ErrorCode::Stale as i32
        ));

        // Partial Body::Patch updates only the Editor -> MUST NOT clear semantic drift on Select!
        running
            .frame(
                Envelope::new(
                    running.identity,
                    2,
                    2,
                    envelope::Body::Patch(panel::PanelPatch {
                        base_revision: 1,
                        revision: 2,
                        operations: vec![panel::PatchOperation {
                            node_id: 1,
                            change: Some(panel::patch_operation::Change::Editor(
                                panel::EditorUpdate {
                                    base_revision: 1,
                                    snapshot: Some(panel::EditorSnapshot {
                                        document_id: 1,
                                        revision: 2,
                                        contents: b"patched".to_vec(),
                                        selection_start: 0,
                                        selection_end: 0,
                                    }),
                                },
                            )),
                        }],
                    }),
                    MAX_OPERATION,
                ),
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.panel_revision(protocol::PANEL_ID), 2);
        assert!(running.main_resync_semantic_drift);
        while updates.try_recv().is_ok() {}

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(wire.try_recv().is_err());
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { ref failure, .. }) if failure.code == ErrorCode::Stale as i32
        ));

        // Full confirming Body::Snapshot clears semantic drift and re-enables Select interaction.
        running
            .frame(
                Envelope::new(
                    running.identity,
                    3,
                    3,
                    envelope::Body::Snapshot(make_snap(3, 2, b"patched", ["beta", "alpha"])),
                    MAX_OPERATION,
                ),
                &outgoing,
            )
            .await
            .unwrap();
        assert!(!running.main_resync_semantic_drift);

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let dispatched = wire.try_recv().unwrap();
        assert!(matches!(
            dispatched.body,
            Some(envelope::Body::UiEvent(ref ev))
                if matches!(ev.event, Some(panel::ui_event::Event::SelectedOption(0)))
        ));
    }
}

#[tokio::test]
async fn timely_rejected_pointer_cancel_snapshot_marks_semantic_drift_against_bare_resync_ack() {
    let (mut running, _calls, mut updates) = running();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], opts: [&str; 2]| PanelSnapshot {
        revision: rev,
        title: format!("cancel-reject-{rev}"),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: contents.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        2,
                        "canvas",
                        panel::node::Kind::Canvas(panel::Canvas {
                            width: 100.0,
                            height: 100.0,
                            commands: vec![],
                            hit_regions: vec![panel::HitRegion {
                                id: 10,
                                bounds: Some(panel::Rect {
                                    x: 0.0,
                                    y: 0.0,
                                    width: 100.0,
                                    height: 100.0,
                                }),
                                accessibility_label: "hit".into(),
                                focusable: false,
                                capture_pointer: true,
                            }],
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec![opts[0].into(), opts[1].into()],
                            selected_index: 0,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };
    running.panel = PanelState::new(make_snap(1, 2, b"newer-host", ["A", "B"])).unwrap();

    let pointer_cmd = |phase: panel::PointerPhase| Control::Event {
        panel_id: protocol::PANEL_ID,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                hit_id: 10,
                phase: phase as i32,
                x: 50.0,
                y: 50.0,
            })),
        },
        event_seq: 0,
    };
    let mut seq = 1u64;
    let mut next_seq = || {
        let s = seq;
        seq += 1;
        s
    };

    running
        .control(pointer_cmd(panel::PointerPhase::Down), &outgoing)
        .await
        .unwrap();
    let down = wire.try_recv().unwrap();
    let mut down_ack = Envelope::new(
        running.identity,
        next_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    down_ack.in_reply_to = down.request_id;
    running.frame(down_ack, &outgoing).await.unwrap();

    running
        .control(pointer_cmd(panel::PointerPhase::Up), &outgoing)
        .await
        .unwrap();
    let up = wire.try_recv().unwrap();
    let mut up_err = Envelope::new(
        running.identity,
        next_seq(),
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up rejected")),
        MAX_OPERATION,
    );
    up_err.in_reply_to = up.request_id;
    running.frame(up_err, &outgoing).await.unwrap();
    let cancel_req = wire.try_recv().unwrap();

    // Defer SelectedOption(0) while Pointer(Cancel) barrier is active.
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert_eq!(running.main_deferred_commands.len(), 1);
    while updates.try_recv().is_ok() {}

    // Timely, structurally valid Pointer(Cancel) Snapshot reorders ["B", "A"] with stale editor_rev=1.
    let mut rejected_snap = Envelope::new(
        running.identity,
        next_seq(),
        2,
        envelope::Body::Snapshot(make_snap(2, 1, b"stale-editor", ["B", "A"])),
        MAX_OPERATION,
    );
    rejected_snap.in_reply_to = cancel_req.request_id;
    running.frame(rejected_snap, &outgoing).await.unwrap();

    assert!(running.main_pending_pointer_cancels.is_empty());
    assert!(running.main_resync_semantic_drift);
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 1);
    let resync = wire.try_recv().unwrap();
    assert!(matches!(resync.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));
    assert!(wire.try_recv().is_err());

    // Bare Ack(1) from legacy Worker must fail BOTH deferred SelectedOption(0) AND any subsequent SelectedOption(0).
    let mut bare_ack = Envelope::new(
        running.identity,
        next_seq(),
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    bare_ack.in_reply_to = resync.request_id;
    running.frame(bare_ack, &outgoing).await.unwrap();
    assert_eq!(running.main_resync_needed_seq, 0);
    assert!(running.main_resync_semantic_drift);
    assert!(running.main_deferred_commands.is_empty());
    assert!(wire.try_recv().is_err());
    while updates.try_recv().is_ok() {}

    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(wire.try_recv().is_err());
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Error { ref failure, .. }) if failure.code == ErrorCode::Stale as i32
    ));

    // Confirming full Snapshot clears drift and allows subsequent SelectedOption(0) to dispatch.
    running
        .frame(
            Envelope::new(
                running.identity,
                next_seq(),
                3,
                envelope::Body::Snapshot(make_snap(3, 2, b"newer-host", ["B", "A"])),
                MAX_OPERATION,
            ),
            &outgoing,
        )
        .await
        .unwrap();
    assert!(!running.main_resync_semantic_drift);

    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ok_ev = wire.try_recv().unwrap();
    assert!(matches!(
        ok_ev.body,
        Some(envelope::Body::UiEvent(ref ev))
            if matches!(ev.event, Some(panel::ui_event::Event::SelectedOption(0)))
    ));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn concurrent_writer_cannot_claim_destroy_close_during_prepare_shutdown_or_stop_cancel() {
    use std::io::{Read, Write};
    use std::sync::{
        Arc,
        atomic::{AtomicBool, AtomicUsize, Ordering},
    };
    use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};

    let make_snap = |rev: u64, title: &str| PanelSnapshot {
        revision: rev,
        title: title.into(),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };

    // Part A: Race concurrent writer draining duplex pipe against both `prepare_shutdown` and `stop_cancel`.
    for iter in 0..8usize {
        let cancel_before_shutdown = iter % 2 == 1;
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        claims.set_stop_cancel(running.cancel.clone());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(256);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let res2 = Uuid::new_v4();
        let (o2_tx, o2_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Open {
                    panel_id: 2,
                    id: res2,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o2_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let mut snap2 = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, "child")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        snap2.in_reply_to = o2_env.request_id;
        running.frame(snap2, &outgoing).await.unwrap();
        o2_rx.await.unwrap().unwrap();

        // Saturate the 256-byte duplex buffer so writer blocks inside write_all on HostResult.
        for s in 1..=24u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(15)).await;

        // Queue BOTH main Open AND child destroy CloseRequest into `writes` while writer is blocked.
        let (o1_tx, _o1_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::Open {
                    panel_id: protocol::PANEL_ID,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o1_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let (d2_tx, _d2_rx) = oneshot::channel();
        running
            .control_with_seq(
                3,
                Control::Revoke {
                    panel_id: 2,
                    id: res2,
                    remove_panel: true,
                    reply: d2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(running.outbound_queue.is_empty());

        if cancel_before_shutdown {
            // External stop_cancel happens BEFORE reader wakes writer and BEFORE prepare_shutdown runs!
            running.cancel.cancel();
            let drained_before_shutdown = Arc::new(tokio::sync::Notify::new());
            let drained_w = drained_before_shutdown.clone();
            let reader_task = tokio::spawn(async move {
                let mut host_results = 0usize;
                loop {
                    let env = read_async_frame(&mut worker_rx).await.unwrap();
                    match env.body {
                        Some(envelope::Body::HostResult(_)) => {
                            host_results += 1;
                            if host_results == 24 {
                                drained_w.notify_one();
                            }
                        }
                        Some(envelope::Body::Shutdown(_)) => return,
                        Some(other) => {
                            panic!("iter {iter}: unclaimed frame leaked after stop_cancel: {other:?}")
                        }
                        None => {}
                    }
                }
            });
            timeout(MAX_OPERATION, drained_before_shutdown.notified())
                .await
                .unwrap();
            tokio::time::sleep(Duration::from_millis(10)).await;
            running.prepare_shutdown(&outgoing);
            timeout(MAX_OPERATION, reader_task).await.unwrap().unwrap();
        } else {
            // Concurrent reader starts draining in parallel while prepare_shutdown runs!
            let reader_task = tokio::spawn(async move {
                loop {
                    let env = read_async_frame(&mut worker_rx).await.unwrap();
                    match env.body {
                        Some(envelope::Body::HostResult(_)) => {
                            tokio::task::yield_now().await;
                        }
                        Some(envelope::Body::Shutdown(_)) => return,
                        Some(other) => {
                            panic!("iter {iter}: unclaimed frame leaked during prepare_shutdown: {other:?}")
                        }
                        None => {}
                    }
                }
            });
            running.prepare_shutdown(&outgoing);
            timeout(MAX_OPERATION, reader_task).await.unwrap().unwrap();
        }

        io_cancel.cancel();
        io_tasks.abort_all();
    }

    // Part B: Real duplex PluginSupervisor::stop() never delivers queued destroy CloseRequest to SDK on_panel_destroy.
    {
        struct GatedReader {
            stream: DuplexStream,
            rt: tokio::runtime::Handle,
            paused: Arc<AtomicBool>,
            resume: Arc<tokio::sync::Notify>,
        }
        impl Read for GatedReader {
            fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
                while self.paused.load(Ordering::SeqCst) {
                    self.rt.block_on(self.resume.notified());
                }
                self.rt.block_on(self.stream.read(buf))
            }
        }
        struct BlockingWriter(DuplexStream, tokio::runtime::Handle);
        impl Write for BlockingWriter {
            fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
                self.1.block_on(self.0.write(buf))
            }
            fn flush(&mut self) -> std::io::Result<()> {
                self.1.block_on(self.0.flush())
            }
        }

        struct DestroyTrackPlugin {
            destroy_calls: Arc<AtomicUsize>,
        }

        impl mio_plugin_sdk::MioPlugin for DestroyTrackPlugin {
            fn id(&self) -> &str {
                "lab.destroy-shutdown-race"
            }

            fn version(&self) -> &str {
                "1.5.0"
            }

            fn supports_panel_multiplexing(&self) -> bool {
                true
            }

            fn initial_panel(&self) -> PanelSnapshot {
                PanelSnapshot {
                    revision: 1,
                    title: "main".into(),
                    root: Some(panel::Node::new(
                        1,
                        "txt",
                        panel::node::Kind::Text(panel::Text {
                            text: "main".into(),
                            tone: 0,
                        }),
                    )),
                }
            }

            fn on_panel_open_request(
                &mut self,
                _ctx: &mut dyn mio_plugin_sdk::HostClient,
                _panel_id: u64,
                _req: mio_plugin_api::protocol::OpenRequest,
            ) -> std::result::Result<Option<PanelSnapshot>, String> {
                Ok(Some(PanelSnapshot {
                    revision: 1,
                    title: "child".into(),
                    root: Some(panel::Node::new(
                        1,
                        "txt",
                        panel::node::Kind::Text(panel::Text {
                            text: "child".into(),
                            tone: 0,
                        }),
                    )),
                }))
            }

            fn on_panel_destroy(
                &mut self,
                _ctx: &mut dyn mio_plugin_sdk::HostClient,
                _panel_id: u64,
                _close: mio_plugin_api::protocol::CloseRequest,
            ) -> std::result::Result<Option<PanelSnapshot>, String> {
                self.destroy_calls.fetch_add(1, Ordering::SeqCst);
                Ok(None)
            }
        }

        let rt_handle = tokio::runtime::Handle::current();
        let identity = super::tests_runtime::identity();
        let manifest = PluginManifest {
            id: "lab.destroy-shutdown-race".into(),
            version: "1.5.0".into(),
            api_version: 1,
            engine: "native".into(),
            entry: "worker".into(),
            permissions: vec![Permission::TrafficRead],
            contributions: vec!["suite_panel".into()],
        };
        let (host_tx, worker_rx) = tokio::io::duplex(512);
        let (worker_tx, host_rx) = tokio::io::duplex(64 * 1024);
        let paused = Arc::new(AtomicBool::new(false));
        let resume = Arc::new(tokio::sync::Notify::new());
        let destroy_calls = Arc::new(AtomicUsize::new(0));

        let paused_w = paused.clone();
        let resume_w = resume.clone();
        let destroy_calls_w = destroy_calls.clone();
        let worker_thread = std::thread::spawn(move || {
            let mut plugin = DestroyTrackPlugin {
                destroy_calls: destroy_calls_w,
            };
            match mio_plugin_sdk::run_with_io(
                GatedReader {
                    stream: worker_rx,
                    rt: rt_handle.clone(),
                    paused: paused_w,
                    resume: resume_w,
                },
                BlockingWriter(worker_tx, rt_handle),
                &mut plugin,
            ) {
                Ok(()) => {}
                Err(err)
                    if matches!(
                        err.kind(),
                        std::io::ErrorKind::BrokenPipe | std::io::ErrorKind::UnexpectedEof
                    ) => {}
                Err(err) => panic!("unexpected duplex worker error during concurrent stop: {err:?}"),
            }
        });

        let (mut supervisor, _services) = super::supervisor::spawn_test_duplex_supervisor(
            identity,
            manifest,
            BTreeSet::from([Permission::TrafficRead]),
            host_tx,
            host_rx,
        )
        .await
        .unwrap();
        let handle = supervisor.handle();

        let _init = timeout(MAX_OPERATION, supervisor.events.recv())
            .await
            .unwrap()
            .unwrap();
        let res2 = Uuid::new_v4();
        handle
            .open_request_on_panel(2, res2, 1, false, request())
            .await
            .unwrap();

        // Pause worker stdin reader so subsequent frames fill the 512-byte pipe and leave Open + CloseRequest in `writes`.
        paused.store(true, Ordering::SeqCst);
        for _ in 0..24 {
            handle
                .try_event(UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Focus(true)),
                })
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(25)).await;

        let main_handle = handle.clone();
        let open_task = tokio::spawn(async move {
            let _ = main_handle
                .open_request(Uuid::new_v4(), 1, false, request())
                .await;
        });
        tokio::time::sleep(Duration::from_millis(15)).await;
        let revoke_handle = handle.begin_revoke_panel_resource(2, res2, true);
        tokio::time::sleep(Duration::from_millis(15)).await;

        let resume_task = tokio::spawn(async move {
            tokio::task::yield_now().await;
            paused.store(false, Ordering::SeqCst);
            resume.notify_one();
        });
        let (stop_res, _, _) = tokio::join!(supervisor.stop(), resume_task, open_task);
        stop_res.unwrap();
        let _ = revoke_handle.wait().await;
        worker_thread.join().unwrap();

        assert_eq!(
            destroy_calls.load(Ordering::SeqCst),
            0,
            "on_panel_destroy must never fire when shutdown races queued Open + destroy CloseRequest"
        );
    }
}

#[tokio::test]
async fn expired_and_late_high_revision_pointer_cancel_acks_latch_semantic_drift_after_budget_exhaustion()
{
    let make_snap = |rev: u64, opts: [&str; 2]| PanelSnapshot {
        revision: rev,
        title: format!("pc-ack-{rev}"),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        2,
                        "canvas",
                        panel::node::Kind::Canvas(panel::Canvas {
                            width: 100.0,
                            height: 100.0,
                            commands: vec![],
                            hit_regions: vec![panel::HitRegion {
                                id: 10,
                                bounds: Some(panel::Rect {
                                    x: 0.0,
                                    y: 0.0,
                                    width: 100.0,
                                    height: 100.0,
                                }),
                                accessibility_label: "hit".into(),
                                focusable: false,
                                capture_pointer: true,
                            }],
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec![opts[0].into(), opts[1].into()],
                            selected_index: 0,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };
    let pointer_cmd = |panel_id: u64, phase: panel::PointerPhase| Control::Event {
        panel_id,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Pointer(panel::PointerEvent {
                hit_id: 10,
                phase: phase as i32,
                x: 50.0,
                y: 50.0,
            })),
        },
        event_seq: 0,
    };
    let select_cmd = |panel_id: u64| Control::Event {
        panel_id,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 3,
            editors: vec![],
            event: Some(panel::ui_event::Event::SelectedOption(0)),
        },
        event_seq: 0,
    };

    // Subcase A: Child panel 2 receives an expired high-rev Ack(2) BEFORE timer on final 3rd Pointer(Cancel) attempt.
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let mut seq = 1u64;
        let mut next_seq = || {
            let s = seq;
            seq += 1;
            s
        };

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_wire = wire.try_recv().unwrap();
        let mut o_snap = Envelope::new(
            running.identity,
            next_seq(),
            1,
            envelope::Body::Snapshot(make_snap(1, ["A", "B"])),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_snap.in_reply_to = o_wire.request_id;
        running.frame(o_snap, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        running
            .control(pointer_cmd(2, panel::PointerPhase::Down), &outgoing)
            .await
            .unwrap();
        let down = wire.try_recv().unwrap();
        let mut down_ack = Envelope::new(
            running.identity,
            next_seq(),
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        down_ack.in_reply_to = down.request_id;
        running.frame(down_ack, &outgoing).await.unwrap();

        running
            .control(pointer_cmd(2, panel::PointerPhase::Up), &outgoing)
            .await
            .unwrap();
        let up = wire.try_recv().unwrap();
        let mut up_err = Envelope::new(
            running.identity,
            next_seq(),
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up failed")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        up_err.in_reply_to = up.request_id;
        running.frame(up_err, &outgoing).await.unwrap();

        let mut current_attempt = wire.try_recv().unwrap();
        for attempt in 1..MAX_RESYNC_RETRIES {
            let _ = attempt;
            running.requests.get_mut(&current_attempt.request_id).unwrap().deadline =
                Instant::now() - Duration::from_secs(1);
            running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
            let cancel_frame = wire.try_recv().unwrap();
            assert!(matches!(cancel_frame.body, Some(envelope::Body::Cancel(_))));
            current_attempt = wire.try_recv().unwrap();
        }
        assert_eq!(running.panels[&2].pending_pointer_cancels[0].attempts, MAX_RESYNC_RETRIES);

        let mut expired_high_ack = Envelope::new(
            running.identity,
            next_seq(),
            2,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        expired_high_ack.deadline_unix_ms = 1;
        expired_high_ack.in_reply_to = current_attempt.request_id;
        running.frame(expired_high_ack, &outgoing).await.unwrap();

        assert!(running.panels[&2].resync_semantic_drift);
        let cancel3 = wire.try_recv().unwrap();
        assert!(matches!(cancel3.body, Some(envelope::Body::Cancel(_))));
        let resync = wire.try_recv().unwrap();
        assert!(matches!(resync.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));
        assert!(wire.try_recv().is_err());

        let mut bare_resync_ack = Envelope::new(
            running.identity,
            next_seq(),
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        bare_resync_ack.in_reply_to = resync.request_id;
        running.frame(bare_resync_ack, &outgoing).await.unwrap();
        assert_eq!(running.panels[&2].resync_needed_seq, 0);
        assert!(running.panels[&2].pending_pointer_cancels.is_empty());
        assert!(running.panels[&2].resync_semantic_drift);
        assert!(wire.try_recv().is_err());
        while updates.try_recv().is_ok() {}

        running.control(select_cmd(2), &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id: 2, ref failure, .. })
                if failure.code == ErrorCode::Stale as i32
        ));
    }

    // Subcase B & C: Timer fires FIRST on final 3rd Pointer(Cancel) attempt (exhausting budget),
    // THEN late high-rev Ack(2) arrives for both main panel and child panel 2.
    for target_panel in [protocol::PANEL_ID, 2u64] {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        running.panel = PanelState::new(make_snap(1, ["A", "B"])).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let mut seq = 1u64;
        let mut next_seq = || {
            let s = seq;
            seq += 1;
            s
        };

        if target_panel != protocol::PANEL_ID {
            let (o_tx, o_rx) = oneshot::channel();
            running
                .control(
                    Control::Open {
                        panel_id: target_panel,
                        id: Uuid::new_v4(),
                        revision: 1,
                        read_only: false,
                        request: request(),
                        reply: o_tx,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            let o_wire = wire.try_recv().unwrap();
            let mut o_snap = Envelope::new(
                running.identity,
                next_seq(),
                1,
                envelope::Body::Snapshot(make_snap(1, ["A", "B"])),
                MAX_OPERATION,
            )
            .with_panel_id(target_panel);
            o_snap.in_reply_to = o_wire.request_id;
            running.frame(o_snap, &outgoing).await.unwrap();
            o_rx.await.unwrap().unwrap();
        }

        running
            .control(pointer_cmd(target_panel, panel::PointerPhase::Down), &outgoing)
            .await
            .unwrap();
        let down = wire.try_recv().unwrap();
        let mut down_ack = Envelope::new(
            running.identity,
            next_seq(),
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        down_ack.in_reply_to = down.request_id;
        running.frame(down_ack, &outgoing).await.unwrap();

        running
            .control(pointer_cmd(target_panel, panel::PointerPhase::Up), &outgoing)
            .await
            .unwrap();
        let up = wire.try_recv().unwrap();
        let mut up_err = Envelope::new(
            running.identity,
            next_seq(),
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Invalid, "up failed")),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        up_err.in_reply_to = up.request_id;
        running.frame(up_err, &outgoing).await.unwrap();

        let mut current_attempt = wire.try_recv().unwrap();
        for attempt in 1..=MAX_RESYNC_RETRIES {
            running.requests.get_mut(&current_attempt.request_id).unwrap().deadline =
                Instant::now() - Duration::from_secs(1);
            running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
            let cancel_frame = wire.try_recv().unwrap();
            assert!(matches!(cancel_frame.body, Some(envelope::Body::Cancel(_))));
            if attempt < MAX_RESYNC_RETRIES {
                current_attempt = wire.try_recv().unwrap();
            }
        }
        assert!(wire.try_recv().is_err());

        // Late high-revision Ack for final cancelled attempt #3 must latch semantic drift & emit Resync!
        let mut late_high_ack = Envelope::new(
            running.identity,
            next_seq(),
            2,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        late_high_ack.in_reply_to = current_attempt.request_id;
        running.frame(late_high_ack, &outgoing).await.unwrap();

        assert!(running.is_panel_semantic_drifted(target_panel));
        let resync = wire.try_recv().unwrap();
        assert!(matches!(resync.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));

        let mut bare_resync_ack = Envelope::new(
            running.identity,
            next_seq(),
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        bare_resync_ack.in_reply_to = resync.request_id;
        running.frame(bare_resync_ack, &outgoing).await.unwrap();
        assert!(!running.is_panel_resyncing(target_panel));
        assert!(running.is_panel_semantic_drifted(target_panel));
        while updates.try_recv().is_ok() {}

        running.control(select_cmd(target_panel), &outgoing).await.unwrap();
        assert!(wire.try_recv().is_err());
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id, ref failure, .. })
                if panel_id == target_panel && failure.code == ErrorCode::Stale as i32
        ));
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn marking_semantic_drift_atomically_retracts_unclaimed_in_writes_events_and_commits_before_resync()
{
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], opts: [&str; 2]| PanelSnapshot {
        revision: rev,
        title: format!("retract-drift-{rev}"),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: contents.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec![opts[0].into(), opts[1].into()],
                            selected_index: 0,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    for target_panel in [protocol::PANEL_ID, 2u64] {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        claims.set_stop_cancel(running.cancel.clone());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(256);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let res = Uuid::new_v4();
        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: target_panel,
                    id: res,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let init_rev = if target_panel == protocol::PANEL_ID { 2 } else { 1 };
        let mut o_snap = Envelope::new(
            running.identity,
            1,
            init_rev,
            envelope::Body::Snapshot(make_snap(init_rev, 2, b"newer-host", ["A", "B"])),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        o_snap.in_reply_to = o_env.request_id;
        running.frame(o_snap, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        // Event A is claimed & written to worker_rx.
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_a = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();

        // Saturate 256-byte duplex buffer so writer blocks in write_all on HostResult.
        for s in 1..=24u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(15)).await;

        // Without any active barrier, B1 (SelectedOption(0)), B2 (CommitEditor), and C (EditorChanged)
        // enter `writes` unclaimed.
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let (cm_tx, mut cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: target_panel,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 2,
                            contents: b"newer-host".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: cm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::EditorChanged(EditorSnapshot {
                            document_id: 1,
                            revision: 3,
                            contents: b"host-ed-3".to_vec(),
                            ..Default::default()
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(running.outbound_queue.is_empty());
        while updates.try_recv().is_ok() {}

        // Event A replies with a reordered Snapshot rejected by PanelState::replace -> resync_panel ->
        // mark_panel_semantic_drift MUST retract B1 & B2 in `writes` BEFORE emitting Resync!
        let stale_rev = init_rev + 1;
        let mut stale_ev_a_snap = Envelope::new(
            running.identity,
            2,
            stale_rev,
            envelope::Body::Snapshot(make_snap(stale_rev, 1, b"stale-ed", ["B", "A"])),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        stale_ev_a_snap.in_reply_to = ev_a.request_id;
        running.frame(stale_ev_a_snap, &outgoing).await.unwrap();

        assert!(cm_rx.try_recv().unwrap().is_err());
        assert_eq!(running.requests.len(), 2); // Only EditorChanged + Resync remain!

        let reader_task = tokio::spawn(async move {
            let mut saw_editor_changed = false;
            let mut saw_resync = false;
            while !(saw_editor_changed && saw_resync) {
                let env = read_async_frame(&mut worker_rx).await.unwrap();
                match env.body {
                    Some(envelope::Body::HostResult(_)) => {}
                    Some(envelope::Body::UiEvent(ref ev))
                        if matches!(ev.event, Some(panel::ui_event::Event::EditorChanged(_))) =>
                    {
                        saw_editor_changed = true;
                    }
                    Some(envelope::Body::Resync(_)) => {
                        saw_resync = true;
                    }
                    Some(other) => {
                        panic!("retracted interaction/commit leaked before Resync: {other:?}")
                    }
                    None => {}
                }
            }
        });
        timeout(MAX_OPERATION, reader_task).await.unwrap().unwrap();

        running.prepare_shutdown(&outgoing);
        io_cancel.cancel();
        io_tasks.abort_all();
    }
}

#[tokio::test]
async fn semantic_drift_blocks_deferred_new_and_inflight_commit_and_commit_response_until_snapshot()
{
    let make_snap = |rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("commit-drift-{rev}"),
        root: Some(panel::Node::new(
            1,
            "ed",
            panel::node::Kind::Editor(panel::Editor {
                document_id: 1,
                revision: 1,
                contents: b"init".to_vec(),
                format: panel::EditorFormat::Utf8 as i32,
                read_only: false,
            }),
        )),
    };
    let make_resp = || mio_plugin_api::HttpResponse {
        status: 200,
        version: mio_plugin_api::HttpVersion::Http11,
        reason_phrase: Some("OK".into()),
        headers: vec![],
        body: b"resp".to_vec(),
        trailers: vec![],
    };

    // Subcase A: Deferred and new Commit/CommitResponse stay blocked across bare Resync Ack until confirming Snapshot.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let res2 = Uuid::new_v4();
        let (o2_tx, o2_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: res2,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o2_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o2_wire = wire.try_recv().unwrap();
        let mut o2_snap = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o2_snap.in_reply_to = o2_wire.request_id;
        running.frame(o2_snap, &outgoing).await.unwrap();
        o2_rx.await.unwrap().unwrap();

        running.schedule_panel_semantic_resync(2);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync = wire.try_recv().unwrap();

        let (def_cm_tx, mut def_cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: 2,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res2.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: def_cm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let (def_rcm_tx, mut def_rcm_rx) = oneshot::channel();
        running
            .control(
                Control::CommitResponse {
                    panel_id: 2,
                    op_id: Uuid::new_v4(),
                    request: protocol::CommitResponseEditor {
                        resource_id: res2.as_bytes().to_vec(),
                        message_revision: 1,
                        response: Some(make_resp().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: def_rcm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.panels[&2].deferred_commands.len(), 2);

        let mut bare_ack = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        bare_ack.in_reply_to = resync.request_id;
        running.frame(bare_ack, &outgoing).await.unwrap();
        assert!(def_cm_rx.try_recv().unwrap().is_err());
        assert!(def_rcm_rx.try_recv().unwrap().is_err());
        assert!(wire.try_recv().is_err());

        // New Commit / CommitResponse after bare Ack must also be blocked without writing to wire!
        let (new_cm_tx, mut new_cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: 2,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res2.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: new_cm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let (new_rcm_tx, mut new_rcm_rx) = oneshot::channel();
        running
            .control(
                Control::CommitResponse {
                    panel_id: 2,
                    op_id: Uuid::new_v4(),
                    request: protocol::CommitResponseEditor {
                        resource_id: res2.as_bytes().to_vec(),
                        message_revision: 1,
                        response: Some(make_resp().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: new_rcm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(new_cm_rx.try_recv().unwrap().is_err());
        assert!(new_rcm_rx.try_recv().unwrap().is_err());
        assert!(wire.try_recv().is_err());
    }

    // Subcase B & C: In-flight Committed/ResponseCommitted fail when drifted or when envelope.revision > host_rev,
    // and full confirming Snapshot restores Commit/CommitResponse execution.
    {
        let (mut running, _calls, _updates) = running();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let res = Uuid::new_v4();
        running.broker.bind_resource(res, 1, false).unwrap();
        running.active_resource = Some((res, 1));
        running.panel = PanelState::new(make_snap(1)).unwrap();

        let (c1_tx, mut c1_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: c1_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let c1_wire = wire.try_recv().unwrap();

        let (rc1_tx, mut rc1_rx) = oneshot::channel();
        running
            .control(
                Control::CommitResponse {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: protocol::CommitResponseEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        response: Some(make_resp().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: rc1_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let rc1_wire = wire.try_recv().unwrap();

        // Mark semantic drift while c1 & rc1 are in flight -> replies MUST fail!
        running.schedule_panel_semantic_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync1 = wire.try_recv().unwrap();

        let mut c1_reply = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Committed(protocol::Committed {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        );
        c1_reply.in_reply_to = c1_wire.request_id;
        running.frame(c1_reply, &outgoing).await.unwrap();
        assert!(c1_rx.try_recv().unwrap().is_err());

        let mut rc1_reply = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::ResponseCommitted(protocol::ResponseCommitted {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                response: Some(make_resp().into()),
            }),
            MAX_OPERATION,
        );
        rc1_reply.in_reply_to = rc1_wire.request_id;
        running.frame(rc1_reply, &outgoing).await.unwrap();
        assert!(rc1_rx.try_recv().unwrap().is_err());

        // Confirm resync1 with Snapshot(rev=2) -> clears semantic drift!
        let mut ok_snap = Envelope::new(
            running.identity,
            3,
            2,
            envelope::Body::Snapshot(make_snap(2)),
            MAX_OPERATION,
        );
        ok_snap.in_reply_to = resync1.request_id;
        running.frame(ok_snap, &outgoing).await.unwrap();
        assert!(!running.main_resync_semantic_drift);

        // Even with no prior drift flag, Committed/ResponseCommitted with envelope.revision > host_rev
        // MUST fail AND mark semantic drift + schedule Resync(2)!
        let (c2_tx, mut c2_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: c2_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let c2_wire = wire.try_recv().unwrap();

        let (rc2_tx, mut rc2_rx) = oneshot::channel();
        running
            .control(
                Control::CommitResponse {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: protocol::CommitResponseEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        response: Some(make_resp().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: rc2_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let rc2_wire = wire.try_recv().unwrap();

        let mut c2_drifted = Envelope::new(
            running.identity,
            4,
            3,
            envelope::Body::Committed(protocol::Committed {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        );
        c2_drifted.in_reply_to = c2_wire.request_id;
        running.frame(c2_drifted, &outgoing).await.unwrap();
        assert!(c2_rx.try_recv().unwrap().is_err());
        assert!(running.main_resync_semantic_drift);
        let resync2 = wire.try_recv().unwrap();
        assert!(matches!(resync2.body, Some(envelope::Body::Resync(ref s)) if s.revision == 2));

        let mut rc2_drifted = Envelope::new(
            running.identity,
            5,
            3,
            envelope::Body::ResponseCommitted(protocol::ResponseCommitted {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                response: Some(make_resp().into()),
            }),
            MAX_OPERATION,
        );
        rc2_drifted.in_reply_to = rc2_wire.request_id;
        running.frame(rc2_drifted, &outgoing).await.unwrap();
        assert!(rc2_rx.try_recv().unwrap().is_err());

        // Confirm resync2 with Snapshot(rev=4) -> Commit and CommitResponse succeed at rev=4!
        let mut ok_snap2 = Envelope::new(
            running.identity,
            6,
            4,
            envelope::Body::Snapshot(make_snap(4)),
            MAX_OPERATION,
        );
        ok_snap2.in_reply_to = resync2.request_id;
        running.frame(ok_snap2, &outgoing).await.unwrap();
        assert!(!running.main_resync_semantic_drift);

        let (ok_cm_tx, ok_cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: ok_cm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ok_cm_wire = wire.try_recv().unwrap();
        let mut ok_cm_reply = Envelope::new(
            running.identity,
            7,
            4,
            envelope::Body::Committed(protocol::Committed {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        );
        ok_cm_reply.in_reply_to = ok_cm_wire.request_id;
        running.frame(ok_cm_reply, &outgoing).await.unwrap();
        assert_eq!(ok_cm_rx.await.unwrap().unwrap().url, request().url);

        let (ok_rcm_tx, ok_rcm_rx) = oneshot::channel();
        running
            .control(
                Control::CommitResponse {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: protocol::CommitResponseEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        response: Some(make_resp().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: ok_rcm_tx,
                                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ok_rcm_wire = wire.try_recv().unwrap();
        let mut ok_rcm_reply = Envelope::new(
            running.identity,
            8,
            4,
            envelope::Body::ResponseCommitted(protocol::ResponseCommitted {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                response: Some(make_resp().into()),
            }),
            MAX_OPERATION,
        );
        ok_rcm_reply.in_reply_to = ok_rcm_wire.request_id;
        running.frame(ok_rcm_reply, &outgoing).await.unwrap();
        assert_eq!(ok_rcm_rx.await.unwrap().unwrap().status, 200);
    }
}

#[tokio::test]
async fn timed_out_resync_late_snapshot_marks_semantic_drift_without_restarting_exhausted_budget()
{
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], opts: [&str; 2]| PanelSnapshot {
        revision: rev,
        title: format!("resync-late-{rev}"),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: contents.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec![opts[0].into(), opts[1].into()],
                            selected_index: 0,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    // Subcase A: Child panel normal timeout schedules non-semantic Resync; attempt #1 times out and
    // returns late Snapshot(rev=2, ["B", "A"]) after cancellation -> MUST latch resync_semantic_drift
    // so bare Ack(1) on attempt #2 fails deferred SelectedOption(0) and blocks subsequent ops.
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let res2 = Uuid::new_v4();
        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: res2,
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_wire = wire.try_recv().unwrap();
        let mut o_snap = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1, b"init", ["A", "B"])),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_snap.in_reply_to = o_wire.request_id;
        running.frame(o_snap, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        running
            .control(
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev1 = wire.try_recv().unwrap();
        running.requests.get_mut(&ev1.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        let cancel_ev1 = wire.try_recv().unwrap();
        assert!(matches!(cancel_ev1.body, Some(envelope::Body::Cancel(_))));
        let resync1 = wire.try_recv().unwrap();
        assert!(matches!(resync1.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));
        assert!(!running.panels[&2].resync_semantic_drift);

        // Resync attempt #1 times out -> Resync attempt #2 sent!
        running.requests.get_mut(&resync1.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        let cancel_resync1 = wire.try_recv().unwrap();
        assert!(matches!(cancel_resync1.body, Some(envelope::Body::Cancel(_))));
        let resync2 = wire.try_recv().unwrap();
        assert!(matches!(resync2.body, Some(envelope::Body::Resync(ref s)) if s.revision == 1));

        // Defer SelectedOption(0) while Resync #2 is active.
        running
            .control(
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.panels[&2].deferred_commands.len(), 1);

        // Late reordered Snapshot replying to timed-out Resync #1 arrives!
        let mut late_resync1_snap = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"init", ["B", "A"])),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        late_resync1_snap.in_reply_to = resync1.request_id;
        running.frame(late_resync1_snap, &outgoing).await.unwrap();
        assert!(running.panels[&2].resync_semantic_drift);
        assert!(wire.try_recv().is_err());

        // Legacy Worker answers Resync #2 with bare Ack(1): barrier clears, deferred & new ops stay rejected!
        let mut bare_ack2 = Envelope::new(
            running.identity,
            3,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        bare_ack2.in_reply_to = resync2.request_id;
        running.frame(bare_ack2, &outgoing).await.unwrap();
        assert!(!running.is_panel_resyncing(2));
        assert!(running.panels[&2].resync_semantic_drift);
        assert!(running.panels[&2].deferred_commands.is_empty());
        assert!(wire.try_recv().is_err());
        while updates.try_recv().is_ok() {}

        running
            .control(
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(wire.try_recv().is_err());
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id: 2, ref failure, .. })
                if failure.code == ErrorCode::Stale as i32
        ));

        let (cm_tx, mut cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: 2,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res2.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: cm_tx,
                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(cm_rx.try_recv().unwrap().is_err());
        assert!(wire.try_recv().is_err());
    }

    // Subcase B: Exhausting MAX_RESYNC_RETRIES on main & child panels (both CancelNotification and
    // expired-in-frame Resync BEFORE timer, plus late Snapshot after timer) latches semantic drift
    // WITHOUT restarting the exhausted Resync budget!
    for target_panel in [protocol::PANEL_ID, 2u64] {
        // B1: All MAX_RESYNC_RETRIES time out; late Snapshot replying to final Resync's CancelNotification
        //     OR late Snapshot replying to final Resync's request_id latches drift without restarting.
        for reply_to_cancel_frame in [false, true] {
            let (mut running, _calls, mut updates) = running();
            running.supports_panel_multiplexing = true;
            running.panel = PanelState::new(make_snap(1, 1, b"init", ["A", "B"])).unwrap();
            let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
            let mut seq = 1u64;
            let mut next_seq = || {
                let s = seq;
                seq += 1;
                s
            };
            if target_panel != protocol::PANEL_ID {
                let (o_tx, o_rx) = oneshot::channel();
                running
                    .control(
                        Control::Open {
                            panel_id: target_panel,
                            id: Uuid::new_v4(),
                            revision: 1,
                            read_only: false,
                            request: request(),
                            reply: o_tx,
                        },
                        &outgoing,
                    )
                    .await
                    .unwrap();
                let o_w = wire.try_recv().unwrap();
                let mut o_s = Envelope::new(
                    running.identity,
                    next_seq(),
                    1,
                    envelope::Body::Snapshot(make_snap(1, 1, b"init", ["A", "B"])),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel);
                o_s.in_reply_to = o_w.request_id;
                running.frame(o_s, &outgoing).await.unwrap();
                o_rx.await.unwrap().unwrap();
            }

            running.schedule_panel_resync(target_panel);
            running.flush_pending_resyncs(&outgoing).unwrap();
            let mut last_resync_id = 0u64;
            let mut last_cancel_id = 0u64;
            for _ in 0..MAX_RESYNC_RETRIES {
                let r = wire.try_recv().unwrap();
                last_resync_id = r.request_id;
                running.requests.get_mut(&r.request_id).unwrap().deadline =
                    Instant::now() - Duration::from_secs(1);
                running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
                let c = wire.try_recv().unwrap();
                last_cancel_id = c.request_id;
            }
            assert!(!running.is_panel_resyncing(target_panel));
            assert!(!running.is_panel_semantic_drifted(target_panel));
            assert!(wire.try_recv().is_err());

            let mut late_snap = Envelope::new(
                running.identity,
                next_seq(),
                2,
                envelope::Body::Snapshot(make_snap(2, 1, b"init", ["B", "A"])),
                MAX_OPERATION,
            )
            .with_panel_id(target_panel);
            late_snap.in_reply_to = if reply_to_cancel_frame {
                last_cancel_id
            } else {
                last_resync_id
            };
            running.frame(late_snap, &outgoing).await.unwrap();
            assert!(running.is_panel_semantic_drifted(target_panel));
            assert!(!running.is_panel_resyncing(target_panel));
            assert!(wire.try_recv().is_err());
            while updates.try_recv().is_ok() {}

            running
                .control(
                    Control::Event {
                        panel_id: target_panel,
                        expected_snapshot: None,
                        event: UiEvent {
                            node_id: 3,
                            editors: vec![],
                            event: Some(panel::ui_event::Event::SelectedOption(0)),
                        },
                        event_seq: 0,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            assert!(wire.try_recv().is_err());
            assert!(matches!(
                updates.try_recv(),
                Ok(PluginEvent::Error { panel_id, ref failure, .. })
                    if panel_id == target_panel && failure.code == ErrorCode::Stale as i32
            ));
        }

        // B2: Expired reply arriving BEFORE timer on final Resync attempt #3 also latches drift.
        {
            let (mut running, _calls, _updates) = running();
            running.supports_panel_multiplexing = true;
            running.panel = PanelState::new(make_snap(1, 1, b"init", ["A", "B"])).unwrap();
            let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
            let mut seq = 1u64;
            let mut next_seq = || {
                let s = seq;
                seq += 1;
                s
            };
            if target_panel != protocol::PANEL_ID {
                let (o_tx, o_rx) = oneshot::channel();
                running
                    .control(
                        Control::Open {
                            panel_id: target_panel,
                            id: Uuid::new_v4(),
                            revision: 1,
                            read_only: false,
                            request: request(),
                            reply: o_tx,
                        },
                        &outgoing,
                    )
                    .await
                    .unwrap();
                let o_w = wire.try_recv().unwrap();
                let mut o_s = Envelope::new(
                    running.identity,
                    next_seq(),
                    1,
                    envelope::Body::Snapshot(make_snap(1, 1, b"init", ["A", "B"])),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel);
                o_s.in_reply_to = o_w.request_id;
                running.frame(o_s, &outgoing).await.unwrap();
                o_rx.await.unwrap().unwrap();
            }

            running.schedule_panel_resync(target_panel);
            running.flush_pending_resyncs(&outgoing).unwrap();
            let mut current_resync = wire.try_recv().unwrap();
            for _ in 1..MAX_RESYNC_RETRIES {
                running.requests.get_mut(&current_resync.request_id).unwrap().deadline =
                    Instant::now() - Duration::from_secs(1);
                running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
                let _cancel = wire.try_recv().unwrap();
                current_resync = wire.try_recv().unwrap();
            }

            let mut expired_final_snap = Envelope::new(
                running.identity,
                next_seq(),
                2,
                envelope::Body::Snapshot(make_snap(2, 1, b"init", ["B", "A"])),
                MAX_OPERATION,
            )
            .with_panel_id(target_panel);
            expired_final_snap.deadline_unix_ms = 1;
            expired_final_snap.in_reply_to = current_resync.request_id;
            running.frame(expired_final_snap, &outgoing).await.unwrap();
            assert!(running.is_panel_semantic_drifted(target_panel));
            assert!(!running.is_panel_resyncing(target_panel));
        }
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn retracting_unclaimed_viewport_rolls_back_host_watermark_so_worker_snapshot_recovers() {
    let make_snap = |rev: u64, ed_rev: u64, contents: &[u8], vp_rev: u64, sel_idx: u32, opts: [&str; 2]| PanelSnapshot {
        revision: rev,
        title: "vp-rollback".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: contents.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        2,
                        "tbl",
                        panel::node::Kind::VirtualTable(panel::VirtualTable {
                            columns: vec![panel::TableColumn {
                                id: "c1".into(),
                                title: "Col".into(),
                                width: 80.0,
                            }],
                            total_rows: 10,
                            offset: 0,
                            viewport_revision: vp_rev,
                            rows: vec![],
                            multi_select: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec![opts[0].into(), opts[1].into()],
                            selected_index: sel_idx,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    for target_panel in [protocol::PANEL_ID, 2u64] {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        claims.set_stop_cancel(running.cancel.clone());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(256);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: target_panel,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let init_rev = if target_panel == protocol::PANEL_ID { 2 } else { 1 };
        let mut o_snap = Envelope::new(
            running.identity,
            1,
            init_rev,
            envelope::Body::Snapshot(make_snap(init_rev, 2, b"host-ed", 1, 0, ["A", "B"])),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        o_snap.in_reply_to = o_env.request_id;
        running.frame(o_snap, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        // Event A claimed and sent onto duplex pipe.
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_a = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();

        // Saturate duplex buffer so writer blocks before reading Viewport(2), Viewport(3), SelectedOption(1), EditorChanged(3).
        for s in 1..=24u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(15)).await;

        for vp_rev in [2u64, 3u64] {
            running
                .control(
                    Control::Event {
                        panel_id: target_panel,
                        expected_snapshot: None,
                        event: UiEvent {
                            node_id: 2,
                            editors: vec![],
                            event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                                revision: vp_rev,
                                offset: 0,
                                limit: 5,
                            })),
                        },
                        event_seq: 0,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
        }
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(1)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::EditorChanged(EditorSnapshot {
                            document_id: 1,
                            revision: 3,
                            contents: b"host-ed-3".to_vec(),
                            ..Default::default()
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(running.outbound_queue.is_empty());

        // Event A replies with stale-editor reordered Snapshot -> rejected -> marks semantic drift
        // AND retracts Viewport(3) -> Viewport(2) + SelectedOption(1) in LIFO order, restoring vp_rev == 1!
        let stale_rev = init_rev + 1;
        let mut stale_ev_a_snap = Envelope::new(
            running.identity,
            2,
            stale_rev,
            envelope::Body::Snapshot(make_snap(stale_rev, 1, b"stale-ed", 1, 0, ["B", "A"])),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        stale_ev_a_snap.in_reply_to = ev_a.request_id;
        running.frame(stale_ev_a_snap, &outgoing).await.unwrap();

        let snap_after_rollback = running.panel_snapshot(target_panel).unwrap();
        let rolled_vp = match snap_after_rollback
            .root
            .as_ref()
            .unwrap()
            .find(2)
            .unwrap()
            .kind
            .as_ref()
            .unwrap()
        {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            other => panic!("expected VirtualTable, got {other:?}"),
        };
        assert_eq!(rolled_vp, 1, "chained unclaimed Viewports must unwind back to 1");
        let rolled_sel = match snap_after_rollback
            .root
            .as_ref()
            .unwrap()
            .find(3)
            .unwrap()
            .kind
            .as_ref()
            .unwrap()
        {
            panel::node::Kind::Select(s) => s.selected_index,
            other => panic!("expected Select, got {other:?}"),
        };
        assert_eq!(rolled_sel, 0);

        let reader_task = tokio::spawn(async move {
            let mut ec_req_id = None;
            loop {
                let env = read_async_frame(&mut worker_rx).await.unwrap();
                match env.body {
                    Some(envelope::Body::HostResult(_)) => {}
                    Some(envelope::Body::UiEvent(ref ev))
                        if matches!(ev.event, Some(panel::ui_event::Event::EditorChanged(_))) =>
                    {
                        ec_req_id = Some(env.request_id);
                    }
                    Some(envelope::Body::Resync(resync_snap)) => {
                        return (ec_req_id, env.request_id, resync_snap);
                    }
                    Some(other) => panic!("unexpected retracted event on wire: {other:?}"),
                    None => {}
                }
            }
        });
        let (ec_req_id, resync_req_id, resync_snap) =
            timeout(MAX_OPERATION, reader_task).await.unwrap().unwrap();
        let ec_req_id = ec_req_id.expect("EditorChanged must reach worker");
        let resync_vp = match resync_snap.root.as_ref().unwrap().find(2).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            _ => unreachable!(),
        };
        assert_eq!(resync_vp, 1, "Resync must carry rolled-back viewport_revision=1");
        let resync_ed_rev = match resync_snap.root.as_ref().unwrap().find(1).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::Editor(e) => e.revision,
            _ => unreachable!(),
        };
        assert_eq!(resync_ed_rev, 3, "EditorChanged must stay intact");

        // Worker replies to Resync with genuine Snapshot at vp_rev=1, ed_rev=3, ["B", "A"] -> ACCEPTED!
        let confirmed_rev = stale_rev + 1;
        let mut confirmed_snap = Envelope::new(
            running.identity,
            3,
            confirmed_rev,
            envelope::Body::Snapshot(make_snap(confirmed_rev, 3, b"host-ed-3", 1, 0, ["B", "A"])),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        confirmed_snap.in_reply_to = resync_req_id;
        running.frame(confirmed_snap, &outgoing).await.unwrap();
        let mut ec_ack = Envelope::new(
            running.identity,
            4,
            confirmed_rev,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        ec_ack.in_reply_to = ec_req_id;
        running.frame(ec_ack, &outgoing).await.unwrap();
        assert!(running.requests.is_empty());
        assert!(!running.is_panel_semantic_drifted(target_panel));
        assert!(!running.is_panel_resyncing(target_panel));
        while updates.try_recv().is_ok() {}

        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.requests.len(), 1);

        running.prepare_shutdown(&outgoing);
        io_cancel.cancel();
        io_tasks.abort_all();
    }
}

#[tokio::test]
async fn commit_and_commit_response_reject_when_panel_options_change_across_deferral_inflight_or_ui_lag()
{
    let make_snap = |rev: u64, ed_rev: u64, ed_bytes: &[u8], opts: [&str; 2]| PanelSnapshot {
        revision: rev,
        title: "commit-sem".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: ed_bytes.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Mode".into(),
                            options: vec![opts[0].into(), opts[1].into()],
                            selected_index: 0,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };
    let make_resp = || mio_plugin_api::HttpResponse {
        status: 200,
        version: mio_plugin_api::HttpVersion::Http11,
        reason_phrase: Some("OK".into()),
        headers: vec![],
        body: b"resp".to_vec(),
        trailers: vec![],
    };

    // Subcase A: Deferred Commit + CommitResponse across a confirming Snapshot that reorders Select
    // options (["A", "B"] -> ["B", "A"]) without changing resource or editor revision MUST fail!
    {
        let (mut running, _calls, _updates) = running();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let res = Uuid::new_v4();
        running.broker.bind_resource(res, 1, false).unwrap();
        running.active_resource = Some((res, 1));
        running.panel = PanelState::new(make_snap(1, 1, b"init", ["A", "B"])).unwrap();

        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync = wire.try_recv().unwrap();

        let (def_cm_tx, mut def_cm_rx) = oneshot::channel();
        running
            .control_with_seq(
                1,
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: def_cm_tx,
                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let (def_rcm_tx, mut def_rcm_rx) = oneshot::channel();
        running
            .control_with_seq(
                2,
                Control::CommitResponse {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: protocol::CommitResponseEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        response: Some(make_resp().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: def_rcm_tx,
                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.main_deferred_commands.len(), 2);

        // Worker confirms Resync with Snapshot(rev=2) that keeps ed_rev=1/"init" & resource rev=1,
        // ONLY changing Select options ["A", "B"] -> ["B", "A"]!
        let mut changed_opts_snap = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 1, b"init", ["B", "A"])),
            MAX_OPERATION,
        );
        changed_opts_snap.in_reply_to = resync.request_id;
        running.frame(changed_opts_snap, &outgoing).await.unwrap();

        assert!(def_cm_rx.try_recv().unwrap().is_err());
        assert!(def_rcm_rx.try_recv().unwrap().is_err());
        assert!(wire.try_recv().is_err());
    }

    // Subcase B: In-flight Commit + CommitResponse fail if concurrent Snapshot changes options before
    // Committed / ResponseCommitted arrives (even at matching latest envelope.revision == host_rev).
    {
        let (mut running, _calls, _updates) = running();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let res = Uuid::new_v4();
        running.broker.bind_resource(res, 1, false).unwrap();
        running.active_resource = Some((res, 1));
        running.panel = PanelState::new(make_snap(1, 1, b"init", ["A", "B"])).unwrap();

        let (cm_tx, mut cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: cm_tx,
                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let cm_wire = wire.try_recv().unwrap();

        let (rcm_tx, mut rcm_rx) = oneshot::channel();
        running
            .control(
                Control::CommitResponse {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: protocol::CommitResponseEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        response: Some(make_resp().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: rcm_tx,
                    expected_snapshot: None,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let rcm_wire = wire.try_recv().unwrap();

        // Unsolicited Snapshot rev=2 reorders Select options without touching resource or editor!
        running
            .frame(
                Envelope::new(
                    running.identity,
                    1,
                    2,
                    envelope::Body::Snapshot(make_snap(2, 1, b"init", ["B", "A"])),
                    MAX_OPERATION,
                ),
                &outgoing,
            )
            .await
            .unwrap();

        let mut cm_reply = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Committed(protocol::Committed {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        );
        cm_reply.in_reply_to = cm_wire.request_id;
        running.frame(cm_reply, &outgoing).await.unwrap();
        assert!(cm_rx.try_recv().unwrap().is_err());

        let mut rcm_reply = Envelope::new(
            running.identity,
            3,
            2,
            envelope::Body::ResponseCommitted(protocol::ResponseCommitted {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 1,
                response: Some(make_resp().into()),
            }),
            MAX_OPERATION,
        );
        rcm_reply.in_reply_to = rcm_wire.request_id;
        running.frame(rcm_reply, &outgoing).await.unwrap();
        assert!(rcm_rx.try_recv().unwrap().is_err());
    }

    // Subcase C: Positive control (confirming only committed Editor's own update lets Commit pass)
    // AND UI-lag protection (explicit older expected_snapshot rejects stale Commit).
    {
        let (mut running, _calls, _updates) = running();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let res = Uuid::new_v4();
        running.broker.bind_resource(res, 1, false).unwrap();
        running.active_resource = Some((res, 1));
        let snap1 = Arc::new(make_snap(1, 1, b"init", ["A", "B"]));
        running.panel = PanelState::new((*snap1).clone()).unwrap();

        // Confirming Snapshot rev=2 updates ONLY the committed Editor to (ed_rev=2, b"typed")
        // while Select options stay identical -> Commit captured at snap1 MUST succeed!
        running
            .frame(
                Envelope::new(
                    running.identity,
                    1,
                    2,
                    envelope::Body::Snapshot(make_snap(2, 2, b"typed", ["A", "B"])),
                    MAX_OPERATION,
                ),
                &outgoing,
            )
            .await
            .unwrap();
        let (ok_cm_tx, ok_cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 2,
                            contents: b"typed".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: ok_cm_tx,
                    expected_snapshot: Some(snap1.clone()),
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ok_cm_wire = wire.try_recv().unwrap();
        let mut ok_cm_reply = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Committed(protocol::Committed {
                resource_id: res.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 2,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        );
        ok_cm_reply.in_reply_to = ok_cm_wire.request_id;
        running.frame(ok_cm_reply, &outgoing).await.unwrap();
        assert_eq!(ok_cm_rx.await.unwrap().unwrap().url, request().url);

        // UI lag: Snapshot rev=3 changes Select options ["A", "B"] -> ["B", "A"];
        // Commit stamped with older snap1 MUST be rejected immediately!
        running
            .frame(
                Envelope::new(
                    running.identity,
                    3,
                    3,
                    envelope::Body::Snapshot(make_snap(3, 2, b"typed", ["B", "A"])),
                    MAX_OPERATION,
                ),
                &outgoing,
            )
            .await
            .unwrap();
        let (lag_cm_tx, mut lag_cm_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: protocol::PANEL_ID,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 2,
                            contents: b"typed".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: lag_cm_tx,
                    expected_snapshot: Some(snap1),
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert!(lag_cm_rx.try_recv().unwrap().is_err());
        assert!(wire.try_recv().is_err());
    }
}

#[tokio::test]
async fn same_revision_optimistic_option_change_rejects_stale_deferred_new_and_inflight_commits() {
    let make_snap = |rev: u64, ed_rev: u64, checked: bool, selected_index: u32| PanelSnapshot {
        revision: rev,
        title: "same-rev-commit".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: b"init".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        2,
                        "chk",
                        panel::node::Kind::Checkbox(panel::CheckboxNode {
                            label: "Sign".into(),
                            checked,
                            enabled: true,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Mode".into(),
                            options: vec!["A".into(), "B".into()],
                            selected_index,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };
    let make_resp = || mio_plugin_api::HttpResponse {
        status: 200,
        version: mio_plugin_api::HttpVersion::Http11,
        reason_phrase: Some("OK".into()),
        headers: vec![],
        body: b"resp".to_vec(),
        trailers: vec![],
    };

    let (mut running, _calls, _updates) = running();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let res = Uuid::new_v4();
    running.broker.bind_resource(res, 1, false).unwrap();
    running.active_resource = Some((res, 1));
    let snap_old = Arc::new(make_snap(1, 1, false, 0));
    running.panel = PanelState::new((*snap_old).clone()).unwrap();

    // Subcase A: Within the SAME panel revision (rev=1), optimistic Toggled(true) changes UI options
    // without incrementing panel.revision -> older snap_old Commit & CommitResponse MUST reject!
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 2,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Toggled(true)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let _toggle_wire = wire.try_recv().unwrap();
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 1);

    let (stale_cm_tx, mut stale_cm_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: protocol::PANEL_ID,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: stale_cm_tx,
                expected_snapshot: Some(snap_old.clone()),
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(stale_cm_rx.try_recv().unwrap().is_err());

    let (stale_rcm_tx, mut stale_rcm_rx) = oneshot::channel();
    running
        .control(
            Control::CommitResponse {
                panel_id: protocol::PANEL_ID,
                op_id: Uuid::new_v4(),
                request: protocol::CommitResponseEditor {
                    resource_id: res.as_bytes().to_vec(),
                    message_revision: 1,
                    response: Some(make_resp().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: stale_rcm_tx,
                expected_snapshot: Some(snap_old),
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(stale_rcm_rx.try_recv().unwrap().is_err());
    assert!(wire.try_recv().is_err());

    // Subcase B: Fresh Commit & CommitResponse at current (checked=true, selected=0, rev=1),
    // then same-revision SelectedOption(1) occurs while both are in flight -> replies at rev=1 MUST reject!
    let (cm_tx, mut cm_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: protocol::PANEL_ID,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: cm_tx,
                expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let cm_wire = wire.try_recv().unwrap();

    let (rcm_tx, mut rcm_rx) = oneshot::channel();
    running
        .control(
            Control::CommitResponse {
                panel_id: protocol::PANEL_ID,
                op_id: Uuid::new_v4(),
                request: protocol::CommitResponseEditor {
                    resource_id: res.as_bytes().to_vec(),
                    message_revision: 1,
                    response: Some(make_resp().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: rcm_tx,
                expected_snapshot: None,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let rcm_wire = wire.try_recv().unwrap();

    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(1)),
                },
                event_seq: 0,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let _select_wire = wire.try_recv().unwrap();
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 1);

    let mut cm_reply = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Committed(protocol::Committed {
            resource_id: res.as_bytes().to_vec(),
            message_revision: 1,
            document_id: 1,
            document_revision: 1,
            request: Some(request().into()),
        }),
        MAX_OPERATION,
    );
    cm_reply.in_reply_to = cm_wire.request_id;
    running.frame(cm_reply, &outgoing).await.unwrap();
    assert!(cm_rx.try_recv().unwrap().is_err());

    let mut rcm_reply = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::ResponseCommitted(protocol::ResponseCommitted {
            resource_id: res.as_bytes().to_vec(),
            message_revision: 1,
            document_id: 1,
            document_revision: 1,
            response: Some(make_resp().into()),
        }),
        MAX_OPERATION,
    );
    rcm_reply.in_reply_to = rcm_wire.request_id;
    running.frame(rcm_reply, &outgoing).await.unwrap();
    assert!(rcm_rx.try_recv().unwrap().is_err());
}

#[tokio::test]
async fn non_lifo_and_split_timeout_child_viewport_retractions_restore_true_base_watermark() {
    let make_snap = |rev: u64, vp_rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("vp-order-{rev}"),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![panel::Node::new(
                    2,
                    "tbl",
                    panel::node::Kind::VirtualTable(panel::VirtualTable {
                        columns: vec![panel::TableColumn {
                            id: "c1".into(),
                            title: "Col".into(),
                            width: 80.0,
                        }],
                        total_rows: 10,
                        offset: 0,
                        viewport_revision: vp_rev,
                        rows: vec![],
                        multi_select: false,
                    }),
                )],
            }),
        )),
    };
    let read_vp = |snap: &PanelSnapshot| -> u64 {
        match snap.root.as_ref().unwrap().find(2).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            other => panic!("expected VirtualTable, got {other:?}"),
        }
    };
    let vp_event = |vp_rev: u64| Control::Event {
        panel_id: 2,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                revision: vp_rev,
                offset: 0,
                limit: 5,
            })),
        },
        event_seq: 0,
    };

    // Subcase A: Same handle_timeouts batch expires unclaimed Viewport(2) then Viewport(3) in ascending order.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, o_w.request_id));
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        running.control(vp_event(2), &outgoing).await.unwrap();
        let vp2 = wire.try_recv().unwrap();
        running.control(vp_event(3), &outgoing).await.unwrap();
        let vp3 = wire.try_recv().unwrap();
        assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 3);

        running.requests.get_mut(&vp2.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(2);
        running.requests.get_mut(&vp3.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();

        assert_eq!(
            read_vp(&running.panel_snapshot(2).unwrap()),
            1,
            "ascending retraction of Viewport(2) then Viewport(3) must unwind back to 1"
        );
        let resync = wire.try_recv().unwrap();
        assert!(matches!(
            resync.body,
            Some(envelope::Body::Resync(ref s)) if read_vp(s) == 1
        ));
        assert!(wire.try_recv().is_err());
        assert!(!claims.claim_for_write(2, vp2.request_id));
        assert!(!claims.claim_for_write(2, vp3.request_id));
        assert!(claims.claim_for_write(2, resync.request_id));

        let mut ok_snap = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Snapshot(make_snap(2, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        ok_snap.in_reply_to = resync.request_id;
        running.frame(ok_snap, &outgoing).await.unwrap();
        assert!(!running.is_panel_resyncing(2));
    }

    // Subcase B1: Two separate timeout batches retract Viewport(2) first, then Viewport(3) second.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, o_w.request_id));
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        running.control(vp_event(2), &outgoing).await.unwrap();
        let vp2 = wire.try_recv().unwrap();
        running.control(vp_event(3), &outgoing).await.unwrap();
        let vp3 = wire.try_recv().unwrap();

        running.requests.get_mut(&vp2.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 3);
        let resync1 = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, resync1.request_id));

        running.requests.get_mut(&vp3.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        assert_eq!(
            read_vp(&running.panel_snapshot(2).unwrap()),
            1,
            "second timeout retracting Viewport(3) must restore true base watermark 1"
        );

        let mut stale_snap = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Snapshot(make_snap(2, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        stale_snap.in_reply_to = resync1.request_id;
        running.frame(stale_snap, &outgoing).await.unwrap();
        assert!(running.is_panel_semantic_drifted(2));
        let resync2 = wire.try_recv().unwrap();
        assert!(matches!(
            resync2.body,
            Some(envelope::Body::Resync(ref s)) if read_vp(s) == 1
        ));

        let mut ok_snap = Envelope::new(
            running.identity,
            3,
            2,
            envelope::Body::Snapshot(make_snap(2, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        ok_snap.in_reply_to = resync2.request_id;
        running.frame(ok_snap, &outgoing).await.unwrap();
        assert!(!running.is_panel_semantic_drifted(2));
        assert_eq!(running.panel_revision(2), 2);
    }

    // Subcase B2: Claimed Viewport(2) + unclaimed Viewport(3) & Viewport(4) split across two batches
    // MUST preserve claimed watermark 2.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, o_w.request_id));
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        running.control(vp_event(2), &outgoing).await.unwrap();
        let vp2 = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, vp2.request_id));
        running.control(vp_event(3), &outgoing).await.unwrap();
        let vp3 = wire.try_recv().unwrap();
        running.control(vp_event(4), &outgoing).await.unwrap();
        let vp4 = wire.try_recv().unwrap();
        assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 4);

        running.requests.get_mut(&vp3.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 4);
        let resync1 = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, resync1.request_id));

        running.requests.get_mut(&vp4.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        assert_eq!(
            read_vp(&running.panel_snapshot(2).unwrap()),
            2,
            "claimed Viewport(2) base must be preserved after retracting Viewport(3) and Viewport(4)"
        );

        let mut stale_snap = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Snapshot(make_snap(2, 2)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        stale_snap.in_reply_to = resync1.request_id;
        running.frame(stale_snap, &outgoing).await.unwrap();
        assert!(running.is_panel_semantic_drifted(2));
        let resync2 = wire.try_recv().unwrap();
        assert!(matches!(
            resync2.body,
            Some(envelope::Body::Resync(ref s)) if read_vp(s) == 2
        ));

        let mut ok_snap = Envelope::new(
            running.identity,
            3,
            2,
            envelope::Body::Snapshot(make_snap(2, 2)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        ok_snap.in_reply_to = resync2.request_id;
        running.frame(ok_snap, &outgoing).await.unwrap();
        assert!(!running.is_panel_semantic_drifted(2));
        assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 2);
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn unrelated_patch_advancing_panel_revision_preserves_unclaimed_viewport_rollback_on_drift()
{
    let make_snap = |rev: u64, ed_rev: u64, ed_bytes: &[u8], vp_rev: u64, opts: [&str; 2]| {
        PanelSnapshot {
            revision: rev,
            title: "patch-vp-rollback".into(),
            root: Some(panel::Node::new(
                10,
                "col",
                panel::node::Kind::Column(panel::Container {
                    children: vec![
                        panel::Node::new(
                            1,
                            "ed",
                            panel::node::Kind::Editor(panel::Editor {
                                document_id: 1,
                                revision: ed_rev,
                                contents: ed_bytes.to_vec(),
                                format: panel::EditorFormat::Utf8 as i32,
                                read_only: false,
                            }),
                        ),
                        panel::Node::new(
                            2,
                            "tbl",
                            panel::node::Kind::VirtualTable(panel::VirtualTable {
                                columns: vec![panel::TableColumn {
                                    id: "c1".into(),
                                    title: "Col".into(),
                                    width: 80.0,
                                }],
                                total_rows: 10,
                                offset: 0,
                                viewport_revision: vp_rev,
                                rows: vec![],
                                multi_select: false,
                            }),
                        ),
                        panel::Node::new(
                            3,
                            "select",
                            panel::node::Kind::Select(panel::SelectNode {
                                label: "Choice".into(),
                                options: vec![opts[0].into(), opts[1].into()],
                                selected_index: 0,
                                enabled: true,
                            }),
                        ),
                    ],
                }),
            )),
        }
    };
    let read_vp = |snap: &PanelSnapshot| -> u64 {
        match snap.root.as_ref().unwrap().find(2).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            other => panic!("expected VirtualTable, got {other:?}"),
        }
    };

    for target_panel in [protocol::PANEL_ID, 2u64] {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        claims.set_stop_cancel(running.cancel.clone());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, writes) = mpsc::channel(OUTGOING_CAPACITY);
        let (wire, _incoming) = mpsc::channel(QUEUE_CAPACITY);
        let (wp_tx, _wp_rx) = tokio::sync::watch::channel(0u64);
        let io_cancel = CancellationToken::new();
        let mut io_tasks = JoinSet::new();

        let (host_to_worker, mut worker_rx) = tokio::io::duplex(256);
        let (_worker_tx, worker_to_host) = tokio::io::duplex(64 * 1024);
        Running::spawn_stream_io(
            host_to_worker,
            worker_to_host,
            writes,
            &wire,
            claims,
            wp_tx,
            &io_cancel,
            &mut io_tasks,
        );

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: target_panel,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_env = timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
            .await
            .unwrap()
            .unwrap();
        let init_rev = if target_panel == protocol::PANEL_ID { 2 } else { 1 };
        let mut o_snap = Envelope::new(
            running.identity,
            1,
            init_rev,
            envelope::Body::Snapshot(make_snap(init_rev, 1, b"retained", 1, ["A", "B"])),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        o_snap.in_reply_to = o_env.request_id;
        running.frame(o_snap, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        // Event A & Event B both claimed onto duplex pipe.
        let mut focus_envs = Vec::new();
        for _ in 0..2 {
            running
                .control(
                    Control::Event {
                        panel_id: target_panel,
                        expected_snapshot: None,
                        event: UiEvent {
                            node_id: 1,
                            editors: vec![],
                            event: Some(panel::ui_event::Event::Focus(true)),
                        },
                        event_seq: 0,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            focus_envs.push(
                timeout(MAX_OPERATION, read_async_frame(&mut worker_rx))
                    .await
                    .unwrap()
                    .unwrap(),
            );
        }
        let ev_a = &focus_envs[0];
        let ev_b = &focus_envs[1];

        // Backpressure duplex writer, then enqueue unclaimed Viewport(2) at init_rev.
        for s in 1..=24u64 {
            running
                .send(
                    &outgoing,
                    envelope::Body::HostResult(HostResult {
                        outcome: Some(host_result::Outcome::Done(panel::Empty {})),
                    }),
                    s,
                )
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(15)).await;

        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                            revision: 2,
                            offset: 0,
                            limit: 5,
                        })),
                    },
                    event_seq: 0,
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(read_vp(&running.panel_snapshot(target_panel).unwrap()), 2);

        // Event A replies with a legitimate unrelated Patch updating ONLY Editor(node=1 -> rev=2)
        // and advancing panel.revision from `init_rev` -> `init_rev + 1`!
        let patch_rev = init_rev + 1;
        let mut ed_patch = Envelope::new(
            running.identity,
            2,
            patch_rev,
            envelope::Body::Patch(panel::PanelPatch {
                base_revision: init_rev,
                revision: patch_rev,
                operations: vec![panel::PatchOperation {
                    node_id: 1,
                    change: Some(panel::patch_operation::Change::Editor(
                        panel::EditorUpdate {
                            base_revision: 1,
                            snapshot: Some(EditorSnapshot {
                                document_id: 1,
                                revision: 2,
                                contents: b"patched-ed".to_vec(),
                                selection_start: 0,
                                selection_end: 0,
                            }),
                        },
                    )),
                }],
            }),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        ed_patch.in_reply_to = ev_a.request_id;
        running.frame(ed_patch, &outgoing).await.unwrap();
        assert_eq!(running.panel_revision(target_panel), patch_rev);
        assert_eq!(read_vp(&running.panel_snapshot(target_panel).unwrap()), 2);

        // Event B replies with reordered Snapshot carrying stale editor_rev=1 -> rejected -> marks drift!
        // Unclaimed Viewport(2) MUST STILL roll back to 1 across the unrelated Patch!
        let stale_rev = patch_rev + 1;
        let mut stale_snap = Envelope::new(
            running.identity,
            3,
            stale_rev,
            envelope::Body::Snapshot(make_snap(stale_rev, 1, b"stale-ed", 1, ["B", "A"])),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        stale_snap.in_reply_to = ev_b.request_id;
        running.frame(stale_snap, &outgoing).await.unwrap();

        assert_eq!(
            read_vp(&running.panel_snapshot(target_panel).unwrap()),
            1,
            "unclaimed Viewport(2) must roll back to 1 even after unrelated Editor Patch bumped panel revision"
        );

        let reader_task = tokio::spawn(async move {
            loop {
                let env = read_async_frame(&mut worker_rx).await.unwrap();
                match env.body {
                    Some(envelope::Body::HostResult(_)) => {}
                    Some(envelope::Body::Resync(resync_snap)) => return (env.request_id, resync_snap),
                    Some(other) => panic!("retracted Viewport(2) leaked on wire: {other:?}"),
                    None => {}
                }
            }
        });
        let (resync_req_id, resync_snap) =
            timeout(MAX_OPERATION, reader_task).await.unwrap().unwrap();
        assert_eq!(read_vp(&resync_snap), 1);

        let confirmed_rev = stale_rev + 1;
        let mut confirmed_snap = Envelope::new(
            running.identity,
            4,
            confirmed_rev,
            envelope::Body::Snapshot(make_snap(
                confirmed_rev,
                2,
                b"patched-ed",
                1,
                ["B", "A"],
            )),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        confirmed_snap.in_reply_to = resync_req_id;
        running.frame(confirmed_snap, &outgoing).await.unwrap();
        assert!(!running.is_panel_semantic_drifted(target_panel));
        assert!(!running.is_panel_resyncing(target_panel));
        while updates.try_recv().is_ok() {}

        running.prepare_shutdown(&outgoing);
        io_cancel.cancel();
        io_tasks.abort_all();
    }
}

#[tokio::test]
async fn repeated_same_value_optimistic_selected_option_retracting_unclaimed_first_stays_settled_at_second()
{
    let make_snap = |rev: u64, ed_rev: u64, ed_bytes: &[u8], selected: u32| PanelSnapshot {
        revision: rev,
        title: "same-value-select".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: ed_bytes.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec!["A".into(), "B".into()],
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };
    let read_selected = |snap: &PanelSnapshot| -> u32 {
        match snap.root.as_ref().unwrap().find(3).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::Select(s) => s.selected_index,
            other => panic!("expected Select, got {other:?}"),
        }
    };

    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let child_res = Uuid::new_v4();
    let (o_tx, o_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: child_res,
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let o_w = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, o_w.request_id));
    let mut o_s = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, 1, b"init", 0)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    o_s.in_reply_to = o_w.request_id;
    running.frame(o_s, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();
    while updates.try_recv().is_ok() {}

    let select_b = || Control::Event {
        panel_id: 2,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 3,
            editors: vec![],
            event: Some(panel::ui_event::Event::SelectedOption(1)),
        },
        event_seq: 0,
    };
    running.control(select_b(), &outgoing).await.unwrap();
    let sel1 = wire.try_recv().unwrap();
    // Leave sel1 UNCLAIMED; claim sel2.
    running.control(select_b(), &outgoing).await.unwrap();
    let sel2 = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, sel2.request_id));
    assert_eq!(read_selected(&running.panel_snapshot(2).unwrap()), 1);

    // Expire unclaimed sel1 -> retracted without rolling back to 0 because sel2 is still pending.
    running.requests.get_mut(&sel1.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    assert_eq!(
        read_selected(&running.panel_snapshot(2).unwrap()),
        1,
        "retracting unclaimed duplicate #1 must keep #2's optimistic value 1"
    );
    let resync1 = wire.try_recv().unwrap();

    // Worker ran sel2 (rev=1) and confirmed non-drifted resync1 with Ack(rev=1).
    let mut ack2 = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    ack2.in_reply_to = sel2.request_id;
    running.frame(ack2, &outgoing).await.unwrap();
    assert_eq!(read_selected(&running.panel_snapshot(2).unwrap()), 1);

    let mut resync_ack = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    resync_ack.in_reply_to = resync1.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();
    assert!(!running.is_panel_resyncing(2));

    let mut saw_synced_1 = false;
    while let Ok(ev) = updates.try_recv() {
        if let PluginEvent::PanelSynced { panel_id: 2, snapshot, .. } = ev {
            assert_eq!(read_selected(&snapshot), 1);
            saw_synced_1 = true;
        }
    }
    assert!(saw_synced_1, "settling sel2 via bare Ack must emit PanelSynced(1)");

    // CommitEditor expecting old Select=0 MUST reject, while Select=1 MUST succeed.
    let (stale_tx, mut stale_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: child_res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: stale_tx,
                expected_snapshot: Some(Arc::new(make_snap(1, 1, b"init", 0))),
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(stale_rx.try_recv().unwrap().is_err());
    assert!(wire.try_recv().is_err());

    let (ok_tx, ok_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: child_res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: ok_tx,
                expected_snapshot: Some(Arc::new(make_snap(1, 1, b"init", 1))),
            },
            &outgoing,
        )
        .await
        .unwrap();
    let cm_wire = wire.try_recv().unwrap();
    let mut cm_reply = Envelope::new(
        running.identity,
        4,
        1,
        envelope::Body::Committed(protocol::Committed {
            resource_id: child_res.as_bytes().to_vec(),
            message_revision: 1,
            document_id: 1,
            document_revision: 1,
            request: Some(request().into()),
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    cm_reply.in_reply_to = cm_wire.request_id;
    running.frame(cm_reply, &outgoing).await.unwrap();
    assert!(ok_rx.await.unwrap().is_ok());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn sdk_deadline_error_and_late_deadline_retract_optimistic_viewport_and_sync_ui() {
    let make_snap = |rev: u64, vp_rev: u64| PanelSnapshot {
        revision: rev,
        title: format!("vp-deadline-{rev}"),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"retained".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        2,
                        "tbl",
                        panel::node::Kind::VirtualTable(panel::VirtualTable {
                            columns: vec![panel::TableColumn {
                                id: "c1".into(),
                                title: "Col".into(),
                                width: 80.0,
                            }],
                            total_rows: 10,
                            offset: 0,
                            viewport_revision: vp_rev,
                            rows: vec![],
                            multi_select: false,
                        }),
                    ),
                ],
            }),
        )),
    };
    let read_vp = |snap: &PanelSnapshot| -> u64 {
        match snap.root.as_ref().unwrap().find(2).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            other => panic!("expected VirtualTable, got {other:?}"),
        }
    };
    let vp_event = |panel_id: u64, vp_rev: u64| Control::Event {
        panel_id,
        expected_snapshot: None,
        event: UiEvent {
            node_id: 2,
            editors: vec![],
            event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                revision: vp_rev,
                offset: 5,
                limit: 5,
            })),
        },
        event_seq: 0,
    };

    // Subtest 1: Timely Error(Deadline) on main & child panels retracts Viewport(2) -> 1, emits PanelSynced(1),
    // and accepts subsequent Snapshot(rev=2, vp=1).
    for target_panel in [protocol::PANEL_ID, 2u64] {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        running.panel = PanelState::new(make_snap(1, 1)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        if target_panel != protocol::PANEL_ID {
            let (o_tx, o_rx) = oneshot::channel();
            running
                .control(
                    Control::Open {
                        panel_id: target_panel,
                        id: Uuid::new_v4(),
                        revision: 1,
                        read_only: false,
                        request: request(),
                        reply: o_tx,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            let o_w = wire.try_recv().unwrap();
            let mut o_s = Envelope::new(
                running.identity,
                1,
                1,
                envelope::Body::Snapshot(make_snap(1, 1)),
                MAX_OPERATION,
            )
            .with_panel_id(target_panel);
            o_s.in_reply_to = o_w.request_id;
            running.frame(o_s, &outgoing).await.unwrap();
            o_rx.await.unwrap().unwrap();
        }
        while updates.try_recv().is_ok() {}

        running.control(vp_event(target_panel, 2), &outgoing).await.unwrap();
        let vp_w = wire.try_recv().unwrap();
        assert_eq!(read_vp(&running.panel_snapshot(target_panel).unwrap()), 2);

        let mut err_env = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "过期未执行")),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        err_env.in_reply_to = vp_w.request_id;
        running.frame(err_env, &outgoing).await.unwrap();

        assert_eq!(
            read_vp(&running.panel_snapshot(target_panel).unwrap()),
            1,
            "timely Error(Deadline) must roll back Viewport(2) -> 1"
        );
        assert!(matches!(updates.try_recv(), Ok(PluginEvent::Error { panel_id, .. }) if panel_id == target_panel));
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::PanelSynced { panel_id, ref snapshot, .. })
                if panel_id == target_panel && read_vp(snapshot) == 1
        ));

        running
            .frame(
                Envelope::new(
                    running.identity,
                    3,
                    2,
                    envelope::Body::Snapshot(make_snap(2, 1)),
                    MAX_OPERATION,
                )
                .with_panel_id(target_panel),
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(read_vp(&running.panel_snapshot(target_panel).unwrap()), 1);
        assert_eq!(running.panel_revision(target_panel), 2);
    }

    // Subtest 2: Expired-in-frame child Error(Deadline) arriving BEFORE handle_timeouts retracts vp -> 1,
    // sends Resync carrying vp=1, emits PanelSynced(1), and accepts Snapshot(rev=2, vp=1).
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();
        while updates.try_recv().is_ok() {}

        running.control(vp_event(2, 2), &outgoing).await.unwrap();
        let vp_w = wire.try_recv().unwrap();
        running.requests.get_mut(&vp_w.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);

        let mut expired_err = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "过期未执行")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        expired_err.in_reply_to = vp_w.request_id;
        running.frame(expired_err, &outgoing).await.unwrap();

        assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 1);
        let _cancel_w = wire.try_recv().unwrap();
        let resync_w = wire.try_recv().unwrap();
        assert!(matches!(
            resync_w.body,
            Some(envelope::Body::Resync(ref s)) if read_vp(s) == 1
        ));
        let mut saw_synced = false;
        while let Ok(ev) = updates.try_recv() {
            if let PluginEvent::PanelSynced { panel_id: 2, snapshot, .. } = ev {
                assert_eq!(read_vp(&snapshot), 1);
                saw_synced = true;
            }
        }
        assert!(saw_synced);

        let mut snap2 = Envelope::new(
            running.identity,
            3,
            2,
            envelope::Body::Snapshot(make_snap(2, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        snap2.in_reply_to = resync_w.request_id;
        running.frame(snap2, &outgoing).await.unwrap();
        assert!(!running.is_panel_resyncing(2));
        assert_eq!(running.panel_revision(2), 2);
    }

    // Subtest 3: Timer fires FIRST on claimed child Viewport(2), THEN late same-revision Error(Deadline) arrives.
    // Part A: With Snapshot(rev=2, vp=1) recovery; Part B: With bare Ack(rev=1) latching semantic drift.
    for reply_with_snapshot in [true, false] {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, o_w.request_id));
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();
        while updates.try_recv().is_ok() {}

        running.control(vp_event(2, 2), &outgoing).await.unwrap();
        let vp_w = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, vp_w.request_id));
        assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 2);

        // Timer fires FIRST -> ledger preserves (vp_w.request_id, 2) & base 1; Cancel + Resync sent.
        running.requests.get_mut(&vp_w.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        let cancel_w = wire.try_recv().unwrap();
        let resync_w = wire.try_recv().unwrap();
        assert!(matches!(cancel_w.body, Some(envelope::Body::Cancel(_))));
        assert!(matches!(resync_w.body, Some(envelope::Body::Resync(_))));
        while updates.try_recv().is_ok() {}

        // Late same-revision Error(Deadline) from SDK -> MUST retract vp 2 -> 1 and emit PanelSynced(1).
        let mut late_deadline = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "子面板请求已超时")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        late_deadline.in_reply_to = vp_w.request_id;
        running.frame(late_deadline, &outgoing).await.unwrap();
        assert_eq!(
            read_vp(&running.panel_snapshot(2).unwrap()),
            1,
            "late same-revision Error(Deadline) after timer must still roll back vp 2 -> 1"
        );
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Error { panel_id: 2, ref failure, .. })
                if failure.code == ErrorCode::Stale as i32
        ));
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::PanelSynced { panel_id: 2, ref snapshot, .. })
                if read_vp(snapshot) == 1
        ));

        let mut seq = 3u64;
        let mut cancel_ack = Envelope::new(
            running.identity,
            seq,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        seq += 1;
        cancel_ack.in_reply_to = cancel_w.request_id;
        running.frame(cancel_ack, &outgoing).await.unwrap();

        if reply_with_snapshot {
            // Worker echoes Resync #1's stale vp=2 Snapshot -> MUST be superseded, sending Resync #2 with vp=1!
            let mut echoed_stale = Envelope::new(
                running.identity,
                seq,
                2,
                envelope::Body::Snapshot(make_snap(2, 2)),
                MAX_OPERATION,
            )
            .with_panel_id(2);
            seq += 1;
            echoed_stale.in_reply_to = resync_w.request_id;
            running.frame(echoed_stale, &outgoing).await.unwrap();
            assert!(running.is_panel_semantic_drifted(2));
            assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 1);

            let resync2 = wire.try_recv().unwrap();
            assert!(matches!(
                resync2.body,
                Some(envelope::Body::Resync(ref s)) if read_vp(s) == 1
            ));

            let mut snap3 = Envelope::new(
                running.identity,
                seq,
                3,
                envelope::Body::Snapshot(make_snap(3, 1)),
                MAX_OPERATION,
            )
            .with_panel_id(2);
            snap3.in_reply_to = resync2.request_id;
            running.frame(snap3, &outgoing).await.unwrap();
            assert!(!running.is_panel_semantic_drifted(2));
            assert!(!running.is_panel_resyncing(2));
            assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 1);
            assert_eq!(running.panel_revision(2), 3);
        } else {
            let mut bare_ack = Envelope::new(
                running.identity,
                seq,
                1,
                envelope::Body::Ack(panel::Empty {}),
                MAX_OPERATION,
            )
            .with_panel_id(2);
            seq += 1;
            bare_ack.in_reply_to = resync_w.request_id;
            running.frame(bare_ack, &outgoing).await.unwrap();
            assert!(
                running.is_panel_semantic_drifted(2),
                "bare Ack to pre-retraction Resync must keep semantic drift latched"
            );
            let resync2 = wire.try_recv().unwrap();
            assert!(matches!(
                resync2.body,
                Some(envelope::Body::Resync(ref s)) if read_vp(s) == 1
            ));
            let mut bare_ack2 = Envelope::new(
                running.identity,
                seq,
                1,
                envelope::Body::Ack(panel::Empty {}),
                MAX_OPERATION,
            )
            .with_panel_id(2);
            bare_ack2.in_reply_to = resync2.request_id;
            running.frame(bare_ack2, &outgoing).await.unwrap();
            assert!(
                running.is_panel_semantic_drifted(2),
                "bare Ack to second Resync must still keep semantic drift latched until full Snapshot"
            );
        }
    }
}

#[tokio::test]
async fn callback_error_on_optimistic_event_marks_drift_and_blocks_commit_until_snapshot() {
    let make_snap = |rev: u64, ed_rev: u64, ed_bytes: &[u8], selected: u32| PanelSnapshot {
        revision: rev,
        title: "cb-error-drift".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: ed_rev,
                            contents: ed_bytes.to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec!["A".into(), "B".into()],
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    for target_panel in [protocol::PANEL_ID, 2u64] {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        running.panel = PanelState::new(make_snap(1, 1, b"retained", 0)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let res_id = Uuid::new_v4();
        if target_panel == protocol::PANEL_ID {
            running.broker.bind_resource(res_id, 1, false).unwrap();
            running.active_resource = Some((res_id, 1));
        } else {
            let (o_tx, o_rx) = oneshot::channel();
            running
                .control(
                    Control::Open {
                        panel_id: 2,
                        id: res_id,
                        revision: 1,
                        read_only: false,
                        request: request(),
                        reply: o_tx,
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            let o_w = wire.try_recv().unwrap();
            let mut o_s = Envelope::new(
                running.identity,
                1,
                1,
                envelope::Body::Snapshot(make_snap(1, 1, b"retained", 0)),
                MAX_OPERATION,
            )
            .with_panel_id(2);
            o_s.in_reply_to = o_w.request_id;
            running.frame(o_s, &outgoing).await.unwrap();
            o_rx.await.unwrap().unwrap();
        }
        while updates.try_recv().is_ok() {}

        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(1)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_w = wire.try_recv().unwrap();

        // Worker callback mutated Select=1 and then returned Invalid Error at same rev=1.
        let mut cb_err = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Invalid, "callback failed after partial mutation")),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        cb_err.in_reply_to = ev_w.request_id;
        running.frame(cb_err, &outgoing).await.unwrap();

        assert!(
            running.is_panel_semantic_drifted(target_panel),
            "non-Deadline callback Error on optimistic event must mark semantic drift"
        );
        let resync_w = wire.try_recv().unwrap();
        assert!(matches!(resync_w.body, Some(envelope::Body::Resync(_))));

        // Commits submitted while Resync is in flight defer behind the barrier and MUST reject if Resync only ACKs.
        let mut deferred_rxs = Vec::new();
        for exp_sel in [0u32, 1u32] {
            let (cm_tx, mut cm_rx) = oneshot::channel();
            running
                .control(
                    Control::Commit {
                        panel_id: target_panel,
                        op_id: Uuid::new_v4(),
                        request: CommitEditor {
                            resource_id: res_id.as_bytes().to_vec(),
                            message_revision: 1,
                            request: Some(request().into()),
                            editor: Some(EditorSnapshot {
                                document_id: 1,
                                revision: 1,
                                contents: b"retained".to_vec(),
                                ..Default::default()
                            }),
                        },
                        cancelled: CancellationToken::new(),
                        reply: cm_tx,
                        expected_snapshot: Some(Arc::new(make_snap(1, 1, b"retained", exp_sel))),
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            assert!(matches!(cm_rx.try_recv(), Err(oneshot::error::TryRecvError::Empty)));
            deferred_rxs.push(cm_rx);
        }
        assert!(wire.try_recv().is_err());

        let mut bare_resync_ack = Envelope::new(
            running.identity,
            3,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        bare_resync_ack.in_reply_to = resync_w.request_id;
        running.frame(bare_resync_ack, &outgoing).await.unwrap();
        for mut rx in deferred_rxs {
            assert!(rx.try_recv().unwrap().is_err());
        }
        assert!(running.is_panel_semantic_drifted(target_panel));
        assert!(!running.is_panel_resyncing(target_panel));

        // Fresh Commits after Resync ended with bare Ack MUST still reject immediately while drifted!
        for exp_sel in [0u32, 1u32] {
            let (cm_tx, mut cm_rx) = oneshot::channel();
            running
                .control(
                    Control::Commit {
                        panel_id: target_panel,
                        op_id: Uuid::new_v4(),
                        request: CommitEditor {
                            resource_id: res_id.as_bytes().to_vec(),
                            message_revision: 1,
                            request: Some(request().into()),
                            editor: Some(EditorSnapshot {
                                document_id: 1,
                                revision: 1,
                                contents: b"retained".to_vec(),
                                ..Default::default()
                            }),
                        },
                        cancelled: CancellationToken::new(),
                        reply: cm_tx,
                        expected_snapshot: Some(Arc::new(make_snap(1, 1, b"retained", exp_sel))),
                    },
                    &outgoing,
                )
                .await
                .unwrap();
            assert!(cm_rx.try_recv().unwrap().is_err());
        }
        assert!(wire.try_recv().is_err());

        // EditorChanged -> confirming Snapshot(rev=2, B=1) clears drift and unlocks Commit(B=1).
        running
            .control(
                Control::Event {
                    panel_id: target_panel,
                    expected_snapshot: None,
                    event_seq: 2,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::EditorChanged(EditorSnapshot {
                            document_id: 1,
                            revision: 2,
                            contents: b"retained-2".to_vec(),
                            ..Default::default()
                        })),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ed_w = wire.try_recv().unwrap();
        let mut snap2 = Envelope::new(
            running.identity,
            4,
            2,
            envelope::Body::Snapshot(make_snap(2, 2, b"retained-2", 1)),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        snap2.in_reply_to = ed_w.request_id;
        running.frame(snap2, &outgoing).await.unwrap();
        assert!(!running.is_panel_semantic_drifted(target_panel));
        assert!(!running.is_panel_resyncing(target_panel));

        let (ok_tx, ok_rx) = oneshot::channel();
        running
            .control(
                Control::Commit {
                    panel_id: target_panel,
                    op_id: Uuid::new_v4(),
                    request: CommitEditor {
                        resource_id: res_id.as_bytes().to_vec(),
                        message_revision: 1,
                        request: Some(request().into()),
                        editor: Some(EditorSnapshot {
                            document_id: 1,
                            revision: 2,
                            contents: b"retained-2".to_vec(),
                            ..Default::default()
                        }),
                    },
                    cancelled: CancellationToken::new(),
                    reply: ok_tx,
                    expected_snapshot: Some(Arc::new(make_snap(2, 2, b"retained-2", 1))),
                },
                &outgoing,
            )
            .await
            .unwrap();
        let cm_w = wire.try_recv().unwrap();
        let mut cm_reply = Envelope::new(
            running.identity,
            5,
            2,
            envelope::Body::Committed(protocol::Committed {
                resource_id: res_id.as_bytes().to_vec(),
                message_revision: 1,
                document_id: 1,
                document_revision: 2,
                request: Some(request().into()),
            }),
            MAX_OPERATION,
        )
        .with_panel_id(target_panel);
        cm_reply.in_reply_to = cm_w.request_id;
        running.frame(cm_reply, &outgoing).await.unwrap();
        assert!(ok_rx.await.unwrap().is_ok());
    }

    // Late-after-timer Error(Invalid) on child panel MUST also mark semantic drift and schedule resync.
    {
        let (mut running, _calls, _updates) = running();
        running.supports_panel_multiplexing = true;
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, o_w.request_id));
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1, b"retained", 0)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();

        running
            .control(
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(1)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_w = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(2, ev_w.request_id));

        running.requests.get_mut(&ev_w.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        let _cancel_w = wire.try_recv().unwrap();
        let _resync1 = wire.try_recv().unwrap();
        assert!(!running.is_panel_semantic_drifted(2));

        let mut late_inv = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Invalid, "late callback error")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        late_inv.in_reply_to = ev_w.request_id;
        running.frame(late_inv, &outgoing).await.unwrap();
        assert!(running.is_panel_semantic_drifted(2));
    }
}

#[tokio::test]
async fn panel_synced_carries_monotonic_processed_ui_seq_excluding_deferred_events() {
    let make_snap = |rev: u64, selected: u32| PanelSnapshot {
        revision: rev,
        title: "ui-seq-sync".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"retained".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec!["A".into(), "B".into()],
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    let (mut running, _calls, mut updates) = running();
    running.panel = PanelState::new(make_snap(1, 0)).unwrap();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event_seq: 1,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(1)),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ev1 = wire.try_recv().unwrap();

    // Activate resync barrier and defer event_seq=2.
    running.schedule_panel_resync(protocol::PANEL_ID);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync_w = wire.try_recv().unwrap();

    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event_seq: 2,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(0)),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();

    // Settling ev1 via Ack emits PanelSynced with synced_ui_seq == 1 (NOT 2, which is still deferred!).
    let mut ack1 = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack1.in_reply_to = ev1.request_id;
    running.frame(ack1, &outgoing).await.unwrap();
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::PanelSynced {
            panel_id: protocol::PANEL_ID,
            synced_ui_seq: 1,
            ..
        })
    ));

    // When resync finishes and deferred event_seq=2 is dispatched, processed_ui_seq advances to 2.
    let mut resync_ack = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    resync_ack.in_reply_to = resync_w.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::PanelSynced {
            panel_id: protocol::PANEL_ID,
            synced_ui_seq: 1,
            ..
        })
    ));
    let ev2 = wire.try_recv().unwrap();
    let mut ack2 = Envelope::new(
        running.identity,
        3,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack2.in_reply_to = ev2.request_id;
    running.frame(ack2, &outgoing).await.unwrap();
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::PanelSynced {
            panel_id: protocol::PANEL_ID,
            synced_ui_seq: 2,
            ..
        })
    ));
}

#[tokio::test]
async fn superseded_resync_patch_replacing_table_watermark_is_rejected_and_retried() {
    let make_snap = |rev: u64, vp_rev: u64| PanelSnapshot {
        revision: rev,
        title: "patch-resync-baseline".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"retained".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        2,
                        "tbl",
                        panel::node::Kind::VirtualTable(panel::VirtualTable {
                            columns: vec![panel::TableColumn {
                                id: "c1".into(),
                                title: "Col".into(),
                                width: 80.0,
                            }],
                            total_rows: 10,
                            offset: 0,
                            viewport_revision: vp_rev,
                            rows: vec![],
                            multi_select: false,
                        }),
                    ),
                ],
            }),
        )),
    };
    let read_vp = |snap: &PanelSnapshot| -> u64 {
        match snap.root.as_ref().unwrap().find(2).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            other => panic!("expected VirtualTable, got {other:?}"),
        }
    };

    let (mut running, _calls, _updates) = running();
    running.supports_panel_multiplexing = true;
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    let (o_tx, o_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let o_w = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, o_w.request_id));
    let mut o_s = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, 1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    o_s.in_reply_to = o_w.request_id;
    running.frame(o_s, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();

    running
        .control(
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event_seq: 1,
                event: UiEvent {
                    node_id: 2,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                        revision: 2,
                        offset: 5,
                        limit: 5,
                    })),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    let vp_w = wire.try_recv().unwrap();
    assert!(claims.claim_for_write(2, vp_w.request_id));

    // Timer fires first -> Resync #1 sent with vp=2.
    running.requests.get_mut(&vp_w.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    let _cancel_w = wire.try_recv().unwrap();
    let resync1 = wire.try_recv().unwrap();

    // Late Error(Deadline) retracts vp 2 -> 1.
    let mut late_deadline = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Deadline, "子面板请求已超时")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    late_deadline.in_reply_to = vp_w.request_id;
    running.frame(late_deadline, &outgoing).await.unwrap();
    assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 1);

    // Worker replies Body::Patch(base=1, rev=2) replacing node 2 with stale vp=2 -> MUST be rejected!
    let mut stale_patch = Envelope::new(
        running.identity,
        3,
        2,
        envelope::Body::Patch(panel::PanelPatch {
            base_revision: 1,
            revision: 2,
            operations: vec![panel::PatchOperation {
                node_id: 2,
                change: Some(panel::patch_operation::Change::Replace(panel::Node::new(
                    2,
                    "tbl",
                    panel::node::Kind::VirtualTable(panel::VirtualTable {
                        columns: vec![panel::TableColumn {
                            id: "c1".into(),
                            title: "Col".into(),
                            width: 80.0,
                        }],
                        total_rows: 10,
                        offset: 0,
                        viewport_revision: 2,
                        rows: vec![],
                        multi_select: false,
                    }),
                ))),
            }],
        }),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    stale_patch.in_reply_to = resync1.request_id;
    running.frame(stale_patch, &outgoing).await.unwrap();

    assert!(running.is_panel_semantic_drifted(2));
    assert_eq!(running.panel_revision(2), 1);
    assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 1);

    let resync2 = wire.try_recv().unwrap();
    assert!(matches!(
        resync2.body,
        Some(envelope::Body::Resync(ref s)) if read_vp(s) == 1
    ));

    let mut snap2 = Envelope::new(
        running.identity,
        4,
        2,
        envelope::Body::Snapshot(make_snap(2, 1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    snap2.in_reply_to = resync2.request_id;
    running.frame(snap2, &outgoing).await.unwrap();
    assert!(!running.is_panel_semantic_drifted(2));
    assert!(!running.is_panel_resyncing(2));
    assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 1);
}

#[tokio::test]
async fn earlier_snapshot_preserves_inflight_subsequent_select_across_ack_and_callback_error() {
    let make_snap = |rev: u64, selected: u32| PanelSnapshot {
        revision: rev,
        title: "pipelined-snap-select".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"retained".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec!["A".into(), "B".into()],
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };
    let read_sel = |snap: &PanelSnapshot| -> u32 {
        match snap.root.as_ref().unwrap().find(3).unwrap().kind.as_ref().unwrap() {
            panel::node::Kind::Select(s) => s.selected_index,
            other => panic!("expected Select, got {other:?}"),
        }
    };

    // Subcase A: Request A (Focus) completes with full Snapshot(rev=2, Select=0) while B (SelectedOption(1))
    // is in flight. B's ledger survives and handles both Ack(rev=2) -> stays B=1, and Error(Invalid) -> marks drift!
    for reply_with_ack in [true, false] {
        let (mut running, _calls, mut updates) = running();
        running.panel = PanelState::new(make_snap(1, 0)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 0,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_a = wire.try_recv().unwrap();

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(1)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_b = wire.try_recv().unwrap();

        let mut snap_a = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, 0)),
            MAX_OPERATION,
        );
        snap_a.in_reply_to = ev_a.request_id;
        running.frame(snap_a, &outgoing).await.unwrap();
        assert_eq!(read_sel(&running.panel_snapshot(protocol::PANEL_ID).unwrap()), 1);
        while updates.try_recv().is_ok() {}

        if reply_with_ack {
            let mut ack_b = Envelope::new(
                running.identity,
                2,
                2,
                envelope::Body::Ack(panel::Empty {}),
                MAX_OPERATION,
            );
            ack_b.in_reply_to = ev_b.request_id;
            running.frame(ack_b, &outgoing).await.unwrap();
            assert_eq!(read_sel(&running.panel_snapshot(protocol::PANEL_ID).unwrap()), 1);
            assert!(!running.is_panel_semantic_drifted(protocol::PANEL_ID));
            assert!(matches!(
                updates.try_recv(),
                Ok(PluginEvent::PanelSynced { panel_id: protocol::PANEL_ID, ref snapshot, .. })
                    if read_sel(snapshot) == 1
            ));
        } else {
            let mut err_b = Envelope::new(
                running.identity,
                2,
                2,
                envelope::Body::Error(Failure::new(ErrorCode::Invalid, "callback failed after select")),
                MAX_OPERATION,
            );
            err_b.in_reply_to = ev_b.request_id;
            running.frame(err_b, &outgoing).await.unwrap();
            assert_eq!(read_sel(&running.panel_snapshot(protocol::PANEL_ID).unwrap()), 0);
            assert!(running.is_panel_semantic_drifted(protocol::PANEL_ID));
            assert!(matches!(
                wire.try_recv().unwrap().body,
                Some(envelope::Body::Resync(_))
            ));
        }
    }

    // Subcase B: Unsolicited Snapshot(rev=2, in_reply_to=0) clears ledger, yet is_optimistic still
    // forces semantic drift & Resync if B later returns bare Ack(rev=2) or Error(Invalid, rev=2).
    for reply_with_ack in [true, false] {
        let (mut running, _calls, _updates) = running();
        running.panel = PanelState::new(make_snap(1, 0)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(1)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_b = wire.try_recv().unwrap();

        running
            .frame(
                Envelope::new(
                    running.identity,
                    1,
                    2,
                    envelope::Body::Snapshot(make_snap(2, 0)),
                    MAX_OPERATION,
                ),
                &outgoing,
            )
            .await
            .unwrap();
        assert!(!running.has_panel_optimistic_request(protocol::PANEL_ID, ev_b.request_id));

        let body = if reply_with_ack {
            envelope::Body::Ack(panel::Empty {})
        } else {
            envelope::Body::Error(Failure::new(ErrorCode::Invalid, "callback failed"))
        };
        let mut reply_b = Envelope::new(running.identity, 2, 2, body, MAX_OPERATION);
        reply_b.in_reply_to = ev_b.request_id;
        running.frame(reply_b, &outgoing).await.unwrap();
        assert!(running.is_panel_semantic_drifted(protocol::PANEL_ID));
        assert!(matches!(
            wire.try_recv().unwrap().body,
            Some(envelope::Body::Resync(_))
        ));
    }
}

#[tokio::test]
async fn deferred_queue_overflow_uses_contiguous_prefix_and_rejected_seq() {
    let make_snap = |rev: u64, selected: u32| PanelSnapshot {
        revision: rev,
        title: "deferred-overflow-seq".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"retained".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec!["A".into(), "B".into()],
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    let (mut running, _calls, mut updates) = running();
    running.panel = PanelState::new(make_snap(1, 0)).unwrap();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    // First process seq=1 cleanly.
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event_seq: 1,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(1)),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    let ev1 = wire.try_recv().unwrap();
    let mut ack1 = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    ack1.in_reply_to = ev1.request_id;
    running.frame(ack1, &outgoing).await.unwrap();
    while updates.try_recv().is_ok() {}

    // Enter Resync barrier and fill deferred queue with seq=2..=(MAX+1).
    running.schedule_panel_resync(protocol::PANEL_ID);
    running.flush_pending_resyncs(&outgoing).unwrap();
    let resync_w = wire.try_recv().unwrap();
    for i in 0..MAX_DEFERRED_PANEL_COMMANDS {
        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 2 + i as u64,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
    }

    // Overflow with high seq=500 -> fails immediately, yet synced_ui_seq MUST stay 1 (below seq=2) with rejected_ui_seqs=[500]!
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event_seq: 500,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(1)),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(matches!(updates.try_recv(), Ok(PluginEvent::Error { .. })));
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::PanelSynced {
            panel_id: protocol::PANEL_ID,
            synced_ui_seq: 1,
            ref rejected_ui_seqs,
            ..
        }) if rejected_ui_seqs == &[500]
    ));

    // Once Resync completes, deferred commands drain sequentially and processed prefix advances monotonically.
    let mut resync_ack = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    );
    resync_ack.in_reply_to = resync_w.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();
    assert_eq!(running.contiguous_processed_ui_seq(protocol::PANEL_ID), 1);
    let mut worker_seq = 3u64;
    while let Ok(ev_wire) = wire.try_recv() {
        let mut ack = Envelope::new(
            running.identity,
            worker_seq,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        );
        worker_seq += 1;
        ack.in_reply_to = ev_wire.request_id;
        running.frame(ack, &outgoing).await.unwrap();
        while updates.try_recv().is_ok() {}
    }
    assert!(running.main_deferred_commands.is_empty());
    assert_eq!(running.contiguous_processed_ui_seq(protocol::PANEL_ID), 500);
}

#[tokio::test]
async fn reordered_snapshot_retracts_unclaimed_select_and_drifts_claimed_select() {
    let make_snap = |rev: u64, options: [&str; 2], selected: u32| PanelSnapshot {
        revision: rev,
        title: "reorder-semantic-guard".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"ok".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: options.into_iter().map(str::to_owned).collect(),
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    // Part A: Unclaimed SelectedOption(0 -> "A") is retracted before writer claims it when req A's Snapshot
    // normalizes editor input and reorders options ["A", "B"] -> ["B", "A"]; causal editor_bases and synced_ui_seq
    // are delivered together on ONE PluginEvent::Panel (never dropped by an earlier empty-base PanelSynced).
    {
        let (mut running, _calls, mut updates) = running();
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        running.panel = PanelState::new(make_snap(1, ["A", "B"], 1)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        let raw_base = panel::EditorSnapshot {
            document_id: 1,
            revision: 2,
            contents: b"  raw  ".to_vec(),
            selection_start: 0,
            selection_end: 0,
        };
        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::EditorChanged(raw_base.clone())),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_a = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, ev_a.request_id));

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 2,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_b = wire.try_recv().unwrap();
        // Do NOT claim ev_b (simulates blocked/slow writer before claiming from `writes`).
        while updates.try_recv().is_ok() {}

        let mut normalized = make_snap(2, ["B", "A"], 1);
        if let Some(panel::node::Kind::Column(col)) =
            normalized.root.as_mut().and_then(|n| n.kind.as_mut())
            && let Some(panel::node::Kind::Editor(ed)) = col.children[0].kind.as_mut()
        {
            ed.revision = 3;
            ed.contents = b"raw".to_vec();
        }
        let mut snap_a = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(normalized),
            MAX_OPERATION,
        );
        snap_a.in_reply_to = ev_a.request_id;
        running.frame(snap_a, &outgoing).await.unwrap();

        // ev_b MUST have been retracted from claims, rejected, and NEVER mark semantic drift.
        assert!(!claims.claim_for_write(protocol::PANEL_ID, ev_b.request_id));
        assert!(!running.requests.contains_key(&ev_b.request_id));
        assert!(!running.is_panel_semantic_drifted(protocol::PANEL_ID));
        assert!(!running.has_inflight_resync(protocol::PANEL_ID));

        let mut saw_stale_error = false;
        let mut saw_separate_panel_synced = false;
        let mut saw_merged_panel = false;
        while let Ok(ev) = updates.try_recv() {
            match ev {
                PluginEvent::Error { failure, .. }
                    if failure.code == protocol::ErrorCode::Stale as i32 =>
                {
                    saw_stale_error = true;
                }
                PluginEvent::PanelSynced { .. } => {
                    saw_separate_panel_synced = true;
                }
                PluginEvent::Panel {
                    snapshot,
                    editor_bases,
                    synced_ui_seq,
                    rejected_ui_seqs,
                    ..
                } if snapshot.revision == 2
                    && editor_bases == vec![raw_base.clone()]
                    && synced_ui_seq == 2
                    && rejected_ui_seqs == [2] =>
                {
                    saw_merged_panel = true;
                }
                _ => {}
            }
        }
        assert!(saw_stale_error);
        assert!(!saw_separate_panel_synced);
        assert!(saw_merged_panel);
    }

    // Part B: Already-claimed SelectedOption(0 -> "A") cannot be retracted when Snapshot reorders
    // ["A", "B"] -> ["B", "A"]; Host immediately arms semantic drift & resync until Snapshot confirms.
    {
        let (mut running, _calls, _updates) = running();
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        running.panel = PanelState::new(make_snap(1, ["A", "B"], 1)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_a = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, ev_a.request_id));

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 2,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_b = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, ev_b.request_id));

        let mut snap_a = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, ["B", "A"], 1)),
            MAX_OPERATION,
        );
        snap_a.in_reply_to = ev_a.request_id;
        running.frame(snap_a, &outgoing).await.unwrap();

        assert!(running.is_panel_semantic_drifted(protocol::PANEL_ID));
        assert!(running.has_inflight_resync(protocol::PANEL_ID));
        let resync_w = wire.try_recv().unwrap();
        assert!(matches!(resync_w.body, Some(envelope::Body::Resync(_))));

        let mut resync_snap = Envelope::new(
            running.identity,
            2,
            3,
            envelope::Body::Snapshot(make_snap(3, ["B", "A"], 0)),
            MAX_OPERATION,
        );
        resync_snap.in_reply_to = resync_w.request_id;
        running.frame(resync_snap, &outgoing).await.unwrap();
        assert!(!running.is_panel_semantic_drifted(protocol::PANEL_ID));
        assert!(!running.has_inflight_resync(protocol::PANEL_ID));
    }
}

#[test]
fn snapshot_validation_and_retraction_hold_writer_claim_barrier() {
    let claims = Arc::new(super::OutboundWriteClaims::default());
    claims.register(protocol::PANEL_ID, 42);

    let (started_tx, started_rx) = std::sync::mpsc::channel();
    let (finished_tx, finished_rx) = std::sync::mpsc::channel();
    let claims_thread = claims.clone();

    let mut barrier = claims.lock_barrier();
    let handle = std::thread::spawn(move || {
        started_tx.send(()).unwrap();
        let claimed = claims_thread.claim_for_write(protocol::PANEL_ID, 42);
        finished_tx.send(claimed).unwrap();
    });

    started_rx.recv().unwrap();
    // Writer claim MUST block on the barrier while Snapshot validation/retraction is in progress.
    assert!(
        finished_rx
            .recv_timeout(std::time::Duration::from_millis(20))
            .is_err(),
        "writer claim_for_write must block until OutboundWriteClaims barrier is released"
    );

    let retracted = barrier.try_retract_batch(&[(protocol::PANEL_ID, 42)]);
    assert_eq!(retracted, vec![(protocol::PANEL_ID, 42)]);
    drop(barrier);

    assert!(
        !finished_rx.recv().unwrap(),
        "writer must observe retracted frame after barrier release"
    );
    handle.join().unwrap();
}

#[tokio::test]
async fn retraction_and_error_sync_report_ui_event_seq_not_worker_cmd_seq() {
    let make_snap = |rev: u64, options: [&str; 2], selected: u32| PanelSnapshot {
        revision: rev,
        title: "seq-separation".into(),
        root: Some(panel::Node::new(
            10,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        1,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"ok".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: options.into_iter().map(str::to_owned).collect(),
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    // Part A: Explicit Error(Deadline) after diverged cmd_seq=10 and ui_event_seq=3 while deferred seq=2
    // pins contiguous_processed_ui_seq == 1 -> PanelSynced must report rejected_ui_seqs == [3], NOT [10].
    {
        let (mut running, _calls, mut updates) = running();
        running.panel = PanelState::new(make_snap(1, ["A", "B"], 1)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running
            .control_with_seq(
                10,
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 3,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_err = wire.try_recv().unwrap();

        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let resync_w = wire.try_recv().unwrap();

        running
            .control_with_seq(
                11,
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 2,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.contiguous_processed_ui_seq(protocol::PANEL_ID), 1);
        while updates.try_recv().is_ok() {}

        let mut deadline_err = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Deadline, "expired")),
            MAX_OPERATION,
        );
        deadline_err.in_reply_to = ev_err.request_id;
        running.frame(deadline_err, &outgoing).await.unwrap();

        assert!(matches!(updates.try_recv(), Ok(PluginEvent::Error { .. })));
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::PanelSynced {
                panel_id: protocol::PANEL_ID,
                synced_ui_seq: 1,
                ref rejected_ui_seqs,
                ..
            }) if rejected_ui_seqs == &[3]
        ));

        let mut ack = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        );
        ack.in_reply_to = resync_w.request_id;
        running.frame(ack, &outgoing).await.unwrap();
    }

    // Part B: Invalidated optimistic retraction under diverged cmd_seq=21 and ui_event_seq=4 while deferred
    // seq=2 pins contiguous_processed_ui_seq == 1 -> merged PluginEvent::Panel carries rejected_ui_seqs == [4], NOT [21].
    {
        let (mut running, _calls, mut updates) = running();
        let claims = Arc::new(super::OutboundWriteClaims::default());
        running.outbound_claims = Some(claims.clone());
        running.panel = PanelState::new(make_snap(1, ["A", "B"], 1)).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running
            .control_with_seq(
                20,
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(true)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let ev_a = wire.try_recv().unwrap();
        assert!(claims.claim_for_write(protocol::PANEL_ID, ev_a.request_id));

        running
            .control_with_seq(
                21,
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 4,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::SelectedOption(0)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let _ev_b = wire.try_recv().unwrap();

        running.schedule_panel_resync(protocol::PANEL_ID);
        running.flush_pending_resyncs(&outgoing).unwrap();
        let _resync_w = wire.try_recv().unwrap();
        running
            .control_with_seq(
                22,
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 2,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Focus(false)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        assert_eq!(running.contiguous_processed_ui_seq(protocol::PANEL_ID), 0);
        while updates.try_recv().is_ok() {}

        let mut snap_a = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Snapshot(make_snap(2, ["B", "A"], 1)),
            MAX_OPERATION,
        );
        snap_a.in_reply_to = ev_a.request_id;
        running.frame(snap_a, &outgoing).await.unwrap();
        assert_eq!(running.contiguous_processed_ui_seq(protocol::PANEL_ID), 1);

        let mut saw_panel = false;
        while let Ok(ev) = updates.try_recv() {
            if let PluginEvent::Panel {
                snapshot,
                synced_ui_seq: 1,
                ref rejected_ui_seqs,
                ..
            } = ev
                && snapshot.revision == 2
                && rejected_ui_seqs == &[4]
            {
                saw_panel = true;
            }
        }
        assert!(saw_panel);
    }
}

#[tokio::test]
async fn claimed_child_viewport_timeout_emits_terminal_panel_synced_across_resync_ack_and_error() {
    let make_snap = |rev: u64, vp_rev: u64| PanelSnapshot {
        revision: rev,
        title: "child-vp-timeout".into(),
        root: Some(panel::Node::new(
            1,
            "tbl",
            panel::node::Kind::VirtualTable(panel::VirtualTable {
                columns: vec![panel::TableColumn {
                    id: "c1".into(),
                    title: "Col".into(),
                    width: 80.0,
                }],
                total_rows: 100,
                offset: 0,
                viewport_revision: vp_rev,
                rows: vec![],
                multi_select: false,
            }),
        )),
    };

    // Case 1: Claimed child Viewport times out -> handle_timeouts emits PanelSynced;
    // follow-up Resync same-revision Ack emits terminal PanelSynced.
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();
        while updates.try_recv().is_ok() {}

        running
            .control(
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                            revision: 2,
                            offset: 50,
                            limit: 50,
                        })),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let vp_w = wire.try_recv().unwrap();
        running.requests.get_mut(&vp_w.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();

        let _cancel_w = wire.try_recv().unwrap();
        let resync_w = wire.try_recv().unwrap();
        assert!(matches!(resync_w.body, Some(envelope::Body::Resync(_))));
        let mut saw_timeout_sync = false;
        while let Ok(ev) = updates.try_recv() {
            if matches!(
                ev,
                PluginEvent::PanelSynced {
                    panel_id: 2,
                    synced_ui_seq: 1,
                    ..
                }
            ) {
                saw_timeout_sync = true;
            }
        }
        assert!(saw_timeout_sync);

        let mut resync_ack = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        resync_ack.in_reply_to = resync_w.request_id;
        running.frame(resync_ack, &outgoing).await.unwrap();

        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::PanelSynced {
                panel_id: 2,
                synced_ui_seq: 1,
                ..
            })
        ));
    }

    // Case 2: Claimed child Viewport times out -> Resync fails with Error(Invalid) -> emits terminal PanelSynced.
    {
        let (mut running, _calls, mut updates) = running();
        running.supports_panel_multiplexing = true;
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
        let (o_tx, o_rx) = oneshot::channel();
        running
            .control(
                Control::Open {
                    panel_id: 2,
                    id: Uuid::new_v4(),
                    revision: 1,
                    read_only: false,
                    request: request(),
                    reply: o_tx,
                },
                &outgoing,
            )
            .await
            .unwrap();
        let o_w = wire.try_recv().unwrap();
        let mut o_s = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Snapshot(make_snap(1, 1)),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        o_s.in_reply_to = o_w.request_id;
        running.frame(o_s, &outgoing).await.unwrap();
        o_rx.await.unwrap().unwrap();
        while updates.try_recv().is_ok() {}

        running
            .control(
                Control::Event {
                    panel_id: 2,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 1,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                            revision: 2,
                            offset: 50,
                            limit: 50,
                        })),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let vp_w = wire.try_recv().unwrap();
        running.requests.get_mut(&vp_w.request_id).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
        let _cancel_w = wire.try_recv().unwrap();
        let resync_w = wire.try_recv().unwrap();
        while updates.try_recv().is_ok() {}

        let mut resync_err = Envelope::new(
            running.identity,
            2,
            1,
            envelope::Body::Error(Failure::new(ErrorCode::Invalid, "resync unsupported")),
            MAX_OPERATION,
        )
        .with_panel_id(2);
        resync_err.in_reply_to = resync_w.request_id;
        running.frame(resync_err, &outgoing).await.unwrap();

        let mut saw_error = false;
        let mut saw_terminal_sync = false;
        while let Ok(ev) = updates.try_recv() {
            match ev {
                PluginEvent::Error { panel_id: 2, .. } => saw_error = true,
                PluginEvent::PanelSynced {
                    panel_id: 2,
                    synced_ui_seq: 1,
                    ..
                } => saw_terminal_sync = true,
                _ => {}
            }
        }
        assert!(saw_error);
        assert!(saw_terminal_sync);
    }
}

#[tokio::test]
async fn timed_out_claimed_viewport_after_resync_abort_accepts_base_watermark_snapshot() {
    let make_snap = |rev: u64, vp_rev: u64| PanelSnapshot {
        revision: rev,
        title: "uncertain-vp-resync-abort".into(),
        root: Some(panel::Node::new(
            1,
            "tbl",
            panel::node::Kind::VirtualTable(panel::VirtualTable {
                columns: vec![panel::TableColumn {
                    id: "c1".into(),
                    title: "Col".into(),
                    width: 80.0,
                }],
                total_rows: 100,
                offset: 0,
                viewport_revision: vp_rev,
                rows: vec![],
                multi_select: false,
            }),
        )),
    };

    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let (o_tx, o_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: Uuid::new_v4(),
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let o_w = wire.try_recv().unwrap();
    let mut o_s = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, 1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    o_s.in_reply_to = o_w.request_id;
    running.frame(o_s, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();
    while updates.try_recv().is_ok() {}

    // Claimed Viewport(2) times out (no late reply ever arrives), then Resync fails with Error(Invalid).
    running
        .control(
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event_seq: 1,
                event: UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                        revision: 2,
                        offset: 50,
                        limit: 50,
                    })),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    let vp_w = wire.try_recv().unwrap();
    running.requests.get_mut(&vp_w.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    let _cancel_w = wire.try_recv().unwrap();
    let resync_w = wire.try_recv().unwrap();
    while updates.try_recv().is_ok() {}

    let mut resync_err = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "resync unsupported")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    resync_err.in_reply_to = resync_w.request_id;
    running.frame(resync_err, &outgoing).await.unwrap();
    while updates.try_recv().is_ok() {}

    // Worker never applied vp=2 and publishes a legitimate Snapshot with vp=1 (both unsolicited rev=2
    // and later causal rev=3); Host MUST accept it without rejecting vp=1 or re-applying vp=2!
    let snap2 = Envelope::new(
        running.identity,
        3,
        2,
        envelope::Body::Snapshot(make_snap(2, 1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.frame(snap2, &outgoing).await.unwrap();
    let read_vp = |snap: &PanelSnapshot| match snap.root.as_ref().unwrap().kind.as_ref().unwrap() {
        panel::node::Kind::VirtualTable(t) => t.viewport_revision,
        other => panic!("expected table, got {other:?}"),
    };
    assert_eq!(running.panel_revision(2), 2);
    assert_eq!(read_vp(&running.panel_snapshot(2).unwrap()), 1);
    assert!(!running.is_panel_semantic_drifted(2));
}

#[tokio::test]
async fn earlier_checkbox_ack_and_unrelated_patch_do_not_clear_inflight_viewport_watermark_or_seq() {
    let make_snap = |rev: u64, checked: bool, vp_rev: u64, text: &str| PanelSnapshot {
        revision: rev,
        title: "inflight-vp-isolation".into(),
        root: Some(panel::Node::new(
            1,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        2,
                        "chk",
                        panel::node::Kind::Checkbox(panel::CheckboxNode {
                            label: "Flag".into(),
                            checked,
                            enabled: true,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "tbl",
                        panel::node::Kind::VirtualTable(panel::VirtualTable {
                            columns: vec![panel::TableColumn {
                                id: "c1".into(),
                                title: "Col".into(),
                                width: 80.0,
                            }],
                            total_rows: 100,
                            offset: 0,
                            viewport_revision: vp_rev,
                            rows: vec![],
                            multi_select: false,
                        }),
                    ),
                    panel::Node::new(
                        4,
                        "txt",
                        panel::node::Kind::Text(panel::Text {
                            text: text.into(),
                            tone: panel::Tone::Foreground as i32,
                        }),
                    ),
                ],
            }),
        )),
    };
    let read_vp = |snap: &PanelSnapshot| {
        match snap
            .root
            .as_ref()
            .unwrap()
            .find(3)
            .unwrap()
            .kind
            .as_ref()
            .unwrap()
        {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            other => panic!("expected table, got {other:?}"),
        }
    };

    // Subtest A: Earlier Checkbox Ack while Viewport(seq=2, vp=2) is in flight MUST emit
    // PanelSynced with synced_ui_seq=1 and confirmed table vp=1.
    {
        let (mut running, _calls, mut updates) = running();
        running.panel = PanelState::new(make_snap(1, false, 1, "v1")).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Toggled(true)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let chk_w = wire.try_recv().unwrap();

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 2,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                            revision: 2,
                            offset: 50,
                            limit: 50,
                        })),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let vp_w = wire.try_recv().unwrap();
        while updates.try_recv().is_ok() {}

        let mut chk_ack = Envelope::new(
            running.identity,
            1,
            1,
            envelope::Body::Ack(panel::Empty {}),
            MAX_OPERATION,
        );
        chk_ack.in_reply_to = chk_w.request_id;
        running.frame(chk_ack, &outgoing).await.unwrap();
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::PanelSynced {
                panel_id: protocol::PANEL_ID,
                synced_ui_seq: 1,
                ref snapshot,
                ..
            }) if read_vp(snapshot) == 1
        ));

        let mut vp_patch = Envelope::new(
            running.identity,
            2,
            2,
            envelope::Body::Patch(panel::PanelPatch {
                base_revision: 1,
                revision: 2,
                operations: vec![panel::PatchOperation {
                    node_id: 3,
                    change: Some(panel::patch_operation::Change::Table(panel::VirtualTable {
                        columns: vec![panel::TableColumn {
                            id: "c1".into(),
                            title: "Col".into(),
                            width: 80.0,
                        }],
                        total_rows: 100,
                        offset: 50,
                        viewport_revision: 2,
                        rows: vec![],
                        multi_select: false,
                    })),
                }],
            }),
            MAX_OPERATION,
        );
        vp_patch.in_reply_to = vp_w.request_id;
        running.frame(vp_patch, &outgoing).await.unwrap();
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Panel {
                panel_id: protocol::PANEL_ID,
                synced_ui_seq: 2,
                ref snapshot,
                ..
            }) if read_vp(snapshot) == 2
        ));
    }

    // Subtest B: Unrelated newer-revision Patch(rev=2) while Viewport(seq=2, vp=2) is in flight MUST
    // publish Panel(rev=2) with synced_ui_seq=1 and confirmed table vp=1.
    {
        let (mut running, _calls, mut updates) = running();
        running.panel = PanelState::new(make_snap(1, false, 1, "v1")).unwrap();
        let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 1,
                    event: UiEvent {
                        node_id: 2,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Toggled(true)),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let chk_w = wire.try_recv().unwrap();

        running
            .control(
                Control::Event {
                    panel_id: protocol::PANEL_ID,
                    expected_snapshot: None,
                    event_seq: 2,
                    event: UiEvent {
                        node_id: 3,
                        editors: vec![],
                        event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                            revision: 2,
                            offset: 50,
                            limit: 50,
                        })),
                    },
                },
                &outgoing,
            )
            .await
            .unwrap();
        let vp_w = wire.try_recv().unwrap();
        while updates.try_recv().is_ok() {}

        let mut patch_ev = Envelope::new(
            running.identity,
            1,
            2,
            envelope::Body::Patch(panel::PanelPatch {
                base_revision: 1,
                revision: 2,
                operations: vec![panel::PatchOperation {
                    node_id: 4,
                    change: Some(panel::patch_operation::Change::Replace(panel::Node::new(
                        4,
                        "txt",
                        panel::node::Kind::Text(panel::Text {
                            text: "v2".into(),
                            tone: panel::Tone::Foreground as i32,
                        }),
                    ))),
                }],
            }),
            MAX_OPERATION,
        );
        patch_ev.in_reply_to = chk_w.request_id;
        running.frame(patch_ev, &outgoing).await.unwrap();

        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Panel {
                panel_id: protocol::PANEL_ID,
                synced_ui_seq: 1,
                ref snapshot,
                ..
            }) if snapshot.revision == 2 && read_vp(snapshot) == 1
        ));

        let mut vp_patch = Envelope::new(
            running.identity,
            2,
            3,
            envelope::Body::Patch(panel::PanelPatch {
                base_revision: 2,
                revision: 3,
                operations: vec![panel::PatchOperation {
                    node_id: 3,
                    change: Some(panel::patch_operation::Change::Table(panel::VirtualTable {
                        columns: vec![panel::TableColumn {
                            id: "c1".into(),
                            title: "Col".into(),
                            width: 80.0,
                        }],
                        total_rows: 100,
                        offset: 50,
                        viewport_revision: 2,
                        rows: vec![],
                        multi_select: false,
                    })),
                }],
            }),
            MAX_OPERATION,
        );
        vp_patch.in_reply_to = vp_w.request_id;
        running.frame(vp_patch, &outgoing).await.unwrap();
        assert!(matches!(
            updates.try_recv(),
            Ok(PluginEvent::Panel {
                panel_id: protocol::PANEL_ID,
                synced_ui_seq: 2,
                ref snapshot,
                ..
            }) if read_vp(snapshot) == 2
        ));
    }
}

#[tokio::test]
async fn resync_bare_ack_settles_uncertain_viewport_for_ui_and_commit() {
    let make_snap = |rev: u64, vp_rev: u64| PanelSnapshot {
        revision: rev,
        title: "resync-ack-settles-uncertain-vp".into(),
        root: Some(panel::Node::new(
            1,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        2,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "tbl",
                        panel::node::Kind::VirtualTable(panel::VirtualTable {
                            columns: vec![panel::TableColumn {
                                id: "c1".into(),
                                title: "Col".into(),
                                width: 80.0,
                            }],
                            total_rows: 100,
                            offset: 0,
                            viewport_revision: vp_rev,
                            rows: vec![],
                            multi_select: false,
                        }),
                    ),
                ],
            }),
        )),
    };
    let read_vp = |snap: &PanelSnapshot| {
        match snap
            .root
            .as_ref()
            .unwrap()
            .find(3)
            .unwrap()
            .kind
            .as_ref()
            .unwrap()
        {
            panel::node::Kind::VirtualTable(t) => t.viewport_revision,
            other => panic!("expected table, got {other:?}"),
        }
    };

    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let child_res = Uuid::new_v4();
    let (o_tx, o_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: child_res,
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let o_w = wire.try_recv().unwrap();
    let mut o_s = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, 1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    o_s.in_reply_to = o_w.request_id;
    running.frame(o_s, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();
    while updates.try_recv().is_ok() {}

    // Claimed Viewport(2) times out -> Host marks it uncertain and emits Resync(vp=2).
    running
        .control(
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event_seq: 1,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                        revision: 2,
                        offset: 50,
                        limit: 50,
                    })),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    let vp_w = wire.try_recv().unwrap();
    running.requests.get_mut(&vp_w.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    let _cancel_w = wire.try_recv().unwrap();
    let resync_w = wire.try_recv().unwrap();
    assert!(matches!(
        resync_w.body,
        Some(envelope::Body::Resync(ref s)) if read_vp(s) == 2
    ));
    while updates.try_recv().is_ok() {}

    // Worker adopts Resync(vp=2) and replies with bare Ack -> Host settles uncertain vp=2,
    // emits PanelSynced with vp=2, and clears drift so CommitEditor(expected vp=2) succeeds!
    let mut resync_ack = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Ack(panel::Empty {}),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    resync_ack.in_reply_to = resync_w.request_id;
    running.frame(resync_ack, &outgoing).await.unwrap();

    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::PanelSynced {
            panel_id: 2,
            synced_ui_seq: 1,
            ref snapshot,
            ..
        }) if read_vp(snapshot) == 2
    ));
    assert!(!running.is_panel_semantic_drifted(2));

    let (commit_tx, mut commit_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: child_res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: commit_tx,
                expected_snapshot: Some(Arc::new(make_snap(1, 2))),
            },
            &outgoing,
        )
        .await
        .unwrap();
    let commit_w = wire.try_recv().unwrap();
    assert!(matches!(
        commit_w.body,
        Some(envelope::Body::CommitEditor(_))
    ));
    assert!(commit_rx.try_recv().is_err());
}

#[tokio::test]
async fn aborted_resync_after_uncertain_select_timeout_latches_drift_and_blocks_commit() {
    let make_snap = |rev: u64, selected: u32| PanelSnapshot {
        revision: rev,
        title: "uncertain-select-abort-drift".into(),
        root: Some(panel::Node::new(
            1,
            "col",
            panel::node::Kind::Column(panel::Container {
                children: vec![
                    panel::Node::new(
                        2,
                        "ed",
                        panel::node::Kind::Editor(panel::Editor {
                            document_id: 1,
                            revision: 1,
                            contents: b"init".to_vec(),
                            format: panel::EditorFormat::Utf8 as i32,
                            read_only: false,
                        }),
                    ),
                    panel::Node::new(
                        3,
                        "select",
                        panel::node::Kind::Select(panel::SelectNode {
                            label: "Choice".into(),
                            options: vec!["A".into(), "B".into()],
                            selected_index: selected,
                            enabled: true,
                        }),
                    ),
                ],
            }),
        )),
    };

    let (mut running, _calls, mut updates) = running();
    running.supports_panel_multiplexing = true;
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);
    let child_res = Uuid::new_v4();
    let (o_tx, o_rx) = oneshot::channel();
    running
        .control(
            Control::Open {
                panel_id: 2,
                id: child_res,
                revision: 1,
                read_only: false,
                request: request(),
                reply: o_tx,
            },
            &outgoing,
        )
        .await
        .unwrap();
    let o_w = wire.try_recv().unwrap();
    let mut o_s = Envelope::new(
        running.identity,
        1,
        1,
        envelope::Body::Snapshot(make_snap(1, 0)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    o_s.in_reply_to = o_w.request_id;
    running.frame(o_s, &outgoing).await.unwrap();
    o_rx.await.unwrap().unwrap();
    while updates.try_recv().is_ok() {}

    // Claimed Select(1 -> "B") times out; Worker fails Resync with same-revision Error(Invalid).
    running
        .control(
            Control::Event {
                panel_id: 2,
                expected_snapshot: None,
                event_seq: 1,
                event: UiEvent {
                    node_id: 3,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::SelectedOption(1)),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    let sel_w = wire.try_recv().unwrap();
    running.requests.get_mut(&sel_w.request_id).unwrap().deadline =
        Instant::now() - Duration::from_secs(1);
    running.handle_timeouts(Instant::now(), &outgoing).await.unwrap();
    let _cancel_w = wire.try_recv().unwrap();
    let resync_w = wire.try_recv().unwrap();
    while updates.try_recv().is_ok() {}

    let mut resync_err = Envelope::new(
        running.identity,
        2,
        1,
        envelope::Body::Error(Failure::new(ErrorCode::Invalid, "resync unsupported")),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    resync_err.in_reply_to = resync_w.request_id;
    running.frame(resync_err, &outgoing).await.unwrap();

    // Retracting uncertain Select(1 -> 0) MUST latch semantic drift and block same-revision CommitEditor!
    assert!(running.is_panel_semantic_drifted(2));
    let (commit_tx, mut commit_rx) = oneshot::channel();
    running
        .control(
            Control::Commit {
                panel_id: 2,
                op_id: Uuid::new_v4(),
                request: CommitEditor {
                    resource_id: child_res.as_bytes().to_vec(),
                    message_revision: 1,
                    request: Some(request().into()),
                    editor: Some(EditorSnapshot {
                        document_id: 1,
                        revision: 1,
                        contents: b"init".to_vec(),
                        ..Default::default()
                    }),
                },
                cancelled: CancellationToken::new(),
                reply: commit_tx,
                expected_snapshot: Some(Arc::new(make_snap(1, 0))),
            },
            &outgoing,
        )
        .await
        .unwrap();
    assert!(commit_rx.try_recv().unwrap().is_err());

    // Authoritative full Snapshot(rev=2, Select=1) clears drift and reconciles state.
    let snap2 = Envelope::new(
        running.identity,
        3,
        2,
        envelope::Body::Snapshot(make_snap(2, 1)),
        MAX_OPERATION,
    )
    .with_panel_id(2);
    running.frame(snap2, &outgoing).await.unwrap();
    assert!(!running.is_panel_semantic_drifted(2));
}

#[tokio::test]
async fn unsolicited_base_snapshot_accepts_and_preserves_unclaimed_viewport_in_writes() {
    let make_snap = |rev: u64, vp_rev: u64| PanelSnapshot {
        revision: rev,
        title: "unsolicited-base-unclaimed-vp".into(),
        root: Some(panel::Node::new(
            1,
            "tbl",
            panel::node::Kind::VirtualTable(panel::VirtualTable {
                columns: vec![panel::TableColumn {
                    id: "c1".into(),
                    title: "Col".into(),
                    width: 80.0,
                }],
                total_rows: 100,
                offset: 0,
                viewport_revision: vp_rev,
                rows: vec![],
                multi_select: false,
            }),
        )),
    };
    let read_vp = |snap: &PanelSnapshot| match snap.root.as_ref().unwrap().kind.as_ref().unwrap() {
        panel::node::Kind::VirtualTable(t) => t.viewport_revision,
        other => panic!("expected table, got {other:?}"),
    };

    let (mut running, _calls, mut updates) = running();
    let claims = Arc::new(super::OutboundWriteClaims::default());
    running.outbound_claims = Some(claims.clone());
    running.panel = PanelState::new(make_snap(1, 1)).unwrap();
    let (outgoing, mut wire) = mpsc::channel(OUTGOING_CAPACITY);

    // Enqueue Viewport(2) with seq=1 leaving it UNCLAIMED in `claims` (`writes`).
    running
        .control(
            Control::Event {
                panel_id: protocol::PANEL_ID,
                expected_snapshot: None,
                event_seq: 1,
                event: UiEvent {
                    node_id: 1,
                    editors: vec![],
                    event: Some(panel::ui_event::Event::Viewport(panel::ViewportRequest {
                        revision: 2,
                        offset: 50,
                        limit: 50,
                    })),
                },
            },
            &outgoing,
        )
        .await
        .unwrap();
    let vp_w = wire.try_recv().unwrap();
    while updates.try_recv().is_ok() {}

    // Worker sends an independent unsolicited Snapshot(rev=2, vp=1, in_reply_to=0).
    let unsolicited = Envelope::new(
        running.identity,
        1,
        2,
        envelope::Body::Snapshot(make_snap(2, 1)),
        MAX_OPERATION,
    );
    running.frame(unsolicited, &outgoing).await.unwrap();

    // Host MUST accept rev=2 without drift/resync, keep Viewport(2) claim alive, and publish rev=2
    // with synced_ui_seq=0 and confirmed table vp=1.
    assert_eq!(running.panel_revision(protocol::PANEL_ID), 2);
    assert!(!running.is_panel_semantic_drifted(protocol::PANEL_ID));
    assert!(!running.has_inflight_resync(protocol::PANEL_ID));
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Panel {
            panel_id: protocol::PANEL_ID,
            synced_ui_seq: 0,
            ref snapshot,
            ..
        }) if snapshot.revision == 2 && read_vp(snapshot) == 1
    ));

    // Writer now claims Viewport(2) and Worker publishes Patch(Change::Table(vp=2)) -> Host settles vp=2 cleanly!
    assert!(claims.claim_for_write(protocol::PANEL_ID, vp_w.request_id));
    let mut vp_patch = Envelope::new(
        running.identity,
        2,
        3,
        envelope::Body::Patch(panel::PanelPatch {
            base_revision: 2,
            revision: 3,
            operations: vec![panel::PatchOperation {
                node_id: 1,
                change: Some(panel::patch_operation::Change::Table(panel::VirtualTable {
                    columns: vec![panel::TableColumn {
                        id: "c1".into(),
                        title: "Col".into(),
                        width: 80.0,
                    }],
                    total_rows: 100,
                    offset: 50,
                    viewport_revision: 2,
                    rows: vec![],
                    multi_select: false,
                })),
            }],
        }),
        MAX_OPERATION,
    );
    vp_patch.in_reply_to = vp_w.request_id;
    running.frame(vp_patch, &outgoing).await.unwrap();
    assert!(matches!(
        updates.try_recv(),
        Ok(PluginEvent::Panel {
            panel_id: protocol::PANEL_ID,
            synced_ui_seq: 1,
            ref snapshot,
            ..
        }) if snapshot.revision == 3 && read_vp(snapshot) == 2
    ));
}

